INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (5329, 'Sekai Monoshiri Ryoko', 1971, 1006, 'TV', 86.9, 'An educational documentary series that depicts a variety of real life places around the world in short 5 minute segments. The series aired Monday through Saturday.  (Source: AniDB)', 11, True, 49);
