INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (5332, 'Burning Village', 1989, 10, 'OVA', 64.5, 'Animal folk tales set in the titular community, in which local eccentric Ohahai retells several popular fairy tales with considerable license.  (Source: AniDB)', 48, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (5333, 'Hajimete no Christmas', 1983, 1, 'Special', 92.5, 'No description available for this anime.', 11, True, 53);
