INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (5533, 'Shita-kiri Suzume', 1917, 1, 'Movie', 83.0, 'This is a short film made in the fall of 1917. It is about a girl asking for rice.', 67, False, 13);
