INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6611, 'Eunhahamdae Jiguho', 1979, 1, 'Movie', 71.9, 'After the pollution of the Earths environment reaches a critical level, a small group of people embark on a journey through space to find a new home for humanity.', 35, True, 11);
