INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6637, 'Nyuuin Bokki Monogatari: Odaijini!', 1991, 2, 'OVA', 97.1, 'Yamashita and Negishi end up in the hospital with broken legs and arms. Its summer vacation and they are very bored, so they start picking on the cute nurse Miyuki.', 62, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6638, 'Hayate no Gotoku! Cuties', 2013, 12, 'TV', 84.2, 'Taking place after the events that occurred in Hayate no Gotoku! Cant Take My Eyes off You. Hayate, Nagi and Maria return to their daily lives at the Sanzenin Mansion and the Violet Mansion.  (Source: Hayate no Gotoku! Wikia)', 65, True, 38);
