INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6654, 'Agigongryong Doolie (2009)', 2009, 26, 'TV', 76.6, 'The story of a baby dinosaur and his friends.', 17, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6655, 'Dallyeola Hani', 1988, 13, 'TV', 77.5, 'Hany is a small tomboy and slightly troublesome teenager who lives life a bit carelessly on her own since her Father lives abroad due to work in the Middle East and her Mother died when she was very small. The only thing Hany is very good at is running~ fast! Hong Du-kke is a new track and field coach of her school and takes notice in her talent and gets her to train with him.  (Source: Cute in Korea)', 99, True, 55);
