INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6724, 'Dog Days Specials', 2012, 13, 'Special', 67.4, 'Summary and commentary for each episode by the main characters.', 17, True, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6725, 'Pink Lady Monogatari: Eikou no Tenshi-tachi', 1978, 33, 'TV', 96.3, 'Based on the real life-story of Pink Lady, a female pop duo that rose to superstardom in the mid-1970s.  (Source: ANN)', 98, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6726, 'Sabaku no Takara no Shiro', 2002, 1, 'OVA', 80.9, 'Yutas teacher gives him a photo of the desert near the Dunhuang Caves in China. As Yuta daydreams about finding the treasures of the caves, he is miraculously transported there. However, the treasures he discovers are way beyond what he had imagined.', 11, True, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6727, 'The iDOLM@STER Movie: Kagayaki no Mukougawa e!', 2014, 1, 'Movie', 91.9, 'The idols of 765 Production continue on their neverending journey—towards a new stage, towards a bright and shiny future!  The girls and their producer have gone through thick and thin, and have stood face to face with all kinds of difficulties.  Its time again for the girls to foster their friendship, and through great discipline, they step forward to their starry future.  (Source: Official website)', 77, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6728, 'Kyojin no Hoshi (Movie)', 1982, 1, 'Movie', 83.3, 'Based on the novel Kyojin no Hoshi by Kajiwara Ikki (Story), Kawasaki Noboru (Art), published in the year 1982.', 44, True, 8);
