INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6740, 'Kiki to Lala no Hansel to Gretel', 1993, 1, 'OVA', 87.6, 'A continuation of Kiki and Lalas adventures. Loosely based on the fairy tale Hansel and Gretel by Grimm Brothers.', 10, True, 20);
