INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (6922, 'Pro Yakyuu wo 10-bai Tanoshiku Miru Houhou', 1983, 1, 'Movie', 66.0, 'Based on the two books of career reminiscences by real-life Hanshin Tigers baseball star Takenori Emoto.  Mix of live action and animation to tell humorous anecdotes from professional baseball (nine short tales in nine innings).   (Source: AniDB)', 95, True, 82);
