INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7009, 'Alice Tantei Kyoku', 1995, 56, 'TV', 65.8, 'No description available for this anime.', 67, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7010, 'Ano Yama ni Noborou yo', 2003, 1, 'OVA', 96.7, 'Three friends find themselves on an adventure to Rainbow Mountain, a magical place where the first rainbow is said to have been created. However, getting to the top of the mountain requires courage and perseverance in the face of many challenges.', 67, False, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7011, 'Hello Kitty no Kieta Santa-san no Okurimono', 2004, 1, 'OVA', 77.5, 'Kitty and Mimmy are preparing for Santas visit by making him cookies.', 96, True, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7012, 'Hello Kitty no Shiawase no Tulip', 1995, 1, 'Special', 68.0, 'Kitty falls ill and has to stay home with her mom while her sister and Papa and classmates get to go on a field-trip. They encounter a motorcycle riding man who helps out both Mimmy and Kitty. Everyone seems to think hes a bad person but he just has a sad past. Kitty and Mama hear out his story and come to find his lover where she planted many tulips, his favourite flower, while he was away for a long time.', 90, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7013, 'Hello Kitty: Mahou no Mori no Ohimesama', 1991, 1, 'Movie', 74.8, 'Kitty and Mimmy have to save a kingdom and break a magical spell on a sleeping princess.', 12, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7014, 'Hello Kitty no Shiawase no Aoi Hotaru', 1993, 1, 'OVA', 72.0, 'A trip to camping with Kitty and her class.', 85, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7015, 'Rinkaku', 2012, 1, 'Music', 75.3, 'Following the release of their 8th album DUM SPIRO SPERO, Japanese rock band Dir en Grey went into hiatus following a vigorous touring schedule in Japan and abroad, a year and a half later returning with their single RINKAKU released on December 19th, 2012.  Once again animator Keita Kurosaka was enlisted to create a hand drawn music video, that in many regards is much less shocking and grotesque than the bands previous collaboration with Kurosaka, the infamous Agitated Screams of Maggots music video.', 47, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7016, 'Hakuouki: Reimeiroku OVA', 2013, 2, 'OVA', 86.1, '2 eps. Tokuten that were released in a Tokuten Disc for those who purchased all 6 volumes of Hakuouki Reimeiroku OVAs.  Including: 1. Natsu no Wazurai (夏のわずらい)  2. Shinpachi Nagakura Saikyou Densetsu (永倉新八最強伝説)', 45, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7017, 'PES: Peace Eco Smile - Drive your Heart', 2012, 1, 'ONA', 94.5, 'Special spin-off episode that aired between episodes three and four of the original PES series. Is also an ad to Toyotas new Vios vehicle.', 38, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7018, 'Ninja Hattori-kun (2012)', 2012, 52, 'TV', 94.7, 'Remake of the Ninja Hattori-kun series.', 95, False, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7019, 'Natsume Yuujinchou: Nyanko-sensei to Hajimete no Otsukai', 2013, 1, 'Special', 82.4, 'Madara, nicknamed Nyanko-sensei, runs into two young children when he gets separated from his temporary owner Takashi Natsume. Unequipped to handle kids, Nyanko-sensei tries to wriggle his way out; but fearing for their safety around the ravenous forest youkai, he decides to escort the siblings to safety. However, even for an all-powerful youkai such as Nyanko-sensei, dealing with the playful and overly curious nature of children can prove to be an exhausting challenge.', 42, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7020, 'Fate/kaleid liner Prisma☆Illya: Undoukai de Dance!', 2014, 1, 'OVA', 99.9, 'Tatsuko of class 5-1 is really excited about the upcoming school sports festival, her proposal for a new Eel Scooping event is less than enthusiastically received though, especially by Suzuka. Illya mentions the main event dance to Miyu, and as teacher Taiga Fujimura points out, it entails a huge reward, but will require quite a bit of practice.  And so the close friends: sarcastic Nanaki, level-headed Suzuka, excitable Tatsuko, energetic Illya, shy Mimi, and reserved but athletic Miyu are off to win the dance event for the honour of their class and for Fujimura, who seems to have some saucy bet going on that she most definitely needs to win, or so the girls misunderstand.  (Source: AniDB)', 39, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7021, 'Ore no Imouto ga Konnani Kawaii Wake ga Nai. Specials', 2013, 3, 'ONA', 98.5, 'Episodes 14–16 of OreImo 2 which finish adapting the OreImo novels.', 48, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7022, 'Code Geass: Hangyaku no Lelouch - Kiseki no Birthday Omake Flash', 2010, 1, 'Special', 96.9, 'From the Code Geass: Lelouch of the Rebellion - Kiseki no Birthday DVD/Blu-ray. It is different from the 9 Omake Flash specials included in the Code Geass R2 DVD/Blu-ray.', 62, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7023, 'Aoki Hagane no Arpeggio: Ars Nova', 2013, 12, 'TV', 63.9, 'In the year 2039, the drastic effects of global warming have caused sea levels to rise, resulting in major loss of land. To ensure humanity learns its lesson, a fleet of powerful warships equipped with advanced weaponry emerges, causing overwhelming defeat for naval forces throughout the world. Calling themselves the Fleet of Fog, each ship has a Mental Model, a humanoid avatar which represents the ships heart, its Union Core. Each model has a different personality but all follow an unknown authority known as the Admiralty Code, who have implemented a blockade to prevent humans from traveling across the sea.   Seventeen years after the blockade, Gunzou Chihaya, a National Marine Academy alumnus, stumbles upon I-401 and its Mental Model, Iona, who sides with mankind for unknown reasons. Utilizing this newfound hope of achieving peace for humanity, Gunzou and his friends form a group of privateers, known as the Blue Steel, as they set out on a dangerous journey.', 25, False, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7024, 'Nisekoi', 2014, 20, 'TV', 99.4, 'Raku Ichijou, a first-year student at Bonyari High School, is the sole heir to an intimidating yakuza family. Ten years ago, Raku made a promise to his childhood friend. Now, all he has to go on is a pendant with a lock, which can only be unlocked with the key which the girl took with her when they parted.  Now, years later, Raku has grown into a typical teenager, and all he wants is to remain as uninvolved in his yakuza background as possible while spending his school days alongside his middle school crush Kosaki Onodera. However, when the American Bee Hive Gang invades his familys turf, Rakus idyllic romantic dreams are sent for a toss as he is dragged into a frustrating conflict: Raku is to pretend that he is in a romantic relationship with Chitoge Kirisaki, the beautiful daughter of the Bee Hives chief, so as to reduce the friction between the two groups. Unfortunately, reality could not be farther from this whopping lie—Raku and Chitoge fall in hate at first sight, as the girl is convinced he is a pathetic pushover, and in Rakus eyes, Chitoge is about as attractive as a savage gorilla.   Nisekoi follows the daily antics of this mismatched couple who have been forced to get along for the sake of maintaining the citys peace. With many more girls popping up his life, all involved with Rakus past somehow, his search for the girl who holds his heart and his promise leads him in more unexpected directions than he expects.', 104, False, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7025, 'Tensai Eri-chan Kingyo wo Tabeta', 1997, 1, 'Movie', 67.2, 'Based on a same name childrens fantasy picture book by Takeshita Ryuunosuke.', 80, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7026, 'The Midnight★Animal', 2013, 12, 'ONA', 75.1, 'The story is set in Savannahs 2nd district, where diva-like animals gather in the dead of night to wax poetic about topics that transcend gender.  (Source: ANN)', 21, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7027, 'Hakken Taiken Daisuki! Shimajirou', 2008, 101, 'TV', 74.0, 'Second season of the Shimajirou childrens television series.', 40, True, 67);
