INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7032, 'Yuuto-kun ga Iku', 2013, 26, 'TV', 82.7, 'No description available for this anime.', 33, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7033, 'Koukaku Kidoutai Arise: Another Mission', 2013, 1, 'Special', 98.8, 'The premise of the story: Snatch the rebel elements secret data using the Surface! There is a leak saying that the giant coporation Ishimiya Industry will commit an act of international terrorism, and Motoko Kusanagi and the Armored Riot Police head out to seize the plug data!  (Source: ANN)  A short animation for promoting Microsofts Surface tablet in Japan.', 110, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7034, 'DS Anime Soushuuhen 98', 1998, 1, 'OVA', 61.0, 'A compilation release featuring 17 short skits about the characters from Compiles video game series. Some of these shorts were also bundled with DiscStation volumes 13-16, a magazine by Compile.', 14, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7035, 'Takanashi Rikka Kai: Chuunibyou demo Koi ga Shitai! Movie', 2013, 1, 'Movie', 61.7, 'Summary of the first season of the show, as seen from Rikkas perspective with new elements.', 110, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7036, 'Wake Up, Girls!', 2014, 12, 'TV', 90.9, 'The gateway to Idol stardom might have opened for the newly formed singing group Wake Up, Girls, but the path to fame is full of perils and pitfalls. And for Mayu, Airi, Minami, Yoshino, Nanami, Kaya and Miyu, its going to be especially difficult knowing who to trust, as their manager Matsudas lack of experience could give other, less scrupulous, individuals a chance to take advantage.  Thats a situation that quickly comes to a head when Green Leaves president suddenly disappears with most of the money, and things only get worse when the replacement producer seems more interested in getting the girls into revealing swimsuits than promoting their music.  As malicious gossip begins to surface regarding Mayus past membership in a rival group, and internal tensions begin to tear the team apart, theyll need more than just ambition to survive. Singing may be a business, but friendship and a love of music is what will keep everything together.  (Source: Sentai Filmworks)', 20, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7037, 'Yuyushiki: Nyanyashiki', 2013, 6, 'Special', 93.1, 'Specials bundled with the BD/DVD volumes.', 34, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7038, 'Tobe! Pegasus Kokoro no Goal ni Shoot', 1995, 1, 'Movie', 87.6, 'The movie is about the soccer team Pegasus created from the visually impaired children studying in the Chiba Prefectural School for the Blind.  (Source: allcinema)', 68, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7039, 'Kaitou Jigoma Ongaku-hen', 1988, 1, 'Movie', 74.0, 'Animated musical by Makoto Wada.', 75, False, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7040, 'UFO Nitsukamatta Kodomo-tachi', 1991, 1, 'OVA', 93.0, 'Educational video that teaches kids about the value of money and the consequences of overconsumption.  *Part of the series of films produced with cooperation of: Japans Central Council for Financial Services Information and Bank of Japan Public Relations Department.', 44, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7041, 'Judo-bu Monogatari', 1991, 2, 'OVA', 83.2, 'Based on the same name manga by Kobayashi Makoto.', 33, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7042, 'Future Card Buddyfight', 2014, 64, 'TV', 89.3, 'An adaptation of the Future Card Buddyfight card game.  Future Card Buddyfight takes place in a more futuristic version of today. The card game connects to a parallel universe through special cards (Buddy Rare Cards) that act as portals. They bring monsters to Earth in order for them to become buddies with humans. Through friendship and courage, they take on and fight challenges, known as Buddyfights, where people of all ages have friendly non-hurtful competitions. The main character, Gaou Mikado has just started Buddyfighting. As the story progresses, Buddyfights are seeming to become a little too real...', 14, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7043, 'Okane wa Mawaru: Kurashi to Kinyuu', 1993, 1, 'OVA', 80.0, 'Educational video that teaches youth about the value of money and importance of financial planning.  *Part of the series of films produced with cooperation of: Japans Central Council for Financial Services Information and Bank of Japan Public Relations Department.', 111, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7044, 'Hyakumannen Attara, Dousuru?', 1999, 1, 'OVA', 98.3, 'Educational video that teaches teenagers about value of money, basic banking principles, use of credit cards and other ways of financial interaction in the society.  *Part of the series of films produced with cooperation of: Japans Central Council for Financial Services Information and Bank of Japan Public Relations Department.', 61, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7045, 'Hoshigari Hime no Bouken', 1992, 1, 'OVA', 88.6, 'A fairy-tale telling the story of a wealthy, spoiled princess Katharine who got changed into normal girl by a Witch and now have to live among common village folks adapting to their modest lifestyle.  *Part of the series of films produced with cooperation of: Japans Central Council for Financial Services Information and Bank of Japan Public Relations Department.', 41, True, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7046, 'Weekender Girl', 2012, 1, 'Music', 74.0, 'Music video for the song Weekender Girl by kz (livetune) and Hachioji P under the label Toys Factory.  *Part of the split single release which includes the songs Weekender Girl for the game Hatsune Miku - Project DIVA -f. and fake doll. Cover artwork is illustrated by TNSK.', 111, True, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7047, 'Kaiketsu Tamagon', 1972, 195, 'TV', 66.6, 'Tamagon is a cute monster who is fond of eggs. He acts as a counselor to those in trouble, asking only eggs in payment. He goes to work as soon as he has eaten his fee. However, despite his schemes, his service usually ends in total failure and he winds up being chased by his irate clients. Short as it is, this program is full of laughs and lively humour.   (Source: AniDB)', 89, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7048, 'Pokemon: Mewtwo - Kakusei e no Prologue', 2013, 1, 'Special', 93.2, 'The original story is set before Mewtwo meets Satoshi and his friends in the upcoming films storyline. It will focus on Mewtwos history, goals, and how it became the strongest Pokémon.', 109, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7049, 'Fate/kaleid liner Prisma☆Illya Specials', 2013, 5, 'Special', 94.5, 'Specials bundled with each of all five Blu-ray/DVD volumes.', 99, True, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7050, 'Love Live! School Idol Project 2nd Season', 2014, 13, 'TV', 62.5, 'Otonokizaka High School has been saved! Despite having to withdraw from the Love Live!, the efforts of μs were able to garner enough interest in their school to prevent it from being shut down. What more, following the conclusion of the first, a second Love Live! is announced, this time on an even larger stage than before. Given a chance for redemption, the nine girls come together once more to sing their hearts out and claim victory.   However, with the end of the school year approaching, the graduation of the third years draws near. As they attempt to reach the top of the Love Live!, they must also consider their future and choose what path the group will take. Though the question of whether to continue without the third years or disband weighs heavily on the minds of its members, μs must quickly come to an answer with graduation right around the corner.   Love Live! School Idol Project 2nd Season continues the story of the girls as they laugh, cry, sing, and dance in their journey to determine the future of their group and conquer the Love Live! in their last chance to win with all nine girls together.', 26, True, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7051, 'Giovanni no Shima', 2014, 1, 'Movie', 70.7, 'In the aftermath of the most devastating conflict mankind had ever experienced, the tiny island of Shikotan became part of the Sakhalin Oblast... and on the unhealed border in this remote corner of the world, friendship among children from two different countries timidly blossomed, striving to overcome language barriers and the waves of history. Inspired by true events.  On August 15th, they told us we had lost the war. At that time, we did not really understand. Then one day, everything changed. Many soldiers, wearing uniforms we had never seen before, arrived on the island. That was the day I met Tanya.  (Source: Production I.G)', 15, False, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7052, 'Toaru Hikuushi e no Koiuta', 2014, 13, 'TV', 82.9, 'In order to uncover the end of the sky, as spoken of in ancient mythology, Kal-el Albus is sent to Isla, an island in the sky. There he attends Cadoques Highs Aerial Division, where he enjoys a carefree life with his schoolmates. That is...until a surprise attack by the air tribe drags Isla into a bloody war.  (Source: NIS America)', 39, True, 92);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7053, 'Doctor Chichibuyama', 1988, 2, 'TV', 80.6, 'Based on the manga by Tanaka Keiichi.  Dr. Chichibuyama is the perverse head of a hospital way out in the mountains and terrorises patients with the help of his lover and a sexy young nurse.  (Source: AniDB)', 116, False, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7054, 'One Piece: Episode of Merry - Mou Hitori no Nakama no Monogatari', 2013, 1, 'Special', 77.1, 'After Brook questions the origin of the Mini Merry name, Usopp and Chopper Tony Tony recall the adventures of the Straw Hat Crews beloved ship, friend, and crew member—the Going Merry. Ussop abandons the crew for a fight over the Going Merry while Robin Nico leaves with the governments top assassin group, CP9. In order to bring the crew back together, Monkey D. Luffy and the remaining Straw Hats follow Robin to rescue her from the claws of the World Government.', 40, False, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7055, 'Mogura no Adventure', 1958, 1, 'Special', 64.8, 'A humorous story of a mole named Kuro-chan who embarks on a space voyage in his dreams.  (Source: ANN)', 86, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7056, 'Turning Girls', 2013, 7, 'ONA', 96.5, 'On the surface, Nana, Kai, and Chiwa seem like typical office workers, but in reality, their everyday lives are spiced up by the bizarre situations they constantly encounter. Joined by their friend and self-proclaimed idol Kaeru, the trio attempts to go through their daily routine while facing the difficulties of being an adult.', 31, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7057, 'Kuroi Ame ni Utarete', 1984, 1, 'Movie', 88.8, 'Black rain, which contained plenty of radioactivity, poured into Hiroshima just after the bombing. The effects of the death ash extend to the second and third generations and still cast the shadow of death behind the living witnesses.  (Source: Official Site)', 119, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7058, 'EDEN', 2011, 1, 'Music', 86.2, 'Music video for the track EDEN by ATOLS from the album MUSIC OF SCIENCE.', 108, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7059, 'Walkure Romanze', 2013, 12, 'TV', 89.2, 'Taking place at Winford Academy located in an old town called Helens Hill, the story is all about knights and the sport of jousting. At this school, students learn how to become knights, ride horses and joust properly. The main character is a young man named Takahiro Mizuno who was training to become a knight and jouster but after suffering an injury he dropped out of the knight program and joined the begleiter (assistant) program instead. Due to his animal handling skills and former experience as a jouster, this makes him a hot commodity. Multiple beautiful girls in the school want him to become their personal begleiter, though Takahiro always refuses their offers.  One day a bizarre accident causes his friend, Mio Kisaski, to be challenged to a jousting duel despite her not actually being a knight. Takahiro agrees to become her temporary begleiter, but that ends up only being the beginning of their partnership as she enrolls in the annual tournament.', 70, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7060, 'Youkai Watch', 2014, 214, 'TV', 79.4, 'Primary school student Keita Amanos curiosity is as innocent as any other childs his age. But when one day he decides to venture deeper into the forest, he encounters a small and mysterious capsule. Out from its depths comes Whisper. After 190 years of imprisonment, this ghost-like creature is glad that someone has been kind enough to set him free. He decides to reward Keita by becoming his guardian against supernatural forces. Whisper is one of many Youkai that exist in the world, and provides Keita with a special Youkai Watch, which enables him to see and interact with all the other Youkai.  Youkai Watch follows Keita, Whisper and the cat spirit Jibanyan as they encounter Youkai, befriend them, fix all the trouble that they so often cause, and, with the help of the watch, use the powers of previously encountered Youkai to aid them. Young Keita may have been just an ordinary primary school student when he first encountered the Youkai, but the many adventures that follow his discovery provide him with invaluable experiences and precious life lessons that help him grow.', 66, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7061, 'Genshiken Nidaime OVA', 2013, 1, 'OVA', 72.3, 'Bundled with the limited edition of the 15th volume of the manga.', 12, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7062, 'Date A Live II', 2014, 10, 'TV', 93.1, 'Spirits are otherworldly entities with immense power, capable of creating spatial quakes whenever they appear. One way of dealing with them is through brute force and killing them... or making them fall in love and sealing their powers.   Having sealed three Spirits, Shidou Itsuka continues his mission with Ratatoskr in locating more spirits and dating them, to ensure the worlds safety from further destruction. However, this time around, their problems will not be limited to Spirits as a more imposing threat seems to have noticed their activities.', 10, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7063, 'Fate/Zero Cafe', 2013, 2, 'Movie', 76.4, 'The story re-imagines the cast of the Fate/Zero as cute super-deformed characters who open a café, led by Saber as the manager.  (Source: ANN)', 26, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7064, 'Senbon Matsubara', 1992, 1, 'Movie', 92.6, 'After suffering severe floods in 1753, the people of Senbon Matsubara in Shizuoka cooperate on flood prevention around the Kiso, Nagara, and Yuhi rivers. The people of Satsuma (Kumamoto Prefecture) endure great hardships after being forced to undertake the work by the central government, a subtle indication of the bad feeling that would foment into open rebellion the following century.  (Source: AnimeVice)', 59, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7065, 'Go! Go! Kadendanshi', 2013, 78, 'ONA', 65.9, 'No description available for this anime.', 40, True, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7066, 'Sanjougattai Transformers Go!', 2013, 10, 'OVA', 90.2, 'Bundled on DVDs with Shogakukans Terebi-kun (TV-kun) magazine and Kodanshas TV Magazine.  (Source: ANN)', 70, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7067, 'Chiisana Love Letter: Mariko to Nemunoki no Kodomo-tachi', 1981, 1, 'Special', 96.2, 'A follow-up to the same studios Helen Keller anime, A Little Love Letter kept the handicapped theme but focused on a wholly Japanese story. During the 1970s, actress Mariko Miyagi became heavily involved in the Silk Tree Academy (Nemunoki Gakuen), a rehabilitation center for disabled children. She appeared in several live-action films to promote the project, including The Silk Tree Ballad, Mariko-Mother, and Children Drawing Rainbows. This anime charts the 14-year period of Miyagis stewardship of the academy and her relationships with several of the children. Divided into four seasonal chapters, the film uses highly realistic character designs based on the actual people involved and features storyboarding from the versatile Star Blazers-director Noboru Ishiguro.  (Source: AnimeVice)', 80, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7068, 'HORIZON feat. Hatsune Miku', 2013, 1, 'Music', 82.8, 'Music video for HORIZON feat. Hatsune Miku by Hachioji-P.', 44, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7069, 'Fake Doll', 2012, 1, 'Music', 75.1, 'Music Video by Hachioji-P featuring Hatsune Miku.', 96, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7070, 'Koukaku Kidoutai Arise: Ghost in the Shell - Border:2 Ghost Whispers', 2013, 1, 'Movie', 89.9, 'Second movie of Ghost in the Shell: Arise.  Freed of her responsibilities with the 501 Organization, Motoko Kusanagi must now learn how to take orders from Aramaki. Someone hacks the Logicomas, and Batou enlists the help of former army intelligence officer Ishikawa and former air artillery expert Borma. Kusanagi also seeks to enlist ace sniper Saito and undercover cop Paz into the new Public Security Section 9. The two groups rival each other in a case involving a man who receives false memories of a refugee transport operation.  (Source: Wikipedia)', 51, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7071, 'Koukaku Kidoutai Arise: Ghost in the Shell - Border:3 Ghost Tears', 2014, 1, 'Movie', 81.3, 'Third movie of Ghost in the Shell: Arise.  Motoko and Batou work to try to stop a terrorist organization whose symbol is the Scylla. Meanwhile, Togusa investigates a murder of a man who possessed a prosthetic leg manufactured by the Mermaids Leg corporation.  (Source: Wikipedia)', 101, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7072, 'Koukaku Kidoutai Arise: Ghost in the Shell - Border:4 Ghost Stands Alone', 2014, 1, 'Movie', 95.0, 'The story of this fourth installment takes place amidst signs of postwar reconstruction in the winter of 2028. Tensions are rising in New Port City as demonstrations are held concerning the interests of foreign cartels. This leads to a shooting incident involving riot police. It all started with a cyberbrain infection released by the terrorist Fire Starter. An independent offensive unit led by Motoko Kusanagi entrusts the suppression of the situation to their ghosts and aims for their own justice. Below the surface of the incident, lies the tin girl Emma and the scarecrow man Burinda Junior. As Kusanagi deals with the incident, she draws near to what those two ghosts were seeking.  (Source: ANN)', 54, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7073, 'Maji de Otaku na English! Ribbon-chan: Eigo de Tatakau Mahou Shoujo - The TV', 2013, 10, 'TV', 71.8, 'The story centers around Ribbon-chan, a girl struggling with English who becomes a magical girl when she makes a contract with a self-described familiar named Toner. She aims to become a super heroine who can fill the Tokyo Dome arena with her singing and dancing.  (Source: ANN)', 98, False, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7074, 'Devour Dinner', 2008, 1, 'Movie', 61.2, 'Various scenes of predation.', 66, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7075, 'Suisei no Gargantia Specials', 2013, 2, 'Special', 73.8, 'Episodes 14 and 15, released with the first and third BD/DVD volumes.', 85, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7076, 'Lost Utopia', 2007, 1, 'Movie', 60.6, 'The story of Adam and Eve with jazzy music. Short experimental animation without words.', 30, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7077, 'And And', 2011, 1, 'Music', 79.3, 'Toru Matsumotos official music video with Mirai Mizues interesting hypnotical-rhythmical animation.', 41, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7078, 'Modern No.2', 2011, 1, 'Movie', 80.5, 'Minimalistic abstract hand made animation from the award winning Mirai Mizue.', 101, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7079, 'Ore no Nounai Sentakushi ga, Gakuen Love Comedy wo Zenryoku de Jama Shiteiru', 2013, 10, 'TV', 92.3, 'For Kanade Amakusa, life as a high schooler should have been normal, and it would have been—if he wasnt living with the most ridiculous curse imaginable. Absolute Choice, a system forced upon him by a self-proclaimed god, randomly presents a mental selection of actions that he must act out based on his choice. To add to his dilemma, it tends to occur in the most public of places, and his options never seem to deviate from the rude and crude in nature.  As a result, the helpless boy stresses through each day, fumbling to repair his already tarnished reputation while desperately praying to avoid the next spontaneous episode of Absolute Choice. To his dismay, the one in charge is always one step ahead of him and proceeds to not-so-subtly choice him into the lives of several girls at his school. Just when Kanades school life cant seem to be doomed any further, a decision that he reluctantly selects on the way home sends a beautiful girl crashing down from the sky, along with the promise of more hysterically hellish choices.', 107, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7080, 'Jam', 2009, 1, 'Music', 68.7, 'This film is based on a very simple idea: the increasingly varied the sounds, the greater is the number of creatures... My intention in this film was to fill the screen with chaotic movements.  (Source: Mirai Mizue)', 114, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7081, 'Around', 2007, 1, 'Movie', 80.7, 'A multiple award-winning, dynamic and powerful short animation about a day of a guy. About perspectives and similarities. About nearby and distant, small and large. Around our world.', 62, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7082, 'Dance, Dance, Dance', 2012, 1, 'Music', 67.5, 'An official music video of People In The Box.', 57, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7083, 'Nimrod', 2011, 1, 'Music', 92.4, 'An official music video of People In The Box.', 55, False, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7084, 'Kyuushigai', 2010, 1, 'Music', 89.0, 'An official People In The Box music video.', 71, True, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7085, 'Uta no☆Prince-sama♪ Maji Love 2000%: Shining Star Xmas', 2013, 1, 'Special', 61.3, 'Unaired episode included in the seventh Blu-ray and DVD volumes.  Haruka is busy working at the agency so she cant help the idols with the preparations for the Christmas Party held by Shining Agency. A lot of memories and information are revealed while Starish is preparing for the party.', 73, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7086, 'Hyakka Ryouran: Samurai Bride Specials', 2013, 6, 'Special', 75.9, 'Specials included on DVDs and Blu-rays.', 33, False, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7087, 'Megane-bu!', 2013, 12, 'TV', 82.4, 'At Himaraya Third Technical School, five bespectacled members of the Glasses club are crazy about eyewear. Their leader, Akira Souma, founded the club to develop the X-ray glasses of his dreams, but their research has been slow in between getting into quirky escapades and fighting off student body president William Satous attempts to further cut their tight club funding. With unbounded youthful passion, these friends set their minds on making their project a resounding success.', 92, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7088, 'Gintama x Mameshiba', 2013, 6, 'Special', 77.1, 'Gintama x Mameshiba aired as a commercial to promote the Gintama: Kanketsu-hen - Yorozuya yo Eien Nare movie.  Gintoki, Kagura, and Shipachi have turned into weird living creatures, parodying the short kids anime Mameshiba that features sword bean-dog hybrid creatures.', 29, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7089, 'Gekitou! Crush Gear Turbo: Kaizabaan no Chousen', 2002, 1, 'Movie', 93.8, 'The very first Gear even made in the world is stolen. The gear, named Kaiservern, beats the prize winners of the Australia convention one after another. Kouya and Manganji, which won a prize in the Asia Convention, become targets too. When the unidentified gear fighter who handles Kaiservern appears in front of Kouya and Manganji, the two boys decide to fight together to win victory over their enemy.  (Source: Sunrise)', 38, True, 9);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7090, 'Pony Metal U-GAIM Promotion Film', 1986, 1, 'Special', 70.2, 'This is a short little pilot film inserting Yuu Morisawa, the heroine of Creamy Mami, into the mecha world of Heavy Metal L-Gaim.   After Yuu Morisawa is killed in a car accident, she is rebuilt as Pony Metal U-GAIM in a scenario à la Astroboy. Put to a high-energy Japanese pop song, this experimental mishmash of genres was the brainchild of studio Anime R.   The series was never made for copyright reasons, and this pilot film is all that remains alongside a handful of merchandise.', 36, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7091, 'Shingeki no Kyojin: Ano Hi Kara', 2013, 1, 'Special', 98.3, 'Recap of the events in Shingeki no Kyojin that happened prior to episode 14.', 64, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7092, 'Reunion (Music)', 2013, 1, 'Music', 62.3, 'Music video/PV for ClariS single reunion. The song was used as the opening theme for Ore no Imoto ga Konna ni Kawaii Wake ga nai second season. Released on April 17, 2013, and was also included in the second story album.', 42, False, 12);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7093, 'Pokemon XY', 2013, 93, 'TV', 74.4, 'Satoshi and Pikachu have arrived in Miare City of the illustrious Kalos region to capture more Pokémon and continue their journey toward becoming the very best. Meanwhile, a genius inventor named Citron and his little sister Eureka wander the city when they run into Satoshi who quickly challenges them to a battle. However, they are soon caught up in a dangerous incident when Team Rocket, following Satoshi into Kalos, cause a Gaburias to rampage through the city.  Far away in the quiet Asame Town, a young girl named Serena slogs through daily Sihorn riding practice at the behest of her mother, a professional Sihorn racer. After practice, she sees the events unfolding in Miare City on television where she recognizes a boy from her childhood. Having left a significant impact on her life, the sight of him stirs in her a desire to meet him again; and so, Serena sets off to Miare City, determined to find the boy from her past.  Pokemon XY follows the group as they travel throughout Kalos in pursuit of their ambitions—Satoshi challenging Pokémon gyms, Citron learning from Satoshi, and Serena searching for what exactly her dream is. Along the way, they meet new friends, face new rivals, and continue to thwart Team Rockets schemes, all the while discovering a little about the mysteries of mega evolution.', 33, True, 13);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7094, 'Ketsuekigata-kun! Featuring Yuri & Nasuno', 2013, 1, 'Special', 94.6, 'An episode of Ketsuekigata-kun that acts as an advertisment for Ketsuekigata-kun and Teekyuu DVDs aired in Ketsuekigata-kuns regular time slot a week after episode 12.', 62, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7095, 'Nyuru Nyuru!! Kakusen-kun', 2013, 25, 'TV', 74.6, 'The anime revolves around little creatures called Kakusen who live in the skin pores of humans.  (Source: ANN)', 36, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7096, 'Turuturutu Narongi', 2004, 52, 'TV', 79.1, 'Somewhere in this world, there is a town named Lala in a forest called Lulu. This is the home of Nalong and many other furry little creatures. Nalong lives with his father and 10 brothers, and attends elementary school. His friends are an otter named Ukkya, an ostrich named Tajori, and the Mandu brothers, who were accidentally made by the famous inventor Professor Penguil.  (Source: Wikipedia)', 63, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7097, 'Pupa', 2014, 12, 'TV', 75.0, 'Abandoned by their abusive parents and with only each other to depend on, siblings Utsutsu and Yume Hasegawa find themselves led astray by beautiful red butterflies that have appeared in their world. Unbeknownst to them, these crimson winged heralds trumpet the beginning of a cannibalistic nightmare—a mysterious virus known as Pupa is about to hatch.   After succumbing to the full effects of Pupa, Yume undergoes a grotesque metamorphosis into a monstrous creature with an insatiable desire for flesh; Utsutsu, on the other hand, is only partially affected, gaining remarkable regenerative powers instead. Reaffirming the resolve to keep the promise he made to himself years ago, Utsutsu is willing to sacrifice everything in order to always be there for his precious little sister.  Pupa tells the story of a loving brothers desperate struggles to save his sister while protecting the world from her uncontrollable hunger.', 48, True, 17);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7098, 'Gundam Build Fighters', 2013, 25, 'TV', 79.4, 'Though Gundam Plastic Models, better known as Gunpla, exploded in popularity with the release of the anime series Mobile Suit Gundam, their presence faded before resurging with a new purpose. Through the power of Plavsky particles, fans are now able to pit their Gunpla against others in a virtual reality-style battle with the best competing at the annual Gunpla World Tournament.   Sei Iori, whose father was a once finalist in the competition, dreams of one day conquering the contest himself. However, while Sei is an expert Gunpla builder, he lacks the prowess to effectively fight his creations during actual battle. In comes Reiji, a mysterious boy who is curiously ignorant of society but quickly demonstrates to Sei tremendous ability in Gunpla battles. The two boys decide to combine their strengths in order to sweep the Gunpla World Tournament and take the Gunpla world by storm.', 47, True, 18);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7099, 'Kwaegeol Longman Narongi', 2006, 52, 'TV', 74.9, 'Someone is out to conquer Lulu forest and its up to the Nalong and his friends to to figure out who and stop them! When Nalongs girlfriend Ukkya is taken by force and Longman is zapped by a laser beam resulting in an unfavorable transformation--Nalong has more on his plate than he can handle!', 54, True, 19);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7100, 'Momoya x Peeping Life: Go en desu yo!', 2013, 4, 'ONA', 96.8, 'This is a sketch drama consisting of four episodes on dating in collaboration with the leading food company Momoya.', 93, False, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7101, 'Nijiiro☆Prism Girl', 2013, 4, 'OVA', 63.6, 'The beautiful and tall Kohinata Nijika, a 6th grade kid who doesnt look her age and daughter of an office chief of a TV station, avoids the entertainment world since her mom, a legendary actress, died from a sickness. Hiding the truth about her family, Nijika keeps another secret. The fact that shes living with the prince-like actor, Ichinose Touya, may create a ruckus if it is discovered.  Running for another errand, Nijika, together with her pet Kapitama-kun, coincidentally run into a drama set thats lacking an actress due to food poisoning. She volunteers for the role and...', 102, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7102, 'Gin no Saji 2nd Season', 2014, 11, 'TV', 97.4, 'Now accustomed to his life at Ooezo Agricultural High School, Yuugo Hachiken explores the deeper aspects of what school life really means. As Hachiken learns more about himself and earns the skills necessary for his everyday tasks, he is even offered the position of the Equestrian Clubs vice-president. The new semester brings a variety of agricultural dilemmas and personal conflicts, but, nevertheless, Hachiken perseveres in order to discover his dream and continue working together with his friends.', 20, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7103, 'Samurai Flamenco', 2013, 22, 'TV', 91.9, 'A hero will never give up, never hide, never be defeated and never accept evil!  Firmly believing these words, Masayoshi Hazama has been obsessed with superhero shows since childhood. By day, he earns his living as a famous model, and by night, he becomes the gallant hero Samurai Flamenco. Armed with only his superhero costume, he seeks to bring justice to the city and faces anybody who tries to break the law—even rebellious juveniles and people who litter on the street.  Masayoshis heroic antics later catch the attention of the public, leading to the fateful discovery of his identity by policeman Hidenori Gotou. Although initially telling Masayoshi to leave the crime-busting activities to the police, Gotou ends up joining him in his antics. However, things soon escalate from preventing littering and petty thefts to bizarre adventures that involve even the fate of the world. Together with their newfound comrades, Masayoshi and Gotou embark on a battle with the world and themselves in order to find the true meaning of being a hero—with or without superpowers.', 80, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7104, 'Galilei Donna', 2013, 11, 'TV', 87.8, 'Three sisters, Hozuki, Kazuki, and Hazuki, are descendants of Galileo and have completely different personalities and tastes; they never meet eye-to-eye. One day, the girls are suddenly attacked by a mysterious organization. The organization was after the Galileo Tesoro which Galileo Galilei was said to have discovered. Still unaware of what was going on, the sisters escape on the airship they built after the sudden attack. But it wont be so easy for these three sisters to help each other out in a pinch when theyre constantly at odds with each other. What is the Tesoro, and what is the organization after? And what about the relationship between the sisters? Its a threesome of cute girls, action, and mystery!  (Source: Fuji Creative)', 51, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7105, 'Outbreak Company', 2013, 12, 'TV', 85.9, 'Shinichi Kanou is a shut-in otaku with a vast knowledge of anime, manga, and video games. One day, after applying for a job in hopes of escaping his secluded lifestyle, he is kidnapped and transported to the Eldant Empire—a fantasy world filled with elves, dragons, and dwarves. Trapped in this strange land, Shinichi is given an unlikely task by the Japanese government: to spread otaku culture across the realm by becoming an Otaku Missionary.  To accomplish his mission, Shinichi has the full support of the Japanese government, as well as the half-elf maid Myucel and Princess Petralka of the Eldant Empire. Together with this ragtag bunch, he will overcome the obstacles of politics, social classes, and ethnic discrimination to promote the ways of the otaku in this holy land.', 71, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7106, 'Yami Shibai', 2013, 13, 'TV', 91.0, 'The mysterious, yellow-masked Storyteller is a man whose true name and origin are both unknown. He appears at dusk where children gather and recites sinister tales based on Japanese urban legends, to which his young audience eerily intakes. However, the Storyteller is no ordinary teller of tales. He incorporates a kamishibai, a traditional paper-scrolling device, to add visuals to his already demented narration.  A series of short horror stories, Yami Shibai begins with a bachelor who, after moving into a new apartment, immediately starts sensing a malevolent glare being pressed into him. A single talisman rests on his ceiling, but he has no way of knowing it is one of the few safeguards that separate him from a bottomless pit of suffering. Each story is more terrifying, more appalling, and more sickening than the last as the Storytellers audience find themselves being sucked into the vicious world of his words.', 37, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7107, 'Shingeki no Kyojin Picture Drama', 2013, 9, 'Special', 60.0, 'Shingeki no Kyojin Picture Drama  is a series of Flash animated gag shorts included with the Blu-ray Disc/DVD releases, featuring the characters in chibi form. Consisting of nine episodes, this series takes a light hearted and comedic take on the the SNK series with many memorable scenes and dialogues from the original series presented in humorous way. Each episodes depicts 2-3 days in the training of the 104th Trainee Corps as they train to become the hope for mankind in the war against the Titans.', 46, False, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7108, 'Zettai Bouei Leviathan: Mini Takibi Gekijou', 2013, 13, 'Special', 67.6, 'A new special mini corner airing after the rebroadcast version of TV series.', 23, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7109, 'Kuusou no Soratobu Kikai-tachi', 2002, 1, 'Movie', 98.7, 'Animated 2002 short film produced by Studio Ghibli for their near exclusive use in the Ghibli Museum. It features famous director Miyazaki Hayao himself as narrator (in the form of a humanoid pig, reminiscent of Porco from Porco Rosso), telling the story of flight and the many machines imagined to achieve it.  Note: The film could also be seen on the in-flight entertainment system used by Japan Airlines.  (Source: AniDB)', 35, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7110, 'Akuma no Riddle', 2014, 12, 'TV', 71.1, 'Tokaku Azuma has just transferred to the elite Myoujou Academy, a private girls boarding school. But theres a catch: she, along with 11 of her fellow students in Class Black, is an assassin taking part in the challenge to kill their sweet-natured classmate, Haru Ichinose. Whoever succeeds will be granted their deepest desire, no matter the difficulty or cost. However, each assassin only gets one chance; if they fail to kill her, they will be expelled.  Despite the extraordinary reward, Tokaku decides to take a different course of action. Though Haru is her target, the young assassin soon finds herself drawn to the very girl she is supposed to kill. With the entire class out for Haru, Tokaku refuses to let her friend die, vowing to protect her from a growing bloodlust.', 103, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7111, 'Gokujo.: Souda Onsen ni Ikou!!', 2013, 1, 'Special', 99.7, 'Unaired ep.13 included on BD/DVD.', 49, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7112, 'Sore Ike! Anpanman: Omusubiman', 1990, 1, 'Movie', 71.5, 'No description available for this anime.', 88, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7113, 'Dokidoki Gakuen Kessen!! Youki Daimashiro', 1988, 1, 'OVA', 82.7, 'Four heroes set out to rescue girls taken by ayakashi.', 67, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7114, 'Tetsujin 28-gou Gao!', 2013, 151, 'TV', 71.4, 'This series of anime shorts, roughly five minutes in length, will focus on protagonist Shoutarou Kanedas everyday life instead of focusing on battle scenes as previous Tetsujin 28 titles have done. The visuals of the title robot, its nemesis Black Ox, and other elements will have a pop-art style.  (Source: ANN)', 113, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7115, 'Arata Kangatari Picture Drama', 2013, 6, 'Special', 88.7, 'Short specials added to DVDs and Blu-rays.', 81, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7116, 'Green Saver', 2009, 26, 'TV', 84.6, 'Nalong, Ukkya, and Longman have teamed up to defend the Earth from alien invaders who are here to pollute the environment! Lulu forest is no longer the main threatened area as the trio travels the world and helps out other animals in need.', 78, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7117, 'Hamuko Mairu!', 1996, 1, 'OVA', 72.0, 'A shinobi sets out to rescue kidnapped rare animals.', 74, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7118, 'Revbahaf Wang-gug Jaegeon-soelgi', 2007, 26, 'TV', 71.0, 'Three people are hiding out in a cabin by the foothills.  Van is the prince from the now-defunct Revbahaf Kingdom, Kona – his hand maiden, and Sian – his philosopher and tutor.  Chased by enemies, these three individuals earn the kindness of Aaron, who feeds them at the cabin.  By helping out with Aaron’s chores, the former royal family learns to live a peaceful life getting by, rather than plotting a revenge on the neighboring country which invaded them. Together they try to rebuild the Kingdom of Revbahaf.   (Source: Manhwa101)', 70, True, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7119, 'Saiki Kusuo no Ψ-nan (ONA)', 2013, 1, 'ONA', 85.9, 'Anime adaptation of the Saiki Kusuo no Ψ-nan manga by Asou Shuichi, telling the story about a male high school student named Kusuo Saiki. He possesses supernatural powers that cause unfortunate events in his everyday life.  (Source: ANN)', 69, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7120, 'Monkey Punch: Manga Katsudou Daishashin - Crime Mate Special', 2005, 1, 'Special', 64.1, 'Miki and Naomi are a pair of assassins who are also friends known as Crime Mate. While Miki is pole dancing for Chinese mafia boss Ramon who deals with biological arms, Naomi warns her about an armed group of ninjas. After Miki deals with Ramons gang and Naomi takes out the ninjas, the next day Miki sees the deceased body of Ricardo Gonzalez in her bed who offers Crime Mate a million dollars for the job. Naomi then gets kidnapped by Ramon so it is up to Miki to save her as they try to deal with Ramon. Also why is a King Cobra after them?  Some characters from Mankatsu as well as the 4 central characters from Lupin III can be seen in the background at times.  (Source: Lupin III Wiki)', 105, False, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7121, 'Juujika You and I', 2010, 1, 'Music', 63.5, 'Music video for the song Juujika You and I from the Base Ball Bears album Cypress Girls. This features vocals reminiscent of Michael Jackson funk.', 111, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7122, 'Little Witch Academia: Mahoujikake no Parade', 2015, 1, 'Movie', 80.8, 'You can tell witch training is not going swimmingly for the young sorceresses Akko, Lotte, and Sucy—they face expulsion for screwing up one class too many, and their only way out is if they successfully organize their academys annual parade through a nearby town. But when they stumble upon the momentous discovery that the objective of the parade is to humiliate witches and commemorate their past subjugation, Akko decides it is time for a change: It is time to show the world how fantastic modern witches truly are! However, with the other girls struggling to keep up with Akkos grandiose ambitions, and everything from mischievous boys to slumbering giants getting in their way, maybe pulling it off will require not only all the magical prowess the pupils of Luna Nova Magical Academy can muster, but also a miracle.', 36, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7123, 'Hakusai Anime', 2013, 3, 'ONA', 68.5, 'School Life of Hakusai and her friends.  Produced by Lamaze P (ラマーズP) in collaboration with Studio Piapro and broadcasted on Nico Nico.', 64, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7124, 'Kagerouka-kun', 2003, 1, 'OVA', 83.9, 'Story of a Mayfly that falls in love with a human girl.  Adapted from childrens picture book by Mitsuru Nakamura aka 326.', 81, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7125, 'Giga Tribe', 2008, 39, 'TV', 71.8, 'Gang Tu-Ji is just a normal passionate and determined (pun intended) 13 year old boy trying to woo the prettiest girl in school. That is until 4 mysterious creatures crash through his roof one day. Tu-Ji ends up reluctantly helping them out by transforming into Tribe Captain via the Giga Stones power they brought. And the creatures themselves are able to morph into fully humanoid super sentai-like warriors! Together they fight against friends and strangers who have been possessed by the evil Bavaria in a catch-phrase sitcom manner.', 110, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7126, 'Kaizoku Ouji', 1966, 31, 'TV', 63.7, 'Kid was brought up on a small island which floats on the Carribean Sea. He lives a pleasant life with many animals as his companions. However, this changes when he learns that his dying father is not his real father. Before he passes away, his foster father reveals to Kid that his real father is actually Captain Morgan, the pirate who rules the seven seas.   Kid decides to set off in search of his real father, only to learn about his death. Other pirates began to hunger for the title of ruler, one of them being the notorious pirate Tiger Hook. In order to protect the seas, Kid became the pirate king of his fathers ship.  (Source: ANN)', 29, True, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7127, 'Naruto: Shippuuden - Sunny Side Battle', 2013, 1, 'Special', 65.7, 'Back at their childhood home, siblings Itachi and Sasuke Uchiha experience an unusual morning together when Itachi becomes obsessed with cooking the perfect fried egg for Sasuke. Despite being completely focused on the task, he continuously fails to achieve the desired result. As Sasuke marvels at his brothers seemingly unnecessary behavior, he comes to realize that there is more than meets the eye to Itachis efforts.', 81, True, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7128, 'Toki-iro Kaima', 1989, 4, 'OVA', 90.1, 'Anime adaptation of the same name horror manga by Suzumiya Wayu, serialized in Shogakuans Weekly Shonen Sunday special issue.', 61, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7129, 'Kentoushi', 1990, 3, 'OVA', 66.3, 'Anime adaptation of the same name sports manga by Kurashina Ryou.', 114, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7130, 'Taabou no Ryuuguusei Daitanken', 1991, 1, 'Movie', 68.5, 'Taabou is on his space patrol. He arrives on an alien planet and has a run-in with the Scorpio Brothers. Luckily hes saved by Poyo, another alien. Poyo is trying to protect a previous plant from them and Taabou decides to help out. They leave the planet and head towards a black hole to worm hole to an aquatic planet with a palace like that in the folktale Urashima Tarou. The dragon god asks Taabou and Poyo to save a princess and so they fly off the the next planet.', 97, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7131, 'Dream Creator feat. GUMI', 2013, 1, 'Music', 63.2, 'Music video for Dream Creator feat. GUMI by Hachioji-P.', 60, True, 51);
