INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7133, 'Fujiko Fujio A no Mumako', 1990, 1, 'Special', 80.1, 'Based on the horror novel by Fujio (A) Fujiko.', 52, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7134, 'Taka no Tsume GO: Utsukushiki Elleair Shoushuu Plus', 2013, 1, 'Movie', 86.5, 'Yoshida-kun and members of the Eagle Talon secret society step up to defend the humankind from evil invaders.', 37, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7135, 'Beompeoking Jaepeo', 2004, 26, 'TV', 96.5, 'Bumper King Zapper is a 3D animation series about bumper car battles of the future.', 72, False, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7136, 'Ttoli Janggun', 1978, 1, 'Movie', 62.4, 'An anti-communist animation about a boy catching Noth Korean spies in South Korea.', 27, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7137, 'Anpanman to Hajimeyou! Iro, Kazu, Katachi Wakaru ka na Iro, Katachi', 2006, 1, 'Special', 84.0, 'Part of the Lets start with Anpanman series of educational animation for kindergarten children featuring characters from Anpanman.', 106, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7138, 'Otoko wa Tsurai yo: Torajirou Wasurenagusa', 1998, 1, 'Special', 74.7, 'Anime adaptation of the Otoko wa Tsurai yo (Its tough being a man) film series by Youji Yamada.  Kuruma Torajirou (or Tora-san), a traveling salesman whose sole possessions include only the contents of a small suitcase, the clothes on his back and some pocket money, wanders from town to town peddling his wares.  (Source: Wikipedia)', 39, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7139, 'Short Peace Opening', 2013, 1, 'Special', 60.6, 'The opening animation of the compilation movie, Short Peace.', 26, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7140, 'Kobayashi ga Kawai sugite Tsurai!!', 2013, 2, 'OVA', 96.7, 'Twins Megumu Kobayashi and Mitsuru Kobayashi attend different schools, one for girls and one for boys. One day, bored with being surrounded by others of their own gender, they decide to swap places with one another. While the deception seems to go unnoticed for some time, things get a bit more complicated when the possibility of romance arises.  Kobayashi ga Kawai sugite Tsurai!! begins when a heartfelt confession from Megumu leads to sharing a kiss with the upperclassman Aoi Sanada while disguised as her brother. This leaves Aoi, who was never good with girls to begin with, questioning if he likes guys instead. Likewise, Mitsuru finds the haughty queen of the school, Azusa Tokugawa, in a vulnerable position that leaves her heart racing while in his (her) arms. The two couples are lovey-dovey, but the secret of the twins switched identities has not been revealed yet...', 57, False, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7141, 'Houseki no Kuni PV', 2013, 1, 'ONA', 64.0, '*Based on a manga of the same name by Ichikawa Haruko, serialised in Afternoon.  In the distant future, a new life form called Houseki is born. The 28 Houseki must fight against the Tsukijin who want to attack them and turn them into decorations, thus each gem is assigned a role such as a fighter or a medic. Though she hopes to fight the moon people, Phos is a gem who is given no assignment until the gems manager Kongo asks her to edit a natural history magazine.  Note: A promotional video that was released through YouTube in commemoration of the publication of the mangas first volume.  (Source: AniDB)', 56, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7142, 'Ishii Hisaichi no Dai Seikai', 1991, 1, 'OVA', 77.0, 'Based the same name gag manga by Hisaichi Ishii.', 10, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7143, 'Kobo-chan', 1992, 63, 'TV', 76.2, 'Kobo Tabata lives in a typical Japanese family. His father is a normal salary-man, his mothers a typical housewife, his grandparents (from his mothers side) help to take care of the family and its pets, and his uncles a slightly obese high school teacher. Still, they manage to find odd situations that sometimes arise due to Kobos growing up process or simply because of their own habits and misunderstandings.  (Source: ANN)', 54, True, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7144, 'Kaiketsu Zorori: Mamoru ze! Kyouryuu no Tamago', 2013, 1, 'Movie', 97.0, 'Three main characters — Zorori, Ishishi, and Noshishi — get a letter from their friend (a dinosaur mother) to come see some dinosaur eggs because they are going to hatch soon.   When they get to the legendary dinosaur island, they are greeted with a warm welcome. However, a huge typhoon hits the island and the eggs go missing. Zorori goes on a quest to save the eggs and have them safely returned to their families.  (Source: ANN)', 54, True, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7145, 'Milk House Dreaming: Ai no Shiki', 1987, 1, 'OVA', 99.8, 'An image video, setting watercolors from Yumiko Kawaharas 1983 manga to a series of 11 pop songs.  (Source: ANN)', 70, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7146, 'New Initial D Movie: Legend 1 - Kakusei', 2014, 1, 'Movie', 73.6, 'One foggy morning, a black and white Toyota AE86 flies past Keisuke Takahashis Mazda RX7 on Mount Akina, making him believe he has seen the ghost of a racer who died on the mountain. Resolving to defeat this phantom, Keisuke mobilizes the Akagi Red Suns to take on the local Akina Speed Stars racing team in an exchange race. He anticipates that the competition will lure the elusive Ghost of Akina out into the open and give him the opportunity to exact revenge for his previous defeat.   While his friend Itsuki Takeuchi is obsessed with cars and racing, Takumi Fujiwara is not. He fails to understand the rush that racers experience and any talk of cars reminds him of the tofu deliveries he makes for his father in an old AE86. His early morning routine takes him up and down Mount Akina, where he has memorized every hairpin, brake point, and turn better than anyone else.   When the Akagi team appears one night to challenge the Speed Stars to an exchange race, they accept the challenge only to find out that they are completely outclassed. The only way the Speed Stars can stand a chance against them is if they can get the panda-colored AE86 to join their team. With a bit of coercion, Takumi takes the wheel of the AE86 and heads off to Mount Akina to defend the pride of all racers in Akina.', 43, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7147, 'Jewelpet Twinkle☆: Hohoemi no Niji ni Dokki☆Doki!', 2013, 1, 'Special', 91.3, 'Special episode included with the Blu-ray box set of the original Jewelpet Tinkle anime series.', 110, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7148, 'Junkers Come Here: Memories of You', 1994, 1, 'OVA', 67.0, 'No description available for this anime.', 112, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7149, 'Doraemon Movie 34: Shin Nobita no Daimakyou - Peko to 5-nin no Tankentai', 2014, 1, 'Movie', 62.2, 'This is a remake of the 1982 film, Doraemon: Nobitas Great Demon, which was written by original Doraemon co-creator Fujiko F. Fujio.  (Source: Wikipedia)', 85, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7150, 'Hajime no Ippo: Rising', 2013, 25, 'TV', 66.1, 'Japanese Featherweight Champion Makunouchi Ippo has defended his title belt once more with the help of his devastating signature move: the Dempsey Roll. However, new challengers are rising up left and right, claiming to have an answer for the move responsible for crushing his opponents. Will Ippo be able to step up to the challenge, or will the weight of his pride destroy him before he finds out just what it means to be strong? Meanwhile, fellow Kamogawa Gym mate Aoki Masaru is just a hop, skip, and a Frog Punch away from claiming his own belt, ready to take on the Japanese Lightweight Champion!  Hajime no Ippo: Rising continues Ippos quest to become stronger, featuring the same cast of loveable dimwits from Kamogawa Gym, as they put their bodies and hearts on the line to make their way in the harsh world of professional boxing. With a will of iron, Ippo steps into the ring once again.', 62, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7151, 'Neppuu Kairiku Bushi Road', 2013, 1, 'Special', 89.7, 'The story takes place in a time when the world is in the pits of despair after being ravaged by a poison called shinobi that came to earth via an asteroid. The people run away to the place called Kairiku, a place that used to be the bottom of the ocean. Here, the people try and protect themselves against the effects of the poison. In such a world, there was a single light of hope. The Holy Weapon Giga Road and the legendary warrior Yagyuu are needed in order to counter the effects of the poison. In order to save the world, Ame, a princess of a fallen nation, stands up in order to save the world.  (Source: ANN)', 37, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7152, 'Kuroko no Basket: Baka ja Katenai no yo!', 2013, 1, 'OVA', 69.8, 'Bundled with the 25th volume of Kuroko no Basket manga. The anime based on the Baka Ja Katenai no yo (バカじゃ勝てないのよ) story that was featured in the mangas fifth volume.  (Source: ANN)', 91, False, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7153, 'Free!: FrFr - Short Movie', 2013, 7, 'Special', 72.1, 'Specials bundled with the DVD/BDs.', 34, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7154, 'Hustle Punch', 1965, 26, 'TV', 84.7, 'The show centers around three hobos that live in a broken car on top of a junkyard: Punch, Touch, and Boom. Punch is a bear who is literally strong-headed: his head is as hard as a rock, and nothing can knock him down. Boom the weasel is an expert shot, using not a gun, but a slingshot. Touch the mouse takes advantage of her smallness in order to get into small holes and sneaking into things without the villains knowing.   Gari-Gari is a mad scientist wolf who wants to build a mansion over the junkyard, constantly thinking up evil plans to get the money needed to buy the property, whether it’s creating a machine that creates counterfeit 10 yen (about 10 cents in US money) or stealing priceless paintings and selling it to a high bidder. He is an inventor, creating things that can aid him into doing his deed. If Gari-Gari buys the junkyard, this of course means that the three heroes will have no place to stay, so they constantly thwart his schemes. Gari-Gari has two henchmen working for him: Black and Nyu. Black is a gangster cat who welds a gun, often shooting at Punch and the gang with it. Nyu is a simple-minded pig who has big strength.   (Source: Cartoon Research)  *Based on Hustle Punch by Mori Yasuji, serialized in Manga O.', 86, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7155, 'Kanojo ga Flag wo Oraretara', 2014, 13, 'TV', 86.1, 'In visual novels, an imaginary flag is defined as an event that serves as a turning point for the whole story. A player triggering the romance flag for a heroine will proceed to her route, or a death flag will signify that a certain character will die afterwards.  High school student Souta Hatate can see these flags above a persons head, and has the ability to bring them down to stop certain events from happening. Using this power, he has prevented other peoples deaths. But, after a past accident with him as a sole survivor, he ended up believing that only misfortune will befall those who are near him, and has refrained from making friends or having relationships ever since.  However, everything starts to change after transferring to a new school. After toppling another death flag, his classmate Nanami Knight Bladefield notices his powers and tries to learn more about him, promising that she will remain at his side no matter what may happen. Thus begins Soutas journey as he meets new friends and acquaintances while uncovering the mysteries of his ability... which might run deeper than what anyone expects.', 97, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7156, 'Kuiba II: Dazhan Yuan Yang Jie', 2013, 1, 'Movie', 73.1, 'Every 333 years, an abomination is born, a being known as Kuiba, destined to be the nemesis of all, and bring disaster to the world. In Kuiba year 1664, the sixth-generation Kuiba appeared. After narrowly escaping a preemptive strike by the forces of heaven, the young Kuiba was adopted by Man Xiaoman of the Beast Nation, who gave him the name Manji. Like those around him, Manji is unaware of his true identity. With the encouragement of his adopted father, Manji overcame numerous trials before finally boarding a warship bound for Maelstrom Island.   There he hopes to prove he is the greatest Spirit Warrior of all by saving the world from the threat known as Kuiba. Meanwhile, on Maelstrom Island, Kuibas most loyal lieutenants are waiting, ready to do battle with all who oppose their masters return Though unaware of his true nature, Manji must soon face the inevitable conflict between his father, the gods of heaven, and Kuibas twelve fiercest lieutenants.  (Source: IMDB)', 78, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7157, 'Clover 4/3', 2000, 24, 'ONA', 88.1, 'Studio Kaabs first work--an inspiring interactive animation.  We follow the lives and turmoils of seven outcasted 17 year olds and you--the protagonist. Between the aches of being a girl whos younger than her body looks or a boy whod rather get into fist fights than give handshakes, we found a piece of ourselves within the outcasted teens thats abnormal. Like a four leaf clover. Which are said to bring luck even though it is a mutant in the sea of three leaves. And so the curtain rises to glimpse at these four leaf Clovers--4 boys and 3 girls.  (Source: Studio Kaab)', 54, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7158, 'Toaru Kagaku no Railgun S: Motto Marutto Railgun', 2013, 2, 'Special', 82.2, 'Toaru Kagaku no Railgun S specials that were released on Blu-ray and DVD volumes.', 57, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7159, 'Kyousou Giga (TV)', 2013, 10, 'TV', 81.1, 'Long ago, there was a monk named Myoue who could bring anything he drew to life. He quietly lived with his wife Koto—a black rabbit in human form—and their three children: Yakushimaru, Kurama, and Yase. One day, the high priest of the land concluded that Myoues drawings caused too many problems for the locals and ordered him to find a solution. In response, the family secretly fled to an alternate world of Myoues own creation—the Looking Glass City.  Everything was peaceful until Myoue and Koto suddenly vanished. Their three children are left to take care of the city, and Yakushimaru inherits Myoues name and duties. Stranded in this alternate world, their problems only get worse when a young girl—also named Koto—crashes down from the sky and declares that she is also looking for the older Myoue and Koto. Armed with a giant hammer and two rowdy familiars, Koto just might be the key to releasing everyone from the eternal paper city.', 56, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7160, 'Meitantei Hangyodon: Kaitou Ruzu Arawaruno-kan', 1993, 1, 'OVA', 96.5, 'Sanrios Hangyodon starring as a detective in the case of the mysterious thief.', 65, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7161, 'Zoku Naniwa Yuukyouden', 1992, 1, 'OVA', 93.7, 'The Kinshu Group is back to their old antics in this mob comedy. Two new recruits join the gang and try to prove their worth. Things take a turn for the worse with the boss takes a bullet and is hospital ridden. What will happen to the gang as snakes begin to creep to break apart company as if the boss is dead?!  *Based on the same name manga by Dookuman Pro, a group of four manga artists.', 32, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7162, 'Nexus', 2011, 1, 'Music', 93.2, 'Third single release from ClariS featuring a tie-up song with the light novel Ore no Imouto ga Konna ni Kawaii Wake ga Nai. Limited edition of volume 9 of the novel includes a bonus DVD with the music video.  (Source: AniDB)', 112, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7163, 'Naniwa Yuukyouden: Nekketsu!! Bakushou Mankai-hen', 1992, 1, 'OVA', 64.2, 'In the 3rd series continues as the gang hits up a karaoke bar at night only to cause a ruckus with their less than desirable signing. They soon find out the karaoke bar might close from local hooligans and attempt to rescue it for compensation. A fellow gang member gets involved too deep with a woman--even though hes married.', 52, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7164, 'Osamu to Musashi', 1994, 1, 'Movie', 75.1, 'The animation was produced for the Tezuka Osamu Manga Museum, thus it features scenes from the life and nature of Tezuka Osamus childhood, themes that are central to the museum as a whole, through exchanges between the boy Osamu and the carabid beetle (Osamushi) who provided the origin for the artists name.  (Source: tezukaosamu.net)', 11, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7165, 'Naniwa Yuukyouden: Chou Gokudou! Yoru no Bat wa Manrui-hen', 1993, 1, 'OVA', 88.9, 'No description available for this anime.', 82, False, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7166, 'Naniwa Yuukyouden: Kyouretsu! Ana ga Attara Iretai-hen', 1993, 1, 'OVA', 80.9, 'No description available for this anime.', 24, True, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7167, 'Gu-Gu Ganmo (Movie)', 1985, 1, 'Movie', 86.8, 'Movie version that lampooned several Japanese Folklore Tales, including that of Princess Kaguya.  Based on a manga by Hosono Fujihiko, serialised in Weekly Shounen Sunday.  (Source: AniDB)', 108, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7168, 'Naniwa Yuukyouden: Kanketsu-hen', 1993, 1, 'OVA', 80.5, 'No description available for this anime.', 23, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7169, 'Oshiri Kajiri Mushi (TV) 2nd Season', 2013, 32, 'TV', 72.5, 'Continuation of the gag comedy about Oshiri Kajiri Mushi XVIII, a 10-year-old insect who goes to Biting School to inherit his familys Biting Shop business.   (Source: ANN)', 60, True, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7170, 'Ansatsu Kyoushitsu: Jump Festa 2013 Special', 2013, 1, 'Special', 64.4, 'Class 3-E is getting ready for their class trip to Kyoto, and Koro-sensei is as excited as ever! Nagisa is in a group with Kaede, Karma, Tomohito, Manami, and the class idol Yukiko Kanzaki. The students are aware of the fact that this is a great opportunity to assassinate Koro-sensei, but they cannot help having great time with him. However, the trip becomes even more exciting and dangerous when they get attacked by a bunch of delinquents who kidnap the girls. As if that is not enough, there is a hired sniper named Red Eye lurking around, ready to be the one who would assassinate Koro-sensei and claim the prize. Can the students of Class 3-E rely on Koro-sensei even now?', 49, True, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7171, 'Mahou Sensou', 2014, 12, 'TV', 73.4, 'The world as we know it is actually just half the story, as Takeshi Nanase finds out abruptly one summer morning. On his way to kendo practice, Takeshi comes across an unconscious girl in a uniform he doesnt recognize. Takeshi does the decent thing and saves her, and in return the girl wakes up and accidentally turns him into a magic-user.  As Takeshi finds out, there is the world he lives in and the world of magic users. Most magic users just want to peacefully coexist with non-magicians, but there are some with bigger ambitions. Mui Aiba is a magician enrolled in the Subaru Magic Academy, where magic users can learn to control and channel their powers and how to live in peace with regular humans. After his fateful encounter with Mui, Takeshi and his newly magician friends Kurumi Isoshima and Kazumi Ida decide to enroll in the Magic Academy as well.  All three friends have different reasons for fighting on, whether theyre fighting to escape the past or catch up to the future. They wield different kinds of powers, which they must learn to harness in order to fight off the Ghost Trailers, a group of magicians who are willing to use violence to assert their superiority over humans.  Pursued by the Ghost Trailers, Takeshi and his friends must train to become stronger, face the leader of the Trailers, and prevent the beginning of the Second Great Magic War.', 99, True, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7172, 'Akuma Tou no Prince: Mitsume ga Tooru', 1985, 1, 'Special', 73.8, 'The popular Manga The Three-Eyed Boy Comes Here was produced as the eighth in an animated series for a special 24-hour broadcast. This time, the movie was produced by Toei Animation Co., Ltd. instead of by Tezuka Productions Co., Ltd. Here, Tezuka Osamu was in charge of only the original story and a synopsis for animation.   Based on the original Manga, Easter Island: Sea voyage, Sharaku and Wato investigate a mysterious old ship, only to find themselves getting involved in a sea voyage around strange islands. More emphasis was placed on entertainment factors than on theme, and this change in the concept line resulted in the withdrawal of Tezuka Productions Co., Ltd. from this series.  (Source: tezukaosamu.net)', 83, True, 92);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7173, 'Sidonia no Kishi', 2014, 12, 'TV', 86.9, 'After destroying Earth many years ago, the alien race Gauna has been pursuing the remnants of humanity—which, having narrowly escaped, fled across the galaxy in a number of giant seed ships. In the year 3394, Nagate Tanikaze surfaces from his lifelong seclusion deep beneath the seed ship Sidonia in search of food on the upper levels, only to find himself dragged into events unfolding without his knowledge.  When the Gauna begin their assault on Sidonia, its up to Tanikaze—with the help of his fellow soldiers and friends Shizuka Hoshijiro, Izana Shinatose, and Yuhata Midorikawa—to defend humanitys last hope for survival, and defeat their alien foes. Sidonia no Kishi follows Tanikaze as he discovers the world that has been above him his entire life, and becomes the hero Sidonia needs.', 47, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7174, 'Kuiba III: Zhanshen Jue Qi', 2014, 1, 'Movie', 88.6, 'Before he can get close to the real enemy, Manji faces challenges from two powerful opponents : Da Cang - a master of using body pulse, and Hai Wen Xiang - a sea witch who is extremely loyal to Kuiba. When Manji is unwillingly engaged in an intense battle with Hai Wen Xiang. Kuiba reveals its mysterious appearance.  (Source: IMDB)', 96, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7175, 'Nanbo no Monjai! Yankee Gurentai', 1992, 2, 'OVA', 97.7, 'A youthful motorcycle gang in Osaka has their fair share of turf wars, lewd women, and full throttles as they go about their too school for school attitude with misconceptions and gags galore!', 80, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7176, 'Robot Girls Z', 2014, 3, 'Special', 62.1, 'The story revolves around a new team of Toei robot girls named Team Z that is made up of three girls based on Toeis Mazinger Z franchise: Mazinger Z, Great Mazinger, and UFO Robot Grendizer. Usually they perform in activities around Nerima ward in Tokyo to raise the awareness of the promising future energy source Photon Power (koushiryoku). However, there are times when Mechanical Beast team of girls emerge from the Subterranean Empire and attempt to steal the energy. Thus Team Z has to battle them to prevent this, though sometimes they just go and beat up the bad girls to relieve stress.  Please note that because in this particular case MAL lists airings, not episodes/chapters/parts, this show is considered to be 3 episodes and not 9. Each of the three airings consisted of three episodes for a total runtime of 27 minutes per airing. The duration on MAL reflects this.', 14, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7177, 'Waanabi.jk', 2013, 2, 'Special', 95.4, 'Promotion videos for Kenichi Kurois web manga Waanabi.jk, commissioned by Studio DEEN.', 49, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7178, 'No Game No Life', 2014, 12, 'TV', 75.5, 'Sixteen sentient races inhabit Disboard, a world overseen by Tet, the One True God. The lowest of the sixteen—Imanity—consists of humans, a race with no affinity for magic. In a place where everything is decided through simple games, humankind seems to have no way out of their predicament—but the arrival of two outsiders poses a change.  On Earth, stepsiblings Sora and Shiro are two inseparable shut-ins who dominate various online games under the username Blank. While notorious on the internet, the pair believe that life is merely another dull game. However, after responding to a message from an unknown user, they are suddenly transported to Disboard. The mysterious sender turns out to be Tet, who informs them about the worlds absolute rules. After Tet leaves, Sora and Shiro begin their search for more information and a place to stay, taking them to Elkia—Imanitys only remaining kingdom.  There, the duo encounters Stephanie Dola, an emotional girl vying for the kingdoms sovereignty. In desperation, she attempts to regain her fathers throne, but her foolhardiness makes her goal unachievable. Inspired by the girls motivation and passion, Sora and Shiro decide to aid Stephanie in getting Elkia back on its feet, ultimately aiming to become the new rulers of the enigmatic realm.', 103, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7179, 'Namakemono ga Miteta', 1988, 2, 'OVA', 61.1, 'Based off a manga by Murakami Takashi that was serialized in Weekly Young Jump.  (Source: AniDB)', 22, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7180, 'Saikyou Ginga Ultimate Zero: Battle Spirits', 2013, 49, 'TV', 88.7, 'In the new, whimsical era of Battle Spirits, cards have become scattered across a colorful galaxy, enticing all card questers to duke it out in search of the strongest cards. Rei is a flamboyant wanderer who is obsessed with being on top. Accompanied by a small dragon named Mugen and a talking robot named Salt, the self-proclaimed Number One Star regularly engages in card-gaming mischief through flashy battles.   One day, Rei meets Raira and Rikuto April, both of whom seem to have clues on the whereabouts of the ultimate Battle Spirits card. Together, they embark on a quest to search for the card, clashing with many vibrant personalities along the way. Soon, their adventure catches the attention of the Guild, wily villains who are also set on obtaining the Ultimate Battle Spirits. In contending against the Guild, Reis status as number one is put to the test—an endeavor that will slowly unveil secrets regarding the fate of the universe.', 91, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7181, 'Ore wa Chokkaku', 1991, 36, 'TV', 93.8, 'No description available for this anime.', 26, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7182, 'Weiqi Shaonian 2', 2009, 26, 'TV', 70.5, 'Jiang Liu Er has fortified his skills as a Go player over the years. He now must make the long journey to become a grandmaster.', 67, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7183, 'Super Seisyun Brothers', 2013, 14, 'TV', 80.8, 'The story involves two pairs of teenage elder sister and younger brother, the Shinmotos who are a bit narcissistic and the Saitous who look a bit mysterious. It follows their everyday life in school and at home.  (Source: MAL News)', 11, False, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7184, 'Tamagotchi! Miracle Friends', 2013, 29, 'TV', 66.2, 'In the new series, Miraitchi and Kururutchi, twin sisters who dream of becoming designers, travel from the future back in time to modern-day Dream Town. (Their names are a wordplay on the Japanese words for future and miracle.)  To get back to the future, they must collect all eight Dreambakutchi — mysterious Tamagotchi who have escaped throughout the town. Mametchi joins Miraitchi and Kururutchi on their mission to find the Dreambakutchi, but then, an enigmatic Tamagotchi named X-Kamen (X-Mask) appears.   (Sourse: ANN)', 10, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7185, 'Ore no Imouto ga Konnani Kawaii Wake ga Nai.: SD Chara ni Yoru Short Movie', 2013, 13, 'Special', 66.6, 'Short specials featuring chibi versions of OreImo characters, included on the first limited editions of the OreImo Season 2 BD/DVD volumes.', 92, False, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7186, 'Peeping Life 5.0ch', 2012, 10, 'OVA', 87.0, 'No description available for this anime.', 31, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7187, 'Nobunagun', 2014, 13, 'TV', 89.3, 'Shio Ogura is a Japanese high school student, who is visiting Taiwan on a school trip when she is suddenly attacked by monsters. Agents known as E-Gene Holders from the government agency DOGOO also arrive, who wield weapons infused with the spirits of historical figures. Shio is revealed to also be an E-Gene Holder when the soul of Oda Nobunaga awakens after she tries to rescue a friend.  (Source: Wikipedia)', 63, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7188, 'Gaist Crusher', 2013, 51, 'TV', 79.3, 'In the year 2047, mankind discovered a rare metal ore called Gaimetal, which possessed a huge amount of energy, and mining for these strange metal ore begins all over the world. However, in 2075, humankind were been constantly attacked by Gaist, a race of metallic creatures whose bodies were encrusted with Gaimetal, thus forming the GCG (also known as Gaist Crusher Garrison), an organization tasked with dealing against the Gaist. In 2064, the GCG send out mankinds line of defense: the Gaist Crushers, humans who can wear a special Gaimetal armor called Gaist Gear, and battle the Gaist,as well as the threat opposed by a mysterious organization called Erasers.  (Source: Wikipedia)', 82, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7189, 'Marude Dameo', 1991, 47, 'TV', 71.1, 'The series stars an elementary school boy named Dameo Marude, who has little success with anything he tries, and a robot named Borot, which is good with housekeeping.  (Source: Wiki)', 34, False, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7190, 'Robotan', 1966, 104, 'TV', 76.2, 'Based on a manga by Morita Kenji.  Household robot Robotan, made by a nerdy school boy named Kan-chan, lives with an everyday Japanese family as a domestic servant and friend to the children.  (Source: AniDB)', 100, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7191, 'Battle Spirits: Sword Eyes Gekitouden', 2013, 21, 'TV', 81.1, 'No description available for this anime.', 10, False, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7192, 'Osomatsu-kun: Suika no Hoshi kara Konnichiwa zansu!', 1989, 1, 'Movie', 80.1, 'No description available for this anime.', 105, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7193, 'Shouri Toushu', 1987, 1, 'Movie', 92.7, 'Baseball coach Hoshiyama offers a chance to turn professional to Katsumi Kunimasa, a star member of the student squad that won the summer tournament. The young girl becomes a star pitcher for the Chunchi Dragons (conveniently, the team her father owns), and, after a year of triumphs, she leads them to victory in the national championships at the legendary Koshien Stadium. Based on the manga by Noriko Umeda, this anime may be compared to the other girl-playing baseball story Song of the Baseball Enthusiasts.   The Dragons team members are all based on the real-life team, though their opponents are  fictional. At the time, the real-life Hoshiyama was a commentator, but fact was eventually true to fiction and he became the manager for the real-life Dragons.   (Source: The Anime Encyclopedia)', 108, False, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7194, 'Genshiken Nidaime Specials', 2013, 4, 'Special', 75.3, 'Special episodes included in BD.', 70, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7195, 'Ohayou! Spank (Movie)', 1982, 1, 'Movie', 98.1, 'Based on the shoujo manga by Yukimuro Shunichi and Takanashi Shizue serialised in Nakayoshi.   (Source: AniDB)', 59, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7196, 'Fujiko F. Fujio: Sukoshi Fushigi Tanpen Theater', 1990, 11, 'OVA', 69.0, 'Based on a story by Fujiko F. Fujio.', 33, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7197, 'Donkikko', 1967, 21, 'TV', 60.3, 'A comedy about the mischievous adventures of a young boy. Each episode contains 2 stories.  (Source: AniDB)', 46, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7198, 'Dai-chan, Daisuki.', 2007, 1, 'Movie', 91.3, 'Main character in this film, Mai, has a handicapped brother, who is totally deaf, called Dai-Chan. He is like a younger brother for Mai yet he is actually her older brother because Dai-Chan always asks Mai to hold him up with smiling all over.   One day, an elementary school Mai goes to and a handicapped school Dai-Chan goes to start to communicate each other. And then, Mais class mates started to make fun of Mai and draw a funny portrait of Dai-Chan on black board in the class. Mai gets shocked and hurt at that mischief. And moreover, their mother gets sickness at the same time. Thats why Dai-Chan should enter in an orphanage for handicapped children; however, Mai really wants to take care of him by herself, so she tries to stop it.   This story is written about a love of family, close bond, and relationship between human and human. We definitely have a common warm heart and a moment we have to use it with honest feeling. This film could remind us some important things we should never forget about our life.  (Source: AniDB)', 106, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7199, 'Ecchan no Sensou', 2002, 1, 'Movie', 60.7, 'Based on a childrens novel by Etsuko Kishikawa.', 91, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7200, 'Pipi Tobenai Hotaru', 1996, 1, 'Movie', 96.6, 'Based on the fairy tale novel series by Akira Ozawa (小沢昭巳).', 109, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7201, 'Nijuushi no Hitomi', 1980, 1, 'Special', 78.1, 'Based on the book by Tsuboi Sakae, which drew on her involvement in Japans anarchist counterculture and opposition to Korean War rearmament.  Combined live action (handled by Akio Jissoji) and animation (handled by Shigetsugu Yoshida). Released as a TV special.  (Source: AniDB)', 56, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7202, 'Tesagure! Bukatsumono', 2013, 12, 'TV', 71.4, 'The CG anime centers around the extracurricular activities of students.  (Source: AniDB)', 53, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7203, 'Ogami Matsugorou', 1989, 1, 'OVA', 70.3, 'Based on the same name manga by Itou Minoru, serialized in Kodanshas Weekly Shounen Magazine.', 52, True, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7204, 'Anata ga Furikaeru Toki', 1993, 1, 'OVA', 88.3, 'Three shorts based on stories by Hanai Aiko, who also directed this OVA.  (Source: AniDB)', 15, False, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7205, 'KY-kei JC Kuuki-chan', 2013, 6, 'ONA', 66.5, 'On the first day as a transfer student, Betao comes to meet one girl. Her name is... Kuuki Yominashi! (Her initials KY mean being unable to read the situation/mood.) When Betao with glasses and Kuuki with skippers meet with each other, the gears of fate starts to spin.  The contemporary story, intersecting lives; a story of duty, human nature and friendship.  Lets begin the story of a KY-style high school girl Kuuki-chan!  (Source: AnimeBancho)', 59, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7206, 'Kimu no Juujika', 1990, 1, 'Movie', 68.4, 'Based on the novel by Noboru Wada.', 112, True, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7207, 'Eikou e no Spur: Igaya Chiharu Monogatari', 1997, 1, 'Movie', 61.2, 'A biography of Chiharu Igaya, who won a silver medal in mens slalom in Cortina dAmpezzo Olympics in 1956, and became the first Japanese Winter Olympics medalist.  (Source: AniDB)', 85, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7208, 'Zoku Natsume Yuujinchou: 3D Nyanko-sensei Gekijou', 2009, 5, 'Special', 64.1, 'Short 3D Nyanko-sensei animations bundled on BD/DVDs of the Zoku Natsume Yuujinchou series.', 91, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7209, 'Ikkyuu-san (1978)', 1978, 26, 'TV', 61.6, 'High-school student Ikkyuu knows nothing about baseball, but his talents are recognized by the manager of the baseball club, and he takes up this enchanting sport. While his ignorance of the game leads him to make many mistakes, Ikkyuu - who is in fact a descendant of ninja - displays his superhuman abilities and leads the team to the High School Baseball Championships.  (Source: Nippon Animation)', 62, True, 9);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7210, 'Hunter x Hunter Movie 2: The Last Mission', 2013, 1, 'Movie', 96.8, 'Nen: the hidden source of energy and potential that runs through everyone, and gives those that master it a source of great power. Inside Nen is the potential for limitless light and limitless darkness. The Hunter Association has arisen to control access to it. Hunters come in many shapes and forms, and with many different appetites - but all of them have learned to master Nen, and use it to chase wealth, power, and their dreams.  The greatest and most powerful Hunter is Isaac Netero, chairman of the Hunter Association. Decades ago he sealed away Jed, a Hunter who had mastered the use of On, the dark shadow of Nen. Now On users have reappeared at the Heavens Arena Battle Olympia tournament. For Netero, this is the last mission: to protect the Association and the world from a threat driven by hatred and the thirst for revenge. And hes going to need all the help he can get in order to succeed.', 69, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7211, 'Zetsumetsu Kigu Shoujo: Amazing Twins', 2014, 2, 'OVA', 70.0, 'Amane Todoroki is a young girl who is straightforward but also unthinking. She will try her very best in everything and say, I dont know how to answer you if you ask me whether this can be done. I just believe it can. If not, then nothing will get started! She easily gets stuck in her thinking, but she can also get easily moved at something small and start crying.  (Source: MAL News)', 71, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7212, 'Huckleberry no Bouken (Movie)', 1991, 1, 'Movie', 99.2, 'Movie version of the TV series Huckleberry no Bouken.', 69, True, 12);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7213, 'Barbapapa (1977)', 1977, 48, 'TV', 98.2, 'Based on a series of childrens books written in the 1970s by Annette Tison and Talus Taylor.  Adding to the first serie from 1975, the second serie brings 48 new episodes.  (Source: AniDB)', 29, True, 13);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7214, 'Heisei Tensai Bakabon', 1990, 46, 'TV', 91.3, 'A comedy about a former genius who has now become very eccentric and senile. His family deals with all the crazy problems he and his old friends cause around the neighborhood.  (Source: AniDB)', 17, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7215, 'Ikinari Dagon', 1988, 12, 'TV', 65.2, 'Dagons little rocket crashes into a beautiful, blue planet and lands on a bed of green weeds. He quickly becomes friends with all kinds of creatures: Zipzap Mantis, General Ant Garibaldi, Andy Ant, Doctor Marilyn Wasp, and many more. Needless to say they are all insects. Insects? Yes, Dagon is only one centimetre tall!  The tiny residents of the land of weeds become curious about the identity of this stranger from another planet. But when Dagon saves them from the danger posed by their ferocious enemies, Gulpo Toad and Godzi Lizard, everyone thinks Dagon is a SUPER-BUG!  This planet is also home to a number of creatures that are very terrifying to these little fellows. They are called the Sapiens, or the human beings. Dagon must confront these massive creatures in order to get his rocket back from them!  So begins Dagons funny and thrilling adventure on Earth...  (Source: AnimeNfo)', 42, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7216, 'Machi Ichiban no Kechinbou', 1978, 1, 'Special', 94.0, 'Based on the novel A Christmas Carol by Charles Dickens.  (Source: AniDB)', 76, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7217, 'Ashita no Joe Pilots', 1969, 2, 'Special', 95.1, 'Pilot episodes.', 23, True, 17);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7218, 'The Impression of First Gundam', 1998, 1, 'Special', 94.3, 'Screened together with Gundam: Mission to the Rise at Gundams 20th Anniversary event Gundam Big Bang Sengen in Pacifico Yokohama National Convention Hall.  Selected scenes from Kidou Senshi Gundam were re-edited for three giant projection screens to give the widescreen feel to the original 4:3 aspect footage. They were also computer synchronized to sweeping lights and lasers to simulate space battles. The soundtrack was remixed for six-channel surround sound.   (Source: AniDB)', 117, True, 18);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7219, 'Shisukon Ouji', 1963, 14, 'TV', 85.0, 'Based on a manga by Fujiko (A) Fujio and Fujiko (F) Fujio.', 80, True, 19);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7220, 'Shounen Ninja Kaze no Fujimaru: Nazo no Arabiya Ningyou', 1964, 1, 'Movie', 62.9, 'Kidnapped and rescued by a Ninja, Fujimaru has mastered martial arts over the years. Now he sets off on a journey to find his mother and also locate an old tome containing secret martial arts techniques.  (Source: AniDB)', 104, True, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7221, 'Uchuujin Pipi', 1965, 52, 'TV', 60.6, 'An alien from another world lands on Earth and befriends a human boy. Pipi tends to help his human friends by giving them sound advice and sometimes using his advanced technology when needed. This is a drama which is mostly live actors and scenery. The main character, Pipi, and many of the special effects are animated.  (Source: AniDB)', 92, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7222, 'Kaitou Pride', 1965, 105, 'TV', 68.5, 'Each episode features a part of the story in which a detective tries to hunt down and capture a notorious and narcissistic thief. This series aired daily, Monday to Friday, in 8 minutes segments to complete a single story by the end of the week.  (Source: AniDB)', 53, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7223, 'Tatakae! Osper', 1965, 52, 'TV', 66.1, 'On a distant world, people with paranormal powers battle each other.  Based on a story by Yamano Kouichi.  (Source: AniDB)', 41, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7224, 'Tobidase! Bacchiri', 1966, 132, 'TV', 83.3, 'The adventures of jug-eared schoolboy detective Bacchiri, who can solve cases that baffle the police, thanks to his brilliantly ingenious mind. The 10 minutes episodes aired daily, Monday through Saturday.  (Source: The Anime Encyclopedia &amp; AniDB)', 74, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7225, 'Kaminari Boy Pikkari★bee', 1967, 53, 'TV', 75.4, 'A comedy about a mischievous boy. Each episode contains 2 stories.  Based on a manga by Murotani Tsunezou.  (Source: AniDB)', 59, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7226, 'King Kong: 001/7 Tom Thumb', 1967, 26, 'TV', 68.8, 'Professor Bond is doing research on an island in the Java Sea when his son discovers the giant ape and befriends him, and together they fight to protect Kong from Dr. Who, who has sinister designs on the ape. Each episode consisted of a King Kong story, a Tom of T.H.U.M.B., then another King Kong story.   Tom of T.H.U.M.B. is a gag cartoon about a secret agent and his oriental sidekick. Animage Pocket Data Notes credits MORI Yasuji and KANISHI Takao as either character designers or animation directors of the latter, differing from the credits for the King Kong portion of the show.   This was the first cartoon TV series animated entirely in Japan expressly for American television. American sources state Rankin-Bass commissioned the work from Videocraft International; Japanese sources state it was produced by Videocraft/Toei Doga.  (Source: AniDB)', 16, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7227, 'Fight Da!! Pyuta', 1968, 26, 'TV', 81.5, 'A young boy uses his scientific skills to fight enemies.  (Source: AniDB)', 115, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7228, 'Sobakasu Pucchi', 1969, 162, 'TV', 77.2, 'A kids adventure and comedy series. Each 5 minute episode aired Monday through Saturday in a continuing story which completed at the end of the week.  (Source: AniDB)', 73, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7229, 'Mouretsu Atarou', 1969, 90, 'TV', 73.5, 'Based on a manga of Akatsuka Fujio.  Batsugoro was the owner of a grocery store, Yaobatsu. When he tried to take a balloon hanged caught on the branch for a little child, he fell on to the ground to die. His son, Ataro, succeeded to the store, but Batsugoro was worried about him, and he remained there being a ghost. Ataro managed the shop alone, but soon his follower, Dekoppachi, began to help him. Being surrounded by strange characters such as, Nyarome, Butamatsu, the heart-warming story develops.  (Source: AnimeNfo)', 19, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7230, 'Roppou Yabure-kun', 1969, 110, 'TV', 64.3, 'Short stories featuring the legal profession. The first anime to be broadcast on the new Nagoya Television Network (NTV).  Based on a story by Saga Sen.  (Source: AniDB)', 61, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7231, 'Pinch to Punch', 1969, 156, 'TV', 73.3, 'A comedy about two goofy twins in the armed forces.  (Source: AniDB)', 73, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7232, 'Doubutsu Mura Monogatari', 1970, 100, 'TV', 65.7, 'A short kids series featuring cute animal stories.  (Source: AniDB)', 11, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7233, 'Sword Art Online: Extra Edition', 2013, 1, 'Special', 68.4, 'The story is set a couple of years after the events of Sword Art Online, where Kazuto Kirito Kirigaya and his sister Suguha meet up with Asuna Yuuki, Rika Lisbeth Shinozaki, and Keiko Silica Ayano at the SAO Survivor School. Kirito then attends emergency counseling, while the girls go for a swim at the pool. It turns out that said emergency counseling is a subterfuge set up by Seijirou Kikuoka, aiming to rehash the incident of Sword Art Online in hopes of determining Akihiko Kayabas motives. What will the girls get up to in the pool, and what awaits Kirito and his counseling?', 45, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7234, 'Otanoshimi Anime Gekijou', 1970, 26, 'TV', 92.0, 'Based on the original story by Studio Zero.', 113, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7235, 'Itazura Tenshi Chippo-chan', 1970, 240, 'TV', 71.8, 'Humorous adventures of a silly angel, 5 minutes per episode.  (Source: AniDB)', 113, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7236, 'Nihon Meisaku Douwa Series: Akai Tori no Kokoro', 1979, 26, 'TV', 96.8, 'A collection of childrens stories originally printed in the popular magazine Akai Tori, which was published from 1918 to 1936.  (Source: AniDB)', 87, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7237, 'D-Frag!', 2014, 12, 'TV', 66.0, 'The Kazama Family—a gang of three wannabe delinquents and close friends, spearheaded by Kenji Kazama, is trying to make a name for themselves at Fujou Academy. On the first day of the term, the gang finds themselves putting out a fire in the Game Development Club. Instead of thanking them, the eccentric club members attack and knock out Kenjis two friends, forcing Kenji to fight for his life. Failing to escape, the gang leader is coerced into joining the Game Development Club.  As he settles in, Kenji gets to know the four girls responsible for his provisional membership—student council president and general tyrant Chitose Karasuyama, spirited tomboy Sakura Mizukami, negligent club advisor Minami Oosawa, and the schools infamous shadow leader Roka Shibasaki. Throughout the Game Development Clubs constant shenanigans and his desperate attempts to leave the club, Kenji begins to realize that he may be actually enjoying himself.', 24, False, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7238, 'Miss Monochrome The Animation', 2013, 13, 'TV', 96.8, 'Miss Monochrome is an android powered by a single AA battery. She lives with her only friend, a robot vacuum named Ruu-chan. With hopes of one day meeting the idol Kikuko, whom she has bizarre recurring dreams about, Miss Monochrome sets foot on the path to stardom. However, she experiences difficulties and struggles to make her own debut as an idol. Though Miss Monochromes methods seem bizarre, such as recruiting her manager from a convenience store, somehow her dedication always results in her standing out from the crowd and shining in the spotlight.', 77, True, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7239, 'Toaru Majutsu no Index-tan Movie: Endymion no Kiseki - Ga Attari Nakattari', 2013, 1, 'Special', 97.1, 'Bonus animation featuring Index-tan included with the BD special edition of the Toaru Majutsu no Index: Endymion no Kiseki movie.', 20, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7240, 'Kill Me Baby: Butsuzou Kegatte Nise Halloween', 2013, 1, 'OVA', 80.5, 'Bundled with the franchises Kill Me Baby Super Best Album CD (キルミーベイベー・スーパー). OAD adapted eight previously unanimated story episodes from Kazuhos original manga.  (Source: ANN)', 73, False, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7241, 'IS: Infinite Stratos 2 - Hitonatsu no Omoide', 2013, 1, 'OVA', 96.7, 'An extended version of the second seasons first episode, which is under the same title.', 59, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7242, 'Sakura Trick', 2014, 12, 'TV', 94.4, 'Having been best friends since middle school, Haruka Takayama and Yuu Sonoda plan to attend Misato West High School together. However, despite being assigned to the same class, a cruel twist of fate has them seated on the opposite ends of their classroom! To make matters worse, their school will shut down in three years, making them the final intake of first-year students. Undeterred by this chain of unfortunate events, Haruka is set on sticking with Yuu, striving to create many wonderful memories with her.  Much to Harukas jealousy however, Yuus easygoing demeanor quickly attracts the attention of their female classmates. Sympathizing with her friends growing insecurity, Yuu ends up sharing a deep, affectionate kiss with her in an empty classroom. The act intensifies their bond as special friends, gradually revealing a different aspect to their unique friendship while also inviting new conflicts.', 35, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7243, 'Wizard Barristers: Benmashi Cecil', 2014, 12, 'TV', 70.1, 'The story takes place in Tokyo in 2018, where normal humans and those who can use magic coexist. As a result, there are laws against using magic, and a magic courtroom exists to preside over lawsuits regarding magic use. In these cases, Benmashi or wizard barristers defend those who use magic. The anime follows Cecil, the youngest Benmashi in history, and her associates as they defend clients in these cases.  (Source: ANN)', 97, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7244, 'Space☆Dandy', 2014, 13, 'TV', 76.7, 'Dandy is a groovy, pompadour-wearing man who explores the stars in search of strange aliens for money, desiring to visit his favorite place: BooBies, the best diner in all the cosmos. Traversing the galaxies in his trusty ship, the Aloha Oe, Dandy is accompanied by his two equally unique friends: QT, the vacuum cleaner robot, and Meow, an alien with a cat-like appearance.   Although exciting, Dandys job is never simple, and each new day promises a completely different, thrilling adventure. Together, Dandy and his crew get dragged into perilous journeys, misadventures in romance, and out of this world scenarios—all whilst steering clear of the evil scientist, Dr. Gel of the Gogol Empire.', 31, False, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7245, 'Obocchama-kun', 1989, 164, 'TV', 89.7, 'Based on the childrens award winning manga by Kobayashi Yoshinori, serialized  in Shogakukans CoroCoro Comic.', 58, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7246, 'Dotanba no Manners', 1984, 283, 'TV', 64.1, 'An introduction to etiquette through the hapless antics of Mr. Dotanba, who manages to put his foot in it in innumerable social situations.  (Source: ANN)', 38, True, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7247, 'Ijiwaru Baasan', 1970, 39, 'TV', 97.1, 'Based on a 1966 manga by Sazae-san creator Hasegawa Machiko.  This is another slice-of-everyday-life tale, centered around a spiteful old woman who causes trouble for neighbours with her constant bumbling and grumbling.  (Source: ANN)', 87, True, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7248, 'Ijiwaru Baasan (1996)', 1996, 46, 'TV', 63.9, 'Grandma is a nasty and manipulative thing most of the time, causing endless trouble for her son-in-law and daughter, her grandchildren, and her neighbours.  (Source: ANN)', 98, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7249, 'Doteraman', 1986, 20, 'TV', 64.6, 'In a small town of Tokyo there lives a middle-aged man, Suzuki, who spends commonplace days conducting a small business. He is ambitious to become such a celebrity as to appear on the cover page of a popular magazine.   One day he happens to discover a mysterious entrance that leads to an alien space. Through it he reaches the world of goblins and attaches control devices to goblins there to make them act at his free command. Capitalizing on those zombies, he grows outrageous and notoriously sets his hand to evil things. Meanwhile two witty pupils, Hajime and his girl friend Mariko, come across a strange alien detective who presents them with Doteraman garments. Wearing those garments, they transform themselves into Doteraman and Doterapink with supernatural strength. Then they challenge the wicked ruler and successfully liberate the poor goblins. They continue to fight in the cause of justice creating excitement and entertainment full of pleasure.  (Source: AniDB)', 81, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7250, 'Only You: Viva! Cabaret Club', 1998, 15, 'TV', 80.6, 'Based on a manga by Fujinami Toshihiko, serialized in Weekly Spa! between 1998 and 1999.   (Source: AniDB)', 41, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7251, 'Treasure Gaust', 2007, 5, 'TV', 94.9, 'Based on a set of toys called Treasure Gaust, the anime was based off of the manga serialized in corocoro with the main character being an anime original character.', 89, False, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7252, 'Furiten-kun', 1981, 1, 'Movie', 65.3, 'Based on the yonkoma manga by Ueda Masashi.', 95, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7253, 'Furiten-kun (1990)', 1990, 2, 'OVA', 86.7, 'Continuation of the everyday life adventures of the avid mahjong player Furiten-kun.', 73, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7254, 'Bokura Mangaka: Tokiwasou Monogatari', 1981, 1, 'Special', 79.6, 'Tokiwa was the apartment complex where a group of stellar artists lived in 1953.  Hiro Terada, Motoo Abiko and Hiroshi Fujimoto, Shotaro Ishinomori, and Fujio Akatsuka shared the trials and tribulations of being struggling young artists and writers with no money and no luck with editors or girls, with a spirit of insane youthful enthusiasm that enabled them to survive the lean years and emerge as stars of the manga firmament.  (Source: AniDB)', 25, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7255, 'Time Ranger Cesar Boy no Bouken: Roma Teikoku-hen', 1999, 1, 'OVA', 79.2, 'Based on the original story by Yasumura Ryou.', 71, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7256, 'Sore Ike! Anpanman: Tekka no Maki-chan to Kin no Kamameshidon', 2002, 1, 'Movie', 97.4, '14th Anpanman short movie.', 96, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7257, 'Gekisou! Rubenkaiser', 1977, 17, 'TV', 68.0, 'A race car driver competes around the world in a race car left to him by his father.  (Source: AniDB)', 63, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7258, 'Kotowaza House', 1987, 773, 'TV', 66.9, 'A public service proverb-of-the-week anime.  Peter the salary man lives a very unhealthy lifestyle, starving then bingeing until he feels seek, or slobbing around the house until badgered into taking up exercise, during which he invariably pulls a muscle.  (Source: ANN)', 68, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7259, 'Kappamaki', 2003, 130, 'TV', 64.8, 'Kappamaki and his sushi friends are cute-cool-charming characters who soothe your grating feelings and heal your weary heart. They are all adorable characters originally made with clay by Miss Eri Okamoto.  Kappamaki and the Sushi Kids are living in a small and peaceful village surrounded by unspoiled nature - flowers, fields, green forest with a crystal-clear river flowing through it. All the inhabitants including Kappamaki and his friends are naïve, honest and tenderhearted. There is a school, a park, houses, business offices and shops just like an ordinary small village anywhere. A friendly guy says that it is a typical Alpine village with the glamour of Paris and the atmosphere of Venice... Is it, really?! OK. Lets take a closer look... Oh, my goodness! The village looks as if it is made of sushi tools - The banks of the canals are sushi pails. The buildings are piled-up sushi baskets etc...  This series of animated shorts is full of humorous mishaps and heart-warming tales giving smiles and chuckles to everybody. They are also educational and entertaining describing friendship and kindness. So, please enjoy the mind-healing tales in this fantasy land.  (Source: AniDB)', 48, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7260, 'Tobidase! Machine Hiryuu', 1977, 21, 'TV', 67.6, 'The bosses of rival car companies decide to fight each other in the sporting arena by backing different race car teams. Chairman Gapporin hires Okkanabichi the supreme racer, while Chairman Misaki hires Riki Kazama, a relatively untried driver for the flying car known as Machine Hiryu. Mixing elements of Speed Racer with Time Bokan, this Tatsunoko production ticks the same boxes, with Rikis cute girlfriend Nana, mini-mechanic Chuta, the cute ape and pooch, and the comic and glamorous villains lurking in the background. Early work from many big names, including Yoshitaka Amano and Kunio Okawara, is strictly in the studio mould. Manga versions of the story ran in several magazines, such as Terebi Magazine and Terebi Land. Racing fever seemed to have struck the Japanese animation business at this time: compare to the same years Arrow Emblem.  (Source: The Anime Encyclopedia)', 91, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7261, 'Kariage-kun', 1989, 59, 'TV', 94.6, 'Based on the same name yonkoma manga by Ueda Masashi, serialized in Weekly Manga Action.  From putting his head of department to embarrasment by announcing to everyone that he has haemmorrhoids through the PA system in a public park to making a whole district dissapointed by putting a notice that there will be a fireworks display, and apparently the only display is him holding one small fireworks, Kariage-kun tells the amusing everyday life of, well, Kariage-kun.   His typical victim is his head of department, although anyone (or anything) can become a prey to his irony or sarcasm. The story began and ended with no special beginning or endings, but it is arranged chronologically (in the sense that it follows seasonal changes).  (Source: ANN)', 105, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7262, 'Lupin III: Princess of the Breeze - Kakusareta Kuuchuu Toshi', 2013, 1, 'Special', 81.3, 'The story is set in Shahalta, a tiny European city-state floating in the air with practically no contact with the outside world for years. The government is transitioning from a monarchy to a republic, and to celebrate the occasion, a national treasure exhibition is being held. Lupin infiltrates the exhibition for the secret royal treasures, but not before sky pirates snatch them first.  (Source: ANN)', 46, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7263, 'Kazu & Yasu Hero Tanjou', 1995, 1, 'Movie', 65.8, 'Based on the real life events. Biography animation depicting the football careers of Kazuyoshi Miura and his elder brother Yasutoshi.', 97, True, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7264, 'Wagahai wa Neko de Aru', 1982, 1, 'Special', 69.5, 'I is a cat without a name who lives with an English teacher, Mr. Kushami (Mr. Sneeze). I cant believe how stupid human beings are and chronicles some of their most incredible foibles. In particular, he is fascinated by Kushamis student Mizushima who falls in love with Haruko, the only daughter of businessman Kaneda.  Based on Natsume Sousekis comical novel.  (Source: The Anime Encyclopedia)', 97, True, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7265, 'Robokko Beeton', 1976, 50, 'TV', 87.3, 'When a boys uncle sends him confusing plans for a robot from America, the boy makes a mistake in the assembly which leads to unexpected results.  (Source: AniDB)', 91, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7266, 'Hana no Hi', 2005, 1, 'Movie', 80.0, 'A haptic animation with comfortable noses.  (Source: Official site)', 50, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7267, 'Ro-Kyu-Bu! SS Recap', 2013, 1, 'Special', 70.9, 'Recap of the first six episodes aired between episode 6-7. Also contains footage from Ro-Kyu-Bu!: Tomoka no Ichigo Sundae OVA.', 104, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7268, 'Pokemon: The Origin', 2013, 4, 'Special', 87.8, 'Pokémon are marvelous creatures that come in a variety of types and sizes, with abilities, powers, and personalities as diverse as they are numerous. Doctor Yukinari Ookido has dedicated his life to studying these fascinating beings, that can be caught, trained, traded, and battled against each other. Theres only so much he can do from his lab though. With this in mind, Ookido entrusts two young boys with a Pokémon of their own and a computerized encyclopedia to catalog them. One of them, Green, is brash, passionate, slightly arrogant, and Doctor Ookidos own nephew. The other boy, Red, is equally passionate, and filled with a wide-eyed, mildly naive sense of wonder.  Pokémon: The Origin follows Red in his journey through the region of Kanto in his attempt to complete his Pokédex by capturing and cataloging all the Pokémon that exist. Along the way hell discover theres more to himself and his goals than he originally thought. Red will have to put both himself and his Pokémon to the test in special Gyms whose leaders are steps along the way to the Pokémon League, in order to challenge the Elite Four and become a Pokémon League Champion.  Aside from his goals to become a Champion, Red has other problems brewing. There are others who capture and train Pokémon for more sinister reasons, with the infamous criminal organization Team Rocket being one of them. If Red can defeat them, fellow trainers, his rival Green, and wild Pokémon all through Kanto, he just may fulfill his own dream, and Doctor Ookidos as well.', 66, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7269, 'Mori no Senshi Bonolon', 2007, 26, 'TV', 81.0, 'Bonolon is touted as the warrior who comes from the forest of the great oaks. Despite his huge body size and outwardly orange appearance, Bonolon is only a child of 9 years old.   However, notwithstanding his tender age, Bonolon possess a strong sense of justice and strives to become a reliable man. The tears of those people who are depressed or troubled will flow through the roots of the great oaks and communicates their feelings to Bonolon. Bonolon will then appear from the great oaks and help the people solve their problems as well as grant their wishes.  (Source: ANN)', 13, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7270, 'Gamba to Kawauso no Bouken', 1991, 1, 'Movie', 64.3, 'The final chapter of the Gamba saga, released in theatres 15 years after the original TV series.  (Source: AniDB)', 13, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7271, 'Gin no Otoko', 1992, 1, 'OVA', 81.4, 'Based on the adult manga by Motomiya Hiroshi.', 22, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7272, 'Manga Ijin Monogatari', 1977, 46, 'TV', 60.8, 'From Genghis Khan to Thomas Edison, each episode in this series focuses on the life and achievement of two of historys greatest and most important persons.  (Source: ANN)', 54, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7273, 'Pa-Pa-Pa the ★ Movie: Perman', 2003, 1, 'Movie', 75.1, 'An origins and highlight film showing how Mitsuo met the alien that gave him the equipment to become a superhero (which for some reason was never explicitly shown in the two main anime, both just start with Mitsuo already having the powers), how he works together with the other Permans, and the rowdy fight with the antagonists.  Screened simultaneously with Doraemon Movie 24: Nobita to Fushigi Kaze Tsukai.', 111, False, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7274, 'Genei wo Kakeru Taiyou: Fumikomenai Kokoro', 2013, 1, 'Special', 80.9, 'Unaired 14th episode of Genei wo Kakeru Taiyou, broadcast on Nico Nico and included in the 4th Blu-ray and DVD volumes. It shows Akari and Fuyunas lives prior to the main series as well as how Luna got started as a magical girl.', 44, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7275, 'Boku no Son Gokuu', 2003, 1, 'Movie', 73.8, 'Son-Goku is a monkey who was born from a stone and is endowed with magical powers. He gets carried away and goes on a rampage until at last Buddha confines him within Mt. Gogyo. Saved by Sanzohoshi, Son-Goku accompanies him on a journey to India. But on their way, monsters lie in wait for them.  (Source: BakaBT)', 71, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7276, 'Ganbare Gonbe', 1980, 77, 'TV', 76.9, 'Based on the long running (1958 to 1992) gag manga by Sonoyama Shuji.  (Source: AniDB)', 62, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7277, 'Easy Cooking Animation: Seishun no Shokutaku', 1989, 25, 'TV', 82.1, 'Something like cooking contests in anime form. Approximately three minutes long per episode, in each story there is an evaluation judgement about preparing home food. The preparation is described as humorously as possible. Funny wordplays are often mentioned several times in a consequence and are particularly salient but are repeated in a merry way.  (Source: AniDB)', 82, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7278, 'Yama ni Kagayaku: Guide-ken Heiji Gou', 2012, 1, 'Special', 84.6, 'A short story about a mountain guide dog Heiji.', 68, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7279, 'Boku no Boukuugou', 2005, 1, 'Special', 78.4, 'The fourth film in Shin-Eis series of annual WWII themed anime television movies for children Sensou Douwa (war story).  (Source: AniDB)', 31, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7280, 'Minami-ke Natsuyasumi', 2013, 1, 'OVA', 98.2, 'Second Minami-ke OVA bundled with the 11th volume of the manga.  Chiaki, Kana, and Haruka decide how to spend their last few days of summer together.  Kana struggles to finish her homework.', 53, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7281, 'Shounen Tokugawa Ieyasu', 1975, 20, 'TV', 98.3, 'A historical tale of the early life of Tokugawa Ieyasu, who would eventually become shogun and establish the Edo Period in Japan.  (Source: AniDB)', 57, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7282, 'Umigame to Shounen', 2002, 1, 'Special', 71.1, 'The first film in Shin-Eis series of annual WWII themed anime television movies for children Sensou Douwa (war story).  (Source: AniDB)', 42, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7283, 'Yocchan no Biidama', 1999, 1, 'Special', 74.3, 'Based on the picture book by Kodama Tatsuharu.', 115, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7284, 'Makkuro na Obentou', 1990, 1, 'Movie', 71.5, 'On the 6th of August, 1945, an atomic bomb was dropped on the city of Hiroshima. A young boy, Shigeru, left home for his job as a building excavator that morning, carrying a bento made by his mother, only to never return home again. Before long, his mother managed to find Shigerus remains, and she noticed the completely black and carbonized bento box next to them.   This is an anime adaptation of the original book, Makkuro na Obentou (The Charred Lunchbox) written by Kodama Tatsuharu and illustrated by Kitajima Shinpei. The bento box that becomes the focus of the story is actually on display in the Hiroshima Peace Memorial Museum.  (Source: AniDB)', 119, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7285, 'Manga Kodomo Bunko', 1978, 51, 'TV', 70.9, 'A collection of childrens stories and tales from traditional Japanese folklore.  (Source: AniDB)', 109, False, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7286, 'Tonari no Tamageta-kun', 1974, 60, 'TV', 95.8, 'The adventures of a witless boy who finds a time machine hidden in a cave near his house. The 5 minutes episodes aired during the morning television show Ohayo Kodomo.  (Source: AniDB)', 23, False, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7287, 'Tako ni Natta Okaasan', 2003, 1, 'Special', 60.3, 'The second film in Shin-Eis series of annual WWII themed anime television movies for children Sensou Douwa (war story).  (Source: AniDB)', 39, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7288, 'Anime Document: München e no Michi', 1972, 16, 'TV', 68.0, 'A short series based on volleyball at the Munich Olympics. The series features a mix of live action blended with animation.  (Source: AniDB)', 14, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7289, 'Hana no Kakarichou', 1976, 25, 'TV', 76.5, 'A wacky comedy about a man from a noble ancestry of long ago, but who in modern times is just a lowly salary man that is constantly being humiliated by his family and co-workers.  (Source: AniDB)', 80, False, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7290, 'Manga Hana no Kakarichou', 1981, 1, 'Movie', 67.5, 'Based on the comedy manga by Sonoyama Shunji.', 19, False, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7291, 'Gatapishi', 1990, 199, 'TV', 89.5, 'Based on the comedy yonkoma manga by Sonoyama Shunji.', 109, True, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7292, 'W-Tails Cat: A Strange Presence', 2013, 7, 'ONA', 92.1, 'An animation based on Shirow Masamunes W-TAILS CAT art books.', 114, True, 92);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7293, 'Wooser no Sono Higurashi: Kakusei-hen', 2014, 12, 'TV', 60.0, 'Second season of Wooser no Sono Higurashi.', 99, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7294, 'Koroshiya-san: The Hired Gun', 2013, 10, 'TV', 75.4, 'The comedy story follows the title character, who is regarded by himself and others as the best hit man in Japan. He goes by the motto, If I have an assignment, I will kill anything. However, his killing assignments have expanded to include everything from summer vacation homework to housekeeping. The hit man never fails to kill the target. Though he does not aim to, he also never misses the laughter.  (Source: ANN)', 21, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7295, 'Gakkou no Yuurei', 1995, 6, 'OVA', 68.8, 'This OVA is a live-action/animation mixed collection of short school ghost stories.  (Source: AniDB)', 41, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7296, 'Zeonic Toyota Special Movie', 2013, 2, 'ONA', 87.1, 'Toyota Auris advertisement on Japanese television, featuring Char Aznable from Gundam series.', 117, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7297, 'Yamada-kun to 7-nin no Majo PV', 2013, 1, 'ONA', 77.9, 'Shiraishi Urara is the top student in her school. One day, due to an accidental kiss, Urara finds herself in the body of the school delinquent, Yamada Ryuu! In trying to switch back to their own bodies, Urara and Ryuu discover that kissing causes them to switch bodies, which leads to their discovery that there are 7 witches in their school. They soon try to uncover the identities of the 7 witches...  Promotional Video for the TV Series.  (Source: AniDB)', 77, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7298, 'Another: Misaki Mei - Shizukani', 2013, 1, 'Music', 84.7, 'An extended music video with minimalistic flash animation, featuring a chibi version of Mei. Bundled with the Complete Collection Blu-ray Box.', 46, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7299, 'Sekaiichi Hatsukoi Movie: Yokozawa Takafumi no Baai', 2014, 1, 'Movie', 72.1, 'Movie adaptation of the Sekaiichi Hatsukoi: Yokozawa Takafumi no Baai BL light novel.', 118, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7300, 'Jungle Taitei Movie', 1966, 1, 'Movie', 80.3, 'The first 2 minutes of this film are taken from the Jungle Emperor Leo (1965) TV series, while the rest is all original. Tezuka was very pleased that this film conveyed his story accurately, something he wasnt able to do with the TV series.   (Source: ANN)', 104, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7301, 'Baka Mukashibanashi Movie: Jijii Wars', 2013, 1, 'Movie', 76.5, 'Animated adaptation of old Japanese folk tales with the modern twists by Keiko Sootome.', 110, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7302, 'Eguchi Hisashi no Kotobuki Gorou Show', 1991, 4, 'OVA', 81.2, 'Based on the gag manga by Hisashi Eguchi.  Originally released as a feature part of Studio Pierrots video magazine show Anime V Comic Rentaman (アニメ・V・コミック レンタマン) along with Abashiri Ikka, Yumemakura Baku Twilight Gekijou and Akai Hayate.   (Source: AniDB)', 17, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7303, 'Hidamari Sketch: Chou Hidamatsuri Special', 2007, 1, 'Special', 95.1, 'A mini-episode/promo for Hidamari Sketch X 365 screened at the 2007 Chou Hidamatsuri in Nippon Budokan event, where the second season of Hidamari Sketch was announced.', 102, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7304, 'Kamisama no Inai Nichiyoubi: Kioku', 2014, 1, 'Special', 69.4, 'Episode 13 of Kamisama no Inai Nichiyoubi, included in the final Blu-ray/DVD volume of the series.  This bonus episode is separated into three parts.  In the first part, taking place before the characters reach Ostia, Ai and the others visit a hot spring.  In the second part, Alice remembers the times he killed his classmates and encounters Hampnie Hambart. A battle ensues.  In the third and final part, Hampnie dreams of when he first met Hana and is then woken up by Ai.  (Source: Wikipedia)', 74, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7305, 'Hoozuki no Reitetsu', 2014, 13, 'TV', 99.5, 'Hell is a bureaucracy, and business is running smoother than ever thanks to the demonic efficiency of Hoozuki, chief deputy to Lord Enma, the King of Hell. Whether offering counsel to the Momotarou of Japanese folklore or receiving diplomatic missions from the Judeo-Christian Hell, the demon who runs the show from behind the kings imposing shadow is ready to beat down any challenges coming his way into a bloody pulp. Metaphorically, of course...  The poster boy for micromanagement and armed with negotiation skills worthy of Wall Street, Hoozuki no Reitetsu follows the sadistic and level-headed Hoozuki as he spends his days troubleshooting hell. With an abundance of familiar faces from popular Japanese legends and East Asian mythology working middle management positions, this referential and anachronistic dark comedy brings new meaning to the phrase employer liability. Just how hard could it be to manage employees from hell, anyway?', 80, True, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7306, 'Meitantei Holmes: Mrs. Hudson Hitojichi Jiken no Maki / Dover Kaikyou no Daikuuchuusen no Maki', 1986, 1, 'Movie', 66.5, 'The second Meitantei Holmes movie featuring two episodes from the anime series.', 33, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7307, 'Watashi ga Motenai no wa Dou Kangaetemo Omaera ga Warui!: Motenaishi, Nazomeite Miru', 2014, 1, 'OVA', 65.0, 'The 13th episode of the TV anime bundled with the special limited first edition of the 7th manga volume.', 25, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7308, 'Mikosuri Han-Gekijou', 2013, 1, 'OVA', 95.2, 'Based on the same name gag yonkoma manga by Tenho Iwatani.', 56, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7309, 'Inari, Konkon, Koi Iroha.', 2014, 10, 'TV', 69.0, 'Frazzle-haired middle schooler Inari Fushimi is less than average; shes painfully shy and horribly clumsy, but despite all this, she is undeniably kind. Running about the winding streets of her hometown, she takes a shortcut through the local shrine and stumbles upon a small fox pup in a river. After rescuing him, she continues on, but from this moment on, her life takes a drastic turn.  Grateful for rescuing the pup, the shrine goddess Uka-no-Mitama-no-Kami, Uka-sama, grants Inari a fragment of her power. Now, Inari has the ability to transform into anyone by shouting the magical phrase Inari, konkon. Could this power also grant her the courage to convey her feelings to her crush, Kouji Tanbabashi? With her new heavenly ability and the fox spirit Kon, Inari forms a sincere friendship with Uka-sama, encounters more of the supernatural world, and learns that true love knows no bounds.', 107, False, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7310, 'Little Nemo Pilot (1987)', 1987, 1, 'Special', 74.6, 'Little Nemo: Adventures in Slumberland was released in American theaters in 1992. However, at one point earlier in its development many people from Studio Ghibli (Spirited Away, My Neighbour Totoro) had been involved with the project. In 1984 they produced a test pilot. In 1987, Osamu Dezaki directed a third one (as a very first one was made by Sadao Tsukioka in the mid-1970s).', 50, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7311, 'Himeyuri', 2012, 1, 'Movie', 95.8, 'The 30-minute film centers around a group of high school nurses called Himeyuri who served during the Battle of Okinawa during World War II.  The Himeyuri Alumnae Incorporated Foundation, which runs the Himeyuri Peace Museum in Okinawa, produced the film with the aim to convey the experiences of those high school nurses, many of whom lost their lives during the battle, to children.  (Source: ANN)', 78, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7312, 'Teekyuu 3', 2013, 12, 'TV', 69.3, 'Third season of Teekyuu series.', 108, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7313, 'Choujigen Game Neptune The Animation: Yakusoku no Eien - True End', 2014, 1, 'OVA', 63.6, 'Unaired episode 13 of Choujigen Game Neptune: The Animation, included in the 7th BD/DVD volume.', 32, False, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7314, 'Maji', 1990, 3, 'OVA', 79.3, 'Maji is a young hood in the Nagisa criminal organization whose name is synonymous with loyalty and truth. While driving away thugs, he meets and falls for local high school girl, Kumiko; however, complications ensue when he and his group run into the rival Kikuchi gang looking for trouble. Based on the first four volumes of the gang chivalry manga by Ayumi Tachihara.  (Source: ANN)', 98, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7315, 'Kimi to Boku', 2001, 1, 'ONA', 73.9, 'Kimi to Boku (You and I) is the story of an aspiring mangaka and his cat, told from the cats perspective. It follows the friendship between the cat and the young man from when they first meet up to when they must part.', 17, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7316, 'Noragami', 2014, 12, 'TV', 77.1, 'In times of need, if you look in the right place, you just may see a strange telephone number scrawled in red. If you call this number, you will hear a young man introduce himself as the Yato God.  Yato is a minor deity and a self-proclaimed Delivery God, who dreams of having millions of worshippers. Without a single shrine dedicated to his name, however, his goals are far from being realized. He spends his days doing odd jobs for five yen apiece, until his weapon partner becomes fed up with her useless master and deserts him.  Just as things seem to be looking grim for the god, his fortune changes when a middle school girl, Hiyori Iki, supposedly saves Yato from a car accident, taking the hit for him. Remarkably, she survives, but the event has caused her soul to become loose and hence able to leave her body. Hiyori demands that Yato return her to normal, but upon learning that he needs a new partner to do so, reluctantly agrees to help him find one. And with Hiyoris help, Yatos luck may finally be turning around.', 58, False, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7317, 'Fate/kaleid liner Prisma☆Illya 2wei!', 2014, 10, 'TV', 91.6, 'Another lovely summer goes by for Illyasviel von Einzbern. Taking a break from her magical girl duties, she enjoys her time off after collecting the Class Cards with her best friend Miyu Edelfelt.   However, her break comes to an abrupt end when she and Miyu are abducted by Rin Toosaka and Luviagelita Edelfelt, while out with her friends. The magical girls learn that their work is far from over, as Clock Tower informs them that the out of control mana thought to have been sealed continues to be dispersing throughout Fuyuki City. After heading to the origin point of the out of control mana, Illya and Miyu are tasked with solving the anomaly.   But after casting their spell, Illyasviel discovers that shes split into two people! As this mysterious new form darts off, she can only wonder: what is to come from the existence of her dopplegänger, running amok in the unsuspecting town?', 33, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7318, 'Little Busters! EX', 2014, 8, 'Special', 90.0, 'The main additions in Little Busters! Ecstasy are 3 heroine routes involving the characters Futaki Kanata, Sasasegawa Sasami and Tokido Saya.  The 3 EX heroines routes take place of the following:  Sayas route - Before the events of Refrain. Sasamis route - After the events of Refrain. Kanatas route - First half of her story is before Refrain and second half is after Refrain.  The episodes will be bundled with the BD/DVD releases of Little Busters!: Refrain.', 116, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7319, 'Harinezumi', 2012, 1, 'Music', 62.1, 'The music video to Hitomi Azumas single Harinezumi. A girl travels through an open, mysterious expanse in between bouts of melancholy glances.', 108, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7320, 'Z/X: Ignition', 2014, 12, 'TV', 67.1, 'The story is set in the not-so-distant future. Five Black Points suddenly appeared around the world as portals to parallel worlds. Immediately after, strange creatures began their invasion from these portals. These creatures are the inhabitants of five worlds—the same worlds in different timeframes. In order to ensure their own future timeframe survives, each of the five invasion forces battle to wipe the other future timeframes out. The key is one card-shaped device.  (Source: ANN)', 72, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7321, 'Nameko-ke no Ichizoku', 2013, 13, 'OVA', 67.8, 'It will be about the daily life of a big family of mushrooms living together.', 117, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7322, 'Mikakunin de Shinkoukei', 2014, 12, 'TV', 93.9, 'Just an ordinary teenager, Kobeni Yonomori receives quite the surprise on her 16th birthday—a fiancé and a sister-in-law she never even knew she had. As a result of an arrangement that her late grandfather made, Hakuya Mitsumine and his younger sister Mashiro have moved from their countryside home to the Yonomori household in order to deepen their relationship with their new family members.  Mikakunin de Shinkoukei follows Kobenis love life with Hakuya as she tries her best to adjust to the abrupt changes forced upon her. However, as some extraordinary secrets regarding the siblings come to light, Kobeni will find her life changed forever.', 17, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7323, 'Bayonetta: Bloody Fate', 2013, 1, 'Movie', 78.8, 'Driven to recover her memories after waking in a coffin at the bottom of a lake 20 years ago, Bayonetta hunts down the forces of Heaven day and night in search of clues to her forgotten past, and to uphold her pact with the demonic forces she draws her powers from as an Umbra Witch. She is armed and guided by the mysterious bartender and weapon-smith, Rodin, and following her every footstep is the intrepid journalist, Luka Redgrave, who believes that she has something to do with the death of his father and will stop at nothing to get the truth. Her quest takes a promising turn when she encounters a little girl named Cereza, but standing in her way is a rival Umbra Witch named Jeanne, who works for the very forces that she should be opposing.  Bayonetta: Bloody Fate is an action-packed anime film that explores the connection between all of characters and works to unravel just how they are seemingly entwined in a conspiracy that eclipses them all.', 66, True, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7324, 'Yuusha ni Narenakatta Ore wa Shibushibu Shuushoku wo Ketsui Shimashita. OVA', 2014, 1, 'OVA', 93.2, 'Rauls sister has come all the way from Rauls home village to see her brother who has become a hero. Raul and his fellow co-workers think its a better idea to trick his sister to thinking Raul is a real hero.  (Source: Wikipedia)', 11, True, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7325, 'Top wo Nerae 2! Kagaku Kouza', 2012, 3, 'Special', 97.1, 'Similar to the Gunbuster! Science Lesson these are short omake bonus features bundled on the Blu-ray Box Complete Edition of the Top wo Nerae 2! Diebuster.  Each short lasts around three minutes, and features super deformed versions of Nono, Lal`C Melk Mark and the Dix-Neuf explaining the various scientific aspects of the series.', 12, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7326, 'SoniAni: Super Sonico The Animation', 2014, 12, 'TV', 63.2, 'Super Sonico is a clutzy, adorable, and well-endowed 18-year old girl. Shes a complete sucker for anything cute, especially stray cats, all of which she giddily adopts. However, though Sonico should be enjoying a carefree and simple lifestyle as a young college student, her life is really anything but easy: she must balance being a professional model, working part-time at her grandmothers restaurant, and practicing guitar and performing concerts with her friends Suzu Fujimi and Fuuri Watanuki in their band, First Astronomical Velocity—all while attending college. SoniAni: Super Sonico the Animation follows Sonico as she faces daunting challenges in her search for her place in the world, even when her days are brimming with love and happiness.', 25, True, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7327, '11eyes Picture Drama', 2010, 13, 'Special', 93.8, 'Picture drama specials included on the seventh BD volume of the 11eyes series.  The stories focused on the Black Knights with jokes.', 85, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7328, 'Nekketsu Tantei Jimusho', 2013, 5, 'ONA', 69.0, 'It is year 40XX in the Universal Era. The story takes place on Jinmen planet which is quite far away in the universe.   This is a passionate tale about a human-faced dog and his troubled comrades.  (Source: Anime Bancho)', 94, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7329, 'Haikyuu!!', 2014, 25, 'TV', 61.2, 'Ever since having witnessed the Little Giant and his astonishing skills on the volleyball court, Shouyou Hinata has been bewitched by the dynamic nature of the sport. Even though his attempt to make his debut as a volleyball regular during a middle school tournament went up in flames, he longs to prove that his less-than-impressive height ceases to be a hindrance in the face of his sheer will and perseverance.  When Hinata enrolls in Karasuno High School, the Little Giants alma mater, he believes that he is one step closer to his goal of becoming a professional volleyball player. Although the school only retains a shadow of its former glory, Hinatas conviction isnt shaken until he learns that Tobio Kageyama—the prodigy who humiliated Hinatas middle school volleyball team in a crushing defeat—is now his teammate.  To fulfill his desire of leaving a mark on the realm of volleyball—so often regarded as the domain of the tall and the strong—Hinata must smooth out his differences with Kageyama. Only when Hinata learns what it takes to be a part of a team will he be able to join the race to the top in earnest.', 52, True, 9);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7330, 'Ashinaga Ojisan', 1979, 1, 'Special', 93.4, 'An orphan girl receives a scholarship for a prestigious school from an anonymous benefactor who she refers to as Daddy Long Legs.  Note: This TV special is not related to the 1990s series directly.  (Source: AniDB)', 65, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7331, 'Kyoufu no Kyou-chan', 1994, 7, 'TV', 83.4, 'A parody of Obake no Q-taro written by the comedian Hitoshi Matsumoto, the series is about a kid and his ugly critter (with a strange likeness with Butthead). You better not hurt the kid or Kyou-chan will grow arms on his head and feet on his mouth to rip off your guts!  (Source: TVTropes)', 89, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7332, 'Viva Namida', 2013, 1, 'Music', 74.6, 'Music video for Yasuyuki Okamuras song Viva Namida.  Its also a promo for Space☆Dandy, animated television series produced by BONES.', 102, True, 12);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7333, 'Kimi no Iru Machi OVA', 2014, 2, 'OVA', 74.5, 'The limited-edition of the 26th manga volume will include an anime adaptation of the popular special flashback chapter Uchi ga Kita Machi (The Town Where I Arrived). The story reveals how Haruto, Akari, and Takashi first met during childhood, and serves as a prologue to the TV anime.  The 27th limited-edition manga volume will include a special anime episode produced in full cooperation with Seo Kouji. This OVA will be the animation of the end of the manga. (Volume 27 is the final volume of the long-running series.)', 42, True, 13);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7334, 'Natsume Yuujinchou: Itsuka Yuki no Hi ni', 2014, 1, 'OVA', 71.9, 'As the first delicate snowflake touches the cold ground, Nyanko-sensei dozes on his hot-water bottle next to Takashi Natsume. While his aunt prepares a warm dinner, Natsume takes a walk, welcoming the snow and the chilly weather. However, his peaceful promenade is disturbed by a white, fluffy snowman yokai with perturbing black eyes, searching for something warm and sparkly. With no further information, Natsume sets off to help find what the spirit desires.', 73, False, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7335, 'Amnesia OVA', 2013, 1, 'OVA', 90.3, 'Animate Tokuten for purchasing all 6 volumes of TV Anime Series.  The contents of the OVA are from the Drama CDs.', 43, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7336, 'Zeonic Front: Kidou Senshi Gundam 0079 - Zeon no Hifun', 2001, 1, 'Special', 71.8, 'Short animated recap of the One Year War from the perspective of LCDR. Garret Schmitzer.   Included on the game disc of the Mobile Suit Gundam: Zeonic Front, a PS2 game by BANDAI.', 64, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7337, 'Shashinkan', 2013, 1, 'Movie', 98.3, 'The story takes place before WWII at a photo studio on top of a hill. Many people visit this studio to have their photos taken. One day, a couple comes, but the wife is so shy that she always lowers her head. The owner of the studio tries all kinds of tricks to get her to smile and eventually succeeds.  One year later, the couple comes again, but this time they bring their daughter along. She always looks grumpy, and again, the owner has to try everything to get her to smile. Thus starts a long-running relationship between the girl and the owner, and time passes to years and then decades...  (Source: MAL)', 91, True, 17);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7338, 'Hinata no Aoshigure', 2013, 1, 'Movie', 71.9, 'Hinata is very good at drawing and falls in love with his classmate, Shigure; however, Hinata is not good at talking to people, so he keeps his feelings in his imagination and drawings. Then, Shigures family decides to move to another town. On the day of their move, Hinata says to himself, I must tell her my feelings! and starts to chase after the train which is taking Shigure away.  (Source: MAL)', 23, True, 18);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7339, 'Hamatora The Animation', 2014, 12, 'TV', 72.0, 'The ability to create miracles is not just a supernatural phenomenon; it is a gift which manifests in a limited number of human beings. Minimum, or small miracles, are special powers that only selected people called Minimum Holders possess. The detective agency Yokohama Troubleshooting, or Hamatora for short, is composed of the Minimum Holder PI Duo, Nice and Murasaki. Their office is a lone table at Cafe Nowhere, where the pair and their coworkers await new clients.  Suddenly, the jobs that they begin to receive seem to have strange connections to the serial killer whom their friend Art, a police officer, is searching for. The murder victims share a single similarity: they are all Minimum Holders. Nice and Murasaki, as holders themselves, are drawn to the case—but what exactly is the link between Nice and the one who orchestrates it all?', 55, True, 19);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7340, 'Goannai Shimasu Another World e', 2004, 1, 'OVA', 88.9, 'Part of the series of educational videos that teaches kids and young adults several basic tax lessons.', 86, True, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7341, 'Baka Misérables', 2013, 3, 'ONA', 84.8, 'Baka Miserables follows the every day life of a family that goes into Les Misérables-style ballads for minor inconveniences or irks.', 75, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7342, '0', 2013, 1, 'Music', 76.1, 'This music video tells how a shy girl with a secret love and curiosity about what surrounds her works.', 94, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7343, 'Sabage-bu!', 2014, 12, 'TV', 88.0, 'On a train to her new middle school, Momoka Sonokawa is preyed upon by a molester, only to be rescued by a girl wielding dual pistols. The girl turns out to be Miou Ootori, Momokas upperclassman and president of the Aogiri Academys Survival Game Club, called Sabage-bu for short. Noticing Momokas aptitude with a pistol, Miou takes a liking to her and tries to persuade her to join the club. In spite of her steadfast refusal, Momoka inexplicably finds herself a member of Sabage-bu.  Sabage-bu is anything but a typical middle-school club. Its members socially awkward behaviors scare Momoka. Their personalities range from the fanatical to the completely delusional. They do not hold back from walking around public areas wearing ghillie suits or even bungee jumping from the school building. Thrown together with this collection of survival game maniacs, the zealously ordinary Momoka must somehow adjust to her unexpectedly wild school life.', 55, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7344, 'Mai Zhu', 2012, 1, 'Movie', 61.8, 'This short film was inspired by the story told in the prose written by Jia Pingwa to memorialize his father in 1989. Set on the North Shannxi Loess Plateau, the story tells about two boys trying to sell a pig, the only valuable property of the poor family, for food. However, things go wrong. The film was artistically designed to present the spectacular and broad scenery of the Loess Plateau as well as the simple life of the people.  This is a black humor about the difficult years in the northwest of China in 1970s.  (Source: Youtube, edited)', 62, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7345, 'Kyousou Giga (TV) Recaps', 2013, 2, 'Special', 65.7, 'Recaps of ONA (Episode 0) and 2013 TV Anime Series (Episode 10.5).', 115, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7346, 'Lies, Lies.', 2010, 1, 'Music', 87.1, 'Dreams Come Trues music video.', 38, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7347, 'Pokemon Best Wishes! Season 2: Decolora Adventure - Dent to Takeshi! Gyarados no Gekirin!!', 2013, 1, 'Special', 89.0, 'Dent and Takeshi! Gyaradoss Outrage!! is the first spin off of the Best Wishes series of the Pokémon anime.  (Source: Bulbapedia)', 31, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7348, 'Love Live! School Idol Project OVA', 2013, 1, 'OVA', 76.9, 'Bundled with the sixth single of the animes μs idol group.', 35, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7349, 'Ganbare! Lulu Lolo', 2013, 26, 'TV', 91.2, 'The new anime centers around the daily life of two twin bear sisters: the orange-colored Lulu and the yellow-colored Lolo. The two take on new jobs and despite the occasional failure and tears, give their best efforts.', 53, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7350, 'Noragami OVA', 2014, 2, 'OVA', 95.9, 'Hiyori Iki is excited to start high school alongside her two middle school friends, but Delivery God Yato seems to have other plans for the day. Will Hiyori be able to make a good impression on her first day? Or will Yato cost her a happy high school life?  On another day, Hiyori decides to take advantage of the beautiful weather and invites a number of people to gaze at the cherry blossoms, including the fearsome combat god, Bishamon. But how long will their blissful day last when Yato and his old rival Bishamon start to drink together?', 104, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7351, 'Mahouka Koukou no Rettousei', 2014, 26, 'TV', 75.7, 'In the dawn of the 21st century, magic, long thought to be folklore and fairy tales, has become a systematized technology and is taught as a technical skill. In First High School, the institution for magicians, students are segregated into two groups based on their entrance exam scores: Blooms, those who receive high scores, are assigned to the First Course, while Weeds are reserve students assigned to the Second Course.  Mahouka Koukou no Rettousei follows the siblings, Tatsuya and Miyuki Shiba, who are enrolled in First High School. Upon taking the exam, the prodigious Miyuki is placed in the First Course, while Tatsuya is relegated to the Second Course. Though his practical test scores and status as a Weed show him to be magically inept, he possesses extraordinary technical knowledge, physical combat capabilities, and unique magic techniques—making Tatsuya the irregular at a magical high school.', 52, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7352, 'Black Bullet', 2014, 13, 'TV', 87.1, 'In the year 2021, a parasitic virus known as Gastrea infects humans and turns them into monsters. What is left of mankind now lives within the Monolith walls, walls that are made of Varanium, the only material that can hurt Gastrea.  To counter the threat that the Gastrea pose, Cursed Children—female children whose bodies contain trace amounts of the virus which grant them superhuman abilities—officially called Initiators by the Tendo Civil Security, are given partners called Promoters, people who work to guide and protect the young Initiators. These teams of two are sent out on missions to fight the monsters created by the Gastrea virus and keep them at bay.   Black Bullet revolves around the team of Enju Aihara, an Initiator, and Satomi Rentaro, a Promoter, as they go on missions to fight the growing threat of Gastrea in their hometown of Tokyo.', 94, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7353, 'Sennen no Yakusoku', 2005, 1, 'OVA', 96.1, 'Part of the series of educational videos that teaches kids and young adults several basic tax lessons.', 91, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7354, 'Norman the Snowman: Kita no Kuni no Aurora', 2013, 1, 'Movie', 68.4, 'As the first snow falls on a town in the northern country, a boy sneaks out of his house to board a northbound train with his friend “Norman the Snowman.” They are off to witness the beautiful wonders of nature that Norman had always talked about.  (Source: JFF Plus)', 51, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7355, 'Maid of the Dead', 2013, 1, 'ONA', 87.0, 'Its just another normal day at a maid café until one of the customers turn out to be a zombie! Disrupting business and infecting some of the maids, everything suddenly descends into chaos as people are attacked. As one of the more experienced maids comes to deal with the unruly customer and newly-made zombie maids, perhaps theres a bright side to this unbelievable turn of events after all?', 49, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7356, 'Sekaiichi Hatsukoi: Valentine-hen', 2014, 1, 'Movie', 96.7, 'Animated short with an original story that was screened alongside Sekaiichi Hatsukoi Movie: Yokozawa Takafumi no Baai.', 15, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7357, 'Joshikousei Nobunaga-chan!!', 2010, 10, 'ONA', 99.9, 'The 16th-century shogun Oda Nobunaga wakes up in a high school girls body.', 100, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7358, 'Senki Zesshou Symphogear G: Senki Zesshou Shinai Symphogear', 2014, 2, 'Special', 98.2, 'Original short episodes featuring characters in super-deformed style.', 32, False, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7359, 'Seitokai Yakuindomo*', 2014, 13, 'TV', 97.8, 'They say that the more things change, the more they stay the same, and those words could not be more true for the student council of Ousai Private Academy. Though an entire year has passed—bringing the senior members to their final year of high school—not much has changed. President Shino Amakusa is just as perverted as ever, Secretary Aria Shichijou still refuses to put on a pair of panties, Treasurer Suzu Hagimura has yet to grow an inch, and Vice President Takatoshi Tsuda is still stuck as the straight man to their crazy antics.   Of course, limiting the fun to a four-way might get a little stale; although the group still messes around with the Judo Club and the Newspaper Club, more girls have come to get in on the excitement. Takatoshis sister Kotomi, a new student at Ousai, is as perverse as the president, while Uomi, the aloof student council president of the nearby Eiryou High School, fits right in with the insanity at Ousai. With loads of absurdity and sexual humor that keeps on coming, Takatoshi needs to harden up if he is going to keep up with all the madness around him.', 111, False, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7360, 'Hitsugi no Chaika', 2014, 12, 'TV', 93.2, 'For 500 years, the Taboo Emperor, Arthur Gaz, ruled the Gaz Empire with an iron fist and conducted inhumane experiments on his own people. But his reign came to an end five years ago, when mighty warriors—later known as the Eight Heroes—defeated him in a battle for the capital. His death ended the 300-yearlong war between the Gaz Empire and the alliance of six nations.  In the present day, Tooru Acura is a former saboteur from the war who has difficulty settling into the peaceful world, as he cannot find a job where he can put his fighting skills to use. An opportunity appears before him, however, when he meets a white-haired Wizard named Chaika Trabant. With a coffin on her back, she is searching for the scattered remains of her father in order to give him a proper burial, and she hires Tooru and his adoptive sister Akari to help her. However, the six nations alliance, which have now formed the Council of Six Nations, dispatches Albéric Gillette and his men from the Kleeman Agency to pursue and apprehend the late Emperor Gazs daughter—Chaika.  With the shocking revelation of Chaikas identity, the Acura siblings must choose between helping her gather the remains of the tyrannical emperor and upholding the peace the continent strives to maintain.', 108, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7361, 'Bacterial Contamination', 2012, 1, 'Music', 90.8, 'All it takes are those words to become the next victim. Ignored, slandered, and outcast, she has nowhere to turn. As their cruelty infects her, she begins to lose sight of herself. Her pain just will not go away, and as it consumes her whole being, she feels the only way to cleanse herself is to contaminate another.', 107, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7362, 'Nebula feat. Hatsune Miku', 2009, 1, 'Music', 86.3, 'Music video for the song Nebula by tripshots.', 18, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7363, 'Nulu-chan to Boku', 2012, 1, 'ONA', 89.8, 'A boy saves a strange, space-manipulating creature from certain death, but she doesnt seem to be grateful!', 51, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7364, 'Nissan Serena x One Piece 3D: Mugiwara Chase - Sennyuu!! Sauzando Sanii-gou', 2011, 1, 'Special', 84.5, 'Brook introduces the Thousand Sunnys while Luffy searches for his straw hat.  This was a special included in a limited edition DVD that was released in Nissan stores across Japan. The DVD also included the making of One Piece 3D: Straw Hat Chase.', 28, False, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7365, 'Hana no Zundamaru', 2013, 8, 'ONA', 99.8, 'Based on the Ninja Awate-maru comedy manga by Jirou Tsunoda.', 93, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7366, 'Music S.T.A.R.T!!', 2013, 1, 'Music', 84.1, 'Music video bundled with the sixth single of the anime-idol group μs.', 88, False, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7367, 'Kuro no Su: Chronus', 2014, 1, 'Movie', 92.3, 'For as long as he can remember, Makoto Nakazono has had the power to see grim reapers watching people shortly before their deaths and escorting their souls to heaven. He realized long ago that nobody would believe him if he talked about his ability. Since there is nothing he can do to alter peoples fates, he tries his best to pretend that he does not see anything out of the ordinary.  This all changes when a reaper at Makotos high school speaks to him and questions him why he never interferes. After learning that the reaper is there for his best friend, Hazuki Horiuchi, Makoto starts to wonder if he can defer her grim fate, even if only for a little while.', 14, False, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7368, 'JoJo no Kimyou na Bouken Part 3: Stardust Crusaders', 2014, 24, 'TV', 60.0, 'Years after an ancient evil was salvaged from the depths of the sea, Joutarou Kuujou sits peacefully within a Japanese jail cell. Hes committed no crime yet demands he not be released, believing hes been possessed by an evil spirit capable of harming those around him. Concerned for her son, Holly Kuujou asks her father, Joseph Joestar, to convince Joutarou to leave the prison. Joseph informs his grandson that the evil spirit is in fact something called a Stand, the physical manifestation of ones fighting spirit which can adopt a variety of deadly forms. After a fiery brawl with Josephs friend Mohammed Avdol, Joutarou is forced out of his cell and begins learning how to control the power of his Stand.  However, when a Stand awakens within Holly and threatens to consume her in 50 days, Joutarou, his grandfather, and their allies must seek out and destroy the immortal vampire responsible for her condition. They must travel halfway across the world to Cairo, Egypt and along the way, do battle with ferocious Stand users set on thwarting them. If Joutarou and his allies fail in their mission, humanity is destined for a grim fate.', 80, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7369, 'Harmonie', 2014, 1, 'Movie', 78.8, 'Akio Honjou is a high school student with a special gift for music. He can perfectly recall any piece of music that he has heard only once. One day, as he tries to reproduce a particularly soothing piano melody, he unexpectedly meets Juri Makina—the girl whose cell phone had spontaneously played the tune earlier in class.  If art is the only way to truly know what landscapes populate others inner worlds, then can this particular tune pave the way for Akio to begin to understand the more intellectual and emotional aspects of his captivating classmate, Juri?', 57, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7370, 'Ookii 1 Nensei to Chiisana 2 Nensei', 2014, 1, 'Movie', 64.4, 'First-grader Masaya is a crybaby despite his large stature, so he cant walk by himself on the dark path to school. The one who holds his hand is Akiyo, a tiny but capable second-grader.  Masaya wants to be strong like Akiyo and admires her, but one day, something happens that leaves Akiyo in tears.  To lift Akiyos spirits, Masaya goes trekking to the distant Ipponsugi forest to find the spotted bellflowers that Akiyo loves.  (Source: ANN)', 51, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7371, 'Kyoukai no Kanata: Mini Gekijou', 2014, 7, 'Special', 65.6, '1. Oniichan Daaisuki♥ 2. Mirai no Akarui Ikkakusenkin Keikaku 3. 20-dai Joshi, Koi Ooki Otoshigoro 4. Idol e no Michi! 5. Pajama Party 6. Gasshuku ni Ikou! 7. Haha Kara no Tegami', 44, True, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7372, '6♥Princess', 2013, 1, 'Music', 83.0, '6HP is a magical girl animation produced by Murakamis Ponkotan studio and features character designs by mebae. 6HP Six Hearts Princess Pink or Black is a promotional video for the series cosmetics, created by Shu Uemura. Music is by livetune and vocal is by Hatsune Miku.', 90, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7373, 'Diabolik Lovers Recap', 2013, 1, 'Special', 62.7, 'Recap of episodes 1-6 with new narrations.', 22, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7374, 'Galo Sengen', 2011, 1, 'Music', 97.9, 'Galo Sengen (Galish Man GAL in English / GAL男宣言 in Japanese) is a 2011 rap music video by the Japanese hip-hop group Policeman.  The animated music video became well-known for its humorous depiction of a Japanese youth culture known as Gyaruo, which is characterized by the dark tanned skin, dyed blond hair and appreciation for dance music.   In the video, a group of men are satirically portrayed as Super Saiyans, a type of superfighters from the Japanese manga franchise Dragon Ball, who transcend into the state of galish or gyaru, a slang term derived from the Japanese pronunciation of English word girl.  (Source: knowyourmeme)', 108, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7375, 'Oneechan ga Kita', 2014, 12, 'TV', 62.4, 'The story revolves around Tomoya Mizuhara, a 13-year-old boy who suddenly gains a big sister when his father remarries. 17-year-old Ichika is a little strange, and her affection for Tomoya is rather overwhelming, if not scary. On top of things, Ichikas friend Ruri is the ultimate sadist. Then there is Ichikas big-breasted quarter-Japanese friend Marina.  (Source: ANN)', 111, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7376, 'Ore no Nounai Sentakushi ga, Gakuen Love Comedy wo Zenryoku de Jama Shiteiru OVA', 2014, 1, 'OVA', 85.9, 'Unaired TV episode bundled with the light novels volume eight.', 48, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7377, 'Iron Kid', 2006, 26, 'TV', 92.1, 'In a futuristic world, young Marty stumbles upon a bionic arm which endows him with superhuman powers and put him at the centre of a centuries-old struggle between good and evil. His teenager heart will now begin a long-way training together with two loyal friends: Buttons, his robo-puppy, and the brave Ally.  (Source: Official website)', 91, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7378, 'DPR Special Movie', 2013, 1, 'Special', 83.8, 'An anime made for JAXA (Japan Aerospace Exploration Agency) and NASA (National Aeronautics and Space Administration) that promotes the GPM/DPR (Global Precipitation Measurement/Dual-frequency Precipitation Radar) space mission.', 80, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7379, 'Peeping Life: YouTuber-kun', 2013, 4, 'ONA', 71.6, 'YouTuber-kun meeting different YouTube celebrities.', 47, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7380, 'Parol no Miraijima', 2014, 1, 'Movie', 74.1, 'Rikotto, Zuzu, and Paroru are intelligent furry creatures who believe more than anything that the world outside their island is too dangerous to explore. Despite this, Rikotto and Zuzu long to see the world that produces the mysterious objects that wash up on their shores. After a particularly exciting find, Rikotto convinces Zuzu to build a boat, and they set sail across the sea with their reluctant friend Paroru in tow.  At first, the trio finds the foreign land beautiful and exciting, but they are overwhelmed when they come across a bustling city of humans. When Rikotto and Zuzu get captured by a circus ringleader who intends to put them on display, Paroru has to decide what fears he is willing to face for his friends.', 77, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7381, 'Shimajirou no Wow! Movie 2: Shimajirou to Kujira no Uta', 2014, 1, 'Movie', 65.0, 'No description available for this anime.', 51, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7382, 'Wonder Garden', 2013, 1, 'ONA', 88.1, 'A young girl is transported to a magical world by a storefront bear in this anime short by Studio Colorido.', 50, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7383, 'Tezuka Osamu no Buddha: Owarinaki Tabi', 2014, 1, 'Movie', 74.6, '2500 years ago, in India, Siddhartha was born as a prince of the Shakya clan, but he gives up his position as a prince to see the world. While he travels he meets a strange boy named Assaji, who can predict the future and a monk with only one eye. Overwhelmed by the sufferings he witnesses around him, Siddhartha strives to restore peace. Meanwhile, Prince Ruri of Kosara begins his attack on the Shakya clan.   (Source: IMDB)', 60, False, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7384, 'Kiniro no Corda: Blue♪Sky', 2014, 12, 'TV', 81.1, 'Soon after transferring to Seisou Gakuin, Kanade finds the orchestra club in the middle of preparing for the National concur. Teaming up with the other members, she will improve her skills, meet new rivals and create memories for what will become an unforgettable summer...  (Source: La Corda Doro Wikia)', 45, True, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7385, 'Sekai Seifuku: Bouryaku no Zvezda', 2014, 12, 'TV', 87.8, 'Asuta Jimon, a runaway, is wandering the streets at night when he has a chance encounter with a young girl collapsed beside her tricycle. After he offers her some food, she is moved by his kindness and asks him to join her organization, offering him a face mask and a sweet bun. In need of a place to stay, Asuta decides to play along and accepts her offer, adopting the nickname Dva.   Little does Dva know, this cute girl is Kate Hoshimiya, the leader of Zvezda, a secret organization bent on world conquest. However, he soon realizes the true weight of her words as peculiar happenings rope him deeper into Zvezda and its eccentric members—the samurai-like vanguard Itsuka Shikabane, tech-genius Natalia Natasha Vasylchenko, troublesome Yasubee Yasu Morozumi, ex-gangster Gorou Shikabane, and multi-purpose robot Roboko Tsujii.   With White Light, a powerful organization of justice, and the entire Japanese government against them, can Zvezda really dominate all humanity and let their light shine throughout the world?', 26, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7386, 'Seisenshi Dunbine Memorial', 1988, 3, 'Special', 72.4, 'Recaps of Aura Battler Dunbine originally released with the Aura Battler Dunbine OVA.', 34, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7387, 'Tonari no Seki-kun OVA', 2014, 1, 'OVA', 98.9, 'OVA of Tonari no Seki-kun bundled with the fifth manga volume.', 93, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7388, 'Yoza-Quar!', 2013, 6, 'Special', 74.2, 'Each of the six BD/DVDs will include one short. They will feature the characters in a slighly risqué light not seen in the main story.', 39, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7389, 'Mini Van Special', 2013, 1, 'Special', 73.5, 'A special episode released with the first DVD volume of Mini Vanguard.', 64, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7390, 'Sekai de Ichiban Tsuyoku Naritai! Specials', 2013, 6, 'Special', 73.4, 'Short specials included on the BD/DVD volumes of Sekai de Ichiban Tsuyoku Naritai!', 74, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7391, 'Marvel Disk Wars: The Avengers', 2014, 51, 'TV', 67.4, 'The story will revolve around how the Avengers—Iron Man, Captain America, Thor, and the Hulk together with the help of Spider-Man and a group of teens—will harness their respective fighting skills and superhuman powers to foil Lokis scheme to take over the world. Marvel Disk Wars: The Avengers will target boys in the 6-12 age group.  (Source: Marvel)', 104, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7392, 'Noonbory', 2009, 26, 'TV', 75.0, 'Having not only a narrator that enhances the educational aspect of the show, it also stars super seven heroes based on the five physical senses in addition to the two mental senses (nonsense and common sense). Noonbory (the main character) is considered to have the ability for common sense. The settings include the four seasons that make up the Technicolor world of Toobalooba.  The cast of villains include Wangury and his band of Bullygury pirates, a lonely girl named Rosygury and an abominable snowman named Coldygury that can throw snowballs from his hat when he is angry at somebory or somegury.  (Source: Wikipedia)', 63, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7393, 'Juugo Shounen Hyouryuuki: Kaizokujima de! Daibouken', 2013, 1, 'Movie', 95.2, 'The film is based on the Jules Verne novel Adrift in the Pacific: Two Years Holiday published in 1888. A group of youngsters find themselves adrift at sea, and after a terrible storm they are cast upon a deserted island, where they must learn to get along with each other in order to survive.   On this occasion, the human protagonists are replaced by cats.', 106, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7394, 'Chang', 2012, 1, 'Movie', 66.9, 'Sergeant Jeong Cheol-mins squad are staying indoors a corroded stockroom renovated without windows. His squad is well known for their hardworking members until councellor Hong Yeong-soo comes in. Jeong Cheol-min does all he can to make Hong Yeong-soo the right man for his squad and the army requires him to. However, private Hong Yeong-soo doesnt adjust to the surroundings and causes trouble.  (Source: Hancinema)', 89, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7395, 'Saibi', 2013, 1, 'Movie', 62.2, 'Who is good and who is evil? What is the boundary between them? An animated thriller about the tension between a good-hearted person speaking falsely and an evil-natured person speaking truthfully, and of those that surround them.  (Source: Hancinema)', 18, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7396, 'Precure All Stars Movie New Stage 3: Eien no Tomodachi', 2014, 1, 'Movie', 87.5, 'Pretty Cure All Stars New Stage 3: Eien no Tomodachi is the sixth of the Pretty Cure All Stars crossover movie series featuring all current Pretty Cure characters and the last of the New Stage film, including the 16th movie of all Pretty Cure movie series.  (Source: Pretty Cure Wikia)', 116, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7397, 'Seikoku no Dragonar', 2014, 12, 'TV', 80.5, 'Learning to ride and tame dragons comes easy to most students at Ansarivan Dragonar Academy—except for first-year student Ash Blake, who is known by his fellow classmates as the number one problem child. Poor Ash is the laughing stock at school because, despite his unfashionably large star-shaped brand that marks him as a future dragon master, he has nothing to show for it. His dragon has never appeared.  Until now, that is. One fateful day, Ashs dragon awakes in full glory, but appears different than any dragon ever seen before—in the form of a beautiful girl! Whats worse, Ash soon discovers that this new dragon has attitude to spare, as she promptly informs him that she is the master, and he, the servant.  Ashs problems with dragon riding have only just begun.  (Source: ANN)', 33, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7398, 'Uchuu Icchokusen', 2010, 1, 'Movie', 94.5, 'Can you share the yearning for space? An astronomy boy has grown up into an artist painting the universe, the world of Greek myths including the zodiac, and a variety of scenes with starry sky. The fulldome screen projects his fantastic CG movies. You will also see a live-action movie of the total solar eclipse in 2003 which was observed for the first time in human history in Antarctica. Receive a message from the artist, KAGAYA: Enjoy science and art. Chase your dreams!  (Source: KAGAYA Studio)', 78, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7399, 'Gatchaman Crowds Insight', 2015, 12, 'TV', 78.4, 'One day, a huge UFO spins over Japan and crashes into a rural farmland outside Nagaoka, disrupting Tsubasa Misudachis ordinary life. As the Gatchaman, the legendary defenders of Tachikawa City, supervise the ordeal, a peaceful alien creature emerges from the spacecraft. In the ensuing chaos, Tsubasa is given a special high-tech notebook, or NOTE, from Gatchaman founder J.J. Robinson, signaling Tsubasas sudden recruitment into their group. Under the tutelage of fellow hero Hajime Ichinose, Tsubasa slowly begins to adjust to life as a defender of justice.    Meanwhile, the CROWDS technology, which enables users to manifest their consciousness into a physical form, is spreading amongst the public, as well as being endorsed by Prime Minister Sugayama. However, a mysterious organization known as VAPE has gained notoriety by using unique red CROWDS to wreak havoc, shifting public opinion against the CROWDS technology. The Gatchaman, along with new recruit Tsubasa, must put a stop to their destructive activities before its too late.', 22, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7400, 'Follow Me', 2012, 1, 'Music', 92.7, 'A story about an unborn child who brought two unfortunate people together and gave them a second chance with a better future.  A beautiful alternative music video for Muses song Follow Me animated by Tekken.', 15, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7401, 'Ikemen Kyuugo-tai Nurse Angels', 2013, 10, 'TV', 66.6, 'Features 5 nurses working at the secret service at International Medical Center.  (Source: CDJapan)', 61, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7402, 'Mission School', 2006, 1, 'Music', 71.2, 'An animated music video for the song MISSION SCHOOL by MOKA☆.  The video was released on a limited edition DVD sold with their 2nd and 4th album.', 85, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7403, 'Yakusoku (ONA)', 2013, 1, 'ONA', 63.5, 'No description available for this anime.', 48, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7404, 'Strange+', 2014, 12, 'TV', 71.0, 'Kou comes to a slum neighborhood in search of his elder brother Takumi and finds him to have become the head of a private detective firm. Kou is drafted by Takumi to do errands and chores in the detective firm, and they come to meet various interesting people...  (Source: MAL News)', 68, False, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7405, 'Puchimas!!: Petit Petit iDOLM@STER', 2014, 74, 'ONA', 90.4, 'From the popular game THE IDOLM@STER, comes a petit spinoff cute and soothing 4-koma! The setting is the same 765 Production from the games.', 40, True, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7406, 'Hetalia: The Beautiful World Extra Disc', 2014, 1, 'OVA', 97.1, 'Unaired episode adapted from the manga chapter I Was Overwhelmed by Heroines.', 26, True, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7407, 'Kakumeiki Valvrave Recaps', 2013, 3, 'ONA', 90.5, 'Three edited ONAs that summarize Valvrave the Liberator 1st season were broadcasted on Nico Nico Live on September 20-22, 2013. They are also were included in BD and DVD limited edition volume one of Kakumeiki Valvrave 2nd Season.', 110, False, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7408, 'Yu Bang Xiang Zheng', 1984, 1, 'Movie', 95.6, 'Based on a story originally told by Su Dai in feudal China, a fisherman observes as a snipe and clam struggle over food.', 119, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7409, 'Witch Craft Works', 2014, 12, 'TV', 65.8, 'Even though they shared the same bus every morning and sat next to each other in class, Ayaka Kagari, the Princess of Tougetsu High School, was nothing more than an unreachable idol for Honoka Takamiya. The horde of students who worshipped the Princess was merely a nuisance to Honoka, living his lazy, regular high school life.  Everything seemed perfectly normal until, one day, Honoka is attacked out of the blue by a mysterious witch. To his surprise, Ayaka saves his life, revealing herself to be a fire witch on a covert mission to protect Honoka.  From that fateful day, the ordinary life of Honoka is turned upside down as he is thrown into the war between the Workshop Witches, who strive to protect the citizens, and the Tower Witches, who desire to steal a power hidden within him.', 61, False, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7410, 'Lost Forest', 2012, 1, 'Music', 82.7, 'An animated music video for the song Lost Forest by MOKA☆.', 10, True, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7411, 'Kenji no Trunk', 1996, 1, 'Movie', 63.2, 'An omnibus movie consisting of three stories by Miyazawa Kenji.', 106, True, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7412, 'Katta-kun Monogatari', 1995, 1, 'Movie', 64.3, 'An anime starring Katta-kun, a real-life pelican who inhabited the Tokiwa Park in Ube.  In this movie, Katta-kun befriends Sho, a little boy whose parents went off to the Middle East because of their work. When war breaks out, Sho and Katta-kun travel to the Middle East to save Shos parents and end the war.  Due to its hilariously ridiculousness this movie achived cult status in Japan.  (Source: AniDB)', 56, True, 92);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7413, 'Utopia', 2014, 1, 'Music', 71.8, 'Utopia is a song that was specially created for the True Tears x Hanasaku Iroha x Tari Tari Joint Festival Live featuring the seiyuu (voice actors) from the three series. P.A. Works produced a video of this song which is included in the the Blu-ray release of this event.', 86, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7414, 'Love Stage!!', 2014, 10, 'TV', 90.7, 'With an actress mother, producer father, and rockstar brother, anyone would expect Izumi Sena to eventually enter showbiz himself. However, aside from a commercial for a wedding magazine when he was a child, Izumi has never been in the spotlight; instead, he aims to become a manga artist.   But a decade after the shoot, the magazine calls for a 10th anniversary ad, requesting the original child actors for the project. This reunites Izumi with Ryouma Ichijou, now a popular actor who, much to Izumis shock, has been in love with him ever since their first meeting! However, due to Izumis feminine appearance and unisex name, Ryouma believed the boy was a girl and continues to do so to this day. Izumis troubles are just beginning, because even after discovering the truth, Ryouma cant seem to shake off his feelings...', 61, False, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7415, 'Buddy Spirits', 2013, 1, 'ONA', 93.1, 'In 202x, robots have become essential partner for humans. One day, a silver security robot went out of control regardless of its emergency shutdown and people were in panic. The robot military unit SARF established in the metropolitan police begins their mission!  (Source: Heros web)', 97, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7416, 'Heart Cocktail Again', 2003, 1, 'OVA', 64.4, 'An OVA produced to celebrate the 20th anniversary of Watase Seizous Heart Cocktail manga.  (Source: AniDB)', 74, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7417, 'Youtai Nuhai Zai Shanghai', 2010, 1, 'Movie', 77.3, 'Set mainly in and around the Shanghai Ghetto in Japanese-occupied Shanghai during the Second World War, the film tells the story of three children.   Rina and her younger brother Mishalli are Jewish refugees who escaped Europe but are without their parents. A-Gen is a Chinese boy who meets Rina and helps her and her brother to survive.   The children form strong friendships and have adventures as they try and fend off the Japanese army occupying the city, and their allies, the Nazis. In the background, the Second Sino-Japanese War takes place, while the children must face the uncertainty that concerns the fate of Rina and Mishallis parents in Europe.   (Source: AniDB)', 74, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7418, 'Wansa-kun OVA', 1989, 1, 'OVA', 92.3, 'Compilation OVA of the Wansa-kun series.  Reminiscent of Disneys Lady and the Tramp, this work depicts the friendship between Wansa, who looks for his mother, and his friends.   Wansa-kun was originally developed as the mascot character for the Sanwa Bank. The character was used for the TV series, and Tezuka Osamu was credited only as the writer of the original story.  (Source: AniDB)', 24, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7419, 'Oni no Ko to Yuki Usagi', 1995, 1, 'Movie', 88.1, 'One night a Goblin father came home gave his son a red handball. But the boy was shocked to hear that his father picked it up in front of the house of a girl called Yuki The boy decided to return it to her. Next morning, he ran in the snow to a village and saw many boys and girls  singing cheerfully. When he came to a small house, he saw a girl sitting alone on the veranda. She said, I am Yuki. Who are you?  He handed a ball to her without an answer. She was very glad and said  I was looking for it. My sickly mother made this for me.  Thank you very much.  That gave him relief and they become friends.  (Source: Kyowa Film)', 93, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7420, 'Escha & Logy no Atelier: Tasogare no Sora no Renkinjutsushi', 2014, 12, 'TV', 83.4, 'This world has gone through many Dusks, and is slowly nearing its end. Within this world, in the western reaches of the Land of Dusk, there was a nation that prospered thanks to its use of alchemy.   There, in order to survive the eventual arrival of the Dusk End, the people devoted their efforts to rediscover and recreate lost alchemic technologies. Rediscovered technology from the past era was gathered in the alchemy research city known as Central, where research was conducted on how to halt the advance of the twilight.   One of the heroes is a young man who researched alchemy in Central, the other a girl living in a small town on the frontier. This girls name is Escha. In the process of using her knowledge of ancient alchemy to help others, she was assigned to the Development Department. The young mans name is Logy. Having learned the newest alchemic techniques in Central, he requested a transfer to this understaffed town to make use of his abilities, and meets Escha when he is assigned to the Development Department as well. The two make a promise to use their alchemy together, and bring success to the Development Department.  (Source: Tecmo Koei Europe)', 36, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7421, 'Nobunaga the Fool', 2014, 24, 'TV', 70.9, 'Guided by her visions revealing the location of the King of Salvation, Jeanne Kaguya dArc flees with the polymath Leonardo da Vinci from the West Star to the East Star. There, she encounters Nobunaga Oda—the son of a local feudal lord who, following a brutal defeat dealt by an enemy clan, has sworn to conquer the world with his friends.  Quickly convinced that Nobunaga is indeed the King of Salvation, Jeanne pledges allegiance to the Oda clan. Meanwhile, King Arthur, the ruler of the West Star, sends his ruthless general Gaius Julius Caesar and his combat machine army to conquer Nobunagas planet and seize the Holy Grail. Although Kaguya believes that Arthur is the King of Destruction, the reckless behavior of Nobunaga The Fool—who named his own combat suit after his nickname—on the battlefield sows doubt in his capability as a leader.  With the help of Himiko, the Yamato Queen, Nobunaga and his clan must unify in order to overcome tragedies, recover from betrayals, and eventually save the world.', 102, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7422, 'Dragon Fist', 1991, 1, 'OVA', 70.7, 'The story follows Ling Fei-long, a Chinese transfer student living in Japan. Ling is the son of the leader of the White Dragon clan, one of four clans who live in the mountains of China and are descended from mythical beasts. After killing an ordinary human, Ling is banished to Japan so that he might learn about humanity and how to control his powers around them.', 113, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7423, 'Baby Steps', 2014, 25, 'TV', 72.3, 'Diligent and methodical honor student Eiichirou Maruo decides to exercise more during the little free time he has available because he is worried about his health. For this reason, after seeing a flyer, he joins the Southern Tennis Club at the beginning of his freshman year.  During his free trial at the club, he meets Natsu Takasaki, another first year student, who is determined on becoming a professional tennis player due to her love for the sport. In contrast, Eiichirous study-oriented life exists because he believes that it is what he has to do, not because he enjoys it. However, his monotonous days come to an end as the more he plays tennis, the more he becomes fascinated by it.  Baby Steps is the story of a boy who makes the most of his hard-working and perfectionist nature to develop his own unique playing style. Little by little, Eiichirous skills begin to improve, and he hopes to stand on equal footing with tennis best players.', 56, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7424, 'Wake Up, Girls! Shichinin no Idol', 2014, 1, 'Movie', 68.3, 'In Wake Up, Girls! Green Leaves Entertainment is in the worst situation any Talent Management Agency can be in... they have NO talent! Desperate for an act, President Junko Tange targets the idol singer market and gives her flunky Matsuda his marching orders: get a girl group to manage, even if it means building one from scratch!  Since complete singing groups rarely appear out of thin air, Matsudas now in the difficult position of having to find girls with the right skills who dont already have contracts with Japans music industry. That girl at the Maid Café? Good enough! A lead singer whos been fired from another group? Sure, why not? How about one whos only 13 years old? What could possibly go wrong there?  They may not be on the A-list, the B-List, or even the C-list to start, but with a little love and a whole lot of hard work, its possible that all Japan may someday wake up to the music of WAKE UP, GIRLS!  (Source: Sentai Filmworks)', 83, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7425, 'Soul Eater: Late Night Show', 2008, 51, 'Special', 82.7, 'Additional specials included in two Blu-ray Box volumes of Soul Eater.   Originally they were a part of late-night version of dual broadcast of Soul Eater; the regular Monday 6:00 p.m. version and a late-night Soul Eater Late Show version.  Special footage was added at the start and end of the commercial break; the next episode preview was also different from the regular version.  (Source: Wikipedia)', 36, True, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7426, 'Teekyuu 2 Specials', 2013, 2, 'Special', 82.7, 'Short specials included in the Blu-ray release.', 17, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7427, 'Zettai Shougeki: Platonic Heart Picture Drama', 2008, 4, 'Special', 73.7, 'Short picture drama specials included in BD/DVD volumes.', 49, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7428, 'Imanara Maniau! Log Horizon', 2013, 1, 'Special', 78.4, 'Recap of the first six episodes of Log Horizon, aired between episode 6-7.', 71, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7429, 'Kyoukai no Kanata: Idol Saiban! Mayoi Nagara mo Kimi wo Sabaku Tami', 2013, 5, 'ONA', 79.4, 'Akihito Kanbara finds himself in a courtroom and faces an unexpected jury for a peculiar lawsuit. Having turned into chibi idol versions of themselves, Mirai Kuriyama, Mitsuki Nase, and Sakura Inami are led by Ai Shindou to present incriminating evidence and deliver their dazzling verdicts.  However, Akihito is not the only one who is assigned a case. Pressed with varying charges, other characters of Kyoukai no Kanata stand trial and endure the comedic truth of their quirky habits.', 47, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7430, 'Takarajima Movie', 1987, 1, 'Movie', 86.7, 'A 88-minute theatrical recut of the original Takarajima TV series.', 103, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7431, 'Go! Go! 575', 2014, 4, 'TV', 68.1, 'Go! Go! 575 adapts the Project 575 games for PlayStation Vita and iOS, which allow anyone to create songs using the traditional Japanese 5-7-5-syllable meter found in haiku and tanka poems.  (Source: ANN)', 58, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7432, 'Gochuumon wa Usagi desu ka?', 2014, 12, 'TV', 95.4, 'Kokoa Hoto is a positive and energetic girl who becomes friends with anyone in just three seconds. After moving in with the Kafuu family in order to attend high school away from home, she immediately befriends the shy and precocious granddaughter of Rabbit House cafes founder, Chino Kafuu, who is often seen with the talking rabbit, Tippy, on her head.  After beginning to work as a waitress in return for room and board, Kokoa also befriends another part-timer, Rize Tedeza, who has unusual behavior and significant physical capabilities due to her military upbringing; Chiya Ujimatsu, a waitress from a rival cafe who does everything at her own pace; and Sharo Kirima, another waitress at a different cafe who has the air of a noblewoman despite being impoverished.  With fluffy silliness and caffeinated fun, Gochuumon wa Usagi Desu ka? is a heartwarming comedy about five young waitresses and their amusing adventures in the town they call home.', 72, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7433, 'Yawaraka Sensha', 2005, 53, 'ONA', 94.2, 'Yawaraka Sensha is a short flash movie series, with a strange soundtrack, about a soft and cowardly tank. It became popular on the Internet a few years ago because of its ironic message for the war.  (Source: AniDB)', 12, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7434, 'Yawaraka Atom', 2007, 7, 'ONA', 78.9, 'Yawaraka Atom, a parody of Astro Boy (Atom) as a squishy tank, went to stop catastrophe and evil.', 109, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7435, 'Sore Ike! Anpanman: Minami no Umi wo Sukue!', 1990, 1, 'Special', 77.0, 'No description available for this anime.', 50, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7436, 'Sore Ike! Anpanman: Shabondama no Purun', 2007, 1, 'Movie', 65.5, 'Anpanmans friends go see a bubble show performed by Shabondama-hime and her Shabondama Girls, who make exquisite bubbles by playing their flutes. One of the girls, Purun, cant make big bubbles no matter how much she rehearses. She feels inadequate as she goes to retrieve her lost flute, which Creampanda finds and goes to return. Meanwhile Baikinman takes over Shabondama-himes castle and steals the flutes, using their power to create evil bubbles, and Purun must realize her own importance and save the day with Anpanmans help.  (Source: ANN)', 56, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7437, 'Sore Ike! Anpanman: Tenohira wo Taiyou ni', 1998, 1, 'Movie', 79.7, 'No description available for this anime.', 13, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7438, 'Sore Ike! Anpanman: Yakisobapanman to Black Sabotenman', 2000, 1, 'Movie', 88.3, 'No description available for this anime.', 84, False, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7439, 'Trick or Alice', 2016, 1, 'OVA', 96.1, 'After a late-night conversation with her beloved brother, high school girl Arisa Minase wakes up the next day in a strange new land. She is greeted as Alice by twins known as Light and Shadow, who express their relief at Alices return home. Arisa is insistent that she is not the Alice they speak of, but the strange characters of this world are adamant that she is.  Upon meeting the kind and mysterious Black Rabbit, she learns that she is trapped in a place called Wonderland with no apparent escape. As she adjusts to her new reality, Arisa comes to find a whole host of peculiar creatures, such as the affectionate Cheshire Cat and the lazy dormouse Round.  But there is more to Wonderland than meets the eye. Each of the wild personalities she now shares a home with resembles someone she knew in her other life, yet not a single one of them recognizes their old name or relationships. Even stranger is the fact that time in Wonderland seems to never change, as every day is the same as the last. There appears to be no end to this cycle—beyond whatever secrets the Black Rabbit is keeping.', 90, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7440, 'Pupipo!', 2013, 15, 'TV', 85.7, 'Himeji Wakaba is a 5th year elementary school student, and she has the ability to see things that others cant. They are mostly frightening evil spirits, and they tend to do bad things to people who are close to her. As a result, Wakaba has no friends and rarely smiles. On a couple of occasions, she brings home stray animals, but her parents wont let her keep them. However, theyre worried about their sad, creepy daughter, so one day they decide that whatever Wakaba brings home next, theyll let her keep.  The next thing she brings home is a pink monster called Pupipo, but her parents stand by their decision and let her keep it. No one is quite sure what Pupipo is, but it protects Wakaba from the other things she sees. Pupipo also helps Wakaba make friends with an occult-obsessed transfer student and solve problems with bullying. Wakabas life is a much better place with her pet pink monster!  (Source: MangaHelpers)', 74, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7441, 'Isshuukan Friends.', 2014, 12, 'TV', 92.9, 'Sixteen-year-old Yuuki Hase finally finds the courage to speak to his crush and ask her if she wants to become friends. The object of his affection, Kaori Fujimiya, is a quiet and reserved girl who cuts herself off from everyone and does not spare him the same blunt rejection she gives everybody else.  Some time after, Yuuki finds her eating lunch on the roof where she secludes herself during break. He decides to start meeting with Kaori every day in the hopes of beginning to understand her better. The more time they spend together, the more she begins to open up to him. However, nearing the end of the week, she starts to push him away once more. It is then revealed to him the reason for Kaoris cold front: at the end of the week, her memories of those close to her, excluding her family, are forgotten, as they are reset every Monday. The result of an accident in middle school, the once popular and kind Kaori is now unable to make friends in fear of hurting the people dear to her.  Determined to become more than just one week friends, Yuuki asks her the exact same question each Monday: Would you like to be friends? Because he knows that deep down, Kaori wishes for that more than anything.', 17, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7442, 'Mushishi: Hihamukage', 2014, 1, 'Special', 72.1, 'The entire countryside comes to a halt midday to witness a rare solar eclipse that is rumored to allow the average person to see Mushi. Unable to avert their gaze, the air is full of awe and wonder—but those who know the Mushi are preparing for the eclipses aftermath.  Based on a prediction from Tanyuu Karibusa, the cursed recorder, Mushishi Ginko finds himself in a very unlucky farming village. Immediately following the solar eclipse, a strange black cloud begins to gather in the sky and blocks the sun once more. Suspecting it to be the work of a Mushi known as Hihami, Ginko seeks to liberate the village from perpetual darkness. However, it seems that not all of the villagers are eager to return to the light.', 55, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7443, 'Kazoku no Hanashi', 2013, 1, 'ONA', 77.4, 'The story follows a family of apple farmers: a mom, a dad, and their adoring son. The young boy idolizes his father and hopes to take part in the family business once he grows up. However, as he grows older and more rebellious, he begins to drift apart from his parents, trying to make it big in Tokyo as a musician. Meanwhile, his parents support him every step of the way, even when their son is absent, even when he is ungrateful, and especially when he begins to falter, all in spite of the struggles they are facing at the farm.  (Source: Rocket News 24)', 16, True, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7444, 'Double Circle', 2013, 6, 'ONA', 78.6, 'Double Circle means the community which evolves infinitely by the energy and ICT in the smart community project. People who live in Kawasaki become a hero, and beat an enemy who steals near from the time-stopped world to the evolving town Kawasaki.  (Source: Official website)', 98, True, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7445, 'Psycho-Pass Movie', 2015, 1, 'Movie', 95.2, 'Due to the incredible success of the Sibyl System, Japan has begun exporting the technology to other countries with the hope that it will one day be used all around the world. In order to test its effectiveness in a foreign location, the war-torn state of the South East Asian Union (SEAUn) decides to implement the system, hoping to bring peace and stability to the town of Shambala Float and keep the population in check.  However, a group of anti-Sibyl terrorists arrive in Japan, and the Ministry of Welfares Public Safety Bureau discovers significant evidence that the invaders are being aided by Shinya Kougami, a former Enforcer who went rogue. Because of their past relationship, Akane Tsunemori is sent to SEAUn to bring him back, but with their last meeting years in the past, their reunion might not go quite as planned.', 44, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7446, 'Tokyo ESP', 2014, 12, 'TV', 98.3, 'Rinka Urushiba works part time as a waitress to help out her unemployed father. By all accounts, her life in Tokyo is a relatively normal one—but her sense of normalcy begins to fade when she inexplicably sees a flying penguin one day. Chasing it all the way to the top of a building, she encounters more surprises, including flying goldfish and another person—a classmate named Kyoutarou Azuma—who can also see these strange things. After Rinka passes out when a goldfish phases through her, she wakes up an esper with the ability to phase her body through solid matter.  However, her newfound ability is not the only strange thing about her: when she uses her powers, her hair turns white. Deciding reluctantly to use this new gift to help the city, she becomes Tokyos new hero, dubbed the White Girl. Along with Kyoutarou, who gained the power of teleportation, Rinka begins righting the wrongs in the city while fighting other espers who have much less noble intentions.', 100, False, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7447, 'Freezing Vibration Specials', 2013, 6, 'Special', 70.4, 'Short specials included on the BD/DVD volumes of Freezing Vibration.', 18, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7448, 'Crayon Shin-chan Movie 22: Gachinko! Gyakushuu no Robo To-chan', 2014, 1, 'Movie', 72.6, 'Hiroshi got a slipped disk due to a back injury. He was taken to an Este salon by a mysterious beautiful girl who appeared suddenly, to receive a free trial of beauty treatment as well as a massage. When Hiroshi returned home after a beauty treatment, he was surprised to see himself in the form of a robot. Shinnosuke gets overjoyed, whereas Misae gets worried on seeing him as a naked robot. The robot version of Hiroshi turns out to be convenient. The robot Hiroshi could be controlled by a remote control and pretty much do anything including cooking and cleaning. Meanwhile, Hiroshi realizes that his turning into a robot has to do something with that Este salon. However, this new change was a dark conspiracy hatched by “Chichi Yure Doumei (The Association of Fathers)” to create a strong father figure for all the fathers in Japan. Soon, many dads in the whole nation go out of control, and the Nohara family (Shinnosukes family) and Kasukabe start falling apart. Before the near-collapse of Kasukabe, Shinnosuke and Hiroshi i.e. Robot dad stand up to save the day. Featuring the most intense battle of middle-aged men, the movie brings a touching story that makes all fathers and families in Japan cry.  (Source: Wikipedia)', 94, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7449, 'Bokura wa Minna Kawai-sou', 2014, 12, 'TV', 63.0, 'Kazunari Usa is a high school freshman who will start living alone due to his parents now working in a different area. Excited for his new independent life, he hopes to go about his teenage days without the worry of dealing with any strange people, but as he soon discovers, his new boarding house Kawai Complex is far from ordinary.  The various tenants at Kawai Complex are all quite eccentric characters. Shirosaki, Kazunaris roommate, is a pervert and masochist; Mayumi Nishikino, a borderline alcoholic office lady, hates couples because of her unfortunate luck with men; and Sayaka Watanabe, a seemingly innocent college student, enjoys leading men on. Shocked with the lack of decent individuals at his new residence, Kazunari is about to leave when he runs into shy senior student Ritsu Kawai and finds himself slowly falling in love with her.', 88, True, 9);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7450, 'Happiness Charge Precure!', 2014, 49, 'TV', 94.1, 'Some time ago, the opening of a box known as the Axia set loose the previously sealed members of the Phantom Empire into the world. Rising to protect humanity from these spiteful villains are warriors known as the Precure, whose heroic feats have garnered them celebrity status on television screens across the globe.  Hime Shirayuki, princess of the kingdom where the Axia was originally held, is one such warrior who transforms into Cure Princess to battle monsters summoned by the Empire. However, Himes timid personality often hampers her success in fending off the enemy. Frustrated with her hard luck and determined to find a Precure partner, Hime befriends Megumi Aino, a happy-go-lucky teenager. When a general of the Phantom Empire appears, Hime fails to do much in the face of his attacks. Intent on protecting her new friend, Megumi ignites her hidden potential—transforming into Cure Lovely.  With their sights set on protecting the world, Megumi and Hime form a new Precure team known as the Happiness Charge Precure whilst embarking on a journey to discover true love.', 18, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7451, 'The iDOLM@STER Cinderella Girls 2-shuunen Kinen PV', 2013, 1, 'Music', 65.1, 'No description available for this anime.', 23, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7452, 'Machine-Doll wa Kizutsukanai Specials', 2013, 6, 'Special', 93.3, 'Original animation to be included in the BD and DVD volume releases of Machine-Doll wa Kizutsukanai.  Volume 1: Soshite Futari wa Manabisha e (And So They Arrive at School) Volume 2: Irori, Rotenburo de Sosou suru (Irori Has an Accident at the Open-Air Bath) Volume 3: Char and Frey, Senritsu no Bathroom (Charl, Frey, and the Bathroom of Terror) Volume 4: Akabane Nadeshiko, Natsu no Yo no Yume (Nadeshiko Akabane, Midsummer Nights Dream) Volume 5: Kojin Jugyou: Imishitsu de Bijo Futari to~ (Private Lesson - Two Beauties in an Infirmary) Volume 6: Bishoujo Shuugou! Mizugi Darake no Daisoudou (Pretty Girls Gather! Swimsuit-Stubbed Pandemonium)', 22, True, 12);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7453, 'Detective Conan Movie 18: The Sniper from Another Dimension', 2014, 1, 'Movie', 93.6, 'One morning, at the observation deck of the Bell Tree Tower, a man is suddenly shot dead by an unknown sniper. Conan Edogawa, who happened to be visiting as the murder occurred, rushes to apprehend the sniper but fails to do so. He later learns that the suspect for the incident, Timothy Hunter, is a former member of the Navy Special Ops squad and was already being investigated for a previous murder case. The FBI believes that there are at least three people Timothy wants dead. However, after the deaths of two of them, Timothy himself is killed, throwing the investigation into disarray.  As they lose their only lead, news about the assassinations spreads across Tokyo, leaving the city in a state of panic. It is up to Conan to find and catch the culprit in the hope of putting an end to this sniping spree terror.', 18, True, 13);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7454, 'Mahou Shoujo Taisen', 2014, 26, 'TV', 90.1, 'Mahou Shoujo Taisen is a project created from a variety show for the Otaku 2.5 Chigen TV (2.5 Dimension TV). The characters are the mahou shoujo that represent each local town in Japan. The characters that won from the second illustration competitions that were held on pixiv will appear in the anime.  (Source: MAL News)', 51, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7455, 'Minna Atsumare! Falcom Gakuen', 2014, 13, 'TV', 85.0, 'Characters from various games released by Falcom (e.g. Dragon Slayer, The Legend of Heroes, and Ys series) come together in a school.', 41, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7456, 'Gokukoku no Brynhildr', 2014, 13, 'TV', 79.1, 'Venturing into the wilderness, the skeptical Ryouta Murakami and the ambitious Kuroneko were on a quest to prove the existence of extraterrestrial life when a tragic accident occurred, reaping Kuroneko of her life and leaving Ryouta in a critically injured state.  Ten years have passed since the disaster, and Ryouta is now living a normal life in high school. He vows to prove that aliens are real in honor of his late friend. A transfer student named Neko Kuroha unexpectedly arrives one day, bearing a striking resemblance to the late Kuroneko—even sharing a similar name. Most mysteriously, she seems to possess supernatural powers.  As Ryouta takes more interest in Neko, he is drawn into a deadly world where dangerous scientists hunt magic-wielding witches that have escaped from their secret research laboratory. Neko is one of these escapees, but there are many others who are in similar situations, and its up to Ryouta to protect them from their would-be captors.', 107, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7457, 'Chou Zenmairobo: Patrasche', 2013, 13, 'TV', 60.6, 'A parody of Flanders no Inu that has Parasche being a key-activated mecha robot who fights the antagonists.', 111, True, 17);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7458, 'Yama no Susume Second Season', 2014, 24, 'TV', 86.9, 'Continuing their treks through the high peaks of Japan, the mountaineering girls are back for more! First-year high school student Aoi Yukimura, a shy girl with a fear of heights, and her wildly energetic friend Hinata Kuraue set out once again to conquer the perils of backyard camping trips, summer homework, and even a climb on the mountain of their dreams. Joined by middle school student Kokona Aoba and their knowledgeable upperclassman Kaede Saitou, the squad members are ready to take on whatever slopes and challenges they might face, no matter how steep.   Through their shared hobby of mountain climbing, they bond closer than ever and even make new friends on trails all over the country. Whether it is just a local hill or the tallest mountain around, nothing is too much for Aoi and the crew to handle. They will climb, stumble, and rise to even greater heights together!', 32, True, 18);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7459, 'Buddy Complex', 2014, 13, 'TV', 77.9, 'When ordinary high school student Aoba Watase is suddenly targeted by a giant robot known as a Valiancer, he is saved by his mysterious classmate Hina Yumihara. After revealing that she and their robotic enemy are from the future, Hina suddenly propels Aoba 70 years forward in order to prevent his death.  Upon arrival, Aoba finds himself in the cockpit of a Valiancer called Luxon, stuck in the midst of a firefight between the military forces of the Free Pact Alliance (FPA) and Zogilia Republic. After he shows high compatibility with an FPA pilot named Dio Weinberg, the two perform a successful coupling, allowing them to share experiences and subsequently increase their capabilities and skills. Although Aoba is able to survive this unexpected battle, he is taken into custody by the FPA ship Cygnus, who wishes to interrogate him. While the students main concern is whether he will ever be able to return home, what he doesnt realize is that he is about to get caught up in a war to protect the world.', 86, True, 19);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7460, 'Uta no☆Prince-sama♪ Maji Love Revolutions', 2015, 13, 'TV', 74.9, 'The third anime adaptation of the otome game Uta no☆Prince-sama♪.  Starish are given new assignments in newly divided teams, and they do their best in order to try and impress Shining Saotome into allowing their entry to SSS, a top level music contest. Meanwhile, Haruka works with the Quartet Night.', 19, True, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7461, 'Meitantei Rascal', 2014, 12, 'TV', 69.8, 'Assistant Detective Rascal travels around the world with Uncle Po to check various mysteries.', 61, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7462, 'Nihonbashi Koukashita R Keikaku', 2012, 1, 'Music', 71.4, 'Music video for Jins seventh published song, created for IA Projects compilation album IA/01 -BIRTH-.', 117, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7463, 'Ikkyuu-san to Yancha Hime', 1978, 1, 'Movie', 67.3, 'Ikkyuu must talk a tomboy into behaving in a more lady-like manner before her habit of calling herself by the boys name Tsuyumaru and attacking shogun Yoshimitsu Ashikaga with a wooden sword gets her into trouble.  (Source: AniDB)', 86, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7464, 'Stand By Me Doraemon', 2014, 1, 'Movie', 82.5, 'Nobita Nobi is an elementary student who hates studying, is bad at sports, and does everything half-heartedly. He is a pushover, unlucky, and fearful of many things. His personality makes him a failure in life, even affecting his progeny. This causes his great-great-grandchild, Sewashi, to take control of the situation.  Sewashi travels back in time from the 22nd century to the 20th century to meet Nobita, who is shocked to see him appear out of his drawer alongside a blue robotic cat. The robotic cat calls himself Doraemon, who claims to have been pressured by Sewashi to assist Nobita, with their ultimate goal being to provide Nobita happiness. Frustrated after seeing Nobitas hopeless state, Doraemon decides to go back to the future. However, Sewashi activates a program within Doraemon that prevents him from doing so.   Forced to stay, Doraemon helps Nobita using futuristic gadgets through his four-dimensional pocket—a bag containing anything inside it. Can Doraemon bring Nobita happiness and return to the future?', 52, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7465, 'Mirai Koushi Harima SACLA', 2013, 1, 'ONA', 70.5, 'The Japanese research lab SACLA has released a short anime titled Future Photon Harima Sakura to promote their X-ray Free Electron Laser (X-FEL), the brightest x-ray source in the world.  As described on her official webpage, the feature character Harima Sakura is a G4-type Picodroid, a living entity with self-learning and evolutionary capability. She can shrink down and dive into the world of atoms, invisible to the human eye, known as the Pico Universe. Her athletic ability is very high. In cooperation with a variety of researchers and scientists, she explores the world inside atoms with a strong sense of justice.  (Source: MAL)', 49, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7466, 'Persona 3 the Movie 2: Midsummer Knights Dream', 2014, 1, 'Movie', 88.5, 'As the season changes from spring to summer, Makoto Yuuki remains alongside the Specialized Extracurricular Execution Squad (SEES). The team continues to defeat Shadows large and small, but they now clash with a new enemy: Strega, a group of rogue Persona users who wish to keep the Dark Hour to their advantage—it seems that Strega may hold a clue to the Dark Hours true nature.  While SEES enjoys summer vacation in Yakushima, they are joined by Aegis, an amnesiac android designed to destroy Shadows. While she proves herself to be a powerful ally, she is inexplicably drawn to Makoto and constantly remains at his side. As they delve deeper into the mysteries of the Dark Hour, the nature of the mysterious connection that binds these two together is slowly unveiled.', 57, False, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7467, 'Ikkyuu-san: Haru Da! Yancha Hime', 1981, 1, 'Movie', 82.8, 'Ikkyuu must help the princess once again as she doesnt have any table manners. Without them she wont be able to attend the plum blossom viewing party.', 106, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7468, 'Metal Fight Beyblade Zero G Specials', 2013, 7, 'Special', 86.4, 'The last seven unaired episodes of Metal Fight Beyblade Zero G released on DVD volumes 6 and 7 of the series.', 17, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7469, 'Sanchoume no Yuuhi', 1990, 27, 'TV', 60.7, 'Based on the same name slice of life manga by Saigan Ryouhei.', 18, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7470, 'Dokkan! Robotendon', 1995, 26, 'TV', 72.3, 'No description available for this anime.', 16, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7471, 'Shin Dokonjou Gaeru', 1981, 30, 'TV', 75.6, 'Continuation of Dokonjougaeru series.', 74, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7472, 'Shin Dokonjou Gaeru: Dokonjou Yumemakura', 1982, 1, 'Movie', 92.6, 'After Hiroshi daydreams about marrying Kyoko, his chauvinistic behavior puts a strain on his relationship with his closest of friends.', 103, False, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7473, 'Ninjaman Ippei', 1982, 13, 'TV', 62.2, 'Way out in the sticks, the fourth-graders of the local school in Tokio village all have their own superpowers of doubtful merit, including flying eyeballs and missile-hair. Ippei and his friends study hard to be ninjas, but they are constantly under treat from the arrogant cheats from the neighbouring village of Techno.  A strange mix of ninjas and school comedy, based on a childrens manga by Kawai Kazuyoshi.  (Source: ANN)', 75, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7474, 'Ninja Hattori-kun: Nin Nin Ninpo Enikki no Maki', 1982, 1, 'Movie', 96.6, 'Short Ninja Hattori-kun movie. Screened as a triple feature with Doraemon: Nobita no Daimakyou and Kaibutsu-kun: Demon no Ken.', 29, False, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7475, 'Shounen Sunday CM: Denpa Kyoushi', 2012, 2, 'Special', 69.2, 'Two short anime clips, produced by A-1 Pictures and serving as promotion for the manga.  (Source: Wikipedia)', 110, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7476, 'Sengoku Musou SP: Sanada no Shou', 2014, 1, 'Special', 90.8, 'The story of the special revolves around the Sanada brothers in their youth. Nobuyuki and Yukimura swear to each other to protect the influential Sanada clan. However, thinking of how to best continue the Sanada clan, Yukimura makes a decision, and meets with Mitsunari Ishida and Naoe Kanetsugu at the location he arrived at. On the other hand, his elder brother Nobuyuki must worry about the selfish demands made by the Tokugawa clan.  (Source: ANN)', 109, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7477, 'Soul Eater NOT!', 2014, 12, 'TV', 80.8, 'Soul Eater NOT! is a spin-off and side story that takes place one year prior to the events of the original Soul Eater. At the Death Weapon Meister Academy, humans born with the power to transform into weapons and those with the power to wield these weapons (Meisters) train to hone their natural talent. The characters of the main series are enrolled in the Especially Advantaged Talent class, where they train to become warriors of justice capable of defeating what threats prey on innocent lives—or even the entire world.  Other students at the DWMA are less talented. Members of the Normally Overcome Target class focus less on being warriors of justice and more on controlling their powers so they dont hurt themselves or anyone around them. Tsugumi Harudori, a new halberd-transforming student, meets Meisters Meme Tatane and Anya Hepburn and quickly grows indecisive about which of the two new friends should be her partner. As they learn to use these powers and settle in, their lives as everyday students will be far from normal.', 34, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7478, 'Trip Trek (2010)', 2010, 8, 'ONA', 71.4, 'More short stories featuring Zocco and Minime.  The series received the first airing starting November 10, 2010. On June 10, 2013 five episodes were released on YouTube.', 61, False, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7479, 'Kantai Collection: KanColle', 2015, 12, 'TV', 79.7, 'With the seas under constant threat from the hostile Abyssal Fleet, a specialized naval base is established to counter them. Rather than standard naval weaponry, however, the base is armed with Kanmusu—girls who harbor the spirits of Japanese warships—possessing the ability to don weaponized gear that allows them to harness the powerful souls within themselves. Fubuki, a young Destroyer-type Kanmusu, joins the base as a new recruit; unfortunately for her, despite her inexperience and timid nature, she is assigned to the famous Third Torpedo Squadron and quickly thrust into the heat of battle. When she is rescued from near annihilation, the rookie warship resolves to become as strong as the one who saved her.', 16, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7480, 'Soratobu Usagi no Yuukai Boushi: Boku Iya da yo!', 1990, 1, 'OVA', 86.0, 'An educational anime designed to prevent child abduction.  (Source: AniDB)', 74, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7481, 'Baku Tech! Bakugan Gachi', 2013, 39, 'TV', 96.8, 'BakuTech! Bakugan Gachi is the sequel to the BakuTech! Bakugan series.', 29, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7482, 'Geba Geba Shou Time!', 1986, 1, 'OVA', 83.3, 'Based on original story by Kinoshita Renzo.', 114, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7483, 'Oraa Guzura Dado', 1967, 52, 'TV', 77.5, 'A comedy about a kind but slow-witted dragon who appears from a nearby volcanic eruption. People find Guzura quite charming and interesting as he can consume metal and change it into useful devices.  (Source: AniDB)', 20, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7484, 'Hentai Ouji to Warawanai Neko.: Henneko BBS', 2013, 13, 'Special', 89.3, 'Specials that were initially broadcasted as CMs starting in January 2013 and later included in BD/DVD volumes.', 65, True, 44);
