INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7713, 'Uchuu Kyoudai: Number Zero', 2014, 1, 'Movie', 82.0, 'Prequel to the TV anime series revolving around the origin of the dream.', 66, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7714, 'Nukko.', 2012, 24, 'TV', 62.4, 'The new Nukko. anime is an adolescent school story revolving around Nukko and Nukkos slightly(?) oddball friends.  (Source: ANN)', 74, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7715, 'Patalliro Saiyuuki! Special', 2006, 1, 'Special', 97.4, 'Unaired episode 27 of Patalliro Saiyuuki! that was included in the 5th DVD volume.', 70, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7716, 'Potecco Babies (2011)', 2011, 12, 'ONA', 72.8, 'Anime about potato characters continues.', 66, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7717, 'Kimezou no Kimarimonku Ja Kimaranee.', 2010, 12, 'ONA', 73.0, 'Follows the story a flamboyant Kimezou who works for a company that makes star shaped confections.', 105, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7718, 'Kimezou no Kimarimonku Ja Kimaranee. Featuring Sabu-Otoko', 2011, 12, 'ONA', 75.4, 'Follows the story of young employee of a company that produces star-shaped confections. The unusual man views society cynically and does not fit typical Japanese competitive male stereotypes.   He has to contend with a variety of coworkers including the flamboyant Kimezou, the company president, and the presidents daughter.  (Source: ANN)', 74, True, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7719, 'Ahiru no Pekkle no Sindbad no Bouken', 1993, 1, 'OVA', 86.2, 'Pekkle re-creates the Adventures of Sinbad.', 105, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7720, 'Kero Kero Keroppi no Ganbare! Keroppooz', 1992, 1, 'OVA', 87.5, 'Kerropi and his friends are hectored when they have fun in the playground. Both of them agree to have a baseball competition. During the exercise, Junk quits the team because of their argument. Will they lose finally?', 66, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7721, 'Ahiru no Pekkle no Suieitaikai wa Oosawagi', 1993, 1, 'OVA', 92.7, 'A new boy moves into Pekkles town, and is trying his hardest to impress Lucy; however, Lucy isnt interested in him. Lucy makes Pekkle out to be a better swimmer than he really is, and the new boy challenges him to a swimming contest.', 32, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7722, 'Patty & Jimmy no Kimikoso Superstar', 1994, 1, 'OVA', 76.4, 'Jimmy is having trouble with pitching a baseball; Patty finds a way to encourage Jimmy to do better.', 46, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7723, 'Ahiru no Pekkle no Aladdin to Mahou no Lamp', 1993, 1, 'OVA', 85.4, 'Pekkle re-creates the story of Aladdin and His Magic Lamp.', 80, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7724, 'Kero Kero Keroppi no Yowamushi-ouji no Daibouken', 1993, 1, 'OVA', 65.8, 'Keroppi is blamed for the tomfoolery of others during a movie. As he runs home crying he is struck by lightening and transported to another world--just like in the movie! There he meets a cowardly prince and the both of them go on adventure to learn about courage and sticking up for oneself.', 18, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7725, 'Kero Kero Keroppi no Kero Kero House no Himitsu', 1993, 1, 'OVA', 96.2, 'On a rainy day Keroppi and friends find their elders old secret club house. But the house ends up being more magical than they thought.', 95, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7726, 'Pochacco no Wakuwaku Birthday', 1993, 1, 'OVA', 63.2, 'Its the day before Pochaccos birthday and hes skateboarding around looking for his friends. He hopes to have a grand party with them the next day, but they all seem busy!', 51, True, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7727, 'Kero Kero Keroppi no Tomodachitte Ii na', 1992, 1, 'OVA', 62.0, 'A new kid moves to town for a short stay with his father. Hes really good at playing the ocarina but difficult to befriend. A bird likes to listen to his music and when a storm arrives they all help the bird by placing it and its nest into a bird house; this helps them all form an everlasting friendship as he moves once again.', 117, False, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7728, 'Ahiru no Pekkle no Hihou wo Sagase', 1993, 1, 'OVA', 84.3, 'Pekkle and his friends find a treasure map that will lead them to a stone that will grant one wish, and they go on a treasure hunt.', 76, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7729, 'Pochacco no Ninjin Hata wa Oosawagi', 1993, 1, 'OVA', 91.4, 'Pochacco and friends open up a carrot land together. One day, they find that all carrots are stolen by someone. Because of this event, they start to suspect each other. Who is the thief?', 44, False, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7730, 'Kero Kero Keroppi no Dai Bouken', 1989, 1, 'OVA', 89.1, 'When Pocapons belly button gone missing, Keroppi, Den Den, and Ruby go to find it as without it he is unable to play the drums.', 33, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7731, 'Santa-san to Tonakai Kuppi', 1992, 1, 'OVA', 72.8, 'Santa is having a race to determine the ten reindeer who will pull his sleigh that year. Kuppi is a young reindeer who wants more than anything to pull Santas sleigh, and he enters the race.', 98, True, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7732, 'Peeping Life: Tezuka Pro - Tatsunoko Pro Wonderland', 2013, 10, 'OVA', 92.0, 'An incarnation of the Peeping Life franchise covers Tezuka anime characters and Tatsunoko Production anime characters such as Princess Sapphire and Casshern.', 90, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7733, 'Peeping Life: Tezuka Pro - Tatsunoko Pro Wonderland Specials', 2013, 2, 'Special', 76.3, '2 bonus episodes done as a part of the 100th Anniversary campaign video collaboration with Universal Studios. Episode 1 features E.T. and episode 2 features Jaws.', 74, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7734, 'Peeping Life: Tezuka Pro - Tatsunoko Pro Wonderland ONA', 2013, 4, 'ONA', 76.8, '4 Peeping Life: Tezuka Pro - Tatsunoko Pro Wonderland episodes that did not make it to the official DVD.', 51, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7735, 'Kero Kero Keroppi no Tomodachi ni Narou yo', 1994, 1, 'OVA', 85.0, 'Wink is a lovely snake. He is Keroppis friend. Keroppi wants to introduce Wink to his other friends. His friends deem Wink is a dangerous animal. Will they accept him finally?', 33, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7736, 'Kero Kero Keroppi no Tomodachi wa Mahoutsukai', 1993, 1, 'OVA', 71.8, 'Keroppis friend who is a magician comes to visit. But a trio of bad frogs was following him and steals a bunch of presents. The magician decides that he must fight them with his own strength.', 59, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7737, 'Kero Kero Keroppi no Bikkuri! Obakeyashiki', 1996, 1, 'OVA', 82.4, 'Keroppi receives a letter from a friend who is scared of an abandoned house in his new town. He and the gang go and visit him to help him feel more comfortable and overcome his fears. While exploring the house they run into some robbers and an apparition that doesnt seem to be what it is.', 64, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7738, 'Kero Kero Keroppi no Kyouryuu ga Deta', 1992, 1, 'OVA', 62.0, 'While playing hide and seek, Keroppi and the gang find some dinosaur bones. With the village elder they dig out more and put the bones back together and find out it was a baby dinosaur. In the nearby museum there is a mama dinosaur on display and as night falls the baby dinosaurs skeleton comes to life in search of its mother. The gang tries to help it reunite it and the cries of the baby dinosaur skeleton animate the mamas skeleton. Once together again their souls ascend to heaven and both skeletons become displayed lovingly at the museum.', 14, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7739, 'Kero Kero Keroppi no Sora wo Tobetara', 1994, 1, 'OVA', 90.2, 'While playing with a kite, a bird is injured during its migration. The gang seeks help from a local pilot to help the bird make its journey.', 112, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7740, 'Kero Kero Keroppi no Soratobu Yume no Fune', 1992, 1, 'OVA', 61.5, 'Keroppi and friends get special tickets to ride a flying ship at night to look at the constellations. Whether they dreamt the same dream or encountered it for real is up interpretation.', 101, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7741, 'Kero Kero Keroppi no Sanjuushi', 1991, 1, 'Movie', 60.0, 'Keroppi version of The Three Musketeers.', 15, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7742, 'Kero Kero Keroppi: Hasunoue Town Kiki Ippatsu!', 2006, 6, 'TV', 89.3, 'No description available for this anime.', 49, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7743, 'Kero Kero Keroppi no Mitsubachi Daisoudou', 1993, 1, 'OVA', 77.1, 'No description available for this anime.', 32, True, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7744, 'Shin Seikimatsu: Yatsuto no Souguu', 2013, 5, 'ONA', 67.3, 'In the corner of the universe, there was a small planet where creatures called men flourished. Doomsday finally looms near to this planet where destruction and creation have occurred repeatedly. The great king of terror appears from the sky and the mankind faces the end.  Encounters with that kind is Director Yutaro Sawadas original stop motion animation.  (Source: Anime Bancho)', 113, True, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7745, 'One Piece: Cry Heart', 2014, 3, 'Special', 76.4, 'Episode 1: Fuyujima ni Furu Sakura  Diligent animators took Banprestos One Piece Cry heart ~Fuyujima ni Furu Sakura~ (One Piece Cry heart ~The Cherry Blossoms That Fall on Winter Island~) line of crane game prize figures and created a five-minute stop-motion short. The short recreates the famous Hiluluks Cherry Blossoms scene from Eiichiro Odas manga and anime One Piece.   Episode 2: Fuyujima ni Furu Sakura  A stop-motion animated video for Banprestos One Piece Cry heart ~childrens dream~ line of crane game prize figures. The short recreates the famous Oath of Brothers scene from Eiichiro Odas manga and anime.  Episode 3: Ace no Saigo  (Source: ANN)', 11, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7746, 'Seiken Tsukai no World Break', 2015, 12, 'TV', 97.8, 'Seiken Tsukai no World Break takes place at Akane Private Academy where students who possess memories of their previous lives are being trained to use Ancestral Arts so that they can serve as defenders against monsters, called Metaphysicals, who randomly attack. Known as saviors, the students are broken up into two categories: the kurogane who are able to use their prana to summon offensive weapons and the kuroma who are able to use magic.  The story begins six months prior to the major climax of the series during the opening ceremonies on the first day of the school year. After the ceremony is over, the main character, Moroha Haimura, meets a girl named Satsuki Ranjou who reveals that she was Morohas little sister in a past life where Moroha was a heroic prince capable of slaying entire armies with his sword skills. Soon afterwards he meets another girl, Shizuno Urushibara, who eventually reveals that she also knew Moroha in an entirely different past life where he was a dark lord capable of using destructive magic but saved her from a life of slavery. Can those whose minds live in both the present and the past truly reach a bright future? Delve into the complex world of Seiken Tsukai no World Break to find out!', 92, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7747, 'Momoya x Peeping Life: Go en desu yo! II', 2013, 5, 'ONA', 91.9, 'A continuation of last season as Shiromeshi-kun continues his attempts at dating and finding refuge in Momoya food toppings.', 105, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7748, 'Kuroko no Basket 2nd Season NG-shuu', 2014, 9, 'Special', 79.9, 'Animated bloopers, based on the extra section of the original manga series, included with the BD/DVD series for Kuroko no Basket Second Season (both limited and normal editions).', 81, False, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7749, 'Peeping Life: Gekijou Original-ban', 2009, 5, 'Movie', 61.8, 'The Peeping Life comedy anime series spawned five shorts for Japanese theaters. Each of the five shorts was running on the lobby monitors in T-Joys theater chain for two weeks before being replaced by the next short. In Tokyos Shinjuku Wald 9 cinema complex the shorts were run on the complexs actual theater screens. They were then included in the Peeping Life: The Perfect Emotions DVD release.', 84, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7750, 'Appleseed Alpha', 2015, 1, 'Movie', 68.2, 'Set in a different series of events, this story does not follow the previous Appleseed movie canon (despite being directed by the same director of the previous movies); it is an alternate story to their beginnings. Briareos is already a cyborg and did not become separated from Deunan to be later reunited in Olympus to join ESWAT.  Appleseed Alpha depicts the early days of Deunan Knute and Briareos in the 22nd century, as they embark on a journey throughout dystopic ruins of New York in search of the city of Olympus. They are hired by Two Horns, the warlord of the ruined city, to eliminate bipedal combat machines. During the fight, they encounter Iris and Olson, both on a mission. Deunan and Briareos befriend them and decide to join their mission.  Iris is tasked with preventing the malevolent cyborg Talos from capturing a secret weapon humans were building. Talos uses Iris to activate the gigantic war machine.  (Source: Wikipedia)', 111, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7751, 'Shiroishi no Yousei Pichi', 2011, 3, 'ONA', 67.6, 'Short promotional videos made for Shiroishi City in Miyagi Prefecture.', 22, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7752, 'Terra Formars', 2014, 13, 'TV', 98.6, 'During the 21st century, humanity attempted to colonize Mars by sending two species which could endure the harsh environment of the planet to terraform it—algae and cockroaches. However, they did not anticipate the species remarkable ability to adapt. Now in the 26th century, a lethal disease known as the Alien Engine Virus has arrived on Earth, and the cure is suspected to be found only on Mars. The problem is, Mars in the present is overrun by creatures known as Terraformars, incredibly powerful and intelligent humanoid cockroaches that mutated from those originally sent to the planet.   The Annex I team, consisting of a hundred men and women genetically enhanced with characteristics of powerful organisms from earth, has been sent to Mars on a mission to find the cause of the Alien Engine Virus and to help cure humanity—signalling the start of the crews fight for survival.', 75, False, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7753, 'Terra Formars: Bugs 2-hen', 2014, 2, 'OVA', 97.2, 'Adaptation of the Bugs 2 arc of the manga.', 72, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7754, 'Lady Jewelpet', 2014, 52, 'TV', 85.3, 'Momona is an ordinary junior-high school student hailing from Jewel Land. At her cousins wedding, she envies the bride, Lady Diana, due to the fact that she is marrying the cousin who she had a slight crush on. However, once she sees Lady Diana and her cousin together, Momona begins to like her, and accepts her as her cousins bride. Just as Lady Diana is about to properly meet her and introduce herself, Momona is transported to a snowy place in Jewel Land where the ruler, Lady Jewel, is giving a speech to the Petit Ladies, girls who are chosen as Jewel Candidates to be the next Lady Jewel. Momona meets her partner and mentor, Ruby, a white rabbit, who will guide her through the tasks in becoming Lady Jewel. Whoever passes the most tasks wins and becomes the next Lady Jewel, but standing in her way is Lillian, a girl who also aims to win the title of Lady Jewel, so she can choose her brother, Cayenne, to be her King alongside her. Momona soon also begins to fall in love with Cayenne, yet Lillian doesnt want her to get too close to him. Cayenne also seems to harbor feelings for Momona, but who will be chosen in the end as Lady Jewel to decide it all? And will Momona and Lillian ever become true friends and will Cayenne and Momona ever be together?  (Source: Wikipedia)', 110, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7755, 'Dragon Ball Z: Summer Vacation Special', 1992, 1, 'Special', 72.5, 'One peaceful afternoon, the Son family and friends are spending the day out on the town shopping in West City. Meanwhile, two strangers enter the city and begin causing havoc, destroying nearly everything in their path. As the Son family is eating, the building theyre in is suddenly attacked, as it turns out the two are after Son Goku. When Goku sees that innocent people are being attacked in his name, he becomes furious. Trunks comes to Goku’s aid, and the two lead the artificial humans out of the city. As the battle is moved elsewhere, Goku and Gohan, now dressed in white tuxes, return and land in West City.  The two proceed to show clips and highlights from the preceding Dragon Ball and Dragon Ball Z movies. Goku of course doesnt much like being all dressed up, and by the end he powers up to change back into his typical dōgi. Gohan tries to do the same, but isnt powerful enough to get out of his tux. Goku says he’ll get there someday, and Gohan tells everyone to be sure to go see “Extreme Battle!! The Three Great Super Saiyans” in theaters.  (Source: Kanzenshuu)', 100, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7756, 'Dragon Ball Z: Zenbu Misemasu Toshi Wasure Dragon Ball Z!', 1993, 1, 'Special', 99.2, 'In this film, which is believed to take place some time around the 25th World Martial Arts Tournament, Gohan and Goten are having a hot bath outside in the middle of winter. Goku (who is still dead) suddenly appears in front of his sons with the help of his Instant Transmission, and joins them in the tub. While there, the three Saiyans reflect back on the events that occurred during the Cell Games. Inside the house after Chi-Chi appeared, Goku tells his sons about Pikkon and the Other World Tournament.  Later, the four members of the Son family appear dressed nicely. Gohan says that the adult division of the Tournament will begin this next year (in 1994), and the special comes to an end.  (Source: Dragon Ball Wikia)', 93, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7757, 'Zettai Zetsumei Dangerous Jiisan (2005)', 2005, 19, 'TV', 86.7, 'The third series of Zettai Zetsumei Dangerous Jiisan with the gags continuing on.', 102, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7758, 'Wazaguu! vs. Dangerous Jiisan Ja: Houfukuzettou! Anime Quiz', 2012, 1, 'OVA', 72.1, 'A crossover OVA featuring Wazabo Saishuushou: Wazaguu! and Dangerous Jiisan Ja.', 21, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7759, 'Aldnoah.Zero', 2014, 12, 'TV', 82.2, 'The discovery of a hypergate on the Moon once allowed the human race to teleport to Mars. Those who chose to settle there unearthed a technology far more advanced than that of their home planet, which they named Aldnoah. This discovery led to the founding of the Vers Empire of Mars and a declaration of war against the Terrans, those who stayed behind on Earth. However, a battle on the moon—later called Heavens Fall—caused the hypergate to explode, destroying the moon and leading the two planets to establish an uneasy ceasefire.  Their peace was a fragile one, however. Fifteen years later, high school student Inaho Kaizuka witnesses the plotted assassination of the Vers Empires Princess Asseylum Vers Allusia, who had come to Earth in hopes of repairing the relationship between the empire and its homeland. The ceasefire is shattered, and the Martians declare war on the Terrans once again. In the face of this insurmountable enemy, Inaho and his friends must now fight against the Vers Empire to settle the war once and for all.', 105, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7760, 'Dragon Collection', 2014, 51, 'TV', 82.4, 'Through an unexpected turn of events, an ordinary elementary school student, Hiro Enryuu, finds himself in the world of the Dragon Collection game. This is a world called Dragon Earth, where gods, humans, and monsters exist side by side. Those who roam this world using a magic book, called a Grimoire, and cards to summon monsters and search for treasures that bear the powers of dragons are called Dracolle Battlers. Despite his bewilderment, Hiro becomes a Dracolle Battler and, together with the friends he meets there, begins his adventure to become a legendary Dragon Master!  (Source: Crunchyroll)', 65, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7761, 'Oreca Battle', 2014, 51, 'TV', 60.9, 'The anime adaptation revolves around a young boy named Faiya Orega who loves Oreca competitions. One day, he is granted the power to summon real Oreca monsters due to the mysterious powers of the treasure chest Pandora. To protect the peace of the Oreca world, Faiya must fight the demon king who threatens the land.  (Source: Crunchyroll)', 115, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7762, 'Brothers Conflict: Setsubou', 2014, 1, 'Special', 87.3, 'Ema finds a special lamp that her father left for her. Ema and the brothers rub the lamp to find that something peculiar happens in front of them.  (Source: ANN)', 58, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7763, 'Chikasugi Idol Akae-chan', 2014, 12, 'TV', 62.9, 'Based on the upcoming Underground Princess idol role playing game for mobile devices.', 88, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7764, 'X Maiden', 2014, 8, 'ONA', 84.3, 'In 20XX C.E., a mysterious alien race named Firow suddenly appears on Earth. The Firows dreadful attacks force humanity to engage in a difficult battle. But humanitys last hope, the X Maiden who wear weapons built to destroy the Firow, are about to set out.  (Source: ANN)', 116, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7765, 'Toaru Kagaku no Railgun S: Daiji na Koto wa Zenbu Sentou ni Osowatta', 2014, 1, 'OVA', 83.8, 'Bundled with the official visual book.', 38, True, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7766, 'Kara no Kyoukai Movie: Mirai Fukuin - Extra Chorus', 2013, 1, 'Special', 97.1, 'Mikiya Kokutou gives Shiki Ryougi a cat to watch, as he will be away for a little while. Though Shiki protests, he leaves the cat anyway, and Shiki is stuck trying to understand her new feline companion. But as luck would have it, the cat seems to have taken a liking to Mikiya and misses him.  Later in another part of the city, Ririsu Miyazuki visits the place where her dear friend committed suicide. She intends to end her life as well, but she meets Fujino Asagami, a blind classmate with a traumatic past. Though the two girls dont have much in common, Asagami reminds Miyazuki of her lost friend and helps her understand her pain.  Two months later, Mikiya elects to celebrate New Years with Shiki instead of his family, which makes his sister Azaka very upset, leading to her spending the holiday with her school friends. As the snow begins to fall, Mikiya reflects on what he wishes for most of all: that Shikis life be filled with happiness.', 94, True, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7767, 'Dragon Ball Kai (2014)', 2014, 61, 'TV', 70.4, 'Remastered version of the Majin Buu saga that adheres more to the mangas story.', 95, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7768, 'Sono Hanabira ni Kuchizuke wo: Risa x Miya Gekijou', 2012, 10, 'ONA', 67.7, 'Short picture episodes with Risa and Miya from Sono Hanabira ni Kuchizuke wo visual novel series.', 43, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7769, 'Barakamon', 2014, 12, 'TV', 86.3, 'Seishuu Handa is an up-and-coming calligrapher: young, handsome, talented, and unfortunately, a narcissist to boot. When a veteran labels his award-winning piece as unoriginal, Seishuu quickly loses his cool with severe repercussions.  As punishment, and also in order to aid him in self-reflection, Seishuus father exiles him to the Goto Islands, far from the comfortable Tokyo lifestyle the temperamental artist is used to. Now thrown into a rural setting, Seishuu must attempt to find new inspiration and develop his own unique art style—that is, if boisterous children (headed by the frisky Naru Kotoishi), fujoshi middle schoolers, and energetic old men stop barging into his house! The newest addition to the intimate and quirky Goto community only wants to get some work done, but the islands are far from the peaceful countryside he signed up for. Thanks to his wacky neighbors who are entirely incapable of minding their own business, the arrogant calligrapher learns so much more than he ever hoped to.', 86, True, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7770, 'Sora Iro Hana Iro', 2005, 1, 'Movie', 98.3, 'A woman and a dog go on a spiritual journey and undergo a spiritual transformation while wandering in a forest side-by-side.  Sora Iro Hana Iro is not a straight-forward narrative story, but rather series of subjective impressions to tell us more about the state of mind of the female protagonist.  (Source: Nishikata Film Review)', 105, True, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7771, 'Kindaichi Shounen no Jikenbo Returns', 2014, 25, 'TV', 80.2, 'High school student Hajime Kindaichi is the supposed grandson of famous private detective Kosuke Kindaichi. Visiting Hong Kong for a fashion event with Kindaichi, our heros girlfriend Miyuki is captured by a stranger in a case of mistaken identity. The journey to save Miyuki itself leads to yet another crime case...  (Source: YTV)', 98, True, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7772, 'Aikatsu! Movie', 2014, 1, 'Movie', 97.1, 'The story of the anime revolves around Ichigo, who was just a normal middle school student until she suddenly got involved in the world of idols. The film will center on Aikatsu!s greatest Super Live concert yet, the Dai Star Miya Ichigo Matsuri. Ichigo prepares for the concert with press conferences, last-minute lessons, and more.  (Source: ANN)', 85, True, 92);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7773, 'Himitsukessha Taka no Tsume EX', 2014, 38, 'TV', 97.5, 'Sequel to the previous season of the flash anime series.', 110, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7774, 'Magical★Taruruuto-kun Movie', 1991, 1, 'Movie', 92.1, 'First movie of Magical Taruruuto-kun', 61, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7775, 'Abarenbou Rikishi!! Matsutarou', 2014, 23, 'TV', 96.9, 'Matsutarou Sakaguchi is a giant roughneck man with strength far beyond ordinary people. He never uttered words like work hard, strive, and dream like the typical shounen manga protagonist. However, he is stronger than anyone and peerless in sumo wrestling. His greatest weakness is his own carefree personality. He grows into a full-fledged sumo wrestler.  (Source: ANN)', 35, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7776, 'Himegoto', 2014, 13, 'TV', 67.0, 'Constantly on the run from loan sharks, Hime Arikawa has to deal with the debt left over from his parents lousy spending habits, which they left under his name. Fleeing in a maid outfit forced upon him by the moneylenders, he is found and rescued by Shimoshina High Schools student council, who pay the debt in full. However, now indebted to the student council for saving him, they not only make Hime transfer schools, but also make him a part of the student council as their servant!  Forced to cross-dress for the rest of his high school years, Hime has no other option but to obey the demands of the girls in the student council. As he is harassed both mentally and physically, he must overcome his somewhat perverted classmates and join forces with other crossdressers throughout the school.', 76, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7777, 'Cross Road', 2014, 1, 'Special', 72.7, 'As college entrance examinations draw near, two students living completely different lives decide to enroll in Z-Kai, a correspondence education service. Balancing their studies with their daily lives, the two diligently work towards their goal, unaware of how much they share in common. Will their hard work pay off and bring about the success they desire?', 20, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7778, 'Okashina Hotel', 2008, 1, 'Special', 67.8, 'Short film made by Michio Mihara in 2008.', 61, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7779, 'Suzu 3 Tarou', 2009, 24, 'ONA', 80.3, 'In a Shinto shrine, life goes on a leisurely pace for three bells who are brothers.', 17, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7780, 'Kara no Kyoukai Movie: Mirai Fukuin - Manner Movie', 2013, 1, 'Movie', 68.2, 'Cinema intro shown before the movie Kara no Kyoukai: Mirai Fukuin and included as a bonus with the Blu-ray/DVD release.', 72, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7781, 'Nyamen', 2014, 12, 'TV', 61.9, 'CGI ramen bowls that look like cats but have the personalities of high school girls talk about every day life things that involve ramen. The opening and ending sequence features them as 2D anime cat-girls with naruto accessories even though they are not represented as such in the actual show.', 63, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7782, 'Apo Apo World: Giant Baba 90-bun 1-hon Shoubu', 1996, 1, 'Movie', 64.7, 'Animation based around the real-life Japanese wrestler Giant Baba (Baba Shouhei, January 23, 1938 - January 31, 1999).  (Source: AniDB)', 30, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7783, 'Takanashi Rikka Kai: Chuunibyou demo Koi ga Shitai! Movie Lite', 2014, 1, 'Special', 81.4, 'Special episode included with the Blu-ray/DVD release of Chuunibyou demo Koi ga Shitai! Movie.', 92, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7784, 'Rokujouma no Shinryakusha!?', 2014, 12, 'TV', 98.2, 'After Koutarou Satomis father is suddenly relocated for his job, the first-year high school student is faced with finding a cheap place to live by himself. Naturally, he jumps at the chance to move into Corona Houses Room 106 for a mere five thousand yen a month. But while everything goes well at first, Koutarou soon gets a lot more than he bargained for after stumbling upon a mysterious cave while working his part-time job.  The following night, Koutarou is visited by various seemingly mythical figures, all of whom claim ownership of the poor students apartment. Among the invaders are Sanae Higashihongan, a ghost supposedly haunting the room, magical girl Yurika, alien princess Theiamillis Gre Fortorthe, and Kiriha Kurano, a direct descendant of the Earth People. But more importantly, each of these four girls needs Koutarous apartment for her own reasons and won’t back down without a fight!  Rokujouma no Shinryakusha!? is a comedic battle royale over a six-tatami mat apartment involving supernatural beings, romantic high school hijinks, and a deceptively cordial landlady.', 113, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7785, 'Seireitsukai no Blade Dance', 2014, 12, 'TV', 68.5, 'On his way to Areishia Spirit Academy, Kamito Kazehaya runs into a naked Claire Rouge, a student who had been bathing as part of a purification ceremony. She had been preparing to form a contract with a powerful spirit in order to acquire more power as an elementalist. Her efforts are wasted, however, when Kamito ends up with the spirit despite the fact that only shrine maidens can become elementalists. Yet to be discouraged, Claire then announces that Kamito must become her contracted spirit instead!  After reaching the school grounds, Kamito escapes from Claire and meets Headmaster Greyworth Ciel Mais, who invites him to enroll at the academy. Although his life at Areishia will be far from easy as the only male student among the shrine princesses-in-training, he begrudgingly accepts in exchange for information about his former contracted spirit, Restia Ashdoll. Adding on to that, he also must fulfill Greyworths main request: to win in the Blade Dance, a battle festival occurring in two months, where he will face the strongest elementalist rumored to be contracted with a darkness spirit.', 74, False, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7786, 'Hyokkori Hyoutan Shima', 1967, 1, 'Movie', 97.1, 'A group of kids are stranded on a volcanic deserted island.  (Source: AniDB)', 74, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7787, 'Mon Cheri CoCo', 1972, 13, 'TV', 93.6, 'A young woman aims to become a famous fashion designer.  (Source: AniDB)', 105, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7788, 'Mugen Senshi Valis', 1987, 1, 'Special', 67.5, 'Mugen Senshi Valis is a Japanese platform game series developed by Telenet Japan.  The Valis games (as they were known in America) tell the story of Yuko Asou, a Japanese student of the late 1980s that is bound to protect three different kingdoms - our own land, the land of the Spirits, and Vecanti, the world of dreams, by using a mystical sword called Valis.  This short anime clip was made as TV commercial for the Nintendo Famicom game.', 32, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7789, 'Hana no Zundamaru: Junk', 2014, 3, 'ONA', 97.6, 'Zundamaru is back... For now! Even without missions, we elite ninjas face grave dangers every day! (Anime Bancho)', 14, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7790, 'Francesca', 2014, 24, 'TV', 90.3, 'TV anime adaptation based on the undead idol character Francesca to promote Hokkaido, Japan.  (Source: MAL News)', 39, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7791, 'Angel ga Tonda Hi', 1996, 1, 'Movie', 70.2, 'A heart-warming story depicting the day-to-day life full of laughter and tears as a mother copes with her children.', 43, False, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7792, 'Date A Live II: Kurumi Star Festival', 2014, 1, 'OVA', 77.8, 'On the day of the Tanabata festival, Shidou Itsuka happens to meet the eerie Kurumi Tokisaki, who proceeds to ask him out on a date. Although nervous, Shidou accepts the offer. The two spend their time visiting to a planetarium, buying food at the festival, and trying out a mock wedding ceremony. Meanwhile, Shirous friends—Tooka Yatogami, Yoshino, and Kotori Itsuka—are looking for him, while also enjoying the festival themselves.   As Shidou spends the day with Kurumi, he begins to notice an unexpected softer side of her. He knows that Kurumi is infamously called the Worst Spirit, but the girl standing before him is a gentle soul. However, as the day draws to a close, Shirou finally begins to understand the truth behind it all.', 89, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7793, 'Sangokushi', 1982, 1, 'Special', 92.5, 'No description available for this anime.', 19, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7794, 'Kaibutsu-kun: Demon no Ken', 1982, 1, 'Movie', 85.3, 'Based on the shounen manga by Fujiko Fujio.  Note: Screened as a triple feature with Doraemon: Nobita no Daimakyou and Ninja Hattori-kun: Nin Nin Ninpo Enikki no Maki.  (Source: AniDB)', 41, True, 114);
