INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (7800, 'Obake no Q-Tarou: Susume! 1/100 Daisakusen', 1987, 1, 'Movie', 70.8, 'Note: Screened as a double feature with Doraemon: Nobita to Ryuu no Kishi and with Pro Golfer Saru: Kouga Hikyou! Kage no Ninpou Golfer Sanjou!.  (Source: AniDB)', 29, True, 120);
