INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8009, 'Ganbare Swimmy', 1986, 1, 'Movie', 84.3, 'Ganbare, a black fish born into a shoal of red fish, tries to fit in amid adventures as he is chased by tuna and must evade the Great Octopus.  (Source: The Anime Encyclopedia)', 53, True, 89);
