INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8013, 'Puchimas!!: Petit Petit iDOLM@STER - Fuyu→Kotatsu←Haru', 2014, 1, 'OVA', 79.8, 'Extra episode bundled with the limited edition of the 6th manga volume.', 69, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8014, 'Gondora', 1997, 1, 'Movie', 96.8, 'Standing alone in a room with symbols scrawled on the wall, a man dressed as an aviator is left to his own devices.', 58, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8015, 'Momons Sand Witch', 2014, 8, 'ONA', 69.2, 'Momon and her pet Tanu have been close friends since childhood and have always been together. Before long, Momon became an elementary school student, and one day when a new student transfers to her class, their lives begin to change...', 13, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8016, 'Momons Sand Witch Episode 0', 2014, 1, 'ONA', 69.2, 'Episode 0 of Momons Sandwitch.', 29, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8017, 'Pyuu to Fuku! Jaguar: Return of Yaku Ichinenburi', 2008, 3, 'OVA', 85.5, 'The second OVA series based on the gag manga written and illustrated by Usuta Kyousuke that ran in Shuukan Shounen Jump from 2000 to 2010.  (Source: AniDB)', 33, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8018, 'REACH x Thermae Romae: Pietrada no Kekkon', 2014, 1, 'Special', 92.0, 'New Thermae Romae short (collaboration with a toothbrush brand REACH) to celebrate the 2nd live action movie. This short is part of an advertising campaign for the Otome Joshi no Tame no Anime Shinsho book series.', 47, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8019, 'Lovely Movie: Itoshi no Muco', 2013, 20, 'TV', 96.3, 'The happy daily life of Muco, a not-too-bright Akita dog, and its owner Komatsu-san the glass-blower.  (Source: MU)', 36, False, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8020, 'Lovely Movie: Itoshi no Muco Specials', 2014, 3, 'Special', 67.2, 'Extra episodes included in the DVD release, as well as the unaired 19th episode.', 33, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8021, 'Lovely Movie: Itoshi no Muco Season 2', 2014, 22, 'TV', 76.7, 'Second season of the Lovely Muco series.', 115, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8022, 'Tuzki: Love Assassin', 2014, 1, 'ONA', 95.2, 'Tuzki, a bunny, is playing video games with his dismembered heart when he receives a notification on his smartwatch: it looks like an assassination needs to be carried out! Armed with his bazooka, Tuzki is on the job. That is until he meets his target.', 79, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8023, 'Hoshi no Yuuenchi', 1989, 1, 'OVA', 79.1, 'A kindly teacher demonstrates origami to his elementary class, but when he gives a paper crane to a child, it is stolen from him by Takeshi, the class bully. Takeshi discovers that the crane is really a talking spaceship that takes him and his friends to visit a fairground in the stars.   A girl falls through a hole into Space Hell, and the children cooperate to rescue her. Takeshi wakes up, wondering if it was all a dream. The next day, he returns the magic crane to its rightful owner. This tale is from Rainbow Across the Pacifics Daisuke Ikeda, the leader of the buddhist Soka Gakkai organization which is commonly considered a cult as it is a part of the shinshuukyou religious movement.   (Source: Anime Encyclopedia)', 106, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8024, 'Subarashii Sekai Ryokou: Alaska no Tabi Daigo Hyougaki', 1967, 2, 'Special', 89.9, 'In the near future, Earth is engulfed in a new ice age as snow falls ceaselessly in summer and glaciers advance with uncharacteristic speed. In this SF spinoff of the live-action Wonderful World Travel series, humanity must decide whether to use science to fight the ice or to adapt to it.   (Source: Anime Encyclopedia)', 106, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8025, 'The Adventures of Hello Kitty & Friends', 2008, 52, 'TV', 89.0, 'Random adventures of Hello Kitty and other Sanrios characters.', 105, False, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8026, 'Sora wa Koko ni Aru', 2014, 1, 'Music', 61.2, 'An animated music video for the song Sora wa Koko ni Aru by Ai Kawashima.  The video was released on a limited edition DVD sold with her 22nd single.', 106, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8027, 'Uchuu Senkan Yamato 2199: Tsuioku no Koukai', 2014, 1, 'Special', 98.7, 'Recap of Uchuu Senkan Yamato 2199.', 54, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8028, 'Kyutai Panic Adventure!', 2003, 1, 'Special', 86.7, 'A special screened at special events named Odaiba Boken-Oh featuring characters from Astro Boy, Dragon Ball Z and One Piece.', 11, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8029, 'Kyutai Panic Adventure Returns!', 2004, 1, 'Special', 80.7, 'A special screened at an event named Odaiba Boken-Oh, featuring characters from Dragon Ball Z, One Piece and Kochira Katsushikaku Kameari Kouenmae Hashutsujo.', 102, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8030, 'Kidou Senshi Gundam UC: One of Seventy Two', 2013, 1, 'Special', 68.7, 'U.C. 0095.12.03 The Neo Zeon remnants known as the Sleeves conduct a performance test on a certain new type of mobile suit in a debris sector. Having gotten wind of this intel, two warships head for the debris sector. One ship is a Earth Federation Forces warship. The other ship is an Anaheim Electronics testing ship. On board the Federation Forces battleship, a newly constructed Unicorn Gundam Unit 3 awaited its time to sortie…  (Source: Zeonic Scanlations)', 104, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8031, 'Majimoji Rurumo', 2014, 12, 'TV', 86.0, 'After an unfortunate accident, completely normal heterosexual high school student Kouta Shibaki is branded as the school pervert. With girls avoiding Kouta like the plague, truly the young mans worst nightmare has come to fruition! One day in the school library, he stumbles upon a peculiar book said to possess the power to summon witches. Partly out of desperation, partly out of boredom, Kouta decides to play along with the joke of a book, until an apprentice witch going by the name of Rurumo Maji Mojiruka appears before him. In an unusual turn of events, Kouta ends up helping Rurumo with some general witchery tasks in exchange for his soul being spared.  Majimoji Rurumo follows the misadventures of Rurumo as she attempts to persuade Kouta to use 666 magical wish-granting tickets in her efforts to become a fully-fledged witch, unaware that every time she grants a wish, Koutas life is shortened. Aided by Rurumos familiar Chiro, Kouta must decide between helping Rurumo or saving his own life.', 85, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8032, 'Fox Wood Monogatari', 1991, 3, 'OVA', 74.6, 'Harvey, Rue, and Willie are a hedgehog, rabbit, and mouse who live in a windmill in the peaceful town of Fox Wood, where they have several adventures in this short-lived series based on the childrens picture books by the British creators Cynthia and Brian Paterson.   (Source: Anime Encyclopedia)', 72, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8033, 'Fuku-chan no Kishuu', 1942, 1, 'Movie', 87.6, 'The first film of the Fuku-chan trilogy. Based on a popular newspaper comic strip at the time, Fuku-chan was re-invented for propaganda use.', 108, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8034, 'Fuku-chan no Zousan Butai', 1943, 1, 'Movie', 97.7, 'The second film of the Fuku-chan triology. Based on a popular newspaper comic strip at the time, Fuku-chan was re-invented for propaganda use. In this one Fuku-chan tries to rally up the fighting spirit of the troops.', 38, False, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8035, 'Fuku-chan', 1982, 71, 'TV', 82.9, 'Childish goings-on for Fukuo Fuchida (also known as Fuku-chan) a small boy who attends nursery school with his girlfriend Kumi and hangs out with his playmates Namiko (whose parents own a china shop), her younger brother, Kiyo, naughty twins Doshako and Garako and school bully Ganchan.  (Source: Anime Encyclopedia)', 24, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8036, 'Fukuyama Gekijou: Natsu no Himitsu', 1990, 1, 'OVA', 70.4, 'Several short animated mini-stories based on the short stories and four-panel manga of Keiko Fukuyama, including My Father the Mouse, The Rabbit Brothers, Summer Secret, The Mysterious Fairy, How Very Strange, and Kuro.   (Source: Anime Encyclopedia)', 37, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8037, 'Something Great Chizu ni Nai Machi', 2006, 1, 'Movie', 73.3, 'Based on the original story by Mukainakano Yoshio.', 111, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8038, 'Fuichin-san', 2004, 1, 'OVA', 62.9, 'Based on Ueda Toshikos shoujo manga.', 90, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8039, 'Futari Ecchi (2014)', 2014, 3, 'OVA', 98.4, 'Three new OVAs of Futari Ecchi released as standard DVDs and as part of a Premium DVD Box containing all seven OVAs of the series.', 79, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8040, 'Sarusuberi: Miss Hokusai', 2015, 1, 'Movie', 62.1, 'The time: 1814. The place: Edo, now known as Tokyo.  One of the highest populated cities in the world, teeming with peasants, samurai, townsmen, merchants, nobles, artists, courtesans, and perhaps even supernatural things.  A much accomplished artist of his time and now in his mid-fifties, Tetsuzo can boast clients from all over Japan, and tirelessly works in the garbage-loaded chaos of his house-atelier. He spends his days creating astounding pieces of art, from a giant-size Bodhidharma portrayed on a 180 square meter-wide sheet of paper, to a pair of sparrows painted on a tiny rice grain. Short-tempered, utterly sarcastic, with no passion for sake or money, he would charge a fortune for any job he is not really interested in.  Third of Tetsuzos four daughters and born out of his second marriage, outspoken 23-year-old O-Ei has inherited her fathers talent and stubbornness, and very often she would paint instead of him, though uncredited. Her art is so powerful that sometimes leads to trouble. Were father and daughter; with two brushes and four chopsticks, I guess we can always manage, in a way or another.  Decades later, Europe was going to discover the immense talent of Tetsuzo. He was to become best known by one of his many names: Katsushika Hokusai. He would mesmerize Renoir and van Gogh, Monet and Klimt.  However, very few today are even aware of the woman who assisted him all his life, and greatly contributed to his art while remaining uncredited. This is the untold story of O-Ei, Master Hokusais daughter: a lively portrayal of a free-spirited woman overshadowed by her larger-than-life father, unfolding through the changing seasons.  (Source: Production I.G)', 84, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8041, 'Maken-Ki! Two Specials', 2014, 5, 'Special', 87.7, 'Blu-ray/DVD specials of Maken-Ki! Two.', 106, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8042, 'Cardfight!! Vanguard Movie: Neon Messiah', 2014, 1, 'Movie', 67.0, 'A hybrid anime/live-action movie for the series to be released Fall 2014.  After the events of Link Joker-hen, Aichi and Kai team up to a confront an enemy that threatens the peace theyve just regained. The movie also covers the events leading up to Aichis disappearance in Legion Mate-hen.', 98, False, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8043, 'Lance N Masques', 2015, 12, 'TV', 99.0, 'Eight words describe the feelings of Youtarou Hanabusa: I just want to live a normal life. Unfortunately for him, as a member of the Knights of the World, his training in this ancient and international order has left him with a condition he calls White Knight Syndrome. This condition causes Youtarou to instinctively act heroically and chivalrously whenever he encounters someone in danger.  To protect his identity in such embarrassing moments, he carries a mask with him at all times. Then one day, he saves the life of Makio Kidouin, the young daughter of an elite and affluent family. Little does he know that this singular act of heroism will change his life forever. Soon, he is simultaneously blessed with a life in the lap of luxury and cursed with one of abnormality, for his new friend Makio lives a life far removed from the everyday.  Between coping with the hijinks of six-year-old Makio, and dealing with a cast of odd friends and scheming enemies, Youtarou must protect his new friend while keeping his identity hidden as the masked hero Knight Lancer.', 91, True, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8044, 'Manabu no Natsuyasumi', 2005, 1, 'OVA', 85.3, 'Released by JCI (Junior Chamber International) Japan to promote self awareness and appreciation of Japans soul.  Manubus mother leaves him with his uncle, grandmother and niece Kiyomi to spend his summer vacation. Him being a real city brat he has no real appreciation for nature and the outdoors and the values of life. He will soon learn differently...  (Source: AniDB)', 54, True, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8045, 'Shijou Saikyou no Deshi Kenichi Specials', 2013, 4, 'Special', 83.8, 'A brief summary of Kenichis new life at Ryouzanpaku.   Included as a bonus on the DVD volumes of the Shijou Saikyou no Deshi Kenichi OVA.', 38, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8046, 'Denki-gai no Honya-san', 2014, 12, 'TV', 64.4, 'Umio is a shy kid who just started his part time job at a manga store smack dab in the middle of the city. But his lifestyle isnt as glamorous as the neon lights that illuminate the city. Umios closest friends are his co-workers who are all unique characters, to say the least, and although theyre nice people, they have their quirks. They are a tight knit group of friends, have nicknames for each other and spend their weekends inside, sheltered from the extravagant scene happening on the outside.  (Source: MU)', 103, False, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8047, 'Selector Spread WIXOSS', 2014, 12, 'TV', 75.5, 'The unforeseen outcome of Iona Urazoes fan gathering continues to weigh heavily on Ruuko Kominato. Having uncovered the truth behind being a Selector, Ruuko and her friends Yuzuki Kurebayashi and Hitoe Uemura hesitate to partake in the battles that may ruin the lives they have come to cherish. The same cannot be said for Chiyori, a fellow Selector who remains oblivious to the consequences of losing despite all warnings. As she tries to convince Chiyori out of her cruel fate, Ruuko learns more about a WIXOSS novel—which may reveal the secrets of LRIGs and the Selector battles very existence.  Meanwhile, Akira Aoi and her model career have rebounded thanks to Iona, who is now possessed by Ulith. With her life back on track, Akira pledges to assist Ulith in any way she can. Unbeknownst to her, Ulith is scheming to utilize a familiar LRIG to not only torment Ruuko but also prevent the latters wish from ever being fulfilled.', 68, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8048, 'Jarujio Animal', 2010, 10, 'TV', 78.4, 'The real female idol group PASSPO☆ are the stars of this anime. The PASSPO☆ members are represented as animals and go on flight-attendant adventures.', 58, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8049, 'Monster ni Natta Domerica', 2011, 1, 'ONA', 99.7, 'In this action epic set in the run-down slums, the title character Domerica is transformed into a monster one day.   (Source: ANN)', 22, True, 9);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8050, 'Kaseki Dorobou to Kyouryuuseki', 2011, 1, 'ONA', 86.5, 'The dinosaur fantasy revolves around a 12-year-old named Yuta and Gobi — a moving fossil. The two embark on a journey with Yutas friends to chase a fossil thief and find Gobis stolen fossil mother.   (Source: ANN)', 118, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8051, 'Kanai', 2011, 1, 'ONA', 63.3, 'The story follows two girls who grow up on the island of Okinawa and a boy as they discover a robot.', 113, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8052, 'Interior', 2011, 1, 'ONA', 85.5, 'Centers around the unprofitable artist Sam, the unprofitable playwright Borman, and their friend Greg. The one thing they all have in common is that they are poor. The three decide to enter a contest to earn money — but since they cannot afford to mail their entries, they decide to take the long trip to the competition site to bring their entries in person.   (Source: ANN)', 64, True, 12);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8053, 'Gunners', 2011, 1, 'ONA', 81.3, 'A 3D-CG promotional video for the Gunners manga.', 84, True, 13);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8054, 'gdgd Fairies Movie: tte Iu Eiga wa Dou kana...?', 2014, 1, 'Movie', 95.3, 'Movie of gdgd Fairies.', 18, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8055, 'Konna Watashitachi ga Nariyuki de Heroine ni Natta Kekka www', 2014, 1, 'Movie', 87.6, 'Airing simultaniously as gdgd Fairies Movie.', 111, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8056, 'Persona 4 the Golden Animation', 2014, 12, 'TV', 60.5, 'Spring. Far from the city, time flows peacefully in this rural town. As the cherry blossoms scatter in the wind, a young man named Yu Narukami steps off the train at Yasoinaba Station. Yu has come to this town, where his uncle lives, for family reasons; he will be transferring into the local high school, Yasogami High. And so begins his school life... The shopping mall after school. A series of murders taking place in town. The Midnight Channel, airing late at night.... What lies in store for Yu and his friends ‘this time around?  (Source: Aniplex USA)', 14, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8057, 'Shura ga Yuku', 1994, 2, 'OVA', 96.6, 'Based on a Yakuza drama manga by Kawabe Yuu and Yamaguchi Masato.', 21, True, 17);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8058, 'Be-Bop Kaizokuban', 1991, 3, 'OVA', 73.1, 'Based on a parody manga of Be-Bop Highschool.', 36, True, 18);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8059, 'High School Jingi', 1992, 1, 'OVA', 66.8, 'The impulsive Yakuza Jouji was ordered by his boss to teach at a misfit-filled school. He now has to settle the score with a fated rival while falling head over heels for a colleague in the process.  (Source: AniDB)', 111, True, 19);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8060, 'Gorillaman', 1992, 2, 'OVA', 70.6, 'A school comedy about a mute transfer student, Tadashi  Iketo, who is constant\xadly shuffled from school to school for his  violent nature, though he really is a mild-mannered boy constantly taunt\xaded into fights over his simian appearance.   Based on a 1989 manga in  Young Magazine by Harold Sakuishi.   (Source: The Anime Encyclopedia)', 53, True, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8061, 'Tooryanse', 2014, 1, 'Music', 81.7, 'Another music video from Kousuke Sugimoto and Handsome Kenya. The title of the song comes from the name of an old childrens tune sometimes played at crosswalks in Japan. After the tune plays, Handsome Kenya is pulled into a beautiful and strange world.', 19, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8062, 'Patta Potta Monta', 2006, 26, 'TV', 69.6, 'Three monkey brothers from the from an urban city go to live in the countryside. Theres no convenience store nor arcades there; truly bare-bones. The story follows their daily lives trying to make friends and have fun amongst the villagers.', 41, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8063, 'Kaette Kita Top wo Nerae! Kagaku Kouza', 2012, 2, 'Special', 77.5, 'Extra science lessons included with the Gunbuster Blu-ray Box Complete Edition. These explain how the space ropeway works, and time dilation from near-lightspeed travel.', 48, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8064, 'Hashi no Mukou', 2012, 1, 'ONA', 91.9, 'There are old stories of children disappearing by the rivers edge. This has haunted Otoha ever since her friend Jiro disappeared  when she was seven years old and now she is back in her hometown covering the war between the government and the dissidents. When she gets separated from the squad, Otoha thinks someone seems to be leading her deeper into the back alleys of the town.', 92, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8065, 'Taimadou Gakuen 35 Shiken Shoutai', 2015, 12, 'TV', 85.2, 'In a world plagued by magical dangers and threats, there exist special warriors—known as Inquisitors—who are tasked with non-violently preventing these threats and nefarious actions. The Anti-Magic Academy is a specialized school built to educate and train these Inquisitors, which splits its students into small squads in order to train them to work together. Among these talented squads is the 35th Test Platoon, also known as the Small Fry Platoon due to its low ranking and incompetent members.   However, everything changes when Ouka Ootori, a powerful yet rebellious former Inquisitor, is forced into joining due to her tendency to break rules and committing a serious violation: the killing of a witch. Tempers flare upon her arrival, as she clashes with their clumsy captain Takeru Kusanagi and argues with the rest of the squad over her views on witches. This eclectic group has a long way to go if they wish to succeed and climb the ranks at the Anti-Magic Academy: they must first set aside their differences and come to work together as a team.', 44, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8066, 'Nobunaga Concerto', 2014, 10, 'TV', 91.9, 'Who cares about what happened in Japans past? It has nothing to do with my life.  With these words, carefree high school student Saburou finds himself unceremoniously thrown back in time to the Sengoku Era, landing directly in front of the legendary general Nobunaga Oda. Nobunaga, on the run from his retainers and wishing to rest due to his frailty, beseeches Saburou to take his place, as the two bear an uncanny resemblance. Although Saburou is still confused by his surroundings, Nobunaga hurriedly provides the boy with the necessary items to prove that he is the bona fide feudal lord and makes a hasty getaway.  Now a stand-in for someone he doesnt even know all that much about—though his modern experiences and knowledge are sure to help him—Saburou begins his unexpected quest to pose as the man who attempted to unite all of Japan.', 67, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8067, 'Tokyo Babylon: Vision', 1992, 1, 'Music', 95.7, 'Music video included as a bonus on a Premium Laser Disc release of the Tokyo Babylon OVA.', 13, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8068, 'Ao Haru Ride OVA', 2014, 2, 'OVA', 72.4, 'Unwritten Junior high student Futaba Yoshioka has always despised boys—she thinks they are all way too rowdy and annoying. The only exception is a boy in the class next to hers, Kou Tanaka, who seems different from the others. Through frequent encounters, Futaba and Kou exchange shy glances and awkward words with one another. Having had no experience in romance prior, Futaba has no idea what her growing feelings for Kou are supposed to imply.  Page.13 During their second year of high school, Futaba and her friends go to a summer festival together. While the other girls decide not to wear yukatas, Yuuri Makita does as she is determined to get closer to Kou. Caught off guard, Futaba can only watch from afar as Yuuri and Kou seem to grow more and more intimate. At this rate, will Futaba be able to make progress with Kou?', 17, False, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8069, 'Kougyou Aika Volley Boys', 1997, 2, 'OVA', 65.6, 'In a mix of Field of Dreams and Ping Pong Club, sex-starved teenage boys at Kudo High School sign up for the girls volleyball team hoping that if they build it, the girls will come, to a year that has no girls in it at all.  (Source: ANN)', 83, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8070, 'Detective Conan: The Fugitive Kogorou Mouri', 2014, 1, 'ONA', 83.3, 'File 594 that was never animated. To celebrate Detective Conan Movie 18 premiere, it was animated and streamed on NOTTV.  This is where Kogorou Mouri is the fugitive.', 103, False, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8071, 'Mushibugyou OVA', 2014, 3, 'OVA', 91.4, 'OVAs bundled with the 15-17th volumes of the Mushibugyou manga.', 28, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8072, 'Nozo x Kimi', 2014, 3, 'OVA', 61.8, 'Suga Kimio finds himself hiding in the girls locker room, unable to move or escape the situation as the girls in his school crowd in. Although he originally had no ulterior motives, he found himself panicking as he heard the girls coming in and hid in a locker. Komine Nozomi, one of the shy girls in his class finds him, but surprisingly covers for him. Perplexed but glad, Kimio goes home.  Later that night, he gets a text from Nozomi who happens to live across the way on the same floor of the complex they both live in. She blackmails him into agreeing to show each others bodies when she texts him. Kimio has to abide by Nozomis insane demands or risk ruining his school life so they both start their little peep show through each others windows...  (Source: MangaHelpers)', 50, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8073, 'Strobe Light', 2011, 1, 'Music', 70.5, 'Music video for the song Strobe Light by siinamota.', 94, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8074, '3-Nen C-Gumi 14-Ban Kubozono Chiyoko no Nyuukaku', 2013, 1, 'Music', 98.1, 'Music video for the song 3-Nen C-Gumi 14-Ban Kubozono Chiyoko no Nyuukaku by siinamota (Shina Mota) from the CD album Kokegane no Uta. Directed by Kenshiro Morii at Studio Moriken.', 59, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8075, 'E no Umakatta Tomodachi', 2014, 1, 'Music', 64.3, 'Music video for the song E no Umakatta Tomodachi by pinocchioP. Collaboration with Pentel Inc.', 37, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8076, 'Oosouji', 2013, 1, 'Music', 64.6, 'Music video for the song Oosouji by DECO*27.', 88, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8077, 'Rakugaki Picasso', 2014, 1, 'Music', 70.8, 'Music video for the song Rakugaki Picasso by 40mP. Collaboration with Pentel Inc.', 72, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8078, 'Orenchi no Furo Jijou', 2014, 13, 'TV', 83.4, 'On his way home from school, Tatsumi sees a man collapsed near a lake. When he approaches him, Tatsumi notices something strange: the person in need of help is actually a beautiful merman named Wakasa! Because Wakasas home has become too polluted to live in, Tatsumi graciously offers his bathtub as a refuge.  With a boisterous merman as his new roommate, Tatsumis normal life wont be returning anytime soon, not to mention Wakasas aquatic friends—Takasu, Mikuni, and Maki—often show up uninvited, making them all quite a handful for the high school student. As he humors their curiosity for human life, Tatsumi sometimes finds himself enjoying their childish antics, but he will have to keep his cool if he intends to keep up with his daily life and newfound friendship.', 78, True, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8079, 'Nisekoi OVA', 2014, 3, 'OVA', 93.5, 'Episodes released on DVDs bundled with the 14th, 16th, and 17th volumes of the Nisekoi manga.', 68, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8080, 'Hitsugi no Chaika: Avenging Battle', 2014, 10, 'TV', 79.6, 'The search for the remains of Emperor Gaz continues. Chaika still in search of knowing who she really is and what her purpose is. Similarly, the Red Chaika continues the search for the rest of Emperor Gazs remains. The Gillette corporation continues the mission to catch every last Chaika. In their adventure they give a revealing account kept secret by the Emperor, which Chaika, Fredrica, Toru, and Akari decide to uncover.  (Source: ANN, edited)', 26, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8081, 'Surprise 4 U.', 2012, 2, 'ONA', 88.5, 'A series of shorts by Production I.G and funded by Acer Japan, which focus on five members of the Sunrise Japan group (not to be confused with the animation studio) of prominent female athletes in celebration of the 2012 Olympics: Yamasaki Shizuyo (boxer/comedian), Hamaguchi Kyouko (wrestler), Itou Satsuki (boxer), Urata Satako (beach volleyball player), and Nishibori Takemi (beach volleyball player).  (Source: AniDB)', 111, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8082, 'Heisei no Cinderella: Kiko-sama Monogatari', 1990, 1, 'Special', 66.1, 'The special is confined to the wedding of Prince Akishino with his chosen Kiko Kawashima.', 59, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8083, 'Mechano: Scientific Attack Force', 1995, 3, 'OVA', 92.1, 'Three 10-minute videos present a trippy view into the minds of their creators. Brought together by Pierre Taki of Denki Groove, Mechano: Scientific Attack Force features three shorts done in very different styles.  The three short films are:  Plastic Gun Man - a 3D Western spoof World Meccano Triangle - a music video reminiscent of 90s era screensavers Haiirogaoka no Soridaijin (translated as Prime Minister of Gray Hill) - an anime-style animated video parody of Akira Mochizukis famous 1977 manga, Yuuhi ga Oka no Souri Daijin', 16, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8084, 'Hitsugi no Chaika: Nerawareta Hitsugi/Yomigaeru Iseki', 2015, 1, 'OVA', 62.4, 'Unaired anime-original OVA bundled with 12th volume of the Hitsugi no Chaika novel.', 97, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8085, 'Chiisana Kyojin Microman: Daigekisen! Microman vs. Saikyou Senshi Gorgon', 1999, 1, 'Movie', 85.9, 'No description available for this anime.', 92, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8086, 'Medamayaki no Kimi Itsu Tsubusu?', 2014, 4, 'Special', 69.2, 'Based on the same name gourmet manga that focuses on the dining of cuisine. The protagonist Jirou Tamiyamaru is more obssessed with how to eat than most people, and the anime comically depicts how he agonizes over the differences with how others eat.  (Source: ANN)', 21, True, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8087, 'Yowamushi Pedal: Grande Road', 2014, 24, 'TV', 92.3, 'Second season of the Yowamushi Pedal series.', 112, True, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8088, 'PoPo Loouise', 2008, 1, 'Music', 69.0, 'Music Video for a song by the Kuricorder Quartet and UA, shown in the NHKs program Minna no Uta.', 23, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8089, 'Hoka Hoka Oden no Uta', 2012, 1, 'Music', 69.4, 'Music video about Japanese oden.', 93, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8090, 'Inazuma Eleven: Chou Jigen Dream Match', 2014, 1, 'Movie', 98.7, 'A new movie featuring a match between fan-voted members of the Inazuma Best Eleven team and the special Battle Eleven team.', 13, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8091, 'Gaia Getter A-kun', 2002, 2, 'ONA', 85.7, 'Far away from our solar system there is a 3rd planet of another called Mangana. A Queen rules it with an iron fist. The first Prince, A-kun, is nothing but naughty kid and so the Queen gives him the task of invading Earth to prove his worth. A-kun comes in tow with his semi-forced attendants and hijinks ensue.', 85, True, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8092, 'Kitsune to Circus', 1948, 1, 'Movie', 96.3, 'A fox steal the worlds most valuable diamond and buries it under a tree, believing it to be well-hidden. The next day, a circus arrives and sets up its tent next to the tree, its animals unwittingly digging up the diamond they believe to be just a worthless rock. They soon lose the diamond inside the circus and the desperate fox attempts to retrieve the stolen diamond before the other animals realise what they have.  (Source: AniDB)', 12, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8093, 'Tonari no Seki-kun Specials', 2014, 2, 'Special', 75.0, 'Two unaired episodes included in the DVD Set release of Tonari no Seki-kun series.  #1. Field Trip (Rinkan Gakkou) (first volume) #2. Snow Playing (Yuki Asobi) (second volume)', 56, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8094, 'Kidou Senshi Gundam Unicorn: Episode EX - Hyakunen no Kodoku', 2014, 1, 'Special', 62.0, 'Recap of Mobile Suit Gundam, Mobile Suit Zeta Gundam, Mobile Suit Gundam ZZ and Mobile Suit Gundam: Chars Counterattack focusing on Newtype and Zeonism ideals told before UC episode 7.  Included as a bonus on a Volume 7 Blu-ray release of the Mobile Suit Gundam Unicorn OVA.', 15, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8095, 'Bakabon Osomatsu no Karee wo Tazunete Sansenri', 1991, 1, 'Special', 94.5, 'No description available for this anime.', 31, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8096, 'Nyanpuku Nyaruma', 2014, 3, 'TV', 77.7, 'Follows twin cats who wish to make others happy and their strange friends.', 27, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8097, 'World Trigger', 2014, 73, 'TV', 75.0, 'When a gate to another world suddenly opens on Earth, Mikado City is invaded by strange creatures known as Neighbors, malicious beings impervious to traditional weaponry. In response to their arrival, an organization called the Border Defense Agency has been established to combat the Neighbor menace through special weapons called Triggers. Even though several years have passed after the gate first opened, Neighbors are still a threat and members of Border remain on guard to ensure the safety of the planet.  Despite this delicate situation, members-in-training, such as Osamu Mikumo, are not permitted to use their Triggers outside of headquarters. But when the mysterious new student in his class is dragged into a forbidden area by bullies, they are attacked by Neighbors, and Osamu has no choice but to do what he believes is right. Much to his surprise, however, the transfer student Yuuma Kuga makes short work of the aliens, revealing that he is a humanoid Neighbor in disguise.', 30, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8098, 'Kuroko no Basket 3rd Season', 2015, 25, 'TV', 92.0, 'Seirin prepares to face major obstacles on their path to winning the Winter Cup, including the teams each possessing a member of the Generation of Miracles. Kuroko goes head-to-head with his old teammates once more as he attempts to show them that individual skill is not the only way to play basketball. His firm belief that his form of basketball, team play, is the right way to play the sport will clash with the talents of a perfect copy and an absolute authority.  While Kuroko tries to prove that his basketball is right, he and the rest of Seirin High ultimately have one goal: to win the Winter Cup and overcome the strength of the Generation of Miracles, who have long dominated the scene of middle and high school basketball.', 116, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8099, 'Maido! Urayasu Tekkin Kazoku', 2014, 25, 'TV', 72.1, 'Sequel to the Urayasu Tekkin Kazoku anime and adaptation of the manga of the same name. The series follows an energetic grade-schooler and his friends as they get into mischief.', 87, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8100, 'Daze', 2014, 1, 'Music', 63.8, 'daze  is the opening theme of Mekakucity Actors performed by MARiA from GARNiDELiA. The song was composed by Shizen no Teki-P (a.k.a. Jin) and a PV for the anime was illustrated and directed by Shidu. The full song was released on May 29, 2014 by Jin.  (Source: Kagerou Project Wikia)', 40, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8101, 'World Fool News', 2013, 6, 'ONA', 92.2, 'Takahashi is transferred to a main anchor of a news program, which is known for being a little...weird. This is a comedy about somewhat ridiculous happenings occurring at a broadcasting station.  (Source: YouTube)', 19, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8102, 'Kekkai Sensen', 2015, 12, 'TV', 62.4, 'Supersonic monkeys, vampires, talking fishmen, and all sorts of different supernatural monsters living alongside humans—this has been part of daily life in Hellsalems Lot, formerly known as New York City, for some time now. When a gateway between Earth and the Beyond opened three years ago, New Yorkers and creatures from the other dimension alike were trapped in an impenetrable bubble and were forced to live together. Libra is a secret organization composed of eccentrics and superhumans, tasked with keeping order in the city and making sure that chaos doesnt spread to the rest of the world.  Pursuing photography as a hobby, Leonardo Watch is living a normal life with his parents and sister. But when he obtains the All-seeing Eyes of the Gods at the expense of his sisters eyesight, he goes to Hellsalems Lot in order to help her by finding answers about the mysterious powers he received. He soon runs into Libra, and when Leo unexpectedly joins their ranks, he gets more than what he bargained for. Kekkai Sensen follows Leos misadventures in the strangest place on Earth with his equally strange comrades—as the ordinary boy unwittingly sees his life take a turn for the extraordinary.', 92, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8103, 'Shiden Pilot', 2004, 1, 'Special', 93.1, 'Described as a modern car racing anime for tween and teen audiences. Though intended to be a television series, several problems led to the projects cancellation after the creation of a 30-minute pilot. The single episode was presented at the 2004 Tokyo Anime Fair.  (Source: ANN)', 97, True, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8104, 'Peeping Life: Shinkon-chan Kansai ni Irasshai', 2014, 1, 'ONA', 80.9, 'The newlyweds have moved to the Kansai region! For now theyve settled down, but their room is still a huge mess. They also realize that theyve been wasting a lot of electricity, and they begin to ponder ways to cut back on their bills...  (Source: Anime Bancho)', 19, True, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8105, 'Wagahai wa Inu de Aru: Don Matsugorou no Seikatsu', 1983, 1, 'Special', 98.1, 'Mr. Matsuzawa is a novelist who lives in Chiba Prefecture. Only his daughter Kazuko knows that the family dog, Don Matsugorou, can talk. Don is wounded in a fight with the neighbors dog, King, a nouveau-riche mongrel with ideas above his station. At the vet, however, he falls in love with a little patchwork puppy called Chotaro.  (Source: The Anime Encyclopedia)', 28, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8106, 'Kanojo ga Flag wo Oraretara: Christmas? Sonna Mono ga Boku ni Tsuuyou Suru to Omou no ka?', 2014, 1, 'OVA', 97.6, 'Bundled with the 11th volume of Kanojo ga Flag wo Oraretara light novel.', 87, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8107, 'Madan no Ou to Vanadis', 2014, 13, 'TV', 79.3, 'In a fantasy version of Europe, a war between enemy countries is brewing. One of these countries, Zhcted, has its seven regions ruled by War Maidens, known as Vanadis. Equipped with powerful dragon-carved weapons, Eleonora Elen Viltaria, one of the Vanadis, launches an invasion against their neighboring rival country of Brune. Eventually, Tigrevurmud Tigre Vorn, a young archer and an earl for Brunes region of Alsace, has his entire army decimated at Elens hands. In a strange twist of events, Elen spares Tigre, and gives him the order, Become mine! What could be the meaning behind this new alliance?  Adapted from the light novel written by Tsukasa Kawaguchi, Madan no Ou to Vanadis is an epic adventure filled with complex war tactics and beautiful women. Trapped in a multinational conflict, Tigre and Elen are swept up in a war filled with dark secrets, conspiracies, and corruption.', 15, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8108, 'Houkago no Ouji-sama', 2014, 5, 'Special', 68.9, 'What do Ryouma Echizen and the Seishun Academy Boys Tennis Team get up to when they are off the court? They are pranking each other with a creepy kokeshi doll in the locker room and incorrectly dressing up for Halloween, just to name a few. With cameos from rival school players to add to the hilarity, Houkago no Ouji-sama explores life outside of the sport that makes these characters tick.', 96, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8109, 'Tales of Zestiria: Doushi no Yoake', 2014, 1, 'Special', 68.8, 'TV anime special of Bandai Namco Games Tales of Zestiria role-playing game.', 104, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8110, 'Heli-Tako Puu-chan', 1998, 42, 'TV', 68.7, 'Based on the manga by Sasaki Takemaru.', 51, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8111, 'Buddy Complex: Kanketsu-hen - Ano Sora ni Kaeru Mirai de', 2014, 2, 'Special', 70.2, 'The two part finale of Buddy Complex television series deals with the final battle between the Free Treaty Alliance and the space division of Zogiria, lead by an elderly Bizon, as Earth and time itself hang in the balance.', 53, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8112, 'Hoozuki no Reitetsu OVA', 2015, 4, 'OVA', 68.7, 'Bundled with the limited editions of 17th, 18th, 19th, and 24th volumes of the Hoozuki no Reitetsu manga.', 100, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8113, 'Mangaka-san to Assistant-san to The Animation Specials', 2014, 6, 'Special', 81.0, 'Specials released with the Blu-ray/DVD volumes.', 30, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8114, 'Koha Ginjiro', 1991, 3, 'OVA', 90.2, 'After the death of his elder brother, Ginjiro Yamazaki appoints himself his parents protector. After transferring to a new school, he gets into a lot of fights.  (Source: The Anime Encyclopedia)', 89, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8115, 'Inui-san!', 2014, 5, 'OVA', 95.1, 'Included in the Ciao Ciao TV bonus DVD that bundled with the  issues of the Ciao magazine.  (Source: AniDB)', 65, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8116, 'Yomigaeru Sora Pilot', 2006, 1, 'Special', 85.7, 'Yomigaeru Sora was initially supposed to have a female protagonist with sharper animation. Due to Yuji Matsukura (J.C.Staff Executive Officer, Head of Production), Katsushi Sakurabi (Director), and Fumihiko Takayama (Series Composition) outvoting Kiyoshi Sugiyama (Producer), the story was changed to have a male protagonist with simpler animation.  Sakurabis original idea for the anime was made into pilot and the pilot was included with the 7th volume of the Limited Edition DVD Box Set.', 92, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8117, 'Ane Log: Moyako Neesan no Tomaranai Monologue', 2014, 3, 'OVA', 87.2, 'When Konoe Moyako and her little brother, Akira, were young, he said he wanted to marry her. Naturally, Moyako decided that her little brother was a complete pervert who was obsessed with her. Now that theyre both teenagers, Moyako is convinced she needs to rehabilitate him. However, it seems that the perversion is entirely in her imagination, and she cant seem to help turning completely innocent situations into creepy ones in her mind!  (Source: MU)  Bundled with the limited edition 5th, 6th, and 7th manga volumes.', 80, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8118, 'Persona 3 the Movie 3: Falling Down', 2015, 1, 'Movie', 67.5, 'As the fall season nears its end, Chidori Yoshino, a member of Strega, abducts Junpei Iori. Meanwhile, Makoto Yuuki and the Specialized Extracurricular Execution Squad (SEES) annihilate the Arcana Hanged Man. Soon after, a mysterious playboy named Ryouji Mochizuki transfers into Gekkoukan High Schools Class 2-F.  Supposedly having achieved their goal, the members of SEES believe they are free from the battle that has ruthlessly stolen away the lives of their loved ones. And yet, Tartarus and the Dark Hour continue to exist, undeterred by the extermination of the twelfth Shadow. Distraught by their apparent failure, SEES must cope with their personal struggles and discover whose sake they fight for. As Makoto and Junpeis journeys of self-discovery progress, Ryoujis identity and the reason behind Aegiss hate for him become clear.', 65, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8119, 'Naniwabushi Daisuki', 1982, 1, 'Special', 89.3, 'Two stories that mix animation with naniwabushi (storytelling accompanied by shamisen playing). One is a tale of General Nogi, the famous suicide, visiting the shrines at lse on his way to Nagoya, while his wife is mistaken for a commoner as she books into a hotel.  The second story is of a sumo wrestling trainee, ridiculed by his fellows, who trains hard and avenges himself-the standard cliches of a sports anime, just with plink-plonky music on top of it.  (Source: The Anime Encyclopedia)', 72, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8120, 'Neko to Nezumi', 1917, 1, 'Movie', 82.4, 'It is most likely a short story about a cat and a mouse.', 40, False, 80);
