INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8122, 'Imokawa Mukuzo: Chuugaeri no Maki', 1917, 1, 'Movie', 98.9, 'It is most likely a story about a Mukuzo Imokawa doing the somersault.  (Source: Anime Database Wiki)', 86, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8123, 'Youkai Watch Movie 1: Tanjou no Himitsu da Nyan!', 2014, 1, 'Movie', 78.2, 'The movie will feature special guests such as popular familiar characters from the TV anime series and the latest Youkai from the upcoming Youkai Watch 2 sequel games.', 85, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8124, 'Xiongmao Monogatari TaoTao', 1981, 1, 'Movie', 76.3, 'TaoTao is an anime series about the eponymous Taotao, a small panda. In the stories, Taotao has adventures with his animal friends and listens to the stories of his mother, the mommy panda.  (Source: AniDB)', 48, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8125, 'Tenkuu Senki Shurato Recaps', 1989, 2, 'Special', 97.4, 'Recaps of the original show. Also known as Episode 32.5 and Episode 39.', 80, True, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8126, 'Gundam Build Fighters Try', 2014, 25, 'TV', 82.1, 'The story of Gundam Build Fighters Try is set 7 years after the end of the 1st series. Now Seiho Academys Gunpla Battle Club has only one member, Hoshino Fumina, who is a third grade student in junior high. As the president of the club, she needs two more members to participate in the upcoming All-Japan Gunpla Battle Championships. One day she encounters a transfer student named Kamiki Sekai, who has traveled around for Kenpo training with his master. Then joining by a young Gunpla builder Kousaka Yuuma, their challenge to the Gunpla Battle begins....  (Source: Crunchyroll)', 89, False, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8127, 'Yamada-kun to 7-nin no Majo: Mou Hitotsu no Suzaku-sai', 2014, 2, 'OVA', 83.6, 'Shiraishi Urara is the top student in her school. One day, due to an accidental kiss, Urara finds herself in the body of the school delinquent, Yamada Ryuu! In trying to switch back to their own bodies, Urara and Ryuu discover that kissing causes them to switch bodies, which leads to their discovery that there are 7 witches in their school. They soon try to uncover the identities of the 7 witches...  (Source: AniDB)', 112, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8128, 'Koufuku Graffiti', 2015, 12, 'TV', 88.3, 'The path to becoming a fine wife begins with being an accomplished cook—at least, that is what Ryou Machikos late grandmother had led her to believe. For a middle schooler, Ryous cooking skills are incomparable; but recently, though Ryous food looks appetizing and smells inviting, the taste has not been delicious. Just when the dejected art student comes to terms with the possibility that she might continue living alone for the rest of her life, her aunt tells her that Kirin Morino—Ryous second cousin—will begin staying with her every weekend since the younger girl has joined a cram school in Tokyo and aims to attend the same school as Ryou.  Surprisingly, with her cousins arrival, Ryou finds that her cooking has vastly improved—apparently, it is not her prowess in the kitchen, but the sharing of the experience with those closest to her that seems to make the flavors shine.', 10, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8129, 'LolitA☆Strawberry in Summer', 2012, 1, 'Music', 63.4, 'Animated music video for Tokyo Girls Style LolitA☆Strawberry in Summer', 31, True, 89);
