INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8226, 'Shoukoushi Cedie Specials', 2001, 2, 'Special', 66.1, 'A summary of the Shoukoushi Cedie full series aired as a TV specials.', 86, False, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8227, 'Bakumatsu Rock: Mystery! Onsen Kaijiken ze yo!!', 2014, 1, 'OVA', 79.9, 'An incident has led to someones death at Teradaya, which the gang went to for a day trip. A 69 on the victims leg will be the key to solving the mystery.  (Source: MAL News)', 80, True, 67);
