INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8230, 'Nanatsu no Umi no Tico Specials', 2001, 2, 'Special', 61.6, 'A summary of the Nanatsu no Umi no Tico full series aired as a TV specials.', 105, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8231, 'Meiken Lassie Specials', 2001, 2, 'Special', 79.1, 'A summary of the Meiken Lassie full series aired as a TV specials.', 94, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8232, 'Ie Naki Ko Remy Specials (2001)', 2001, 2, 'Special', 97.5, 'A summary of the Ie Naki Ko Remy full series aired as a TV specials.', 112, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8233, 'Araiguma Rascal Specials', 2000, 2, 'Special', 68.4, 'A summary of the Araiguma Rascal full series aired as a TV specials.', 12, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8234, 'Hyakubanme no Saru', 1986, 1, 'Movie', 63.7, 'Based on the 1981 book of the same name by new age guru Ken Keyes, Jr., which in turn is based on the story of a 1952 experiment on the southern Japanese island of Kojima. (Please note that the Hundredth monkey effect is discredited in the scientific community.)  Once one monkey has learned how to wash its food, it is able to teach others the same skill. When a certain number have learned (and Keyes suggests an arbitrary figure of 100), not only do the remaining monkeys suddenly appear to know how to do it, but so too does a completely different group of apes on a completely separate island. Keyes uses this apocryphal tale as a parable for the antinuclear movement, as proof that change would come if enough people joined forces.  (Source: The Anime Encyclopedia)', 99, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8235, 'Shiawase no Ouji', 1975, 1, 'Movie', 78.2, 'Based on the story by written Oscar Wilde. It won the 17th Ministry of Health and Welfare Child Welfare Culture Award for Best Educational Film.', 77, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8236, 'Hana Ichi Monme (OVA)', 1990, 3, 'OVA', 60.8, 'Animated versions of tales that won the Short Story Prize in the Hanaichi Monme bulletin, including Noboru and the Wildcat, The Misleading Friends, Sanma s March, Red Mail-Box on the Mountain-Tot), and One Sunday Morning at the Beginning of May.  (Source: The Anime Encyclopedia)', 50, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8237, 'Ore ga Ojousama Gakkou ni Shomin Sample Toshite Gets♥Sareta Ken', 2015, 12, 'TV', 80.6, 'Kimito Kagurazaka is a commoner with a fetish for mens muscles—or at least thats the lie he must keep telling if he wants to keep himself out of trouble at the elite all-girls school, Seikain Academy. Kidnapped by the school under the assumption that he prefers men, Kimito is made to be their commoner sample, exposing the girls to both commoner and man so that the transition to the world after school is not jarring. Threatened with castration should his sexual preferences not match the schools assumptions, Kimito keeps up the facade to protect his manhood.  But there are eccentric individuals around every corner who begin to make Kimitos life even more difficult. Among them are Aika Tenkuubashi, a social outcast who blurts out whatever comes to mind; Hakua Shiodome, a young genius; Karen Jinryou, the daughter of samurai who is obsessed with defeating Kimito; and Reiko Arisugawa, the perfect student who has delusions of marrying Kimito. Along with the commoner himself, these four girls make up the Commoner Club, which attempts to teach the girls more about life outside the school, while Kimito gradually learns about the odd girls surrounding him.', 50, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8238, 'Sumiko', 2008, 2, 'Special', 74.2, 'Shorts following a young girls life.', 62, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8239, 'Sumiko no Egao', 2012, 1, 'Music', 70.8, 'A music video starring Sumiko.', 81, False, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8240, 'Inuyama Kamiko no Kireigoto ja Owaranai!', 2014, 2, 'ONA', 91.4, 'A series (collaboration with a toothbrush brand REACH) following two women that aims to educate about proper dental health.', 18, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8241, 'Majokko Shimai no Yoyo to Nene Movie Extra: Hatsukoi - Mikako Komatsu', 2014, 1, 'Special', 98.8, 'An animated music video included as a bonus on the Blu-ray/DVD release of Majokko Shimai no Yoyo to Nene.', 105, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8242, 'Ryuugajou Nanana no Maizoukin: Nanana Nippon Mukashibanashi', 2014, 6, 'Special', 73.4, 'Specials included on the Blu-ray/DVD volumes.', 20, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8243, 'Oh! My Konbu', 1991, 22, 'TV', 71.0, 'Fifth-grader Nabeyama Konbu is the son of a cook in a slice-of-life gourmet comedy that tries to add an element of adventure to slaving in the kitchen. Konbu helps his father solve problems in the world through the judicious use of seasonings, the right choice of menu, and the pleasing of fickle customers.  (Source: AniDB)', 94, False, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8244, 'Kono Danshi, Sekka ni Nayandemasu.', 2014, 1, 'OVA', 70.4, 'Ayumu Tamari suffers from a condition known as Crystallization Syndrome. In moments of high stress, parts of his body begin to crystallize and become extremely difficult to move. Unfortunately, Ayumus severe social anxiety makes him completely unable to speak to anyone in his class, and ultimately causes him to crystallize so frequently that he has to repeat a year in high school.  Ayumus only solace is his homeroom teacher, Kouya Onihara, whom he affectionately refers to as Oni-chan Sensei. Kouya collects and studies crystals, and he finds Ayumus crystalline body both beautiful and fascinating. With his stress from school compounded by the complexities of a forbidden student-teacher relationship, Ayumu struggles to find normalcy in his life while managing his emotions and trying to prevent complete crystallization.', 46, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8245, 'Lu Ling', 1982, 1, 'Movie', 92.0, 'An old man and his grand daughter rescued an injured young deer. The girl and the young deer would develop a close relationship. After the recovery, the deer returned to the wild. Feeling sad the girl put a bell on the deer. Disappearing into the mountain valley, the deers bell continues to echo.  (Source: Wikipedia)', 36, True, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8246, 'Trinity Seven', 2014, 12, 'TV', 75.1, 'One day, the bright red sun stopped shining, causing the Breakdown Phenomenon—the destruction of Arata Kasugas town and the disappearance of the people inhabiting it. All, however, is not yet lost; by utilizing the magical grimoire given to him by his childhood friend and cousin Hijiri Kasuga, Aratas world gets artificially reconstructed.  In order to investigate the phenomenon, Lilith Asami appears before Arata, whose artificial world suddenly disintegrates. He is given two choices: hand over the book, or die. However, Arata chooses the third option—enrolling in the top-secret magic school Royal Biblia Academy, where six other magical users await him. Together with Lilith, these six form the Trinity Seven, the elite of the school who each bolster their own power and skill.  With the ambition to save Hijiri and the help of his newfound friends, Arata stops at nothing to prevent the destruction of his beloved hometown and to bring his best friend back.', 58, False, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8247, 'Inou-Battle wa Nichijou-kei no Naka de', 2014, 12, 'TV', 91.7, 'During a Literature Club meeting, the four club members—along with their faculty advisers niece—suddenly find themselves with supernatural powers. Now capable of fabricating black flames, resident chuunibyou Jurai Andou is the most ecstatic about their new abilities; unfortunately, his own is only for show and unable to accomplish anything of substance. Moreover, he is completely outclassed by those around him: fellow club member Tomoyo Kanzaki manipulates time, Jurais childhood friend Hatoko Kushikawa wields control over the five elements, club president Sayumi Takanashi can repair both inanimate objects and living things, and their advisers niece Chifuyu Himeki is able to create objects out of thin air.  However, while the mystery of why they received these powers looms overhead, very little has changed for the Literature Club. The everyday lives of these five superpowered students continue on, albeit now tinged with the supernatural.', 113, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8248, 'One Piece 3D2Y: Ace no shi wo Koete! Luffy Nakama Tono Chikai', 2014, 1, 'Special', 90.1, 'After suffering great personal loss during the battle of Marineford, Monkey D. Luffy finds himself stranded on Rusukaina, a treacherous island crawling with huge and dangerous creatures. There, he has committed himself to a two-year stretch of training to learn Haki, the energy that combatants can use to grant themselves a variety of abilities in battle.  Luffy is jerked away from his otherwise peaceful training by the abduction of Sandersonia and Marigold, sisters of his friend and ally Boa Hancock. With Boas aid, Luffy seeks to track down the infamous pirate responsible for the kidnapping, a man whose recent prison break is the result of Luffys own reckless actions. Luffy must use his developing grasp of Haki to defeat this new foe while coming to terms with his overbearing grief in the process.', 71, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8249, 'Tamayura: More Aggressive Picture Drama', 2013, 1, 'Special', 71.0, 'Picture drama included in the 1st Blu-ray and DVD volumes.', 119, True, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8250, 'Xiao Kedou Zhao Mama', 1960, 1, 'Movie', 62.3, 'The narrated film describes the adventures and misadventures of a group of tadpoles in search of their mother. It is one of Te Weis first attempts to break away from Western style animation and aim for a painterly style influenced by Qi Baishi and more in keeping with native Chinese aesthetic sensibilities.  (Source: Wikipedia)', 113, False, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8251, 'Gangsta.', 2015, 12, 'TV', 81.8, 'Nicholas Brown and Worick Arcangelo, known in the city of Ergastalum as the Handymen, are mercenaries for hire who take on jobs no one else can handle. Contracted by powerful mob syndicates and police alike, the Handymen have to be ready and willing for anything. After completing the order of killing a local pimp, the Handymen add Alex Benedetto—a prostitute also designated for elimination—to their ranks to protect her from forces that want her gone from the decrepit hellhole of a city she has come to call home. However, this criminal’s paradise is undergoing a profound period of change that threatens to corrode the delicate balance of power.  Ergastalum was once a safe haven for Twilights, super-human beings born as the result of a special drug but are now being hunted down by a fierce underground organization. This new threat is rising up to challenge everything the city stands for, and the Handymen will not be able to avoid this coming war.', 16, True, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8252, 'Donguri Mori e', 1999, 1, 'OVA', 73.6, 'No description available for this anime.', 93, False, 92);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8253, 'AkaKill! Gekijou', 2014, 24, 'ONA', 90.5, 'Short specials that aired on the official website.', 13, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8254, 'Nekketsu Jinmen Inu: Life Is Movie', 2014, 3, 'OVA', 94.4, 'The Life Is Movie featuring indie animator Junichi Yamamoto and Flash animator Tokumaru Naoko reintroducing the Hidenori Takahashi voiced passionate human-faced dog NEET/would be detective will be released as OVA and online on the Bandai Channel later this summer.  (Sourced: Crunchyroll)', 112, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8255, 'Persona 4 the Animation: Mr. Experiment Shorts', 2013, 5, 'Special', 79.5, 'Short animations included in the Persona 4 The Animation Collection 2nd DVD Box set.', 68, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8256, 'Persona 4 the Animation: A Brief Lesson on Izanagi & Izanami', 2013, 1, 'Special', 93.2, 'Included in the Persona 4 The Animation Collection 2nd DVD Box set.', 17, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8257, 'Megumi to Taiyou: Kajuu Gummi Tweet Love Story', 2011, 1, 'Special', 74.1, 'The Megumi and Taiyou commercial depicts the reunion of a girl named Megumi (Ai Hashimoto), who was raised near a grape orchard, and her childhood friend Taiyou (Sakuma Kazuyuki).  (Source: ANN)', 112, False, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8258, 'Megumi to Taiyou II: Kajuu Gummi Tweet Mystery - Kieta Sapphire Roman no Nazo', 2012, 1, 'Special', 68.5, 'The Megumi and Taiyou II commercial centers on the mystery of Taiyous missing Sapphire Roman—a seedling for grapes of legendary taste.  (Source: ANN)', 82, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8259, 'Shinano Mainichi Shinbun', 2007, 1, 'Special', 84.1, 'A 15-second animated commercial for The Shinano Mainichi Shimbun newspaper in Nagano.', 67, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8260, 'Kuusen Madoushi Kouhosei no Kyoukan', 2015, 12, 'TV', 80.9, 'Years ago, humanity almost got wiped out by huge magical armored insects that had become too strong and aggressive to handle. Because of these giant bugs, humans do not live on the earth anymore, but in floating cities instead. However, this does not mean that everything is lost, because the wizards from prestigious floating wizard academies are fighting these monsters.  Kanata Age is a young man now labelled as a traitor even though he was once praised as the Black Master Swordsman. He gets a chance to repair his reputation by instructing the team E601, which seems to be facing some difficulties. It consists of three girls, Misora Whitale, Lecty Eisenach, and Rico Flamel, each with problems of their own. It appears that Kanata will get in deep waters more than once because of them...', 118, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8261, 'Seireitsukai no Blade Dance Specials', 2014, 6, 'Special', 67.3, 'Mini specials bundled with each Blu-ray/DVD volume of Seireitsukai no Blade Dance.  Each special is tied to the new 32-page short story that original light novel author Shimizu Yuu wrote for the limited first pressing of every Blu-ray/DVD volume.', 58, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8262, 'Yomiuri Shimbun', 2009, 1, 'Special', 96.6, 'A 15 second long commercial produced for the Yomiuri Shimbun newspaper.', 46, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8263, 'Futago no Mahoutsukai Lico to Gli', 2013, 4, 'ONA', 86.4, 'Glico, the prominent food manufacturer best known for its pretzel stick snacks Pocky and Pretz, has long relied on its classic running man character and real-life celebrities to promote its products. Now it has finally bowed to prevailing trends and introduced two moe-style anime characters to broadcast its message.  Lico and Gli are twin brother and sister magicians dedicated to making the world tastier. A newly posted music video has Lico sing (via Vocaloid) about granting everyones wishes with her sparkly magic.  (Source: ANN)', 14, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8264, 'Dosukoi! Wanpaku Dohyou', 1994, 1, 'Movie', 98.2, 'Shown as a double feature with Dohyou no Oni-tachi.  (Source: AniDB)', 42, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8265, 'Maya no Isshou', 1996, 1, 'Movie', 99.8, 'No description available for this anime.', 116, False, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8266, 'Haikyuu!! Lev Genzan!', 2015, 1, 'OVA', 81.7, 'Nekoma High Schools volleyball team recruits a new member: the half-Japanese, half-Russian Lev Haiba. Though the self-proclaimed ace is blessed with great height, he lacks basic volleyball techniques. This gives the teams setter, Kenma Kozume, a hard time when matching up with him.   To everyones surprise, Nekomas coach suggests that Lev play in the Kunihira Senior High Schools practice match, leaving Kenma no choice but to cooperate with the tall player. Will Kenma be able to overcome this new challenge?', 62, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8267, 'Isewan Taifuu Monogatari', 1989, 1, 'Movie', 80.1, 'On September 26, 1959, Super Typhoon #15 (also known as T5915, Vera, or Isewan Typhoon), struck the coast of Japan with the maximum wind speed of 305 km/h, causing over 5,000 dead or missing plus over 30,000 injured, the heaviest casualty caused by a single typhoon in Japan in 20th century. This animated movie was produced on the 30th anniversary of the tragedy in order to commemorate the dead and survivors.  (Source: AniDB)', 60, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8268, 'Gintama: Futon ni Haitte kara Buki Nokoshi ni Kizuite Neru ni Nerenai Toki mo Aru', 2015, 1, 'Special', 79.5, 'Bundled with limited edition of the 58th Gintama manga volume.  The tagline for the bundled anime reads, Its time for all the Yorozuya members ...to wake up just one more time.  (Source: MAL News, edited)', 93, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8269, 'Sensuikan ni Koi wo Shita Kujira no Hanashi', 1989, 1, 'Movie', 62.2, 'No description available for this anime.', 89, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8270, 'Diamond no Ace OVA', 2014, 3, 'OVA', 64.6, 'One hundred boys, each of them in love with baseball, represent the Seidou High School baseball team. On any team, the Ace is the star of the game. Besides the main heroes, others are striving to attain this position, and each of them has their strengths, weaknesses, and emotional journeys that they have to undertake to become the best that they can be.  Ryousuke Kominato is known in Seidou not only for his impressive fielding skills but also as an intimidating presence despite his small stature. While together with his partner, Youichi Kuramochi, they are the cornerstones of the teams defense on the field.  Youichi is shadowed by his younger brother, Haruichi, whose admiration for Ryousuke is only matched by his own skills at the sport. Together with Yoichis roommate, Eijun Sawamura, the players reminisce about their path to Seidou High.', 32, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8271, 'Gensei Shugoshin P-hyoro Ikka', 1988, 3, 'OVA', 70.2, 'Based on Kaori Kimekis fantasy manga serialized in Princess magazine.', 27, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8272, 'Pokemon XY: Koukoku no Princess Diancie', 2014, 1, 'Special', 80.5, 'In order to save the Diamond Ore Kingdom from certain danger Princess Diancie and the Carbink who serve as her butlers set off together on a journey to find the legendary Pokémon Xerneas. But who is that waiting for them on the road ahead...!?   (Source: Pokémon Wiki)', 71, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8273, 'Moon Pride', 2014, 1, 'Music', 68.6, 'Music video for Momoiro Clover Zs song MOON PRIDE', 105, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8274, 'TOTO Green Challenge', 2011, 1, 'ONA', 97.8, 'A four minute educational commercial by TOTO about water and how the TOTO ecotechnology works.', 43, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8275, 'Doraemon Movie 35: Nobita no Space Heroes', 2015, 1, 'Movie', 76.2, 'Nobita wishes to be a real hero. Doraemon uses his gadget, the Burger Director to make them a real movie superhero. Aron saw the five powers and abilities and asks them to help him save his planet, the planet Pokkuru. After their journey to the planet, the gang thought it was only Burgers doing but realizing that it is not a movie and they are actually fighting bad guys.  (Source: IMDb)', 27, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8276, 'Dragon Ball Z Movie 15: Fukkatsu no F', 2015, 1, 'Movie', 83.8, 'Earth is finally peaceful again, but this calm is short-lived. The remnants of Friezas army, led by Sorbet and his right hand Tagoma, arrive on Earth in order to summon Shen Long with the goal of resurrecting their old master. To do so, they threaten Emperor Pilaf, Shuu, and Mai for the Dragon Balls in their possession.  Once successfully revived, Frieza—who had been stoking his hatred for Gokuu Son and Future Trunks in Hell—proclaims that he will not be content until they are dead by his hand. Sorbet informs him that Future Trunks has not been heard of in years, and Gokuus power has far surpassed even that of the mighty Majin Buu. Unfazed, Frieza responds that he only requires a few months of training before being capable of defeating Gokuu.  Will Frieza be able to exact revenge upon his nemesis, or will Gokuu, Vegeta, and their friends prevail against adversity, saving Earth once more?', 108, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8277, 'Master of Torque 2', 2015, 1, 'ONA', 70.0, 'A continuation of the first season.  Makina lost consciousness when the Marishi Machina suit developed by the Hyuga Corporation seized control of her body and sent her charging onto the new Shutoko expressway on an MT-07. Luckily, Dan was able to stop her before it was too late. With Makina on the back of his MT-09 Street Rally, Dan began riding back towards the Genesis Café only to be intercepted by Hyuga Corporation chairman Mitsukuni Hyuga. He was waiting for them with an unsettling expression on his face.  Dan was sure that he would be forced to resign his job for getting the heir to the company’s presidency, Kotaro Hyuga, involved in this mess. But when Makina confronts Mitsukuni about the truth behind the incident that claimed their parents’ lives, Dan is given an order he would never have expected.  Dan keeps trying to avoid facing the trauma he experienced as a child, but is encouraged to find the truth by Makina. Sanae, the owner of the Genesis Café, seems to notice their troubled state and takes matters into her own hands.  Can Dan face his past and free himself of the curse he has borne and reclaim his future with his own hands?  The interlocked gears of fate driving the destinies Dan, Makina and Kotaro begin to move again, and the next part of their story is about to unfold...  (Source: Yamaha site)', 64, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8278, 'Absolute Duo', 2015, 12, 'TV', 86.3, 'Individuals who can materialize weapons from their soul are called Blazers, and they attend Kouryou Academy High School in order to harness their abilities. Each student is required to partner with another, in the hopes that one day, the pair can attain the power of Absolute Duo.  Tooru Kokonoe hopes to attend this academy in order to gain power after his sister and friends were slain by a mysterious man. However, at the opening ceremony, he is forced to duel against the person sitting next to him, with the loser being expelled. As Tooru prepares to give the match his all, it is not a weapon that manifests from his soul, but a shield, an irregularity which catches the attention of a foreign student named Julie Sigtuna.', 94, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8279, 'Isuca', 2015, 10, 'TV', 88.8, 'Poor Shinichirou Asano has the worst of luck. His parents abandoned him and ran off to Europe. If that isnt bad enough on its own, they barely left him any money to take care of himself. In order to pay rent and keep a roof over his head, he has to work. Unfortunately, he was just fired from his last job and as a high school student, he doesnt have many other prospects.  One evening, hes attacked by a centipede monster on his way home. Shinichirou is saved by a mysterious girl with a bow and arrow, who he later discovers is Sakuya Shimazu, a beautiful student who attends his school. But when he later helps an injured girl, he discovers two things. First, the injured girl isnt human at all but rather a nekomata, a two-tailed demon cat. And second, Sakuya comes from a family of exorcists, whove protected humanity from rogue monsters and spirits for generations. Because Shinichirou was responsible for releasing the nekomata, Sakuya enlists his help in recapturing the demon, but thats just the beginning of Shinichirous relationship with Sakuya. It turns out the Shimazu family needs a housekeeper and it just so happens that Shinichirou excels at cooking and likes to clean! It may not be his dream job, but if it pays the rent and puts food on the table...', 75, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8280, 'Chain Chronicle: Short Animation', 2014, 8, 'OVA', 62.6, 'An anime adaptation of the game for mobile devices Chain Chronicle.  Features eight short episodes that introduces the story, setting, and characters.', 21, False, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8281, 'Brothers Conflict OVA', 2014, 2, 'OVA', 70.5, 'Two Brothers Conflict OVAs about Christmas and Valentines Day. New OP and ED songs by the same singers were presented in these two OVAs.  (Source: MAL News, edited)', 109, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8282, 'Choboraunyopomi Gekijou Dai Ni Maku Ai Mai Mii: Mousou Catastrophe - Shojo Kuriya', 2014, 1, 'Special', 82.9, 'Unaired episode inluded with the Blu-ray/DVD release.', 40, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8283, 'Shin Strange+ Special', 2014, 1, 'Special', 67.2, 'Unaired episode included with the Blu-ray/DVD release.', 77, True, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8284, 'Avengers Confidential: Black Widow to Punisher', 2014, 1, 'Movie', 85.8, 'After interfering with a top secret mission, the Punisher is taken into custody by S.H.I.E.L.D. Agent and Avenger, Black Widow. At the orders of Director Nick Fury, Punisher and Black Widow are sent on a mission to stop Leviathan, a global terrorist organization that plans to sell stolen S.H.I.E.L.D. technology to the highest bidder. Now, the vigilante and spy must work together to prevent this technology from falling into the wrong hands. The fate of the world, and of the Avengers, hangs in the balance.   The Japan Blu-ray/DVD release date is September 3rd, 2014.', 51, True, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8285, 'Tatamp', 2011, 1, 'Movie', 98.2, 'Mirai Mizue continues his experimentation with music and movement in his latest cell animation, Tatamp. Not to be confused with the animation technique of cel animation, Mizue’s unique style of cell animation is hand-drawn and colored on paper then scanned onto the computer for editing. The name refers to the fact that the creatures that he draws resemble amoeba and other minute organic creatures one might find under the lens of a microscope.  (Source: Nishikataeiga Reviews)', 20, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8286, 'Ishinomori Shoutarou no Rekishi Adventure', 1992, 5, 'OVA', 76.5, 'A two-part video series in which Dr. Teng (a researcher at the Time Institute) and his faithful kappa assistant Pasuke travel through time, first to the Battle of Sekigahara (1600) and then to the fourth Battle of Kawanakajima (1561). In the second installment, they then look in on the last stand of the Japanese underdog hero Yoshitsune in Hiraizu mi (1189) and then, after spending so much time on the Genpei War, suddenly leap several centuries into the future, to cover the first time Nobunaga Oda used firearms in battle, at Nagashino (1575) . A mixture of live-action and anime, described by Japanese sources as a documentary with a touch of story, and presumably related in some way to Shotaro Ishinomoris multivolume manga history of Japan.  (Source: The Anime Encyclopedia)', 38, True, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8287, 'Megumi to Taiyou III: Kajuu Gummi Tweet Fantasy - Timeline World', 2012, 1, 'Special', 88.2, 'The third Megumi to Taiyou CM for Meijis Kajuu Gummi candies.', 62, False, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8288, 'fake!fake!', 2014, 1, 'Music', 67.7, 'Music video for the song fake!fake! by A Crow Is White.', 40, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8289, 'Fuusen Inu Tinny', 2014, 26, 'TV', 91.9, 'Based on a picture book series, it follows a dog who flies above the clouds with a balloon.', 34, True, 9);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8290, 'Magic Kaito 1412', 2014, 24, 'TV', 61.0, 'Eight years after the mysterious death of his father, Kaito Kuroba, a slightly mischievous but otherwise ordinary teenager, discovers a shocking secret: the Phantom Thief Kaito Kid—also known as The Magician Under the Moonlight—was none other than his own father. The former thief was murdered by a criminal organization seeking a mythical stone called the Pandora Gem, said to shed a tear with the passing of the Valley Comet that comes every ten thousand years. When the tear is consumed, the gem supposedly grants immortality.  Vowing to bring those responsible for his fathers death to justice, Kaito dons the Phantom Thiefs disguise, stealing priceless jewels night after night to find the Pandora Gem before his enemies can use the power for themselves.', 61, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8291, 'Yuuki Yuuna wa Yuusha de Aru', 2014, 12, 'TV', 88.0, 'In her everyday life, Yuuna Yuuki is a hero. As proof, she is in her middle schools Hero Club, where she does her best to help others and bring a smile to everyones face.  But Yuuna, always up to any task, is about to become an even bigger hero. Mysterious destructive forces called Vertexes begin threatening the world she loves, and the Hero Club is called upon by a strange phone app to save it. Along with her best friend Mimori Tougou, as well as sisters Fuu and Itsuki Inubouzaki, they must transform into magical girls in order to battle the Vertexes.  In between studying and putting on shows for kids, Yuuna and the Hero Club must fight for the very existence of their world and face the harsh truths behind their own powers, all the while discovering what it truly means to be a hero.', 43, False, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8292, 'Many Mary', 2013, 1, 'Music', 96.0, 'Music video for the song Many Mary by A Crow Is White.', 26, True, 12);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8293, 'Fate/stay night Movie: Heavens Feel - I. Presage Flower', 2017, 1, 'Movie', 77.6, 'The Holy Grail War: a violent battle between mages in which seven masters and their summoned servants fight for the Holy Grail, a magical artifact that can grant the victor any wish. Nearly 10 years ago, the final battle of the Fourth Holy Grail War wreaked havoc on Fuyuki City and took over 500 lives, leaving the city devastated.   Shirou Emiya, a survivor of this tragedy, aspires to become a hero of justice like his rescuer and adoptive father, Kiritsugu Emiya. Despite only being a student, Shirou is thrown into the Fifth Holy Grail War when he accidentally sees a battle between servants at school and summons his own servant, Saber.   When a mysterious shadow begins a murderous spree in Fuyuki City, Shirou aligns himself with Rin Toosaka, a fellow participant in the Holy Grail War, in order to stop the deaths of countless people. However, Shirous feelings for his close friend Sakura Matou lead him deeper into the dark secrets surrounding the war and the feuding families involved.', 117, True, 13);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8294, 'Moom', 2016, 1, 'Movie', 98.8, 'Every forgotten object has a memory with its previous owner still attached. This is a story of Moom, one of those memories stuck in this world. One day, Moom meets another memory just like him.  (Source: AniDB)', 59, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8295, 'M3: Sono Kuroki Hagane Recap', 2014, 1, 'ONA', 71.4, 'Recap of episodes 1-13.', 85, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8296, 'Tanu no Magical Holiday', 2014, 1, 'Music', 77.4, 'No description available for this anime.', 92, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8297, 'Momons Sand Witch Bangai-hen: Tanu no Kyuujitsu', 2014, 1, 'ONA', 65.9, 'No description available for this anime.', 116, True, 17);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8298, 'Psychedelic Afternoon', 2013, 1, 'Music', 72.4, 'Seiji is tormented by horrible tsunami-flashback dreams, but one night he wakes up and his beloved grandfather has appeared. With a strum of his grandfather’s guitar, Seiji is transported to a colorful, slightly strange, psychedelic world and finally manages to have a good dream.  (Source: Zapuni.com)', 110, True, 18);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8299, 'DRAMAtical Murder: Data_xx_Transitory', 2014, 1, 'Special', 93.8, 'Data xx Transitory is the thirteenth and bonus episode of the DRAMAtical Murder animation. It features all of the bad endings from the original game.  (Source: DRAMAtical Murder Wiki)', 118, True, 19);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8300, 'Yeongsimi', 1990, 13, 'TV', 68.5, 'No description available for this anime.', 33, True, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8301, 'Tokyo Juushouden: Fuuma Gogyou Denshou', 2001, 3, 'OVA', 92.0, 'Long ago, in feudal Japan, there was a fierce warrior named the Demon King. He controlled a band of demons, known as the Kyouma. Only the powers of ten warriors sealed the Demon King away and kept the Kyouma under control. But now, Lord Shindigan, a powerful Kyouma is planning to free the Demon King, and the reincarnations of the ten warriors must band together and save the earth.  (Source: ANN)', 65, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8302, 'Vampiyan Kids Specials', 2002, 3, 'Special', 85.6, 'DVD-only specials released on the 6th and 7th discs that are sometimes considered episode 24, 25, and 26 as a whole. And episode 22, 23, and 24 chronologically.', 45, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8303, 'Vampiyan Kids Promotion', 1999, 1, 'Special', 61.5, 'This shows the pre-character designs and the pre-pilot scenes in animated in 3D CG. It is part animation, part live-action. The live-action part shows Suzuka Yoshida as she is the original character designer for the franchise with her drawing coming to life.', 62, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8304, 'Pink Lady Monogatari: Eikou no Tenshi-tachi Recaps', 1979, 2, 'Special', 85.9, 'Omnibus/compilation episodes of the main series that aired on TV right after the main series finished broadcasting sometimes known as episode 34 &amp; 35.', 106, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8305, 'Mochi Mochi no Ki (OVA)', 1992, 1, 'OVA', 91.3, 'Five-year-old Mameta lives with Grandpa. Hes a timid boy, who always wakes Grandpa up to accompany him when he has to go to the outhouse in the middle of the night. The shadow of the giant horse-chestnut tree in the yard scares him.  Grandpa tells him that just once a year, on November 20, a single brave child sees a light in the tree, but Mameta is still too scared and goes to sleep. But that very night, Grandpa suffers from intense stomach pain, and Mameta, forgetting his fears, races barefoot down the mountain to summon the doctor. On the way back up the mountain, the doctor carries him piggyback, and from his perch on the doctors back, Mameta sees a light in the tree.  Even so, the next night and the night after, he continues to ask Grandpa to go with him to the outhouse.  The moral of the story is summarized in Grandpas words to Mameta: You should never think of yourself as weak or timid. So long as you have caring in your heart, youll find that youll be able to do what needs doing.  (Source: booksfromjapan.jp)', 99, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8306, 'Sekai no Fushigi Tanken Series', 1978, 10, 'TV', 61.1, 'Documentaries combining anime with live action, exploring a mixed bag of mysteries and historical topics, including the statues of Easter Island, the search for a lost continent, the Bermuda Triangle, the NAZCA Lines, the Sphinx and the Pyramids, the Greenwich Meridian, the Leaning Tower of Pisa, and the Great Buddha of Nara. Confusing in its inability to decide whether it wants to be history, geography, travelogue, or the titular mysteries.  (Source: The Anime Encyclopedia)', 61, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8307, 'Genki Genki Non-tan', 2002, 15, 'TV', 81.4, 'This 3D animated series for young children is based on the adventures of perky white kitten Non-tan. With his friends, fun-loving Tanuki, strong Bear, and the pink Rabbit triplets and his rival, Pig, he teaches children positive lessons about the beauty and wonder of life.  (Source: The Anime Encyclopedia)', 85, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8308, 'Genki Genki Non-tan (2004)', 2004, 10, 'TV', 93.9, 'Direct continuation of the first season. Also labeled as episode 16-25.', 25, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8309, 'Genki Genki Non-tan: Utaou! Christmas', 2004, 1, 'OVA', 98.5, 'A Christmas OVA of Non-tan that features eight classic Christmas songs sung and acted out by the characters.', 33, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8310, 'Genki Genki Non-tan (2006)', 2006, 10, 'TV', 94.9, 'Direct continuation of the second season. Also labeled as episode 26-35.', 48, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8311, 'Genki Genki Non-tan: Deka Deka Arigatou', 2009, 1, 'OVA', 68.7, '7 sing-along songs and nursery rhymes featuring the main cast acting them out. Some are international classics such as Ten Little Indians and others are classic Japanese ones such as Close Hands, Open Hands (Musunde Hiraite).', 66, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8312, 'Genki Genki Non-tan: Spoon Tan Tan Tan', 2013, 1, 'OVA', 96.8, 'This edition focuses on teaching kids good house manners. Such as eating all the food on your plate; to taking naps when instructed to so you can grow up big and strong; to avoiding wetting the bed and how to handle the situation if you do.', 70, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8313, 'Rouge: Ladys Comic Video', 1997, 2, 'OVA', 95.4, 'Bereaved strangers lose themselves in a sordid double life of prostitution but find love with each other. A loveless marriage blossoms through bondage. A trainee gets more than she bargained for when the head nurse takes the biology lesson to the limit. And a male beautician uses unorthodox methods to put color in a makeup artists cheeks. Four erotically charged tales animated for a female audience, based on stories originally printed in the manga magazine Rouge.  (Source: The Anime Encyclopedia)', 118, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8314, 'Aesop no Ohanashi yori: Ushi to Kaeru, Yokubatta Inu', 1970, 1, 'Movie', 75.8, 'Based on Aesops Fables.', 64, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8315, 'Futari no Tarou', 1990, 1, 'OVA', 61.3, 'A modern boy Tarou timeslips into the Edo period and experiences the severity of the caste system.', 25, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8316, 'Space☆Dandy Picture Drama', 2014, 2, 'Special', 69.2, 'Picture drama episodes included on the Blu-ray/DVD volume four and five.', 43, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8317, 'Toilet no Kamisama', 2010, 1, 'Music', 91.5, 'An animated music video by Daisuke Hashimoto for the song Toilet no Kamisama by Kana Uemura.', 58, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8318, 'Monotonous Purgatory', 2012, 1, 'Music', 92.7, 'Animated with oil on glass music video by Shiroki Saori for the song Monotonous Purgatory by Matryoshka from their album Laideronnette.', 35, True, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8319, 'Sabage-bu! Specials', 2014, 6, 'Special', 97.4, 'Short OVA bundled with the volumes 1 to 6 of the Blu-ray releases of Sabagebu!', 108, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8320, 'Junjou Romantica 3', 2015, 12, 'TV', 67.8, 'After living together for three years, Misaki Takahashi and Akihiko Usagi Usamis relationship has been progressing smoothly. However, all great relationships have problems, and theirs is just beginning. With a new rival on the horizon, Usagi worries about Misakis feelings towards him.   Meanwhile, Ryuuichirou Isaka has always loved to intrude on Misaki and Usagis love life, but his own love life hasnt been all smooth sailing—Isaka and his secretary Kaoru Asahina have been dating for a few years; however, Asahina prefers to keep their professional and private lives separate, often leading to troubled waters between them.  As for Nowaki Kusama and Hiroki Kamijou, now that their careers are finally taking off, they hardly see each other anymore. With the time they spend together lessening, doubts and insecurities threaten to creep in between them. On the other hand, the 17-year age gap between Shinobu Takatsuki and You Miyagi has been a constant barrier in their relationship, but as they learn more about each other, their self-consciousness continues to fade.  The beloved couples of Junjou Romantica, Junjou Egoist, and Junjou Terrorist are back again, this time with a new addition: Junjou Mistake!', 59, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8321, 'Mikan Enikki Specials', 1993, 2, 'Special', 62.9, 'An extra episode and a special of the Mikan Enikki series included as a bonus on VHS/DVDs.', 99, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8322, 'Kamisama Hajimemashita◎', 2015, 12, 'TV', 94.5, 'Nanami Momozono and her familiars Tomoe and Mizuki have survived quite a few challenges since Nanami took up the mantle of Mikage Shrines patron god. Naturally, the wind god Otohiko comes to invite Nanami to the Divine Assembly in Izumo, the home of the gods, and Nanami chooses to take Mizuki with her, leaving Tomoe to pose as her at school. However, she has an ulterior motive for attending the Divine Assembly: to discover the whereabouts of the missing Lord Mikage, the former god of the shrine.   After her adventures in Izumo, Nanami meets Botanmaru, a tengu child looking for someone she knows all too well—tengu turned goth idol Shinjirou Kurama. Botanmaru needs Shinjirou, their prince, to return home to Mount Kurama and stop the tyranny of Jirou, who has taken over the rule of their hometown. However, Nanami soon discovers a force much darker than Jirou is at work on the mountain.  As a fledgling god becoming more accustomed to divinity, Nanami finds herself dealing with a tengu rebellion, her blooming feelings for Tomoe, and a strange man with ties to both Tomoes past and Nanamis future.', 35, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8323, 'Digimon Adventure tri. 1: Saikai', 2015, 1, 'Movie', 80.7, 'The gate to the Digital World has been closed for three years. Taichi Yagami and his friends have since moved on, and now that he is in his second year of high school, it is time for him to grow up. While everyone else knows what they want to do with their lives, Taichi remains unsure. Meanwhile, the group drifts further apart as they follow their own paths.  One day, a rogue insectoid Digimon called Kuwagamon materializes and disrupts electronics all over the city. Taichi recklessly chases after it and ends up cornered by the attacking Digimon. Suddenly, the Digivice that he still carries—a digital device that serves various purposes including helping ones Digimon partner to evolve—glows, and Agumon appears. The two are able to defeat Kuwagamon, but why did the Digimon cross over to this world in the first place? What is happening in the Digital World, and how exactly does this involve Meiko Mochizuki, the new transfer student in Taichis class?', 107, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8324, 'Hyakka Ryouran: Samurai After', 2015, 2, 'OVA', 61.2, 'OVA bundled with Niθ Art Works Vol. 2, featuring a new character named Kagekatsu Uesugi.', 14, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8325, 'AIUEO Anime Sekai no Douwa: Aesop Monogatari Anime Series', 1989, 26, 'TV', 93.8, 'Based on the Fairy tales by international authors.', 100, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8326, 'Futsuu no Joshikousei ga [Locodol] Yattemita.: Nagarekawa, Annai Shitemita.', 2014, 1, 'Special', 63.9, 'Unaired episode titled Nagarekawa, Annai Shite Mita. bundled with the Volume 1 Blu-ray/DVD.', 111, True, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8327, 'Tamayura: Sotsugyou Shashin Part 1 - Kizashi', 2015, 1, 'Movie', 85.6, 'The first movie of a four-part finale of Tamayura.', 42, True, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8328, 'Cross Ange: Tenshi to Ryuu no Rondo', 2014, 25, 'TV', 70.3, 'Angelise Ikaruga Misurugi is the first princess of the noble Misurugi Empire. The kingdom has seen great power and prosperity due to the advancement of the revolutionary technology known as Mana, an abstract bending of light that has reduced the worlds problems of war and pollution to a timeless peace.   However, not all are blessed with the ability to wield Mana. Those who cannot are labeled Norma, outcasts of society who are considered a threat to civilization and live under constant persecution, and Angelise herself is one of many who want the Norma exterminated. But as Angelises sixteenth birthday commences, it is discovered in a shocking revelation that she is actually a Norma. Chaos ensues, the public is outraged, and the once adored princess is exiled to Arzenal: a remote military base where Normas are forced into conscription.  Now, the former royal must adapt to a harsh and vastly different lifestyle; piloting mechanical robots known as Paramail to fend off large, devastating beasts referred to as DRAGONs. However, a sinister truth about these savage creatures threatens to change everything.', 29, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8329, 'Yatterman Specials', 2008, 2, 'Special', 60.6, 'Two extended specials. The first one parodies Monta Mino, a famous real life Japanese entertainer. The second one parodies the US television show 24.', 35, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8330, 'Yowamushi Pedal: Re:Ride', 2014, 1, 'Movie', 98.7, 'A retelling of the first season, taking place at Toudous family inn where he, Makishima, and Onoda reflect on the events.', 103, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8331, 'Shingeki no Kyojin Season 2', 2017, 12, 'TV', 88.2, 'For centuries, humanity has been hunted by giant, mysterious predators known as the Titans. Three mighty walls—Wall Maria, Rose, and Sheena—provided peace and protection for humanity for over a hundred years. That peace, however, was shattered when the Colossal Titan and Armored Titan appeared and destroyed the outermost wall, Wall Maria. Forced to retreat behind Wall Rose, humanity waited with bated breath for the Titans to reappear and destroy their safe haven once more.  In Shingeki no Kyojin Season 2, Eren Yeager and others of the 104th Training Corps have just begun to become full members of the Survey Corps. As they ready themselves to face the Titans once again, their preparations are interrupted by the invasion of Wall Rose—but all is not as it seems as more mysteries are unraveled. As the Survey Corps races to save the wall, they uncover more about the invading Titans and the dark secrets of their own members.', 24, True, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8332, 'Shingeki no Kyojin: Kuinaki Sentaku', 2014, 2, 'OVA', 92.9, 'Many years before becoming the famed captain of the Survey Corps, a young Levi struggles to survive in the capitals garbage dump, the Underground. As the boss of his own criminal operation, Levi attempts to get by with meager earnings while aided by fellow criminals, Isabel Magnolia and Farlan Church. With little hope for the future, Levi accepts a deal from the anti-expedition faction leader Nicholas Lobov, who promises the trio citizenship aboveground if they are able to successfully assassinate Erwin Smith, a squad leader of the Survey Corps.  As Levi and Erwin cross paths, Erwin acknowledges Levis agility and skill and gives him the option to either become part of the expedition team, or be turned over to the Military Police, to atone for his crimes. Now closer to the man they are tasked to kill, the group plans to complete their mission and save themselves from a grim demise in the dim recesses of their past home. However, they are about to learn that the surface world is not as liberating as they had thought and that sometimes, freedom can come at a heavy price.  Based on the popular spin-off manga of the same name, Shingeki no Kyojin: Kuinaki Sentaku illustrates the encounter between two of Shingeki no Kyojins pivotal characters, as well as the events of the 23rd expedition beyond the walls.', 38, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8333, 'Shouwa Genroku Rakugo Shinjuu: Yotarou Hourou-hen', 2015, 2, 'OVA', 83.4, 'Bundled with the special editions of the mangas 7th and 8th volumes.  When a certain man is released from prison, he knows exactly where hes heading first. After falling in love with a traditional comic storytellers rendition of the story called Shinigami, he is determined to become his apprentice. The performer, Yakumo, has never taken an apprentice before, but to everyones surprise, he accepts the eager ex-prisoner, nicknaming him Yotaro.  As Yotaro happily begins his new life, he meets others in Yakumos life, including Yakumos ward Konatsu. Konatsu was the daughter of a famous storyteller, and Yakumo took her in after her fathers tragic death. Konatsu loved her fathers storytelling, and would love to become a performer in her own right—but that path is not available for women.  (Source: MangaHelpers)', 68, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8334, 'Pokemon Movie 18: Ring no Choumajin Hoopa', 2015, 1, 'Movie', 76.6, 'A century ago, the power of a mighty creature known as Hoopa, who is capable of single-handedly defeating legendary Pokémon, was captured in a bottle by a lone traveler. The bottle was then hidden deep inside a cave in the desert, in the hopes that the darkness sealed within it would never see the light of day again.  Years later, a young man finds the bottle and breaks the curses surrounding it, releasing the power confined within it. Its contents take the form of Hoopas shadow, and it uses its unbound power to shatter the bottle and prevent anyone from capturing it again. The shadow then goes on a rampage and attacks the original Hoopa, while both Pokémon summon other legendary creatures to aid them in their brawl. Satoshi—a budding Pokémon trainer from the Kanto region—and his friends are caught up in the crossfire, and must now work to stop the ravaging Pokémon, or face a devastating clash of legends.', 55, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8335, 'Oretachi Ijiwaru Kei', 2004, 14, 'TV', 83.0, 'An anime about Keis daily life.', 87, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8336, 'Yokohama Bakkure-tai', 1993, 4, 'OVA', 82.2, 'Its all gags and fighting as gangster Tsunematsu Narita (the biggest idiot in Yokohama) causes havoc in the neighborhood with his two henchmen.   Based on the Shonen Champion manga by Tetsu Kusumoto.   (Source: The Anime Encyclopedia)', 95, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8337, 'Zephyr', 2014, 1, 'Special', 63.5, 'The story revolves around the boy band named Zephyr, who lives in the slums of Tokyo in the near future. They stopped producing music after a war. One day Ned, the lead vocalist, receives a message on his phone from his girlfriend who he thought died in the war.  (Source: ANN)', 19, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8338, 'Shirobako', 2014, 24, 'TV', 99.3, 'It all started in Kaminoyama High School, when five best friends—Aoi Miyamori, Ema Yasuhara, Midori Imai, Shizuka Sakaki, and Misa Toudou—discovered their collective love for all things anime and formed the animation club. After making their first amateur anime together and showcasing it at the culture festival, the group vows to pursue careers in the industry, aiming to one day work together and create their own mainstream show.  Two and a half years later, Aoi and Ema have managed to land jobs at the illustrious Musashino Animation production company. The others, however, are finding it difficult to get their dream jobs. Shizuka is feeling the weight of not being recognized as a capable voice actor, Misa has a secure yet unsatisfying career designing 3D models for a car company, and Midori is a university student intent on pursuing her dream as a story writer. These five girls will learn that the path to success is one with many diversions, but dreams can still be achieved through perseverance and a touch of eccentric creativity.', 40, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8339, 'Bonjour♪Koiaji Pâtisserie', 2014, 24, 'ONA', 93.7, 'With dreams of becoming a pâtissiere, Sayuri Haruno has worked hard for her scholarship to Fleurir Confectionery Academy, an elite school designed to train world class pastry chefs. The staff consists of unrivalled pâtissiers, who work with absolute precision—the prince-like Mitsuki Aoi, famous for his work with chocolate; the friendly and extroverted Gilbert Hanafusa, an expert in confectionery hailing from France; and the stoic Yoshinosuke Suzumi, who has perfected the art of Japanese sweets.  Upon admission to the school, Sayuri is thrust into a world of advanced baking, surrounded by both supportive and charming staff and fascinating classmates. Sayuris attention is captured by the dedicated Ryou Kouzuki, who seems to share the same determination to achieve his dream.  Sayuri is set on the path for greatness, and her newly cultivated culinary skill will help her handle any challenge the school throws her way.', 13, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8340, 'PriPara Movie: Mi~nna Atsumare! Prism☆Tours', 2015, 1, 'Movie', 82.1, 'PriPara the Movie: Everyone, Assemble! Prism ☆ Tours is the film based on and starring the characters from PriPara. The film is scheduled to begin showing in theaters across Japan from March 7, 2015. The plot will focus on Laala Manaka finding out about Saints top idol journey, and will feature the return of many characters from across all the Pretty Rhythm series.  (Source: PriPara Wikia)', 60, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8341, 'Re-Kan!', 2015, 13, 'TV', 98.3, 'Hibiki Amami would be a regular high school girl if it werent for one thing: a sixth sense that allows her to see ghosts. Rather than being scared, Amami is more interested in befriending and helping the apparitions. This often leads to her human friends witnessing paranormal activity as the ghosts try to help Amami with everyday tasks.   The majority of Amamis friends accept that she has a sixth sense, but Narumi Inoue—a girl who is terrified of the supernatural—refuses to acknowledge that ghosts are real. Though she is scared and stubborn, Inoue goes along with the rest of her friends, who decide to take up Amamis mission of helping ghosts however they can.', 102, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8342, 'Inugami-san to Nekoyama-san: Nekoyama-san to Onsen Ryokou', 2014, 1, 'Special', 64.4, 'Unaired episode bundled with the Blu-ray/DVD Box-Set.', 94, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8343, 'Rolling☆Girls', 2015, 12, 'TV', 99.0, 'In a dystopian future where Japans political organization has crumbled after the Great Tokyo War, Japan is broken up into 10 independent nations, with each nation controlled by a gang led by a Best, a human-proclaimed prophet with destructive superpowers. Nozomi Moritomo is a Rest—a normal girl that has just started out as a rookie in the local gang. She wants to help the Best Masami Utoku, her childhood friend and role model, in the ongoing territorial dispute.   When Masami becomes severely injured and unable to fight, Nozomi decides to go on a mission to complete the requests sent to Masami from all over Japan. Along the way, she meets Yukina Kosaka, a shy girl with no sense of direction; Ai Hibiki, an upbeat girl who loves eating; and Chiaya Misono, a quiet and mysterious girl that wears a gas mask. Together, the four girls travel all over the country on their motorcycles while getting involved in territorial wars, disagreements, and even suspicious conspiracies.', 75, True, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8344, 'Hello Kitty to Issho', 1994, 16, 'OVA', 84.5, 'Hello Kitty and her twin sister Mimmy learn to share, eat their vegetables, sleeping by themselves, answer the phone, use proper table manners, and much more.   (Source:  AnimEigo)', 19, True, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8345, 'Toukiden Kiwami', 2014, 1, 'ONA', 68.3, 'A five-minute promotional anime for PlayStation Vita and PlayStation Portable game Toukiden Kiwami.', 65, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8346, 'Wake Up, Girl Zoo!', 2014, 10, 'ONA', 80.7, 'Wake Up, Girl Zoo! is a small zoo located in the outskirts of Sendai. On the verge of closure, its director Tange and breeding staff Matsuda must set out to find a new animal unit for the zoo. How will they revive the zoo with the seven newly gathered animals?  (Source: Official website)', 45, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8347, 'Working!!!', 2015, 13, 'TV', 88.1, 'As the stories of those connected to Wagnaria come to a close, only one thing is certain: the workplace is about to get crazier than ever before! Whether it be incredibly awkward romances, relentless searches for lost relatives, or even uncomfortable family reunions, lover of all things cute and tiny Souta Takanashi and his motley crew have plenty on their plates. With more Napoleon complexes, androphobia, and katana-wielding than you can shake a frying pan at, Working!!! delivers a final serving of the staffs hilarious misadventures working at everybodys favorite family restaurant.', 85, False, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8348, 'Stitch!: Itazura Alien no Daibouken - Uchuu Ichi no Oniichan', 2010, 1, 'Special', 63.9, 'An exclusive episode showing the guest character, Kijimunaas sister, who looks like Kijimunaa and is pink.   (Source: Wikipedia)', 108, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8349, 'Stitch to Suna no Wakusei', 2012, 1, 'Special', 76.3, 'To confront a planetary war at the sand planet of Katuuna, Stitch must leave Yuna and Earth behind.   (Source: Wikipedia)', 90, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8350, 'Love Live! School Idol Project: μs →NEXT LoveLive! 2014 - Endless Parade Makuai Drama', 2014, 3, 'Special', 96.8, 'Bonus included in a Blu-ray/DVD disc of μs live concert that took place in Saitama Super Arena on February 8th and 9th, 2014.', 100, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8351, 'Glass no Hana to Kowasu Sekai', 2016, 1, 'Movie', 98.5, 'Dual and Dorothy, faithful computer antivirus programs, monitor and constantly scan for corruptions in the simulated worlds of the Box of Wisdom. Whenever a virus is detected, it—and in many cases the entire world as well—is forcibly purged. This routine occurs every day without change, until the deletion of a particularly large virus cluster reveals an unknown program—calling herself Remo—with no memory of her function. She offers a fresh perspective into the monotony of Dual and Dorothys lives as her influence causes the two programs to realize that there is more to life than just their mission.  No longer spending their time only watching over the worlds, the three girls start truly experiencing them. As they explore digitally recreated cities and landscapes, Dual and Dorothy develop a special appreciation for what they have, all while searching for clues regarding Remos forgotten purpose.', 82, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8352, 'Sakura Capusule', 2014, 1, 'OVA', 86.3, 'On a small hill in a neighbourhood in the outskirts of Tokyo, there was a little park. There were six close girls who always used to play there together since they were small.  But when they were fourth-graders, they had to change schools. The six of them made a promise to bury a time capsule, but in the end they were not able to keep this promise and separated eventually. Four years later and grown up, they now live their own lives.  While all of them have their own troubles and worries, the days pass and one day, a miracle happens to them.  (Source: AniDB)', 19, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8353, 'Koori no Kuni no Misuke', 1970, 1, 'Movie', 67.3, 'A puppy, Poko, jumps out of a refrigerator and takes a boy, Misuke, to an ice world full of adventure through the refrigerator. In the ice world, there is a girl called Nally who wants warm food. So they try to find some warm food for her, but everything freezes so quickly in the ice world...  Note: Short animated piece designed to attract new students for Yamaha electric organ classes.  (Source: tezukaosamu.net)', 51, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8354, 'Mahou Shoujo Lyrical Nanoha ViVid', 2015, 12, 'TV', 90.1, 'Vivio Takamachi, a Sankt Kaiser royalty of ancient Belka, was previously subjected to mistreatment. Fortunately, she now lives a peaceful life with family and friends while practicing martial arts with her coach, Nove Nakajima. However, Vivio soon becomes the target of the mysterious fighter Heidi E. S. Ingvalt, who demands Nove to reveal the location of the ancient Belkan royals. Refusing to disclose this information, Nove finds herself in a losing battle but Heidi soon falls unconscious. In addition, Nove discovers Heidis true identity to be a middle school student named Einhald Stratos.  When she regains consciousness, Einhald clarifies that she has no animosity toward ancient Belkan royals. Having inherited the passion to defend and harboring regretful memories of her ancestor, the ancient Belkan ruler Claus Ingvalt, she simply wants to prove that her fighting ability is strong enough to protect others. Intrigued by the girls situation, Nove arranges for Einhald to meet with Vivio. Although they get off to an unconventional start, Vivio enthusiastically trains with Einhald, assisting her in finding peace of mind while developing a vivid friendship along the way.', 87, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8355, 'Peeping Life: The Perfect Explosion Specials', 2012, 2, 'Special', 97.5, 'Specials included on the DVD release of Peeping Life: The Perfect Explosion that focus on Otaku-kun talking about Celebrating Universals 100th Anniversary and Otaku-kun interacting with a animegao kigurumi performer in Madeleine and the Pocket Tissues.', 55, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8356, 'Hacka Doll', 2014, 2, 'ONA', 60.2, 'In the year 2xxx, development of information are going so fast, humans being are drowning in the sea information. This leads to a situation where people can not find the necessary information. The only hope to solve this problem is the navigator program, Hacka Doll.  (Source: Anime Bibly)', 56, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8357, 'Backkom Meogeujan Yeohaeng', 2007, 1, 'Movie', 87.2, 'A cowardly boy ends up having a magic necklace delivered to him which transports him to the world of Backkom. There the rag-tag team get out of jams and the boy learns a bit of courage by the time he arrives home.', 14, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8358, 'Backkom 2', 2007, 52, 'TV', 68.4, 'The continuation of the previous season with more of a focus on the female penguin Backkom fancies (even though she has a boyfriend).', 72, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8359, 'Backkom Sports', 2009, 52, 'TV', 90.9, 'The 3rd season of Backkom which focuses on him participating and failing at a wide variety of sports.', 68, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8360, 'Clock', 1999, 1, 'Special', 74.0, 'A bizarre short about a man who wakes up by a bunch of clocks only to act as a cuckoo clock for a room full of chickens at a bar.', 103, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8361, 'Angel (Special)', 2001, 1, 'Special', 87.4, 'A man in a prison dreams of being an angel.', 57, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8362, 'I Love Picnic', 2003, 1, 'Special', 87.4, 'The original short that kicked off the Backkom franchise.', 68, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8363, 'I Love Sky', 2004, 1, 'Special', 75.4, 'The original short that the first episode of the Backkom the TV series uses its material from. The short is composed of two parts, Backkom skydiving into cow poop and Backkom skydiving into cactuses.', 91, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8364, 'Contact 2', 2006, 1, 'Special', 82.8, 'A Backkom short about him meeting an alien that aired between the 1st and 2nd season.', 104, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8365, 'Sheep in the Island', 2004, 2, 'Special', 86.3, 'A boat sinks leaving a sheep and a duck-dinosaur-fish hybrid stranded on an island.', 67, False, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8366, 'Ultra Dino Makera', 2008, 1, 'Special', 94.5, 'The Makera demo reel for RG Studios. It features a dinosaur in a yellow jumpsuit rescuing a girl tied to train tracks.', 100, True, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8367, 'Private Eye Dol', 1995, 3, 'Special', 87.8, 'Concurrent with an ADV game by HuneX/NEC-HE, the title is a pun about its detective and idol protagonist. It was released on issues 1 to 3 of NECs Anime Freak FX, a CD-ROM magazine resembling a game for the PC-FX platform.  The hacker Idol King is targeting idols, exposing awkward scenes of their private lives. Now, the next is the popular May Star...  (Source: AniDB)', 14, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8368, 'Contact', 2004, 1, 'Special', 77.5, 'A Backkom short about him meeting an alien.', 33, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8369, 'Tensai Bakavon: Yomigaeru Flanders no Inu', 2015, 1, 'Movie', 90.6, 'No description available for this anime.', 84, False, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8370, 'Bishoujo Mobage: Mobami-chan', 2014, 1, 'ONA', 62.6, 'DeNA promotional anime video for its line of mobile game. The mascot character for the line of games is called Mobami (a combination of mobile and beauty.)  (Source: ANN)', 44, True, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8371, 'Minna Atsumare! Falcom Gakuen SC', 2015, 12, 'TV', 60.2, 'The warriors who have been warped by the rampaging power of Justice have been summoned into the world of Xanadu. It is up to Dark Fact, a former villain, and principal Lappi to re-educate these students.  (Source: AniDB)', 14, True, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8372, 'SheepWolf', 2009, 1, 'ONA', 60.2, 'A wolf makes a fool of himself trying to eat sheep that are playing baseball.', 14, True, 92);
