INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8728, 'Boku wa Sugu ni Nigetanda: Higashi Nihon Daishinsai kara Mananda Koto', 2012, 1, 'OVA', 79.6, 'An educational video about the 2011 Touhoku earthquake and tsunami for kids. Its meant to show younger kids what happened and what everyone learned from it as the childrens early memories are fuzzy on the events even though they have lived through it.', 21, True, 88);
