INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8733, 'Saru Tarou Jishin ni wa Makenai zo!: Jishin e no Sonae Dai Sakusen', 2009, 1, 'OVA', 84.8, 'An educational earthquake disaster safety video for kids.', 37, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8734, 'Hi Asobi wa Kaji no Moto: Kenta to Nyanta no Hi no Youjin', 2007, 1, 'OVA', 71.7, 'An educational dont play with fire safety video for kids with talking animals.', 46, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8735, 'Jishin da!! Mii-chan no Bousai Kunren', 2006, 1, 'OVA', 71.8, 'An educational disaster safety video for kids featuring Mii-chan the cat and Daiki-kun after their animal abuse issue from the previous educational short.', 114, True, 95);
