INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8737, 'Kogitsune no Shouboutai', 1997, 1, 'OVA', 87.8, 'The three kitsune brothers have moved away from the country and into the city. They use their transformation powers to become young men and start firefighting school to become firefighters.', 54, True, 97);
