INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8860, 'Chiisana Teien', 2014, 1, 'Movie', 76.1, 'Story of a life form which wakes up in an unknown mysterious world. As he go deeper, he slowly understands what kind of place it is. The world seems beautiful, but it lacks what the real life has. He has to make a choice to stay or not.', 112, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8861, 'Atama wa Tsukaiyou. Card mo Tsukaiyou.', 2014, 1, 'Special', 79.5, 'A commercial commissioned by Credit Saison. The first 500 people to enroll for a Saison Card would receive an anime character Rina Takeda karate alarm clock. Rina is a real Japanese actress with a double black belt in Ryukyu Shorin-ryu Karate, she had previously done a commercial for the banking company where she uses her forehead to chop 15 concrete slabs in half. The anime commercial focuses on an animated Rina and her famous karate technique.', 97, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8862, 'Tezuka Osamu Monogatari', 2013, 10, 'ONA', 61.5, 'Flash animation ONA that tells about Tezuka Osamus life.', 113, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8863, 'Usagi to Kame (Music)', 2011, 1, 'Music', 84.7, 'A music video representing the classic story about rabbit and tortoise racing.', 36, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8864, 'Sore ga Seiyuu!', 2015, 13, 'TV', 63.6, 'Dreaming of becoming a top-tier professional in the fast-paced, competitive world of voice acting, rookie Futaba Ichinose frantically scurries around, searching for auditions and performance sessions. Rubbing elbows with some of the biggest names in the industry, she tries to find her own unique voice and style.   Along the way, she befriends two important allies: Ichigo Moesaki, an aspiring idol who claims to be a princess from another planet, and Rin Kohana, a cheerful child actress who tries her best to balance her career and school at the same time. Together, the girls brave the ups and downs of the entertainment industry—but as for Futaba, whose performance assessment at her agency is just around the corner, her career might be over sooner than expected! Sore ga Seiyuu! is a humorous and sincere celebration of the industry that gives anime its voice.', 87, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8865, 'Daitoshokan no Hitsujikai Picture Drama', 2014, 6, 'Special', 97.2, 'Picture Drama episodes bundled with the Blu-ray/DVD Volumes.   Sakuraba tries to draw Shirasaki, and things take a turn for the ecchi.', 60, True, 105);
