INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8870, 'Jeremy no Ki', 1983, 1, 'Movie', 83.8, 'Based on a childrens picture book of the same name. A Christmas tale about a bird who was raised by tree after it was abandoned. The tree was then cut down for people in the city to use for Christmas celebrations. The bird desperately is trying to find its adoptive tree mother with the help of Jeremy, a penniless orphan, who heard her story so they go and search every tree being used in town. The search in the cold takes a toll on Jeremy until Santa Claus appears, but is it really him?', 83, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8871, 'Tomodachi de Iyou ne', 1992, 26, 'TV', 81.2, 'Short childrens anime depicting Neko-kun, Nyaago, Usagi-kun, Kuma-kun, and other forest animals in their daily lives. It originally aired as a part of the early morning childrens program Hirake! Ponkikki before the anime was combined and released on VHS.', 63, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8872, 'Aldnoah.Zero Extra Archives', 2015, 1, 'Special', 62.4, 'Recap of the first season of Aldnoah.Zero series.', 44, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8873, 'Fushigiboshi no☆Futagohime Gyu! Recap', 2006, 1, 'OVA', 75.5, 'Rein and Fine receive a care package from their mother and father which contains a device to show past memories and events.', 48, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8874, 'Ninja Hattori-kun Plus Perman: Ninja Kaijuu Jippou tai Miracle Tamago', 1985, 1, 'Movie', 77.6, 'Crossover film featuring both of Motoo Abikos work. Both casts gets wrapped up when an alien egg falls from the sky that becomes a monster seeking destruction of the Earth.  It was screened as a double feature with Doraemon: Nobita no Little Star Wars.', 71, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8875, 'Ninja Hattori-kun Plus Perman: Chounouryoku Wars', 1984, 1, 'Movie', 60.7, 'Crossover film featuring both of Motoo Abikos work. Both casts gets wrapped up in an ESP war helping a psychic girl named Yuri whose homeland was destroyed by an evil psychic man who is trying to capture all the psychics in the world and use them for world domination.  It was screened as a double feature with Doraemon: Nobita no Makai Daibouken.', 19, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8876, 'Kiki to Lala no Habatake! Pegasus', 1994, 1, 'OVA', 79.8, 'Kiki and Lala try to help a lost Pegasus get home. Pegasus keeps getting on Kikis nerves with his foolishness and the journey becomes increasingly difficult.', 56, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8877, 'Kiki to Lala no Mamatte Suteki!', 1995, 1, 'OVA', 73.7, 'Lala finds a myserious egg that hatches into a baby dragon who they name Will. She and Kiki try to bring him up but Will grows far too big too fast and uses his dragon instincts which cause a lot of destruction.', 101, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8878, 'Koukaku Kidoutai Arise [.jp]', 2013, 1, 'Special', 96.9, 'A short about the move of the kokaku-jprs website from .com to .jp -  promoting the Japan Registry Services (JPRS).', 51, True, 118);
