INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8896, 'Eien', 2006, 1, 'Music', 75.4, 'Official music video for Park Yong-has Eien single directed by Itou Yuuichi.', 28, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8897, 'Bazar dé Gozarre', 1991, 33, 'Special', 71.3, 'A commercial campaign by NEC to sell various goods with a monkey mascot named Bazar. Each commercial essentially has Bazar trying to go to the NEC store to buy a specific good (that the commercial is selling) but failing along the way. The commercials are narrated in puns and tongue twisters.', 95, True, 17);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8898, 'Kareshi wa Hammerhead Shark', 2019, 1, 'Music', 96.5, 'No description available for this anime.', 95, True, 18);
