INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8900, 'Mirai e no Niji: Boku no Ojisan wa, Hansen-byou', 2005, 1, 'OVA', 96.6, 'An educational film out leprosy. As of 2009, there are 2,600 people with leprosy in Japan--all of whom are living in sanatoriums and hospitals. The story follows two kids going to visit their uncle who lives in a sanatorium.', 56, True, 20);
