INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8902, 'Tick & Tack', 1998, 18, 'TV', 92.5, 'Tick &amp; Tack are very good friends who get caught up in mysterious events that let them make friends along the way.', 110, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8903, 'Naccio to Pomm', 2002, 41, 'TV', 81.9, 'Naccio and Pomm have come to Earth from a far-away planet. What they discover, and what viewers of all ages delight in, is fun, fun, fun! Italian-based, Japanese master animator Fusako Yusaki uses mere clay (plasticine), plus a great deal of off-the-wall imagination, to create a simple, yet captivatingly busy world of play. Naccio and Pomm bounce and bumble through their explorations of everyday settings -- everyday to us Earthlings, that is. For the two aliens, every experience is new and endlessly enjoyable.  (Source: microjapan.com)', 35, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8904, 'Bip to Bap', 2001, 4, 'TV', 60.5, 'CG anime about Bip and Bap who are a boy detective and a talented frog. They go on wild adventures that usually revolve around a thief.', 119, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8905, 'Pulsar', 1990, 1, 'Movie', 92.8, 'Clay (technically gypsum) animation set to a beat with robots, scifi motif, and alligators with human arms. It was broadcasted a year later (1991) by the Japanese TV program Miyake Yuuji no Ebizori Kyoshou Tengoku, Ebiten for short, which showed works of independent film makers.  This has the prototype character, Pulta, which was used for Bowda Katsuhis Robot Pulta anime when he was hired by the NHK.', 41, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8906, 'Form of Stress', 1992, 1, 'Movie', 99.6, 'Bowda Katsuhis independent work, again featuring another prototype of Pulta for the Robot Pulta anime when he was hired by the NHK.', 74, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8907, 'Kai Douryoku', 1994, 1, 'Movie', 98.9, 'Not much is known about the piece compared to its award-winning Real counterpart made 4 years later.', 33, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8908, 'Kai Douryoku Real', 1998, 1, 'Movie', 60.4, 'Montage of the human body fusing stop-motion and computer animation into a bizzare scifi representation. It was shown at the Japanese Media Arts Festival and got the Excellence Award. And it won the Special Jury Prize in the Off Theatre Competition at the 10th Yubari International Fantastic Film Festival.', 91, True, 28);
