INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8942, 'Tsunagaru Animal', 2011, 1, 'Special', 77.3, 'As the forest begins to thaw, animals are looking forward to spring. But they need to help each other to survive the period of when the flora has not yet produced food.', 79, True, 62);
