INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (8999, 'Stone', 1975, 1, 'Movie', 90.6, 'Independent, stop motion animation by Aihara Nobuhiro, combining drawings and real landscapes.', 53, False, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9000, 'Karma', 1977, 1, 'Movie', 65.5, 'In his early experimental short Karma (カルマ, 1977), Aihara uses water as his central motif.  The film is hand drawn and appears to be shot on 16mm using a blue filter.  At first we can only see tiny specks on the screen, coming and going like snow flurries.  The specks gradually grow larger and take the shape of bubbles, then even larger into rivulets of water on a transparent surface.  (Source: Nishikata Film Review)', 51, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9001, 'Genei Toshi', 1967, 1, 'Movie', 91.2, 'Independent animation by Shimamura Tatsuo.', 88, True, 1);
