INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9010, 'Duel Masters VSR', 2015, 51, 'TV', 76.8, 'A next fierce fight is about to begin after Katta Kirifuda finally become the Duel Masters National Tournament champion.  Japans largest theme park, Duel Masters Land has appeared. With numerous fun attractions and events, Katta was also having fun.  However, after meeting the mascot of the park, Duemouse, Katta got involved in a ridiculous conspiracy of the park.  A shadow that invades the Duel Masters World, which is the mysterious team of duelists! The mysterious identity of the legendary card is to be revealed. A new stage and revolution of Duel Masters befalls Katta!  (Source: Duel Masters Wikia)', 84, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9011, 'Tennis no Ouji-sama: Message in a Bottle', 2009, 1, 'Special', 78.3, 'The Rikkai University-Affiliated Middle Schools Boys Tennis Team stumbles upon a strange bottle. Inside, a cryptic message asks for the recipient to add another item to the bottle and toss it back into the river. Having broken the container to read the note, the team puts it back together with tape and includes a few extra items before sending it on the long journey back to its owner. However, the bottle ends up washing ashore elsewhere, and the tennis team from Seishun Academy finds it instead.', 54, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9012, 'Ni-hiki no Sanma (1968)', 1968, 1, 'Movie', 82.6, 'The international version of Ni-hiki no Sanma that is colored, redrawn, and edited.', 75, True, 12);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9013, 'Yume no Ukiyo ni Saitemina', 2015, 1, 'Music', 97.3, 'Music video for Yume no Ukiyo ni Saitemina, a collaboration between idol group Momoiro Clover Z, and rock band KISS.', 55, False, 13);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9014, 'Üks Uks', 2003, 1, 'Movie', 83.7, 'Opening ones inner doors of conflict is the key to finding harmony.  An independent film by Yonesho Maya, which won the Yuri Norstein Award music prize at the Laputa Animation Festival.', 16, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9015, 'Introspection', 1998, 1, 'Movie', 87.3, 'We can understand each other without understanding each language.  (Source: Maya Yonesho)', 108, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9016, 'Believe in It', 1998, 1, 'Movie', 77.5, 'Your dream will come true if you believe in it.  (Source: Maya Yonesho)', 64, True, 16);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9017, 'Countdown', 2002, 1, 'Movie', 72.0, 'I would make my new animation with my New Years cards, and my New Years cards with my new animation.  (Source: Maya Yonesho)', 69, True, 17);
