INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9022, 'Maze Maze Wien', 2006, 1, 'Movie', 70.8, 'An independent film by Yonesho Maya using her unique style of combining card-sized drawings and stop motion animation that walks the viewer through real locales, in this case, Vienna.', 43, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9023, 'Eikoku Ikka, Nihon wo Taberu', 2015, 24, 'TV', 93.8, 'Based on a book by British travel and dining journalist Michael Booth. Follows Booth, his wife Lissen, and two kids Ansger (6) and Emil (4), on their 100-day trip to Japan as they try a wide variety of Japanese foods. Booth was inspired to make the trip by Shizuo Tsujis book, Japanese Cooking, A Simple Art.  (Source: ANN)', 37, True, 23);
