INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9072, 'The iDOLM@STER Million Live! 1-shuunen Kinen PV', 2014, 1, 'Special', 89.5, 'No description available for this anime.', 13, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9073, 'Overlord', 2015, 13, 'TV', 94.4, 'The final hour of the popular virtual reality game Yggdrasil has come. However, Momonga, a powerful wizard and master of the dark guild Ainz Ooal Gown, decides to spend his last few moments in the game as the servers begin to shut down. To his surprise, despite the clock having struck midnight, Momonga is still fully conscious as his character and, moreover, the non-player characters appear to have developed personalities of their own!  Confronted with this abnormal situation, Momonga commands his loyal servants to help him investigate and take control of this new world, with the hopes of figuring out what has caused this development and if there may be others in the same predicament.', 111, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9074, 'Yumemi Douji', 1958, 1, 'Movie', 61.4, 'An early Toei film directed by Fukiya Kouji.', 118, True, 74);
