INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9093, 'Omakase! Miracle Cat-dan', 2015, 32, 'TV', 96.1, 'Nakagawa owns 10 cats in real life, and she adores one in particular named Mamitasu, the animes namesake. The anime depicts the slapstick comedy of the idiosyncratic 10 cats and the folks in the unusual Nakagawa family.   (Source: ANN)', 89, False, 93);
