INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9105, 'BAR Kiraware Yasai', 2015, 13, 'TV', 98.9, 'The anime adapts artist Daisuke Kimuras four-panel manga of the same name, the story centers on vegetables that children hate, everyone hesitates to eat, and are smelly. The series follows these vegetables as they visit a bar to share drinks together while they talk about their worries.  (Source: ANN)', 21, True, 105);
