INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9178, 'Aoki Uru: Overture', 2015, 1, 'Special', 62.6, 'A short special created by a newly launched Uru in Blue LLP (Limited Liability Partnership) in Singapore that was streamed in 2015. Aoki Uru: Overture is a lead up/preview to the full film.', 29, False, 58);
