INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9242, 'Black Bullet: Tenchuu＊Girls', 2014, 1, 'Special', 67.2, 'Short special featuring Tenchu Girls, a group of characters from the TV series. Included in the 4th volume of the Blu-ray/DVD releases.', 14, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9243, 'Precure All Stars Movie: Haru no Carnival♪ - Ima Koko kara', 2015, 1, 'Music', 84.1, 'A dance video clip from the Precure All Stars: Haru no Carnival film. The clip shows the forty Precure warriors from the past anime series, as well as the upcoming series Go! Princess Precure. The song featured in the video is Ima Koko Kara.  (Source: ANN)', 114, True, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9244, 'Seichou Rap', 2014, 1, 'Music', 94.9, 'A rap video about intestines, bacteria, and pooping commissioned by the National Museum of Emerging Science and Innovation (shortened to Miraikan) to promote their exhibit Toilet!? Human Waste &amp; Earths Future which ran from July 2 to October 5th in 2014.', 26, True, 4);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9245, 'Fukashigi no Kazoekata', 2012, 1, 'ONA', 90.6, 'An anime commissioned by The National Museum of Emerging Science and Innovation (Miraikan for short) for its The Art of 10^64 -Understanding Vastness- exhibition which ran from August 1, 2012 to April 15, 2013.  This is an example about combinatorial explosion. I want to demonstrate how amazing combinatorial explosion is! Please dont stop me! Teacher and children tell you how difficult it is.  (Source: Official YouTube Page)', 51, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9246, 'Graphillion: Kazoeage Oneesan wo Sukue', 2013, 1, 'ONA', 86.1, 'A direct sequel to Fukashigi no Kazoekata commissioned by Graphillion. Graphillion is a Python software package on search, optimization, and enumeration for a very large set of graphs. This video is a quick tutorial to learn what Graphillion is.  (Source: Official YouTube Page)', 46, False, 6);
