INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9338, 'Strike the Blood: Valkyria no Oukoku-hen', 2015, 2, 'OVA', 63.6, 'It was officially announced at the Dengeki Game Festival 2015 event that Strike the Blood will be getting a two-episode OVA series to be released at the end of 2015. The OVA will be an original story written by Gakuto Mikumo.  (Source: MAL News)', 25, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9339, 'Obake no Dokurou', 2015, 1, 'ONA', 86.1, 'Back alley of candy shop which everybody has called it Alley of ghosts. Gacharico the Ghost lives there, but its a secret that only little Miku, from the family candy shop, knows. The content of the capsules appear to be ordinary toys, but inside Gacharico the Ghost, live an abundant of other ghosts, each with their own personality. Even today, the ghosts are using all their powers to try to inspire awe and feelings in the children around them.  (Source: Official website)', 45, True, 99);
