INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9349, 'Tori', 1985, 1, 'Movie', 88.8, 'A short film by Furukawa Taku.  After a sleeping man is harassed by a bird, he becomes hell-bend on chasing it down and capturing it for revenge, but the bird turns out to be smarter than it looks.', 77, True, 109);
