INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9352, 'Direct Animation', 1987, 1, 'Movie', 73.1, 'As if imitating overexcited atoms or rapidly moving molecules, a convulsive world of multicolored shapes and patterns transforms endlessly in the rhythm of a gentle blend between classic oriental instrumentation and synthesizers.', 32, False, 112);
