INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9392, 'Ishindenshin Shiyou', 1993, 1, 'Music', 97.8, 'An adaptation of a previously released song for FM Miyazaki Joy, a local FM radio stations driver safety campaign commercial. The commercials song was so popular people were requesting the commercial to air instead of regular songs. NHK eventually purchased the rights to feature and have a music video created for a cleaned up version of the song (a significant portion of the lyrics were changed). This was a rare instance as it is one of the few Minna no Uta songs that came from private broadcasters as almost all are created from public broadcasters such as NHK themselves.  The remade version was still a popular hit and was featured on the Minna no Uta program for 4 months straight.', 44, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9393, 'Kitsutsuki: The Ten Hole Stories', 2009, 1, 'Movie', 69.3, 'G9+1 film.', 106, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9394, 'Tokyo SOS', 2011, 1, 'Movie', 72.1, 'The fourth anthology work by animation collective G9+1, this time on the theme of global warming. The film features music by Kazunori Maruyama.', 30, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9395, 'Nepos Napos', 2005, 26, 'TV', 89.9, 'You see a whale-shaped cloud drifting in the blue sky. What you dont see is a strange land of Nepos Napos that lies above it. Dont you want to know what is happening and how everybody lives up there?  (Source: The Answer Studio)', 112, False, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9396, 'Gon 2nd Season', 2015, 26, 'TV', 88.9, 'Continuation of the Gon series.', 52, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9397, 'Happy Jozy', 2015, 52, 'TV', 65.4, 'A comedic family of Americans experience life in Japan.', 11, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9398, 'Shi Xiong', 2014, 41, 'ONA', 94.8, 'Protagonist XiaoFei used to be an ordinary guy from H city. After the spring water was contaminated with a virus, however, he unexpectedly encountered an unprecedented crisis. The people living in H City became zombies one by one, devouring each other, and gradually evolving. Can XiaoFei escape from H city and meet up with his girlfriend Wei? The story now begins...  (Source: The Faiien Scans)', 107, True, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9399, 'Yowamushi Pedal Movie', 2015, 1, 'Movie', 73.0, 'With the Inter-high over and as the end of summer approaches, Sakamichi trains intensely with Imaizumi Shunsuke and Naruko Shoukichi so he can carry on Team Sohoku’s spirit of supporting each other entrusted to him by Kinjou Shingo, Makishima Yusuke, and Tadokoro Jin, the third years who will be graduating before long. One day, Team Sohoku receives an invitation to the Kumamoto Fire Country Mountain Race, an invitational race for teams that performed well at the Inter-high, and their captain Kinjou decides their core Inter-high team will attend.  (Source: Crunchyroll)', 42, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9400, 'High☆Speed! Movie: Free! Starting Days', 2015, 1, 'Movie', 71.8, 'Haruka Nanase and Makoto Tachibana have started middle school and must adjust to the changes that come along with growing up. While Makoto fits in with his classmates and remains positive about swimming, Haruka struggles to befriend others or join his schools swim club, as his previous issues with swimming trouble him. Distancing himself from his lively classmates and the swimming club, he has difficulty deciding which club to join instead. The rest of his classmates, including Makoto, are also hesitant as to which clubs to participate in. After an argument leads them to join the swimming club anyway, the boys strive to hone their skills, harmonize their swimming styles, and refine their conflicting feelings toward swimming and each other.  As determination and talent run high, Haruka and Makoto—along with their classmates—discover themselves and improve their talents during their starting days.', 71, True, 40);
