INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9418, 'Kana Kana Kazoku: Stop Rubella', 2014, 1, 'ONA', 96.8, 'A public service special for rubella vaccines. Most of this episode recycles the animation sequences from episode 5 of Kana Kana Kazoku but new dialogue is put in.', 11, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9419, 'Wake Up, Girls! Deai no Kiroku: A Brief Recording', 2013, 1, 'OVA', 80.2, 'Special animation disc sold to advance ticket buyers of a Wake Up, Girls! preview event at Akihabara UDX. It contains audition footage of the main characters of the series that is not included in the movie.', 84, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9420, 'Akazukin to Kenkou', 2007, 1, 'OVA', 89.9, 'Graduation Work of Inoue Ryou which won the Toronto Japanese Short Film Festival award in 2011. A funny animation about Little Red Riding Hood who tries to help the wolfs organs who are troubled by the fact that the wolf has metabolic syndrome.  (Source: AniDB)', 75, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9421, 'Shika to Kanta', 1992, 1, 'OVA', 76.9, 'One day, Kanta, a lonely boy, rescues an orphaned baby deer and names it Poyu. There is something special about Poyu, his golden tail. When hunters go after Poyu, Kanta is determined to protect his golden-tailed friend and the other deer.', 83, True, 61);
