INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9584, 'Son Gokuu no Koutsuu Rule Shugyou Chuu', 2005, 1, 'OVA', 95.0, 'An educational film about traffic safety staring the Saiyuuki cast.', 10, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9585, 'Douwa Mondai to Jinken: Anata wa Dou Kangaemasuka', 2009, 1, 'OVA', 97.4, 'An educational film about discrimination. The story follows Tomokazus return to his hometown for vacation and his eyes opened up to the casual discrimination around him.', 55, True, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9586, 'Ijime Juuyon-sai no Message', 2000, 1, 'OVA', 92.1, 'An educational film based on an award winning novel. The story follows a girl who is bullied to the point of hospitalization even when she requested the help of adults and teachers.', 84, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9587, 'Shiranpuri', 1999, 1, 'OVA', 69.3, 'An educational film about bullying.', 14, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9588, 'Shounen Muku Hatojuu Monogatari', 2000, 1, 'OVA', 60.5, 'An educational film that follows the famous Japanese writer Muku Hatojuu in his boyhood as he gets bullied.', 21, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9589, 'Utsukushii Message', 2001, 1, 'OVA', 64.8, 'An educational film about discrimination in Japan.', 38, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9590, 'Ojarumaru: Chitchai Mono no Ookina Chikara', 2000, 1, 'OVA', 60.3, 'An educational film about the importance of helping people starring the Ojarumaru cast.', 115, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9591, 'Ojiichan wa Boku no Hero', 2000, 1, 'OVA', 67.2, 'An educational film for Respect for the Aged Day.', 96, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9592, 'Muku Hatojuu no Meiken Monogatari', 1997, 1, 'OVA', 69.6, 'Follows the story of a boy and two jackals he befriends in the adventure sin the Southern Alps.', 71, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9593, 'Kurayami Santa', 2015, 13, 'TV', 78.4, 'In the midst of Shouwa era Japan, greed runs rampant through the bustling cities and communities of the nation. King of Hell Enma Daiou summons an envoy into his office in the form of a small boy named Kurayami Santa. Through Enmas debriefing, Santa learns that the amount of greed and selfish behavior produced by humans will soon create an enormous wave of souls entering into Hell simultaneously, which would be catastrophic for Hell itself.   Santa is given one mission: do something about it. With neither guidelines nor rules, Santa is tasked to handle the situation as he sees fit. In the human world, a rampaging thunderstorm strikes a nearby cemetery with a bolt of lightning, and the envoy of Hell appears.   Teleported into the human world, Santa quickly realizes that humans are just as wicked as Enma had described. Without upsetting the balance between light and dark, Santa begins his quest to complete the mission from Hell and restore order to the human world.', 43, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9594, 'Kowabon', 2015, 13, 'TV', 98.7, 'In todays world full of wondrous technological innovation, the unnatural and mysterious sometimes appear even more horrifying than usual. But despite how far society has advanced, the fear of the unknown always remains. The unfortunate participants in Kowabon find themselves in such a predicament, experiencing the supernatural through their everyday technology. From a frightening sight caught on a parking garage camera to a video chat that takes an unexpected turn, the victims struggle to escape that which haunts them. However, what awaits these doomed souls may be a fate even worse than death...', 56, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9595, 'New Initial D Movie: Legend 3 - Mugen', 2016, 1, 'Movie', 79.5, 'After spending his summer racing against some of the best racers in Gunma, Takumi Fujiwara receives a formal challenge from the leader of the Akagi Red Suns, Ryousuke Takahashi. Despite his initial reluctance to get into the hobby, Takumi cannot help but feel excited to go up against the former White Comet of Akagi. In preparation for the battle, Ryousuke downgrades his car, putting his pride and racing career at stake.   With the title of the fastest racer in all of Gunma on the line, will Takumi and his panda-colored Toyota AE86 be able to defeat Ryousukes Mazda RX-7 FC?', 52, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9596, 'Arslan Senki (TV): Arsen 4-koma Gekijou', 2015, 8, 'Special', 87.5, 'Bundled with the Blu-ray/DVD Volumes of Arslan Senki (TV).', 28, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9597, 'Jakusansei Million Arthur', 2015, 60, 'ONA', 99.5, 'During the live-stream of the Majo Labo! program, it was announced that Kakusansei Million Arthur will be receiving an ONA adaptation. The ONA will be based on the official 4-koma web comic and will run for four cours, debuting in Fall.  Kakusansei Million Arthur is a card-battle game based on the legend of King Arthur. One million people also claim this title, wielding their own Excalibur. Developed by Square Enix, the game was originally released on iOS and Android in 2012 and since received a PlayStation Vita and Nintendo 3DS version in 2014.  The comic is based on the game and is drawn by Choboraunyopomi (Ai Mai Mi). It was published online in October 2014 and currently, there are 17 chapters.  (Source: MAL News)', 48, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9598, 'Crazy Monkey', 1980, 1, 'Movie', 97.1, 'Jackie Chans 1979 film The Fearless Hyena opened in Japan a year later under the name Crazy Monkey accompanied with an independent original animated piece by Toei Animation based on designs by Monkey Punch set to the insert song Monkey Man.', 119, True, 118);
