INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9624, 'Ojiichan no Tomato', 1998, 1, 'OVA', 78.7, 'An educational film concerning the bullying and discrimination of elderly handicapped people.', 88, True, 24);
