INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9627, 'Kizuna: Ningen no Uta Part 2', 1990, 1, 'OVA', 95.6, 'An educational film about marriage discrimination; how hard it is for a lower class person to marry into upper class.', 56, False, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9628, 'Mirai Kara no Message', 1989, 1, 'OVA', 66.7, 'An educational film about adoption discrimination in Japan. How those who are adopted are seen as rejects of society and the public koseki allows for companies to see the family tree of applicants and not hire/fire employees based on the fact that theyre adopted.', 117, True, 28);
