INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9821, 'Love & Gift', 2014, 2, 'ONA', 92.4, 'A and B have never met each other, but there is a thread that ties them together.  (Source: Official website)', 73, True, 101);
