INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9880, 'Mr. Deniroo in Henteko Mushi', 2006, 1, 'Special', 91.9, 'No description available for this anime.', 41, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9881, 'Deniroos Circus', 2004, 1, 'Special', 90.8, 'No description available for this anime.', 60, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9882, 'Persona 5 the Animation: The Day Breakers', 2016, 1, 'Special', 69.6, 'There is a new urban legend circulating Tokyo. It claims that if you make a request in the Ask-a-Thief Channel, the Phantom Thieves of Hearts will show up and bring justice by stealing a corrupt persons heart and making them regret all their wrongdoings. As strange and inexplicable events continue to happen all around town, more people submit their requests in hope that the mysterious vigilante group will help.  Kazuya Makigami is a burglar by night, but has started to have second thoughts about his crimes and those who help him commit them. Unable to stand up to his comrades himself, Kazuya submits a request to the Ask-a-Thief Channel.', 44, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9883, '3-gatsu no Lion', 2016, 22, 'TV', 88.1, 'Having reached professional status in middle school, Rei Kiriyama is one of the few elite in the world of shogi. Due to this, he faces an enormous amount of pressure, both from the shogi community and his adoptive family. Seeking independence from his tense home life, he moves into an apartment in Tokyo. As a 17-year-old living on his own, Rei tends to take poor care of himself, and his reclusive personality ostracizes him from his peers in school and at the shogi hall.  However, not long after his arrival in Tokyo, Rei meets Akari, Hinata, and Momo Kawamoto, a trio of sisters living with their grandfather who owns a traditional wagashi shop. Akari, the oldest of the three girls, is determined to combat Reis loneliness and poorly sustained lifestyle with motherly hospitality. The Kawamoto sisters, coping with past tragedies, also share with Rei a unique familial bond that he has lacked for most of his life. As he struggles to maintain himself physically and mentally through his shogi career, Rei must learn how to interact with others and understand his own complex emotions.', 41, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9884, 'Ponkotsuland Saga', 2015, 3, 'ONA', 63.2, 'Ponkotsuland Saga is a collaboration between Ponkotsu Quest and Vinland Saga.', 112, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9885, 'Kuroko no Basket Movie 4: Last Game', 2017, 1, 'Movie', 80.8, 'Hailing from America, Jabberwock—a street basketball team with skills comparable to those of the NBA—has come to Japan to play an exhibition match against Strky, a team of former third-year students who once played in the Interhigh and Winter Cup. However, due to the vast difference in skill, Jabberwock easily wins. Their captain, Nash Gold Jr., mocks the basketball style of all players in Japan by comparing them to monkeys.   Infuriated by the nasty comment, Kagetora Aida challenges them to a revenge match. Because of pride and the belief that the results will be no different, Nash accepts the challenge. Kagetora then assembles Vorpal Swords, a team composed of the Generation of Miracles, including Kuroko Tetsuya and Kagami Taiga, for they are the only ones who stand a chance against a foe that seems unbeatable from every angle.', 100, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9886, 'Bary-san x Gospe Rats: Tonde Bary Bary Monogatari', 2015, 1, 'Music', 73.0, 'No description available for this anime.', 34, True, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9887, 'Hibike! Euphonium: Kakedasu Monaka', 2015, 1, 'Special', 78.0, 'After the Kitauji High School concert bands auditions for club member participation in the Kyoto Prefectural Concert Band competition, 10 members fail to pass the strict evaluation. Despite being unable to play with the rest of the wind ensemble, the group—who decide to name themselves Team Monaka—is determined to support their peers in any way possible until the day of the competition.  From carrying supplies to creating monaka-shaped good-luck charms, Team Monakas efforts prove to be pivotal for the unforgettable, bittersweet summer in the concert bands journey toward nationals.', 48, True, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9888, 'Teekyuu 5 Specials', 2015, 2, 'Special', 90.0, 'Unaired specials included in the Blu-ray and DVD release.', 21, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9889, 'Takamiya Nasuno desu! Teekyuu Spin-off Special', 2015, 1, 'Special', 98.9, 'Unaired special included in the Blu-ray and DVD release.', 42, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9890, 'Kaitou Joker 3rd Season', 2016, 13, 'TV', 64.0, 'Third season in the Kaitou Joker anime series.  The thief Mysterious Joker doesnt just steal things. An audacious and elusive miracle-maker, he travels the world searching for treasure with his partner and cook Hachi. As they circle the globe, they must avoid traps set by the police and compete in various competitions to reach their final goal, the Timeslip Treasure.  (Source: ANN)', 88, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (9891, 'Ojarumaru: Wasureta Mori no Hinata', 2015, 1, 'Special', 67.5, 'A special of the Ojarumaru series.', 24, True, 51);
