INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10095, 'Robocar Poli 2', 2011, 26, 'TV', 82.1, 'In Brooms Town, a small town with a strong rescue team, there are always accidents and troubles such as a car sliding off a cliff in the rain, a car crash, a child locked in a firehouse and so on. In every episode the towns rescue team saves characters. At the end of each episode, the rescue team strongly advises the characters who were in danger and children.  (Source: AniDB)', 80, True, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10096, 'Youkai Watch Movie 3: Soratobu Kujira to Double Sekai no Daibouken da Nyan!', 2016, 1, 'Movie', 84.2, 'When a giant flying whale suddenly appears over Sakura New Town and its sound is heard the Yo-Kai undergo a transformation. The characters soon realize that as a result they have become corporeal and exist in a material world. This is the third film in the Yok-Kai Watch series based on the hit game.  (Source: IMDb)', 114, True, 16);
