INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10103, 'Xi You Ji', 1999, 52, 'TV', 67.7, 'Sun Wukong, who was born from a magic stone, has been imprisoned underneath a mountain for five centuries for his mischief in the heavens. One day, the Diety Guanyin told Wukong that the Monk Tangsen will set him free, and Wukong will join him on a pilgrimage from China to India. The next day, Xuanzang came and set him free, and the two started their Journey to the west. Along the way, they meet two new friends, Zhu Bajie and the Hermit Sha Wujing who joins them on the journey; together, they face many dangers and evil creatures and sorcerers and learn to get along.  (Source: Wikipedia)', 86, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10104, 'Micchiri Neko March', 2013, 1, 'Music', 65.5, 'A music video created for the Micchiri Neko character and brand. The video features cat characters playing in a marching band.', 17, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10105, 'Code Geass: Boukoku no Akito 4 - Nikushimi no Kioku kara Picture Drama', 2015, 1, 'Special', 85.8, 'Picture drama included in the Code Geass: Boukoku no Akito 4 Blu-ray/DVD release.', 78, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10106, 'Kuromukuro', 2016, 26, 'TV', 64.8, 'During the dawn of the 21st century, the United Nations Kurobe Research Institute was established in Japan to investigate an ancient artifact, which was discovered during the construction of the Kurobe Dam. Scientists from around the world have gathered in the facility to study the object, while their children enjoy their everyday lives attending Mt. Tate International Senior High School.  Yukina Shirahane, a reserved high school girl, is the daughter of the facilitys head scientist. While visiting her mother at the facility, Yukina manages to solve part of the artifacts puzzle. To her surprise, what appears before her is Kennosuke Tokisada Ouma, a young samurai from the Sengoku era.  As a threat approaches from outer space, Yukina, along with Kennosuke, finds herself defending Earth against the invading forces. Along the way, she discovers the mystery behind Kennosuke and the reason he is determined to protect her.', 66, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10107, 'Tekkon Kinkreet Pilot', 1999, 1, 'Special', 93.7, 'Softimages Michael Arias started the project as a short CG exercise, which then came to the attention of Morimoto, who then agreed to work on the project on the Softimage 3D software. A few months later, Visual Director Wilson Tang and Animation Supervisor Lee Fulton introduced a pilot to the Softimage staff, made entirely on computer with a staff of only 12. The pilot won the Excellence Award at the 3rd Japan Media Arts Festival in the Digital Art Division.  (Source: ANN)', 30, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10108, 'Masamune Datenicle', 2016, 6, 'ONA', 87.8, 'The coming-of-age battle story will center on the famous 17th-century Japanese warlord Date Masamune when he was young. The Date clan took its name from the Date region of the former Mutsu province, which comprises part of the modern-day city of Date.  The anime will be the first in the citys Kirari na Wonder Project (Twinkling Wonder Project), which aims to highlight tourist attractions and the appeal of the region.  Gainaxs newly founded Fukushima studio will work on the anime, and will complete it at the end of March. The anime will have a private screening in April and will also screen in anime events and be posted online.  (Source: ANN)', 109, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10109, 'Mirai e no Kakehashi: Bridge for Future', 2015, 6, 'ONA', 62.5, 'Fukushima Gainaxs commissioned commercials for TOHO Bank. The series involves Sayaka Hinata, an overly-energetic new bank employee (voiced by Sarah Emi Bridcutt), and her beleaguered boss, Mitsuya (voiced by Tomokazu Sugita).  (Source: Crunchyroll)', 36, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10110, 'Japonese', 1977, 1, 'Movie', 70.7, 'A film by Renzou Kinoshita about culture and tradition.', 74, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10111, 'Ama Gli Animali', 1983, 1, 'Movie', 66.7, 'A clay animation film by Yusaki Fusako.', 44, True, 31);
