INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10113, 'Ashita Kirarin', 2004, 1, 'OVA', 92.0, 'Ayako suffers from autism, and all kids in the class mock her except for Yuri - the only girl who shows some kindness towards her. Greatly appreciating that, Ayako gives Yuri a present - a beaded bracelet.  Later, the school is preparing for the summer cultural festival, and Ayakos present inspires Yuri with an idea to make a decoration for one of the schools exterior walls - a giant picture made of ropes beaded with empty cans of different colours. All kids including Ayako then gather empty cans from all around the city and start creating the picture. However, the day before the festival is scheduled to open a typhoon hits the city, threatening to ruin the kids hard work.  (Source: AniDB)', 26, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10114, 'Mahou no Tenshi Creamy Mami: Zutto Kitto Motto', 1998, 1, 'Music', 66.5, 'A music clip made for the LD Mahou no Tenshi Creamy Mami Featherstar Box 1. It features an adult Yuu reminiscing about her past.', 85, True, 34);
