INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10291, 'Persona 3 the Movie Meets Walkman', 2016, 1, 'ONA', 99.4, 'Standing on the rooftop of Gekkoukan High School, Makoto Yuuki watches the snow fall on a peaceful winter night. With a Sony Walkman in hand, Makoto puts on his headphones. The music flowing through his ears brings about the birth of spring, showing the splendor of the device.  Persona 3 the Movie Meets Walkman is a short commercial depicting the clarity and beauty of Sonys high-resolution audio throughout the changing seasons.', 44, True, 91);
