INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10526, 'Kachikachi Yama (1940)', 1940, 1, 'Movie', 83.1, 'A 10-minute film based on the folktale of the same name. The screenplay was done by Masaoka Kenzo.', 43, True, 86);
