INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10531, 'Detective Conan: Lets Experience the Jomon Period!', 1999, 1, 'OVA', 63.8, 'An educational Meitantei Conan OVA where the Shounen Tantei-dan (Detective Boys/The Junior Detective League) go on a field trip with Ran to learn about the Jomon Period of Japan, which is the earliest historical era of Japan. This OVA was released as a bundle with Shogakukans Nijuuisseiki Kodomo Hyakka Rekishi-kan (21st Century Childrens Encyclopedia History Museum). It uses animated characters on top of live-action backgrounds.', 113, True, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10532, 'Detective Conan: The Internet - The Mysterious E-mail Case', 2000, 1, 'OVA', 93.0, 'An educational Meitantei Conan OVA where the Shounen Tantei-dan (Detective Boys/The Junior Detective League) have to do a school research project in the library when they receive a mysterious email that leads them on an educational scavenger hunt. This OVA was released as a bundle with Shogakukans Nijuuisseiki Kodomo Hyakka Kagaku-kan Dai 2-ban (WOW!) (21st Century Childrens Encyclopedia Science Museum 2nd Edition (WOW!)). It uses animated characters on top of live-action backgrounds.', 107, True, 92);
