INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10537, 'Code Geass: Hangyaku no Lelouch Picture Drama - Hajimari no Zenya', 2013, 1, 'Special', 73.1, 'A special included with the Blu-Ray release of the main series. Lelouch monologues on his dissatisfaction with Britannias rule and the need to hide his and Nunnallys connection to the Britannian throne.  (Source: Wikipedia)', 78, True, 97);
