INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10539, 'Tanaka-kun wa Itsumo Kedaruge Specials', 2016, 7, 'Special', 77.5, 'Bundled with the Blu-ray and DVD releases of Tanaka-kun wa Itsumo Kedaruge.', 34, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10540, 'Yahari Ore no Seishun Love Comedy wa Machigatteiru. Zoku OVA', 2016, 1, 'OVA', 62.9, 'After accepting a weekend invitation, Hachiman Hikigaya accompanies Isshiki Iroha around the Chiba Prefecture to brainstorm ideas suitable for an ideal date with Hayato Hayama. As the duo wanders from place to place without a plan, they seemingly enjoy each others company. Yet, through these straightforward and sincere interactions, the meaning behind what it means to be genuine continues to intrigue Hachiman and his outlook for the future of the Volunteer Service Club and its members.', 87, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10541, 'Seishain Cyborg 003', 2012, 2, 'ONA', 75.4, 'A collaboration between 009 Re:Cyborg and Staff Service, featuring Cyborg 003 as a businesswoman.', 63, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10542, 'Musaigen no Phantom World: Limitless Phantom World', 2016, 7, 'Special', 69.5, 'Picture drama specials bundled with the main series Blu-ray/DVD volumes.', 79, True, 102);
