INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10545, 'Nori P-chan', 1989, 1, 'OVA', 75.8, 'An anime adaptation of a shoujo manga of the same name. The story follow Nori P-chans everyday live and the antics she gets in with her friends.', 88, True, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10546, 'Oyone to Mattsan: Ai no Uta', 1990, 1, 'OVA', 80.5, 'A story set in the countryside of Japan. Two teens meet and slowly fall in love. Their relationship has difficulties developing as her father doesnt approve of the boys request for her hand in marriage. Part of the OVA features a karaoke-style songs with lyrics present on-screen.', 95, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10547, 'Nyancos: Hello! Our Brilliant Future', 2003, 1, 'OVA', 71.6, 'Nyancos are UFO-riding cat women from space. They are whimsical, charming, and love all things beautiful and artistic as they watch worlds blossom. The OVA contains no dialogue, only background music.', 20, True, 107);
