INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10808, 'Mahou Shoujo? Naria☆Girls Nama de Anime wo Tsukuru Sama', 2016, 12, 'ONA', 81.3, 'Urara, Hanabi, and Inaho are three girls who aim to become nationally-renowned characters by creating animation of themselves! They chose the magical girl theme to catch the attention of everyone from children to adults! Can they safely become popular characters in a one-cours magical girl anime?  (Source: MAL News)', 20, True, 8);
