INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10911, 'Utsukushii Chikyuu wo Yogosanai de', 1995, 1, 'OVA', 76.8, 'Nana is a 3rd grader who finds a strange picture book. Shes able to jump into the book and be friends with the girl in it as they traveled around the work. She learns about the innocent cries of children all around the world suffering from pollution. The video has some live action segements.', 53, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10912, 'Torikaekko Please', 1998, 1, 'Music', 72.3, 'Official music video for Suzukisans Torikaekko Please song. The song and characters had been used to promote the Pokémon franchise. Nintendo has revived the song for the 20th anniversary campaign.', 106, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10913, 'IDOLiSH7', 2018, 17, 'TV', 60.2, 'On her first day of work at her fathers small production agency, Tsumugi Takanashi was not expecting to be made the manager of the agencys new male idol group. Though shocked that her father is trusting her with such a major project so soon, Tsumugi vows to do everything she can to support the seven young boys. After seeing how well the boys work as a team, Tsumugi meets with her father and learns that her first job as manager will be to cut four boys from the group. This is because her father believes seven idols are too much to manage, and the current top group, TRIGGER, only has three members.  After holding an impromptu audition, Tsumugi returns to her father and boldly declares that she refuses to cut anyone from the group, as each member has a unique allure which collectively enhances the groups appeal. She returns to the boys and they are thrilled that none of them will get to miss out on their dreams. Together they become IDOLiSH7, and prepare to take on the fiercely competitive world of idols.', 15, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (10914, 'Suntory Minami Alps no Tennensui', 2016, 3, 'Special', 62.5, 'Collaboration commercials with Suntory and Kimi no Na wa..  The Mitsuha no Omoi (Mitsuhas Thoughts) commercial shows the character Mitsuha Miyamizu drinking SUNTORY Minami Alps Tennensui Yogurina, which is yogurt-flavored mineral water.  The Taki no Omoi (Takis Thoughts) commercial shows the character Taki Tachibana drinking SUNTORY Minami Alps Tennensui, which is mineral water.   The Kasanaru Omoi (Overlap Thoughts) commercial shows both Taki and Mitsuha combining their thoughts through mixed dialogue with some alternative footage and a new song.  (Source: ANN)', 13, True, 114);
