INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11039, 'Nezumi-kun no Kimochi', 2008, 1, 'OVA', 79.5, 'Based on a well known childrens book by Yoshio Nakae with illustrations by Noriko Ueno.  It features various simple stories about a mouse in his red vest and his other animal friends as they learn about feelings.', 10, True, 119);
