INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11041, 'Fushou Shita Senro to Tsuki', 2010, 1, 'OVA', 85.2, 'Based on a childrens book of the same name.  The film teaches the importance of mind and that everything is connected.', 109, True, 1);
