INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11065, 'Pittanko! Nekozakana', 2016, 50, 'TV', 83.7, 'On a distant southern island, a fish (sakana) opened its mouth for a cat (neko), thus nekozakana (cat-fish) is born.  (Source: ANN)', 10, True, 25);
