INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11067, 'Miraijin Go Home', 2016, 8, 'ONA', 63.4, 'A person from the future visits a girl on her 16th birthday and asks for her hand in marriage because in the future, the female population has decreased to minimal numbers.', 25, False, 27);
