INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11121, 'Ocha-ken: Ryokutto Monogatari', 2008, 13, 'TV', 79.4, 'The third Ocha-ken series, this season focuses on environmental friendly themes.', 92, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11122, 'Kimi dake no Boku de Iru kara', 2016, 1, 'Music', 61.1, 'Music video for the opening theme from Trickster: Edogawa Ranpo Shounen Tanteidan yori.', 72, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11123, 'Long Riders! Recap', 2016, 1, 'Special', 76.6, 'Recap of the first four episodes of the Long Riders series.', 55, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11124, 'Vatican Kiseki Chousakan', 2017, 12, 'TV', 88.1, 'Fathers Josef Kou Hiraga and Roberto Nicholas are Vatican Miracle Examiners who investigate the authenticity of miraculous phenomena reported from all over the world. In every seemingly sacred event lies horrors of hidden conspiracies, mysterious murders, and devil worship. In this battle of good and evil, Hiraga, a scientific and mathematical genius, and Roberto, a polymath in linguistics and classics, must work together to bring the truth to light. Will their friendship and faith endure the evils in their journey to find a true miracle?', 118, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11125, 'Himitsukessha Taka no Tsume Countdown Specials', 2009, 5, 'Special', 72.1, 'Specials included on the DVD release of the Himitsukessha Taka no Tsume Countdown series.', 69, True, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11126, 'Cofun Gal no Coffy Campus Life Specials', 2009, 5, 'Special', 66.3, 'Specials included on the DVD release of the Cofun Gal no Coffy Campus Life series.', 99, False, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11127, 'Taka no Tsume x Ballad Katte ni Senden Movie', 2009, 1, 'ONA', 66.1, 'A promotional episode where the Eagle Talon team goes to Toho Cinemas to see Ballad: Namonaki Koi no Uta. At the very end the short promotes the 3rd Himitsukessha Taka no Tsume film coming out in three months.', 27, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11128, 'Cofun Gal no Coffy Campus Life: Intro', 2009, 1, 'ONA', 68.3, 'An introduction web episode to Cofun Gal no Coffy Campus Life while also covering the main cast and characters of the previous season. This episode was also included in Cofun Gal no Coffy Campus Lifes DVD release.', 97, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11129, 'Himitsukessha Taka no Tsume: Teikyou Kakutoku Daisakusen - Sakusen Kaigi', 2009, 12, 'Special', 81.0, 'Due to a sponsor issue, Himitsukessha Taka no Tsume Countdown had a Suntory designated advertising campaign that was posted online the same day as it aired on TV Asahis airing of the main anime (but not for any other TV channel). The ads were also included on the DVD release of the main anime.', 116, True, 89);
