INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11292, 'Kimi to no Tadashii Yakusoku', 2007, 3, 'Special', 82.8, 'Isami and Higashiba both play baseball in college. But what kind of thing did the two promise each other 7 years ago become?', 85, True, 12);
