INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11294, 'Anata no Katagoshi Chotto Ue', 2008, 3, 'ONA', 60.8, 'Guardian Spirit is something that you can only see in fortune telling and television spirit features. But there are guardian spirits who are quietly behind everyone and are working hard. The story of Guardian Services Agency Service by freelance spirits of guardian spirits for those who can not take such holidays.', 24, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11295, 'Shinmai', 2008, 4, 'Special', 69.6, 'Everyone is brand new (shinmai) at the beginning of their job. The story follows new rice (shinmai) grains in their jobs.', 16, True, 15);
