INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11298, 'Bikkuriman Kids: Theme Fighter Nyander', 2008, 4, 'ONA', 90.3, 'A Bikkuriman spinoff. This anime was a brand-awareness promotion for a new chocolate candy line; but the anime focuses on the characters in their universe without any actual product placement or reference to the chocolate.', 62, True, 18);
