INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11300, 'Kawaijuku Manavis CM', 2016, 1, 'ONA', 89.4, 'Kawaijuku Manavis, a cram school, commissioned commercial staring their first mascot, Manabear.', 25, True, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11301, 'Choco Kyouju no Oheya', 2016, 1, 'ONA', 86.8, 'A Meiji commissioned commercial teaching viewers the health benefits of chocolate such as alleviating high blood pressure.', 87, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11302, 'Benpiyaku Colace', 2014, 7, 'ONA', 82.6, 'Taisho Pharmaceutical commissioned commercials for their new Benpiyaku Colace anti-constipation medicine. It features an intestinal-stressed struggling doe as she encounters other animals who can easily go.', 106, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11303, 'Kujira no Kora wa Sajou ni Utau', 2017, 12, 'TV', 75.7, 'In a world covered by an endless sea of sand, there sails an island known as the Mud Whale. In its interior lies an ancient town, where the majority of its inhabitants are said to be Marked, a double-edged trait that grants them supernatural abilities at the cost of an untimely death. Chakuro is the village archivist; young and curious, he spends his time documenting the discovery of newfound islands. But each one is like the rest—abandoned save for the remnants of those who lived there long ago.   For the first time in six months, another island crosses the horizon, so Chakuro and his friends join the scouting group. During the expedition, they find vestiges of an archaic civilization. And inside one of its crumbling remains, Chakuro discovers a girl who will change his destiny and the world inside the Mud Whale as he knows it.', 10, True, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11304, 'Crocotires Traction AAA', 1999, 1, 'Movie', 67.7, 'A huge garbage dump where old tires are piled up place turns into a different world late at night when no ones around. The old tires come to life, transforming their appearances and immersing themselves in boxing.  (Source: Official Youtube channel)', 71, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11305, 'Warau Tsuki', 2000, 1, 'Movie', 70.6, 'A play on the ancient Chinese puzzle of tangram.  (Source: British animation awards)', 36, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11306, 'Sekisou-tai', 1982, 1, 'Movie', 91.2, 'By changing the overlapping of sections in the time axis / space axis, the laminate based on the die cut of the hand transforms into various shapes.', 91, False, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11307, 'the FLY BanD!', 1998, 1, 'Special', 62.8, 'The FLY BanD is a group of funky, fashionable musicians from NY who have an outstanding sense of rhythm and groove. They start another music session using daily products somewhere in the world.  (Source: Official Youtube channel)', 105, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11308, 'In Search of Axis', 1989, 3, 'Special', 69.8, 'Polygon Pictures Inc.s first animated work.', 25, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11309, 'Samuroid Zero', 2005, 1, 'Special', 76.4, 'This is a pilot movie for a Polygon Picutres Inc. original project, a full CG SF action samurai drama movie originally announced at the 2005 Tokyo International Anime Fair. The project was scrapped and only the pilot remains.', 115, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11310, 'Shiseido HG Super Hard', 1995, 6, 'Special', 91.7, 'Shiseido commissioned commercials for their Super Hard hair mousse product.', 55, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11311, 'Youjo Shenki Episode 0', 2017, 1, 'ONA', 77.1, 'Episode 0 of the Mini Anime for Youjo Senki.', 14, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11312, 'Junlin Chengxia', 2016, 13, 'ONA', 71.3, 'In a day like any other, Cao Xiao Mans brother, Xiao Bei, is stabbed by a man after defending a mysterious girl. Due to the incident, and to buy medicine for his brother, Cao Xiao Man decides to earn money in a rather strange way: cross-dressing as a girl and seducing men. When he arrives to his clients house everything seems to go as planned, but the client soon discovers that Cao Xiao Man is, in fact, a boy. He decides to put Cao Xiao Man in a game where he is turned into a girl. In order for Cao Xiao Man to go back to being a boy he needs to complete the game and find the 7 Loyalties located all over the country.  (Source: YouTube)', 70, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11313, 'Kaito x Ansa', 2017, 12, 'TV', 71.7, 'Second season of Nazotokine.', 110, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11314, 'Minna no Okayama-ken', 2015, 10, 'ONA', 77.3, 'An Okayama Prefecture tourism promotional anime. It follows three girls; a monkey, a pheasant, a dog--all companion animals in the folktale Momotarou. Other folktale characters make appearances but the main episode progression is the girls doing things in the city while non-stop chatting about things happening in the city. This shows off efficient public transportation, volunteer work to help others such as blood donation, countryside landscapes that are friendly for the elderly, fun sporting events, etc.', 46, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11315, 'One Room Special', 2017, 1, 'Special', 68.4, 'Unaired episode included with the Blu-ray release. It uses clips of the initial introduction of all three girls respectively but has them in swimsuits instead of their normal attire.', 95, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11316, 'Minami Kamakura Koukou Joshi Jitensha-bu: Kita yo, Taiwan!', 2017, 1, 'Special', 71.5, 'Unaired episode included with the special edition BD release.  The girls hear from school principal Ryuko that the school is considering Taiwan as the destination for the school trip. Since Taiwan is one of only a few advance cycling nations, she instructs the cycling club to go to Taiwan as part of a preliminary inspection for the school trip. But as soon as they arrive in Taiwan, Hiromi and Sandy become separated...  (Source: Crunchyroll)', 28, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11317, 'Sengoku Choujuu Giga: Otsu', 2017, 13, 'TV', 93.9, 'Second season of Sengoku Choujuu Giga.', 117, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11318, 'Tomica Hyper Rescue Drive Head: Kidou Kyuukyuu Keisatsu', 2017, 37, 'TV', 64.3, 'A little bit in the future, the government has established a brand new organization with the purpose of rescuing lives to respond to the increasingly complicated and varied types of disasters, accidents and crimes that go beyond human comprehension. It is called the Mobile Emergency Police DRIVE HEAD force combining specialized police, firefighting and rescue skills. DRIVE HEAD is an advanced mobile device that transforms in form factor from car to humanoid walker vehicle. The drivers are high-aptitude, grade school students such as Go Kurumada who collaborate with mobile emergency police adults and rush to crisis situations to secure public safety and preserve the peace for all!  (Source: TBS Global Business)', 24, True, 38);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11319, 'Youjo Shenki', 2017, 12, 'ONA', 89.1, 'A chibi parody of Youjo Senki.', 93, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11320, 'Shita-kiri Suzume (1974)', 1974, 1, 'Movie', 71.6, 'A traditional Japanese fable telling of a kind old man, his avaricious wife and an injured sparrow. The story explores the effects of greed, friendship and jealousy on the characters.  (Source: Wikipedia)', 58, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11321, 'Kumo no Gakkou', 2005, 1, 'Movie', 66.5, 'Near the end of the 19th century, a young boy loses his father and has to move from a comfortable city to a poor village in Saitama. There, living with his mother, elder sister, and a dog, he learns valuable lessons about whats truly important in life.', 52, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11322, 'Mahoujin Guruguru (2017)', 2017, 24, 'TV', 60.8, 'Nike was a simple boy from Boering Village, and the last thing he ever wanted was to become a hero. But when a sign appears from the king of Ainshent Castle Town recruiting heroes to slay the Demon Lord Giri, Nikes father enthusiastically forces him out the door. Along with Kukuri, a member of the Migu Migu Clan, Nike sets out on an adventure to become the legendary hero that the world needs.  As Nike and Kukuri travel across different continents, they attempt to learn the secrets of Guru Guru Magic, a strange but powerful type of magic used to seal Demon Lord Giris power. While reluctantly taking on their assigned quest, the duo does not fail to acquire new comrades and have fun along the way.', 45, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11323, 'Fussa-shi PR Anime', 2017, 2, 'ONA', 86.2, 'Episode 1: This is Kaori who works at an international IT firm in Roppongi, Tokyo. Her plan to serve Japanese Sake made in Tokyo at a PR event she was in charge of was not accepted. Kaori who had lived overseas for a long time was unable to hide her frustration with this limitation because she was unable to understand the Japanese office customs and regulations.  Later, her colleague calmed her down and suggested she go to the Japanese Sake breweries to see the important traditional process of making Sake.  She discovered that it takes only an hour by train from Shinjuku to Fussa City, and there she visited two sake breweries. What she saw there was ….?  Episode 2: A young assistant director, Matsuko, who was struggling to find a location for the drama that was being shot the next week. When she consulted with Mr. Higuchi, Director of Shin Godzilla and Director Onoe, Fussa City in Tokyo was proposed to her. When I visited Fussa City the next day, she met Haraguchi-san, who was engaged in creative activities at the American House in the city during her school days. Looking around the city with three directors, the various expressions of the Fussa are emerging ...!  (Source: Official YouTube channel)', 46, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11324, 'Blood Lad: Kanketsu Kinen', 2017, 1, 'ONA', 63.9, 'A short conclusion memorial PV promoting the final tankoubon volume of the Blood Lad manga going on sale. The PV shows various moments throughout the whole manga.', 48, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11325, 'ChäoS;Child Episode 0', 2017, 1, 'Special', 68.3, 'A recap of ChäoS;HEAd that aired along with episode 1 of ChäoS;Child as part of a one-hour special.', 116, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11326, 'Rilu Rilu Fairilu: Yousei no Door', 2016, 59, 'TV', 61.7, 'Fairilu are fairies of flowers, insects, mermaids, or other entities that are born from Farilu Seeds. All Fairilu are born with their own key, and they must search to find and open the door that fits only their key. Once the Fairilu pass through the doors, they mature. The doors are also related to the human world.  (Source: ANN)', 31, True, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11327, 'Kuma no Gakkou: Patissier Jackie to Ohisama no Sweets', 2017, 1, 'Movie', 74.7, 'No description available for this anime.', 82, False, 47);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11328, 'Fuusen Inu Tinny: Nandaka Fushigi na - Kyouryuu no Kuni', 2017, 1, 'Movie', 78.1, 'Follows a dog and his friends who wear balloons and explore a kingdom in the clouds.', 15, True, 48);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11329, 'Town Workers', 2014, 3, 'ONA', 83.6, 'An omnibus work portraying the lives of youth who have just started to work.  (Source: Rockwell Eyes)', 95, True, 49);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11330, 'Chen-Kuro Gakuen', 2016, 3, 'Movie', 95.4, 'Each of the three Chain Chronicle: Haecceitas no Hikari films will run with a Chen-Kuro Gakuen (Chen-Kuro Academy) short. Chen-Kuro is a diminutive way of shortening Chain Chronicle in Japanese.  (Source: ANN)', 115, True, 50);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11331, 'Kine-Pass Gekijou', 2016, 3, 'Movie', 95.8, 'The T-Joy theater chain will also screen three Kine-Pass Gekijou (Kine-Pass Theater) commercials to promote its Kine-Pass ticket sales app using the chibified Chen-Kuro Gakuen characters.  (Source: ANN)', 36, True, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11332, 'Kuro-Nikuru Girls', 2016, 3, 'ONA', 68.1, 'The digital sale/airing of the Chain Chronicle: Haecceitas no Hikari movies includes its own unique version of the Chain Chronicle chibi shorts, different from the chibi shorts shown with the theater airing. Their focus is on the female cast.', 38, False, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11333, 'Chein Kuro-Nikuru!!', 2017, 12, 'Special', 79.7, 'Each television episode of Chain Chronicle: Haecceitas no Hikari will air weekly with one of 12 Chein Kuro-Nikuru, a wordplay on Chain Chronicles Japanese pronunciation and the Japanese term for black shorts.  (Source: ANN)', 80, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11334, 'Elsword: Ain-ui Gieog Animation', 2016, 1, 'ONA', 60.0, 'This was the Secret Video that was shown in Anime premiere event. It tells the story of, Ain, a secretive timekeeper during the events of Elsword: El-ui Yeoins first episode.  (Source: 2nafish)', 70, False, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11335, 'Dynamic Chord', 2017, 12, 'TV', 89.7, 'Dynamic Chord is a record company and music agency representing the hottest artists right now with, in particular, four of the countrys most popular bands.  They are rêve parfait with its own unique world view and progressive sound, Liar-S, an emo rock band, KYOSO, a group of highly-polished performers, and apple-polisher, which fuses dance with rock and roll. Against the backdrop of Japans four seasons, comes a realistically depicted documentary movie about the encounters, breakups and trajectory of these 16 band members as they vie for musical preeminence.  (Source: TBS Global Business)', 19, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11336, 'Eureka Seven AO: One More Time - Lord Dont Slow Me Down', 2017, 5, 'ONA', 82.2, 'A new episode split into five parts, further explaining the end of Eureka Seven AO.', 44, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11337, '91 Days: Toki no Asase/Subete no Kinou/Ashita, Mata Ashita', 2017, 1, 'Special', 99.8, '1. Toki no Asase (Shoal of Time) 2. Subete no Kinou (All Our Yesterdays) 3. Ashita, Mata Ashita (Tomorrow and Tomorrow)', 100, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11338, 'Ar:pieL - 6-seosgae-ui Unmyeong', 2014, 3, 'ONA', 92.5, 'Entry for the canceled anime of the Nexon Animation Project. Like the first two, it was supposed to be an adaptation of an action fantasy PC game.  Contains the PV and the 2 released Openings.', 12, True, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11339, 'Tama Pawns', 2017, 6, 'ONA', 78.7, 'The story follows Mihiro and begins on a day like any other. Mihiro bumps heads with a pet dog and loses consciousness. When she wakes up, she finds herself in a mysterious animal world. Mihiro discovers the shocking truth of her new situation and starts work at an animal pawn shop. She sets her sights on the day she can leave the shop and return to her former world.  (Source: ANN)', 27, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11340, 'Kuroko no Basket: Oshaberi Shiyou ka', 2017, 1, 'Special', 91.1, 'Special included on Kuroko no Basket Fan Disc 3: Korekara Nandodemo.', 104, True, 60);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11341, 'Tamashichi!', 2015, 1, 'ONA', 69.3, 'The show follows Mayas day at work at the Tamaya Shichi Pawn Shop.', 111, True, 61);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11342, 'Idol Time PriPara', 2017, 51, 'TV', 80.0, 'The story focuses on Yui, a girl who lives in the town of Paparajuku, and who dreams of being an idol, even if she realizes that being an idol is next to impossible for her. Her friends often remark on how much she dreams about it. But then, the PriPara idol theme park opens in her town, and that an idol named Laala is coming to town from Parajuku, which only makes Yui dream even bigger. The new PriPara theme park has been updated with new concepts. However, due to a system error, Laala is no longer able to PriPara Change.  (Source: ANN)', 10, True, 62);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11343, 'Shin Biofermin S', 2016, 1, 'Special', 90.9, 'TV commercials for Shin Biofermin S, a lactic acid bacteria probiotic supplement manufactured by Biofermin Pharmaceutical. The first commercial explains how the supplement improves intestinal flora and the mechanisms behind it.', 31, True, 63);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11344, 'Yoake Tsugeru Lu no Uta', 2017, 1, 'Movie', 89.0, 'In the seaside village of Hinashi Town, Kai Ashimotos grandfather is one of the locals who reinforces the legend that mermaids lurk near Merfolk Island and consume humans. Due to allegedly attracting merfolk and subsequently causing the death of the elders mother, music is seldom discussed in the Ashimoto household. Even so, Kai finds solace in making looped beats on his laptop and uploading them to the internet.  Despite his reserved and glum demeanor, Kai is approached by Kunio and Yuuho Ebina, two cheerful classmates that happened upon one of his videos. The pair ask him to join their rock band but are met with apathy. Nevertheless, Kai agrees to accompany them in a practice session on Merfolk Island, where he soon witnesses something that he cannot explain.  Later that night, Kai is composing music in his room when he attracts a familiar entity—a mermaid. As she twirls and grins to the sound of his stereo, Kai discovers a number of aspects about the being who introduces herself as Lu: she possesses incredible water manipulation powers; she buds a pair of functioning legs with the sound of music; but most notably, she is a truly benevolent creature who simply wants people to like her. Fostering a dynamic friendship, Kai and Lu gradually come to express their genuine selves, testing the long-standing boundaries that have deafened the resounding harmony among the people of Hinashi Town.', 59, True, 64);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11345, 'Yukai na Animal Bus', 2017, 12, 'TV', 83.0, 'No description available for this anime.', 35, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11346, 'Yuru Camp△', 2018, 12, 'TV', 75.4, 'While the perfect getaway for most girls her age might be a fancy vacation with their loved ones, Rin Shimas ideal way of spending her days off is camping alone at the base of Mount Fuji. From pitching her tent to gathering firewood, she has always done everything by herself, and has no plans of leaving her little solitary world.  However, what starts off as one of Rins usual camping sessions somehow ends up as a surprise get-together for two when the lost Nadeshiko Kagamihara is forced to take refuge at her campsite. Originally intending to see the picturesque view of Mount Fuji for herself, Nadeshikos plans are disrupted when she ends up falling asleep partway to her destination. Alone and with no other choice, she seeks help from the only other person nearby. Despite their hasty introductions, the two girls nevertheless enjoy the chilly night together, eating ramen and conversing while the campfire keeps them warm. And even after Nadeshikos sister finally picks her up later that night, both girls silently ponder the possibility of another camping trip together.', 76, True, 66);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11347, 'PriPri Chii-chan!!', 2017, 36, 'TV', 94.1, 'The story revolves around a girl named Yuuka, who encounters a being from the depths of the Earth named Chii-chan (a pun of chiteijin, the Japanese word for underground-dweller), and an alien named Ucchan (a pun of uchuujin or alien). The story follows their heartwarming and chaotic everyday lives together.', 13, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11348, 'Action Heroine Cheer Fruits', 2017, 12, 'TV', 89.8, 'Several years ago, local heroines—superhero characters who represent towns and perform stage shows in order to raise their towns acclaim—had a boom in popularity. The most famous of these local heroines, Kamidaio, is scheduled to perform in the small town of Hinano, much to the excitement of Mikan Kises little sister Yuzu. Unfortunately, when Mikan takes Yuzu to the show, she finds out that it has been canceled. She promises her distraught sister that shell make sure she can see the show. Desperate not to let her down, Mikan asks her classmate, the local heroine fanatic An Akagi, for help.  Mikan and Ann put on their own Kamidaio performance clad in homemade costumes, which the kids in the audience love despite its lack of production value. The show is recorded by the student council president Misaki Shirogane, who posts it online to garner attention. Misaki is from a family of politicians and has taken it upon herself to revitalize Hinano. Impressed by their show, she recruits Mikan and An to become the official local heroines of their town. As the group works to improve their shows, they enlist the help of a variety of colorful individuals.', 90, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11349, 'Cobalt World', 2016, 1, 'Music', 68.9, 'Music video for the song Cobalt World by Sangatsu no Phantasia.', 75, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11350, 'ViVid Strike! Specials', 2017, 3, 'Special', 75.1, 'Episodes 5.5, 5.75, and 13 bundled with the second, third, and fourth Blu-ray volumes of ViVid Strike!', 62, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11351, 'Susume! Godzilland', 1994, 4, 'OVA', 91.6, 'Advance! Godzilland is a series of four educational OVAs released on VHS in 1994 and 1996 by Gakken. They use Godzilla and other kaiju to teach children about hiragana, counting, addition, and subtraction.', 55, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11352, 'Ningyohime', 1974, 1, 'Movie', 75.9, 'A stop-motion film adaptation of Hans Christian Andersens The Little Mermaid.', 31, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11353, 'Zo Zo Zo Zombie-kun', 2017, 2, 'ONA', 63.6, 'A gag comedy aimed at young children featuring Zombie-kun, a child zombie, and his interactions with the world. Its not intended to be scary in the slightest, but rather, it focuses on the comical and bizarre things Zombie-kuns body can do, and the common-sense-defying way Zombie-kun behaves. For example, hell take out his stomach and inflate it with air to use as a pillow, or if he gets wet, hell detach parts of his body and wring them out like towels, then reattach them with a glue stick. Everything is depicted in a cute, cartoony fashion so as not to be too graphic for kids.   (Source: Baka-Updates)', 99, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11354, 'Sakura Internet', 2017, 1, 'ONA', 80.2, 'Freelancer Touno Kouhei, office lady Hamada Saori, and graphic designer Ginji realize that theyre not content in their current jobs, and break free to pursue their dreams - as a musician, a photographer, and an artist, respectively.  (Source: Crunchyroll)', 12, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11355, 'Mazinger Z Movie: Infinity', 2018, 1, 'Movie', 92.4, 'Ten years ago, the villainous scientist Dr. Hell led his wicked followers, known as the Underground Empire, in a struggle to destroy all of humanity. It was against these forces that the young hero Kouji Kabuto fought, piloting the legendary super robot Mazinger Z. Koujis victory stopped Dr. Hells evil plan and returned peace to the Earth.  Now Kouji has left the pilot seat behind and become a scientist in his own right, following in his fathers and grandfathers footsteps. Yet an unexpected encounter deep under Mt. Fuji triggers an even greater threat to mankind than ever before and alters Koujis destiny forever. With humanitys fate in their hands, Kouji and Mazinger Z face a choice between good... and evil.  (Source: VIZ Media)', 38, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11356, 'Tsuki ga Kirei', 2017, 12, 'TV', 79.5, 'With a new school year comes a new crowd of classmates, and for their final year of junior high, aspiring writer Kotarou Azumi and track team member Akane Mizuno end up in the same class. Though initially complete strangers, a few chance encounters stir an innocent desire within their hearts. A yearning gaze, a fluttering heart—the hallmarks of young love slip into their lives as fate brings their paths to a cross.  However, though love is patient and love is kind, Kotarou and Akane discover it is not always straightforward. Despite the comfort they find in each others company, heartache and anxiety come hand in hand with pursuing the feelings in their hearts. With the uncertainty of how the other truly feels as well as the competing affections of those around them, the road ahead is unclear. Even so, under the shining light of a beautiful full moon, Kotarou gathers his courage to ask Akane a single question, one that forever changes their quiet relationship.', 56, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11357, 'Keppeki Danshi! Aoyama-kun', 2017, 12, 'TV', 92.1, 'He is charming, cool, athletic, a good cook, but more importantly, hes a clean freak. Aoyama is idolized and respected by everyone, but they can only admire him from afar due to his mysophobia. Despite that, he plays soccer—a rather dirty sport!  As the playmaker for Fujimi High Schools soccer club, Aoyama avoids physical contact at all cost and cleanly dribbles toward victory. However, the path to Nationals will not be easy for Fujimis underdog team. But alongside striker Kaoru Zaizen, Aoyama will show everyone that even as a clean freak, there are things hes willing to get dirty for.', 119, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11358, 'Maple Town Monogatari (Movie)', 1986, 1, 'Movie', 89.3, 'No description available for this anime.', 28, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11359, 'Dance with Devils: Fortuna', 2017, 1, 'Movie', 78.3, 'Ritsuka Tachibana. She lives a calm and unchanging life. Ritsukas older brother Lindo returns from studying abroad in the United Kingdom. Shikou Academy student council president Rem Kaginuki calls on the girl, and she begins having mysterious encounters with the student council members. Her life changed a little from that day, but Ritsuka expected nothing more.   However, she comes home to find her mother collapsed with suspicious hooded men nearby. They were not human but devils, vampires, and exorcists seeking the Forbidden Grimoire. Ritsukas former daily life crumbles around her, and she finds herself slowly becoming attracted to Rem, who helps her in her predicament. On the other hand, confusion deepens with regard to her brother who carries a secret. Ritsuka is unsure what path to choose as she finds herself at the center of a love story.  (Source: ANN)', 25, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11360, 'Hanitarou desu.', 1997, 70, 'TV', 84.7, 'Shown daily during the Super J Channel news programme.', 53, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11361, 'Hina Logi: From Luck & Logic', 2017, 12, 'TV', 89.5, 'Liones Yelistratova, a pure princess from a small country, enters a school in Hokkaido on a spring day. The school is a specialized educational institution operated by ALCA to train Logicalists, who maintain world peace. Liones enters class S, where she meets many classmates with unique personalities, like Nina. A lively and cute everyday life begins now.  (Source: MAL News)', 64, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11362, 'Crayon Shin-chan Gaiden: Kazokuzure Ookami', 2017, 13, 'ONA', 97.6, 'Master butt-swordsman Hiroshinosuke Nohara (Lone Wolf) travels with his family seeking employment. The family encounters a mysterious girl Hazumi and a wild dog Shiro, and decides to travel together. The group is attacked by various assassins, eventually their lives are threatened by the butt-swordsmens enemy, the armpit-swordsmen of the Demon Bull Clan. Who will win: butts or armpits? Against an array of idiosyncratic enemies, Hiroshinosuke Nohara and his son Shinnosuke have the chance to display their swashbuckling skills.  (Source: ANN)', 65, True, 82);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11363, 'Future Card Buddyfight Battsu', 2017, 52, 'TV', 93.9, 'The fourth season of Future Card Buddyfight.', 21, True, 83);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11364, 'Sanrio Danshi', 2018, 12, 'TV', 81.6, 'Kouta Hasegawa is a completely normal high school student who likes his Pompompurin stuffed animal, a Sanrio character modelled after a Golden Retriever, which his grandmother gave him when he was young. However, an incident in which other kids accused him of being girly for liking Sanrio characters made him ashamed of his attachment to Pompompurin.   Through a series of unexpected events, Kouta ends up meeting others at school who also like Sanrio characters—Yuu Mizuno, a flashy boy who is popular with girls; Shunsuke Yoshino, a member of the soccer team; Ryou Nishimiya, an underclassman who is a library assistant; and Seiichirou Minamoto, the student council president.  Through his new friends, Kouta learns that there is no need to be embarrassed for liking Sanrio characters; and together, they aim to create a play for the cultural festival in order to transform his normal school life into a sparkly one.', 14, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11365, 'Kitsune Tsuki', 2015, 1, 'Movie', 83.8, 'In the evening of a village festival, a young boy named Bunroku goes to the festival with his friend and visits a clog shop on the way. There he learns an old superstition about the fox.  (Source: haff.nl)', 86, True, 85);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11366, 'Haruniwa Ie no 3 Nin-me', 1998, 45, 'TV', 82.6, 'The Haruba family is a wonderful family of three kids. The protagonist is the youngest son of the three siblings, who is in actuality, a spirit. The story unfolds in a nostalgic background of Japan and relates the life of this incredible family.  (Source: ANN)', 16, True, 86);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11367, 'Ponkotsu Quest x Monsterz', 2014, 3, 'ONA', 67.5, 'A collaboration promotion between the Ponkotsu Quest anime and the Monsterz live action horror film (which is a remake of a South Korean film titled  Haunters) airing in theaters.', 11, True, 87);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11368, 'Ponkotsu Quest x Gatchaman Special', 2014, 1, 'ONA', 96.3, 'A collaboration promotion between the Ponkotsu Quest anime and the 2013 Gatchaman live action films release on DVD/BD March 5, 2014.', 82, True, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11369, 'Konohana no Sakuya Mori', 2015, 1, 'Movie', 88.8, 'A horse puppet wanders into a silver world and pauses before an ethereal flower.  (Source: CoolConnections)', 28, True, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11370, 'This Is My House', 2015, 1, 'Movie', 69.8, 'This is a story of an adolescent boy living in a burning house with his parents. He cant drink black coffee yet he refuses his mothers offer of sugar lump. Rejecting his mothers kindness and ignoring his fathers concern, he struggles with his own internal conflicts and continues to perform the minor rebellions of youth. Trying to attract the attention of a girl, the boy crashes a stolen motorcycle. In the aftermath of the accident he finds in his pocket a bill stolen from his mothers purse, now changed into a sugar lump. Rather than mend the relationship with his family, he takes the sugar lump to his friends, but they reject him, throwing the sugar lump away.  (Source: airport-anifes.jp)', 45, True, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11371, 'Kaibutsu Gakushou', 2016, 1, 'Movie', 92.1, 'An animated archive of imaginary monsters written by a fictitious monsterologist in Medieval Europe.  This work depicts the habits of monsters using movement inspired by short phrases such as “Taste of Tears”, “Tamed Wildness”, etc.  (Source: Yamamura Animation)', 83, False, 91);
