INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11631, 'Mori no Kaori x Kamiusagi Rope', 2013, 3, 'ONA', 87.1, 'A collaboration between Kamiusagi Rope and Nipponhams Mori no Kaori product line. Meant to showcase sausages, bacon, ham, etc. that have a rustic  forest flavor with no added colors and reduced sodium. Episodes were available to view by entering a code online that was given on the inner label of a Mori no Kaoris product package.', 94, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11632, 'Shiseido x Kamiusagi Rope', 2014, 2, 'ONA', 83.0, 'A collaboration between Kamiusagi Rope and two of Shiseidos product lines: Anessa and Fullmake Washable Base (FWB). These episodes were included on the 6th DVD of Kamiusagi Rope: Warau Asa ni wa Fukuraitaru tte Maji ssuka!? as episode 23 and 24 released on March 18, 2015.', 34, True, 112);
