INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11636, 'Kemono Friends 2', 2019, 12, 'TV', 74.0, 'Serval and Caracal find a human child in the forest. As they travel with the child, they meet new Friends, uncover the secrets of Japari Park, and become involved in an event that will shake the earth.  (Source: ANN)', 21, False, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11637, 'Busou Shoujo Machiavellianism: Doki! Goken-darake no Ian Ryokou', 2017, 1, 'OVA', 88.1, 'Original 13th episode bundled with the limited edition 7th volume of the Busou Shoujo Machiavellianism manga.', 54, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11638, 'ChäoS;Child: Silent Sky', 2017, 1, 'Movie', 89.0, 'Silent Sky is a combination of the additional episodes 13 and 14. It consists of the story in the future, three months after the incident that was similar to New Generation Madness and the disease Chaos Child Syndrome that brought by the past earthquake in Shibuya.', 38, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11639, 'Mini Rope', 2012, 4, 'TV', 67.1, 'A short broadcast of Kamiusagi Rope meant to promote the feature film that was released during the middle as well as promote features of the Nihon Eiga Senmon Channel (Japanese Movie Specialty Channel) which is a luxury TV channel that specializes in broadcasting films that costs about 700 yen a month. Rope and Akira talk about what mono sound is and what does the service feature actually do.', 99, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11640, 'Freaky Highschool', 2016, 69, 'TV', 72.2, 'A cutesy horror anime. Everyone in town is monster but theyre living their lives like normal while attending high school.', 49, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11641, 'Cardcaptor Sakura: Clear Card-hen Prologue - Sakura to Futatsu no Kuma', 2017, 1, 'OVA', 97.8, 'After the conclusion of the Sakura Card Arc, life is going back to normal. There are no more mysteries, no more disturbances of evil, no more tests of strength. Everyone is moving on with their lives and Sakura feels a sadness in her heart. Even through the goodbyes, Sakura perseveres to keep everyone and a special someone, dear to her heart.', 94, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11642, 'Haikyuu!! Tokushuu! Haru-kou Volley ni Kaketa Seishun', 2017, 1, 'OVA', 89.2, 'The OVA episode revisits the primary matches from the spring tournament and features interviews with players.  (Source: MAL News)', 49, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11643, 'Tadaima.', 2017, 1, 'Music', 71.8, 'Music video by Oshima Tomoko.', 112, True, 3);
