INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11770, 'Kaiketsu Zorori no Dragon Taiji', 1989, 1, 'OVA', 89.8, 'The first anime adaptation of the Kaiketsu Zorori franchise. It adapted 3 of the picture books stories. A 2nd OVA was planned to cover 3 more books but it was postponed and eventually cancelled.', 92, False, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11771, 'Slow Start', 2018, 12, 'TV', 78.2, 'Hana Ichinose, a 17-year-old high school student who is not only introverted, but also insecure and timid, has just moved and will be attending a new school. To make her situation more difficult,  Hana is a slow start, which means that she missed a year and worries about attending a class where everyone is younger than her.  During her introduction, the teacher reveals it is Hanas birthday, which gives her the jumping-off point  to meet three of her classmates: Tamate Momochi, a charismatic and extroverted girl; Kanmuri Sengoku, who is shy and small; and the popular and pretty Eiko Tokura. Not wanting to lose the chance to make new friends, Hanas interactions with these three mark the beginning of some beautiful relationships that will change her life.', 62, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11772, 'Turning Mecard', 2015, 52, 'TV', 96.6, 'A Korean/Japanese co-production created by Bakugan and Dragon Ball Super contributor Atsushi Maekawa.  Turning Mecard stars Jason, a grade-schooler who meets a Mecanimal, a transforming minicar from the alternate world of Triforce, named Evan. Jason and Evan are both searching for missing family members, and team up to help each other. Together, they meet more Mecanimals as they battle across dimensions and learn important lessons along the way.  (Source: Crunchyroll)', 118, True, 12);
