INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11784, 'Koe no Katachi Specials', 2017, 2, 'Special', 91.0, 'The limited first edition of the Blu-ray Disc for Kyoto Animations film adaptation of Yoshitoki Ooimas A Silent Voice manga includes two bonus new animation videos of AIKOs theme song Koi wo Shita no wa and Kensuke Ushios in-film track Speed of Youth.  Kyoto Animation produced the videos inspired by the songs, and the films director Naoko Yamada personally handled the videos storyboards and technical direction.  (Source: ANN)', 79, True, 24);
