INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11792, 'Jinryoku Senkan!? Shiokaze Sawakaze', 2017, 3, 'ONA', 73.0, 'The series plays out in the Onahama district in Iwaki, in the Fukushima prefectures coastal region.   It follows the personifications of two WW2 japanese warships, Shiokaze and Sawakaze, who worked as breakwaters in Onahama Port. In this fictional story, the 2011 earthquake pierces a worm hole in the spacetime continuum, starting an invasion from another dimension.', 107, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11793, 'Boku wa Kimi no Namida', 1998, 1, 'Music', 69.6, 'A song about water and tears by Oota Hiromi that was featured on NHKs Minna no Uta.', 31, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11794, 'Watashi to Kotori to Suzu to', 2006, 1, 'Music', 77.9, 'The poem Watashi to Kotori to Suzu to was originally written by Misuzu Kaneko. Composer Ryuichi Sugimoto converted the poem into a song and it was sung by Aragaki Tsutomu. This song was animated for NHKs Minna no Uta program.', 85, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11795, 'Toji no Miko', 2018, 24, 'TV', 88.3, 'Throughout history, an elite group of shrine maidens known as Toji have saved the world from Aratama, strange and malevolent beings bent on destroying humanity. In modern times, these warriors have been assigned to a special police squad to exterminate Aratama. The government has also set up five elite schools across the country to provide young girls the necessary sword fighting skills to eradicate these monsters and eventually join their fellow Toji in protecting the world.  A student of one of those five schools, Kanami Etou is chosen to represent Minoseki Academy in a sword fighting tournament, where she meets the mysterious Hiyori Juujou. Although Kanami and Hiyori rise to the top of the tournament, their battle takes an unexpected turn, throwing the world of the Toji into chaos. Likely that the Toji are facing betrayal from within, the two are forced to flee the tournament, clashing with former comrades on the way.', 43, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11796, 'Meiken Lassie: Yume ni Mukatte Hashire!', 1997, 1, 'Special', 69.4, 'The unaired episode 26 of Meiken Lassie.', 73, False, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11797, 'Ylion to Callysia', 2017, 1, 'Movie', 79.3, 'Calysia and Ylion are very close siblings. One day, Calysia was kidnapped because their father tried to catch a unicorn. After 10 years Ylion grew up and trained as a warrior. He left to go to the hanging garden where unicorns live with a sword that was made from a unicorns horn.  (Source: ShortShorts)', 34, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11798, 'Tsuki ga Kirei: Michinori', 2017, 1, 'Special', 63.0, 'Recap of the first six episodes of Tsuki ga Kirei.', 95, True, 38);
