INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11854, 'Cake Sushi', 2015, 2, 'ONA', 62.4, 'Stop-motion commercials for Mizkans cake sushi. The first episode features a jack-o-lantern ghoul tired of eating candy. The second episode features a depressed Santa Claus because he always has to eat Christmas cake.', 105, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11855, 'Mori no Hito to Shoutengu-chan', 2014, 1, 'Special', 62.8, 'A small tengoku practices as much as he can to be an attendant. While practicing flying in the forest, he hears the plea of a parent bird.', 38, True, 95);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11856, 'NoisyCell x Ponkotsu Quest', 2017, 1, 'ONA', 72.2, 'A collaboration promotion between the Ponkotsu Quest and NoisyCell for their 3rd minialbum Pieces being released on June 21, 2017 as well as their tour New Game+ starting on July 16, 2017.', 42, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11857, 'Akichi Asobi: Playground', 2013, 1, 'Movie', 80.1, 'A boy is always alone, at school, or at home.  One day, he finds a sandlot on the way home and thinks of making a ‘town’ of his own.  Another boy was watching his play and starts to imitate him.', 27, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11858, 'Anime Mitai na', 2014, 1, 'Music', 78.0, 'Music Video by the dresscodes of the albums 6th track Anime Mitai na to promote the new Album 1.', 90, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11859, 'Afureko! AR', 2011, 3, 'ONA', 95.1, 'Saori was thrown into a voice actor vocational school to escape from being a NEET. There she meets Miki, a former nurse, and Ayano, who aims to become an idol voice actor. School life begins with three beautiful girls aiming to become voice actors!  (Source: Official Site)', 103, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11860, 'Arara', 2014, 1, 'Movie', 77.5, 'Naoko had a fight with her brother over a trivial thing and pushed him away. She knew she was childish but she ran away from home.', 96, True, 100);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11861, 'Baby Gamba', 2014, 13, 'TV', 93.0, 'No description available for this anime.', 110, False, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11862, 'Boku no Kanojo ga Majimesugiru Sho-bitch na Ken', 2017, 10, 'TV', 90.9, 'Haruka Shinozaki has been interested in the class representative, Akiho Kousaka, since his first year in high school. She is attractive, good at sports, and is an all-around model student. Since they are in the same class this year, Shinozaki decides to confess his feelings—and, to his shock, Kousaka agrees to be his girlfriend!  However, he finds that Kousaka is a bit stranger than he first thought: this seemingly perfect girl has never been in a relationship. But even though she is inexperienced, she vows to please Shinozaki in every way she can... such as learning multiple sex positions or his fetishes. Shinozaki tries to assure her that her studies into such subjects arent necessary, but Kousaka devotes herself to making him happy in more ways than one.', 105, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11863, 'Yami Shibai 5', 2017, 13, 'TV', 79.3, 'The mysterious masked Storyteller returns to tell more twisted tales of horror. Continuing his particular style of kamishibai inspired storytelling, he now finds that his audience is an eerie crowd of young girls, who eagerly await his devilish stories.  He recounts ghostly legends involving girls of all ages: a housewife who receives a barrage of chilling phone calls; a strange girl whose flower readings are always right; a mother and daughters ominous meeting with the crow lady; and a young girl whose demands from others grow more and more outrageous with each request. Witness once again the Storytellers haunting and gripping tales, which are sure to leave one with more than just chills...', 79, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (11864, 'ACCA: 13-ku Kansatsu-ka Specials', 2017, 6, 'Special', 73.2, 'The Kingdom of Dowa is free at last of political tensions and coup détat rumors. Jean and Lotta Otus spend their days together with their best friend Niino, enjoying carefree conversations accompanied by alcohol and cigarettes. Although they look out for any potential threat to Dowa, even the administrative leaders of ACCA seem to relax in the long-awaited warmth of peace.', 63, False, 104);
