INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12009, 'Aiseki Mogol Girl', 2017, 12, 'TV', 66.3, 'The series features colorful stop-motion mascot characters made out of pipe cleaners. In Japanese, aiseki refers to the situation of sharing a table at a restaurant with a person you dont know. The show is surreal datsuryoku-kei comedy with a variety of male guest voice actors who banter with Fuyumi and Haruko at a table in the Mongol Cafe.', 99, True, 9);
