INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12068, 'Yaoguai Mingdan 2nd Season', 2017, 21, 'ONA', 98.9, 'No description available for this anime.', 78, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12069, 'Annyeong, Jeonwoochi! Dosoolrobotdaegyeoljeon', 2015, 1, 'Movie', 68.4, 'Jeon Woo-chi travels over 500 years into the year 2015 on the elevator after defeating a king who bullies his people. He meets Suk and San-cho, two kids who are masters at martial arts and they become friends. In the meantime, Jeon Woo-chis friend and rival Woo Dang-tang and the king join forces to take revenge on Jeon Woo-chi. They even make a martial arts robot.  Meanwhile, Woo-chi and his friends get trapped in a time room according to Woo Dang-tangs plan and they face danger. Their time is taken away and Jeon Woo-chi becomes a kid, losing all of his powers. The king takes this time to use the robot to bully the people.   (Source: Hancinema)', 63, True, 69);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12070, 'Sou: Uchiage Hanabi, Shita kara Miru ka? Yoko kara Miru ka?-hen', 2017, 1, 'Special', 98.1, 'A collaboration between the Lotte brand ice-cream Sou and the film Uchiage Hanabi, Shita kara Miru ka? Yoko kara Miru ka?.', 50, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12071, 'Aoi Triton', 2002, 1, 'Special', 62.4, 'Pilot movie of Umi no Triton, it was created in October 1971 for the intention of selling the series to international markets and features a more Western-style drawn Triton. The pilot was released to the public on the Umi no Triton: Original Gekijou-ban DVD release nearly 3 decades later.', 117, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12072, 'Qiang Niang', 2017, 12, 'ONA', 76.5, 'Qiang Niang mainly tells of the protagonist Carrie, who has lost her combat memories, searching for herself and the story of her final Awakening. In the years between 2025 to 2030, a world war involving the entire world has resulted in the demise of half the worlds population, and humanity has already lost control of the direction the war shall go in. In order to seize ultimate victory, war has gradually been turned into a battle without people, similar to a game. War has already become about Satellite lasers, Bomb drones, Intelligent AI, a battlefield between unmanned gun turrets and tanks... Then, there are also a group of young maidens who uses outdated firearms to engage in battle —— the Gun Girls.', 14, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12073, 'Fireball Humorous', 2017, 3, 'TV', 70.8, 'No description available for this anime.', 95, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12074, 'Yuhuwa Chingudeul', 2009, 26, 'TV', 64.2, 'The characters are species at risk of extinction who take a journey together to find new friends on other continents. The show is designed to teach children about environmental protection and preservation. The series was developed in 2007 and targeted at the global market.  (Source: AWN)', 99, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12075, 'Worlds End Umbrella', 2010, 1, 'Music', 66.8, 'Music video for Kenshi Yonezus song Worlds End Umbrella animated by Minakata Laboratory. The song was also released on his 1st album titled Hanataba to Suisou.', 26, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12076, 'Wonderland to Hitsuji no Uta', 2010, 1, 'Music', 94.3, 'Music video for Kenshi Yonezus song Wonderland to Hitsuji no Uta animated by Minakata Laboratory. The song was also released on his 2nd album titled OFFICIAL ORANGE.', 70, True, 76);
