INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12173, 'Saraba Seishun', 1975, 1, 'Music', 63.6, 'A retrospective of a long journey on a great open highway. The time spent, the people they see, the billboards they gaze upon, and the records the go through.', 60, True, 53);
