INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12209, 'Ima demo Senchou to Yobarete iru Senchou no Yoru', 1971, 1, 'Music', 89.2, 'A sea captain enjoys a nice night slumber at home. But he ponders about all the adventures hed had before finally drifting off.', 110, True, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12210, 'Shiyan Pin Jiating', 2018, 12, 'ONA', 96.7, 'Tanis, a child genius, is the youngest son of two mad scientists. His family has spent their lives withdrawn from normal society living on an isolated island, where the couple conducts experiments on Tanis siblings that result in them gaining abnormal abilities. However, this activity is put to a stop when they are caught and arrested.  Tanis is brought by government officials to a more populated island, alongside his four siblings: Snow, a dog-human hybrid; Ashise, a plant-human hybrid; Aisley, a spider-human hybrid; and Suishi, a mind-reader. Being the only one who has not been genetically modified, Tanis takes on the responsibility of adapting his siblings to society, all while trying to conceal their distinctive characteristics.', 49, True, 90);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12211, 'Na mo Nai Hana no Youni', 2000, 1, 'Music', 69.9, 'Various people take care of their pet dogs.', 90, False, 91);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12212, 'Yumehito: Yumejin', 2007, 1, 'Music', 87.5, 'A university student dreams of becoming a ballet dancer. She feels like she cant ever achieve it but goes through a period of self-reflection of what makes her happy.', 45, True, 92);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12213, 'Koinu no Blue', 1972, 1, 'Music', 98.7, 'A man plays with his puppy through the different seasons but the dog passes away. The man feels blue that he lost his best friend but doesnt regret the time he spent with it.', 77, True, 93);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12214, 'Kozou no Koushin', 1976, 1, 'Music', 62.0, 'A Japanese rendition of Henry Mancinis song Baby Elephant Walk which was originally created for the 1962 American film Hatari!.', 45, True, 94);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12215, 'Chiisana Tegami', 2000, 1, 'Music', 63.7, 'Various people try to write a small letter to those significant in their lives.', 117, True, 95);
