INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12384, 'Overlord Movie: Manner Movie', 2017, 1, 'Movie', 74.2, 'A theater manners short bundled with the recap movies BD/DVD releases. Each film had its own short with slight differences (eg. Fushisha no Ou had a smiling Shalltear but the Shikoku no Eiyuu one showed her sneering). Due to the minimal changes between the two, resulting in only a few seconds of alternative footage, MAL will reflect it as a single episode as the blunt majority was identical.', 74, True, 24);
