INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12388, 'Senki Zesshou Symphogear AXZ: Senki Zesshou Shinai Symphogear', 2017, 4, 'Special', 87.6, 'Original short episodes featuring characters in super-deformed style. Bundled with Blu-ray/DVD volumes 3 to 6 of the anime.', 49, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12389, 'Kimitachi wa Dou Ikiru ka', 2023, 1, 'Movie', 76.7, 'Miyazaki derived the films title from writer Genzaburou Yoshinos 1937 masterpiece of the same name. He added that this book is a story that has great meaning to the protagonist of his film. Yoshinos book centers around a man named Koperu and his uncle, and through Koperus spiritual growth, it discusses how to live as human beings.   (source: ANN)', 43, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12390, 'Ari to Kaeru', 1935, 1, 'Movie', 98.0, 'No description available for this anime.', 57, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12391, 'Shingeki no Kyojin Season 2 Movie: Kakusei no Houkou', 2018, 1, 'Movie', 91.5, 'Eren Yeager and others of the 104th Training Corps have just begun to become full members of the Survey Corps. As they ready themselves to face the Titans once again, their preparations are interrupted by the invasion of Wall Rose—but all is not as it seems as more mysteries are unraveled. As the Survey Corps races to save the wall, they uncover more about the invading Titans and the dark secrets of their own members.', 86, False, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12392, 'Free! Dive to the Future', 2018, 12, 'TV', 90.7, 'With the seniors having graduated from high school, the determined swimmers eagerly take on their futures with a dream to fulfill.   Now attending Hidaka University in Tokyo, Haruka Nanase unexpectedly runs into Shiina Asahi, an old teammate and friend from his middle school days. Consequently, the troubling memories regarding his middle school swim team resurface, as it was a time when Harukas views on swimming became negative and led him to quit the team. Haruka later reconnects with his other middle school classmates; all except for Ikuya Kirishima, who still resents Haruka for quitting the team, resulting in its disbandment. Aware of the issues between them, Haruka resolves to improve his friendship with Ikuya. However, he quickly realizes that making amends with an old friend isnt his only obstacle.   Facing the reality and challenges of encountering higher calibre swimmers, Haruka must work hard to establish himself if he dreams of competing on an international level.', 26, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12393, 'Yuuwaku★Office Lover 2', 2017, 10, 'ONA', 88.7, 'Working at an advertising agency, you suddenly become in charge of a new CM project. For an inaugural party, you had help from your friends to turn into a beauty from your normal homely office look. There you met an attractive man who saves you from falling down. But you find out hes the new hateful company president and hes set his eyes on you as prey!', 57, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12394, 'Mighty Thor: Battle Royale', 2017, 1, 'ONA', 86.1, 'In an alternate Azeroth, Thor and Loki have decidedly more Japanese names and face Ohera-sans (Hela) destructive wrath in what looks like ancient Japan. In reality, its a silly short to promote the release of Thor: Ragnarok, titled Mighty Thor: Battle Royale in Japan.   (Source: ANN)', 50, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12395, 'Hashire! Osomatsu-san', 2016, 3, 'Special', 91.1, 'TV collaboration commercials between JRA (Japanese Racing Association) and Osomatsu-san. The first episode promotes the G1 Series. The second episode promotes the Japan Cup. And the third episode promotes the Grand Prix.', 16, False, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12396, 'Ponkotsu Quest x Digimon Story: Cyber Sleuth - Hackers Memory', 2017, 1, 'ONA', 66.3, 'A collaboration between Ponkotsu Quest and the video game Digimon Story: Cyber Sleuth - Hackers Memory for the latters release on December 14, 2017.', 74, True, 36);
