INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12435, 'Joutoku', 2012, 1, 'Music', 95.7, 'Music video for Mr. Childrens song Joutoku.', 55, False, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12436, 'Baito-saki wa Aku no Soshiki!?', 2017, 10, 'ONA', 61.5, 'Arihisa Aokura needs money. He needs money in order to support his family of orphans and earn a living at the same time. Looking online for potential employees, he finds a posting for a part time job in an evil organization. Seeing that the pay and benefits were fairly substantial, he took the chance and took the interview. He was somehow hired and now has to work as a henchman inside the evil organization Antares. Will he be able to survive the onslaught of missions against heroes while providing for his orphan brothers and sisters?  (Source: MangaHelpers)', 37, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12437, 'Star Wars/Saigo no Jedai: Tokubetsu Eizou', 2017, 1, 'ONA', 91.1, 'A promotional video for Star Wars: The Last Jedi, titled Star Wars: Saigo no Jedai in Japan. The video re-imagines the Star Wars cast in BB-8s cute design and recaps the events of the previous film Star Wars: The Force Awakens, titled Star Wars: Force no Kakusei in Japan.', 36, True, 77);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12438, 'Wo Shi Jiang Xiaobai', 2017, 12, 'ONA', 61.6, 'Ten years ago, Jiang Xiaobai lost all his memories due to a traumatic event he no longer remembers. Now working as a trainee in Editorial Office No.2 of Wen Zheng Magazine, a literary periodical based in Chongqing, he is excited to begin a new chapter of his life: in two days, he finishes his probationary period and officially starts his job as an editor. He gives no thought to his recurring dream of a girl whose face can never clearly see.  That evening, one of Jiang Xiaobais seniors passes him the task of rushing to the airport to escort the idiosyncratic rising author Tong Li, who has returned from America to launch her first serialized novel in Chinese. As punishment for this senior reneging on his own duties, Jiang Xiaobai replaces him as Tong Lis new editor. Though they get off to a rough start, Tong Li soon recognizes Jiang Xiaobai as someone precious from her high school days. Before they know it, the wheels of fate are set in motion, as Jiang Xiaobai slowly uncovers clues about a long-forgotten girl from his past.', 37, True, 78);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12439, 'Utawarerumono: Tusukuru-koujo no Karei Naru Hibi', 2018, 1, 'OVA', 81.5, 'Included with the premium collection release of the PS4 remake of Utawarerumono: Chiriyukumono e no Komoriuta. The anime will tell the story of Kuons childhood days.   (Source: ANN)', 36, True, 79);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12440, 'Kando≠Reduction', 2012, 1, 'Music', 78.3, 'A music video for Aki Akanes song Kando≠Reduction', 80, True, 80);
