INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12456, 'Servamp Movie: Alice in the Garden', 2018, 1, 'Movie', 96.7, 'The Servamps and their pact-bound Eves are finally getting back to their normal lives as they recover from their injuries from the previous battles. However, when it starts snowing in the middle of summer, one of the Eves, Mahiru Shirota, suspects vampiric interference. Concerned by the strange phenomenon, he sets out to gather the group once more to try and solve the mystery; however, they suddenly lose contact with Misono Arisuin, the Eve of the Servamp of Lust.  Servamp Movie: Alice in the Garden delves into the untold past of Misono and his brother Mikuni Arisuin, as well as the many mysteries of the grand Arisuin Mansion.', 18, True, 96);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12457, 'Lala-chan Santa no Fantasy Christmas', 2017, 1, 'Music', 92.5, 'A Christmas song done by the cast of Lalala Lala-chan for everyone to sing-a-long and dance to.', 99, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12458, 'Kirara Fantasia', 2017, 13, 'ONA', 81.0, 'Kirara Fantasia is a mobile fantasy RPG using characters from the manga magazines under the Manga Time Kirara brand. Animated advertisements and promotions were made for the game and streamed on Aniplexs official YouTube channel.', 48, True, 98);
