INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (12677, 'Arigatou', 1995, 1, 'Music', 76.0, 'A Minna no Uta music video sung by Keiko Utsumi and animated by Nanke Kouji. It has no relation to the Minna no Uta music video from 2010 which shares the name name.', 22, True, 77);
