INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13812, 'Yuuki no Hana ga Hiraku Toki: Yanase Takashi to Anpanman no Monogatari', 2019, 1, 'Special', 81.4, 'A biographical anime about Sore Ike! Anpanman creator Takashi Yanase, based on Kumiko Kakehashis novel of the same name, and celebrates what would have been the 100th birthday of the manga creator.', 38, True, 12);
