INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13939, 'Dash! Yonkurou: Horizon Gundan vs. Dash Gundan', 1990, 1, 'Special', 89.6, 'A TV Special of Dash! Yonkurou that aired 4 months after the TV anime ended.  Because the Dash Warriors won against Oomiyas senior citizen team the Silver Warriors, they travel to the Amazon in Brazil to try out his natural tracks that he built. When the arrive they find the natural track has been destroyed by a storm when they are suddenly attacked by the Amazon Warriors. One of the boys has Horizon, an original Mini 4WD created by Yonkurous father who disappeared.', 100, True, 19);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13940, 'Genji Fantasy: Neko ga Hikaru Genji ni Koi wo Shita', 2019, 1, 'Special', 77.8, 'The Tale of Genji Museum in Uji City, Kyoto will be airing a short film blending history and fantasy, the story follows a modern high school girl named Hana who is transformed into a cat and transported back in time. She travels 1,000 years ago to the Heian Era as portrayed in The Tale Of Genji, arguably the most famous novel in Japanese literature. Guided by the novels titular character Hikaru Genji, Hana experiences firsthand the emotions that the author Murasaki Shikibu depicted in her novel. The short features scenes based on The Diary of Lady Murasaki and other historical materials, such as the real-life noble Fujiwara no Michinaga swiping early drafts of The Tale Of Genji because he could not wait to read chapters as Murasaki wrote them.   (Source: ANN)', 88, True, 20);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13941, 'Channeler', 2012, 1, 'Movie', 77.4, 'Abstract animated short film by Takashi Ohashi, visually syncing Japanese hip-hop with with a variety of symbols and shapes.', 113, True, 21);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13942, 'Dragon Quest: Your Story', 2019, 1, 'Movie', 60.2, 'Following in his fathers footsteps, Luca must find the hero who wields the zenithian sword to save his mother from Ladja. Based on Dragon Quest V: Hand of the Heavenly Bride games story.  (Source: Apple TV)', 41, True, 22);
