INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13944, 'Youkai Watch!', 2019, 36, 'TV', 85.2, 'A new season of Youkai Watch focusing on elementary schooler Keita Amano again. The events take place right after the original season; but still chronologically occur before the now complete Shadow Side events as they take place 30 years in the future.', 85, True, 24);
