INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13951, 'Anger', 2008, 1, 'Music', 96.4, 'This is the first original VOCALOID song by Tripshots. The WIP version without PV was uploaded on December 12, 2007 on Nicovideo. The full version was released some five months later.  (Source: Vocaloid Wiki)', 63, True, 31);
