INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (13962, 'Kyonshii Kyonta no Koutsuu Anzen', 1985, 1, 'OVA', 97.0, 'A traffic safety film starring a kyonshii, known as a Chinese hopping vampire/zombie (natively called jianshi in Chinese but kyonshii in Japan). Kyonshii horror films were popular in the late 80s.', 41, True, 42);
