INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14273, 'Kappa no Kui Kuo Kua', 1975, 1, 'Music', 99.3, 'Music video for the song Kappa no Kui Kuo Kua by Japanese vocal group Duke Aces and actress Nobue Ichitani that was featured on NHKs Minna no Uta program. The video was animated by Yoji Kuri.  The video aired in 1975, but was considered lost media some time later. It was recovered thanks to the Minna no Uta Hakkutsu Project.', 105, True, 113);
