INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14382, 'Sinbi Apateu: Ghost Ball X-ui Tansaeng', 2017, 23, 'TV', 95.6, 'With help from a 102-year-old goblin dwelling beneath their haunted apartment building, two siblings deal with ghosts and take on spooky mysteries.', 96, False, 102);
