INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14501, 'Taka no Tsume-dan x Uchicomi!', 2019, 5, 'ONA', 99.5, 'A collaboration between Eagle Talon and Uchicomi the real estate company. Eagle Talon informs various people about Uchicomis app and easy ways for them to find housing meeting their specific requirements. Episodes were streamed on Uchicomis official YouTube channel and later, a compilation of all of them, were posted to DLEs official YouTube channel.', 71, True, 101);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14502, 'Baumkuchen End', 2019, 1, 'Music', 69.4, 'Official music video for Eves song Baumkuchen End made in collaboration with Space Shower TV as it is the stations 30th anniversary. The music video will also be used in part as a Station ID.', 48, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14503, 'Shounen Sunday CM: Devil & Devil', 1998, 1, 'Special', 70.5, 'Devil &amp; Devil commercial for Shounen Sunday magazine.', 15, True, 103);
