INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14696, 'Obentou Bako no Uta: Anata e no Otegami', 2017, 1, 'Music', 73.3, 'Music video for the song Obentou Bako no Uta: Anata e no Otegami by Yoshiko Hanzaki that was featured on NHKs Minna no Uta program. It was later included on DVD with the release of her first major single after her professional debut titled Sakura: Sotsugyou Dekinakatta Kimi e. The video was animated by Toshiaki Hanzaki.', 44, True, 56);
