INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14704, 'Life Size', 2011, 1, 'Music', 83.2, 'MMD music video for the song Life size by 40mP, featuring the mascot character CUL using the VY1 voicebank. This version of the song was used as the opening for the VOCALO Revolution television program that aired in Japan on January, 2011. The original version of the song was included on 40mPs first album Life Size Note and featured vocals by Hatsune Miku.', 44, True, 64);
