INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14707, 'Monster Musume no Oishasan', 2020, 12, 'TV', 93.9, 'After years of conflict, humans and monsters have settled their differences and are now at peace. This post-war era led to the foundation of Lindworm—a town which has since become the focal point of racial harmony.  As a human doctor specializing in monster biology, Glenn Litbeit runs a small clinic alongside his partner, Saphentite Neikes, who is a half-snake monster known as a lamia. He uses his knowledge to tend to any monsters who seek his aid. Whatever affliction, concern, or injury it may be, he will always be there, ready to help.', 111, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14708, 'Iiwake Love Song', 2011, 1, 'Music', 83.9, 'MMD music video for the song Iiwake Love Song by Vocaloid composer Noah, featuring Hatsune Miku. It was included as the title track for the album distributed by 2D M3NTiON on their website, featuring various remixes of the song.', 96, True, 68);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14709, 'Distorted Princess', 2011, 1, 'Music', 70.7, 'MMD music video for the song Distorted Princess by Hachioji-P, featuring Hatsune Miku and Megurine Luka. The song was included on his first album Electric Love.', 98, True, 69);
