INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14743, 'Keishichou Tokumubu Tokushu Kyouakuhan Taisakushitsu Dainanaka: Tokunana OVA', 2020, 1, 'OVA', 96.9, 'The OVA will be focus on when Kujaku Nijou first entering group, which occurs one year before the main anime begins.', 90, True, 103);
