INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14866, 'Duel Masters Zero: Tokubetsu-hen - Tamashii Shoukan Special!', 2008, 1, 'Special', 65.1, 'The 25th episode of Duel Masters Zero, it acted as a side-story recap episode going over the seasons hottest duels.', 40, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14867, 'Mousou Kanshou Daishou Renmei feat. Hatsune Miku', 2016, 1, 'Music', 72.2, 'No description available for this anime.', 84, True, 107);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14868, 'Negative Shinkaron feat. Hatsune Miku', 2019, 1, 'Music', 73.2, 'No description available for this anime.', 44, True, 108);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14869, 'Fumetsu no Anata e', 2021, 20, 'TV', 83.3, 'An Orb, known only as It, is cast to Earth to be observed from afar. Capable of changing forms from beings whose reflections It captures, It first becomes a rock and then, due to the rising temperature, moss.  It does not move until one snowy day, a wolf at deaths door barely crosses by. When It takes the animals form, It attains awareness of its consciousness and starts to wander with an unclear destination in mind. Soon, It comes across the wolfs master—a young boy waiting for his tribe to return from a paradise abundant with fish and fruit in the south. Although the boy is lonely, he still hopes those whom he holds dear in his memories have not forgotten him and that he will reunite with them one day.  The boy wants to explore new surroundings and decides to abandon his home with It to find the paradise using the traces his tribe left behind. However, with a heavily injured body and no sight of his elder comrades, what will become of the boy?  Fumetsu no Anata e illustrates the story of an immortal being experiencing humanity, meeting all types of people in many places throughout time.', 72, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14870, 'Kaiketsu Zorori no Kyoufu no Hanayome Sakusen', 2002, 1, 'OVA', 66.7, 'CG pilot film produced in 2002. It was given a limited VHS release.', 86, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14871, 'Sore Ike! Anpanman: Fuwa Fuwa Fuwaly to Kumo no Kuni', 2021, 1, 'Movie', 75.9, 'Anpanman, his friends, and the cloud child Fuwari strive to save Cloud Country. In order for flowers and plants to be healthy, Cloud Country travels to distribute clouds that can make rain and rainbows to various towns and stars. A cloud baby born in Cloud Country runs across Baikinman and his friends. After meeting them, the baby gets the name Fuwari and quickly grows while developing a bond with Dokin-chan.  (Source: ANN)', 88, True, 111);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14872, 'Amrita no Kyouen', 2023, 1, 'Movie', 76.9, 'On their way home from high school, Tamahi and some classmates are shocked as they witness someone fall from the rooftop of nearby apartment. Panicked and confused, they rush to the building only to find it deserted. As Tamahi wonders about this, she has the uneasy feeling they are being watched. What is the strange presence around her...  (Source: HIDIVE)', 35, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14873, 'Evangelion Shito, Hakata Shuurai', 2019, 1, 'Movie', 97.6, 'When the Fourth Angel attacks Shin Fukuoka City, its up to Shinji Ikari and his friends Asuka Langley Soryu, Rei Ayanami, and Mari Illustrious Makinami to stop it through any means necessary.', 108, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14874, 'Umiyuri Kaiteitan', 2017, 1, 'Music', 88.6, 'No description available for this anime.', 20, False, 114);
