INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14876, 'Melty Land Nightmare', 2018, 1, 'Music', 66.8, 'The song is about a girl (blue) who has dreams of Melty Land. Blue is lonely and sad, and Pink exists to make Blue happier. The forks and dinnertime represent Blue consuming her dreams. Thats her way of coping with the mean things her classmates and mom might say. At the end, Blue stops relying on Pink, so they disappear.', 35, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (14877, 'Vanilla', 2019, 1, 'Music', 82.4, 'To coinside with Sachiko Aoyamas first solo EP Maboroshi, a music video featuring the song Vanilla was released onto YouTube.', 100, False, 117);
