INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15193, '365-nichi no Love Song', 2011, 1, 'Music', 90.1, 'Music video for the song 365-nichi no Love Song by Japanese singer-songwriter Mayo Okamoto that was featured on BS Fujis Be Ponkickies (P-kies) program as part of the Be Pon Melody segment (P-kies Melody). The video was animated by Kouji Nanke. It was also posted on Crown Records YouTube channel a year later to promote Okamotos eleventh studio album Tomorrow that released March 7, 2012.', 117, True, 73);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15194, 'An Instant', 2003, 1, 'Movie', 78.0, 'Azuru Isshiki’s animated short An Instant, pares the art of animation down to its essentials: A series of images drawn in paint on paper. It begins and ends with a small dot, but in-between Isshiki explores the full range of expression possible with just simple animation tools. The film consists of just black and red paint on a variety of different papers. Dots, lines, and spirals dance across the screen, as does a cheerful female figure.  (Source: Nishikata Film Review)', 34, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15195, 'Koukaku Kidoutai: SAC_2045 Season 2', 2022, 12, 'ONA', 91.3, 'Second season of Koukaku Kidoutai: SAC_2045.', 41, True, 75);
