INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15208, 'BanG Dream! Movie: Poppin Dream!', 2022, 1, 'Movie', 70.8, 'Bands... are always making me dream.  PoppinParty, Roselia, and RAISE A SUILENs successful concert at the Budokan has passed. Kasumi and the others, who have left a lingering sound on the stage of their dreams, are approached by a mysterious woman. Their next stage is overseas?!  PoppinPartys music isnt stopping yet!  (Source: BanG Dream! Wiki)', 98, False, 88);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15209, 'Iwa Kakeru! Sport Climbing Girls', 2020, 12, 'TV', 75.5, 'Video games, especially puzzle games, were always at the center of Konomi Kasaharas life. However, upon entering Hanamiya High School, she decides to break away from this lifestyle. As Konomi wanders the halls in search of a new activity to engage herself in, she stumbles upon a gigantic wall owned by the schools rock climbing team. Fascinated, she attempts to scale the wall, discovering that she can use her puzzle-solving skills to help her reach the top.  Certain that she has found her calling, Konomi immediately joins the club. As she strives to improve her climbing skills, Konomi, alongside the rest of the Hanamiya Climbing Team, will learn what it truly means to be a sports climber and work to achieve victory in the upcoming competitions.', 47, True, 89);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15210, 'Ze Tian Ji 5th Season', 2020, 12, 'ONA', 98.7, 'The fifth season of Ze Tian Ji.', 109, True, 90);
