INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15248, 'Kizuna (2014)', 2014, 1, 'Music', 87.5, 'A story passed on is a living memorial. In eternal remembrance of March 11, 2011.  (Source: Official Website)', 100, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15249, 'Shuumatsu no Harem', 2022, 11, 'TV', 64.3, 'Reito Mizuhara is a medical student at the National Advanced Medical School in Tokyo who contracts a rare, lethal disease called cellular sclerosis. In order to be treated, he is put into cryogenic sleep for five years. Upon awakening, he learns that a year into his slumber, a worldwide pandemic broke out, caused by the novel Male Killer (MK) virus which exclusively afflicts males and has killed all other men on Earth.   Fortunately, Reito and four other men were spared during their cryosleep and are now immune to the virus. As the only men left in the world, they are thus tasked with mating with as many women as possible to repopulate the planet. However, Reito is committed to his childhood friend and sole love interest, Elisa Tachibana—only to learn that she went missing three years ago. While the other male survivors adapt accordingly to this new world, Reito instead chooses to pursue Elisa, fight never-ending temptation, and investigate this mysterious virus.', 98, True, 9);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15250, 'Mukashi Keibanashi 2nd Season', 2020, 4, 'TV', 80.5, 'Second season of Mukashi Keibanashi.', 114, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15251, 'Chanbara Johnny', 2015, 1, 'Music', 67.2, 'Music video for the song Chanbara Johnny from DECO*27.', 108, True, 11);
