INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15342, 'Princess Aya', 2019, 1, 'Movie', 72.0, 'Princess Aya of the Sabi Kingdom has a curse that transforms her into wild animals. The only thing that can stop the morphing is her mothers priceless amulet. When her home comes under siege, her father the King creates an alliance with the Kingdom of Vatar by marrying Aya off to Prince Bari. En route to Vatar, her convoy is attacked by a magical beast and Ayas amulet is stolen. The Princess must try with all her might to both conceal her secret and to find out who wants to stop the union of Kingdoms.  Source: (letterboxd.com)', 22, True, 102);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15343, 'Ani ni Tsukeru Kusuri wa Nai! 4', 2020, 12, 'TV', 74.5, 'Shi Miao has a lot of experience dealing with her older brothers peculiar habits. After all her scolding, it is natural to expect that Shi Fens antics would come to an end. But having spent their whole life together, it is obvious to Miao that some things never change—and maybe that is for the best.  Despite his recklessness, Fen usually means well. As a result, a tight-knit friend group has formed around him and his sister. Joined by their classmates—Kai Xin, Wan Sui, and Miaomiao—the Shi siblings tenure at high school continues to be an absolute spectacle.', 28, True, 103);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15344, 'Refrain', 1993, 1, 'OVA', 80.1, 'An educational short film about paint thinner abuse. It was directed by Umanosuke Iida.', 30, True, 104);
