INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15353, 'Ninja Collection', 2020, 13, 'TV', 92.4, 'Set in modern-day Tokyo where dreams and desires are afloat, a group of ninjas called Toukeshuu is set to stop the spread of darkness that prevails in the world using ancient techniques passed down through generations.  (Source: MAL News)', 108, True, 113);
