INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15401, 'Senpai ga Uzai Kouhai no Hanashi', 2021, 12, 'TV', 69.6, 'At a certain trading company, saleswoman Futaba Igarashi has managed to hold her respectable job for almost two years thanks to the guidance of her senior coworker—Harumi Takeda. However, due to Igarashis short stature, Takeda often teases her and treats her like a kid, leaving Igarashi constantly annoyed by his antics.  Despite this, Igarashi notices Takedas reliability as he is always ready to help whenever something at their workplace goes awry. As Igarashi and Takeda spend more time together, their relationship soon develops further than simply being coworkers at the office.', 112, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15402, 'Fusuma no Oku', 2012, 1, 'Movie', 90.8, 'The theme came from the Japanese unique folklore, Red Uncleanness or defilement with blood. A girl, whose thinking pattern jumps at a leap without any train of thought, confines her various thoughts in the other side of the mirror and inside the sliding doors to go outside.  (Source: Geidai Animation)', 34, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15403, 'Dai 13-kai Indies Anime Festa OP', 2015, 1, 'Special', 83.5, 'An original opening animation by Takashi Taniguchi for the 13th Indie Anime Festa, held in Mitaka, Tokyo.', 82, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15404, 'Real Koke-kun', 2013, 1, 'ONA', 96.9, 'KOKE-kun is a merchandise franchise of eight cartoon characters that each represent a real species of moss. To promote the brand, the Real Koke-kun initiative was born, where flash mobs dressed as the main green moss character would appear around Japan. During this time, an animated version of Real Koke-kun was created by Takashi Taniguchi.', 56, False, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15405, 'Zhen Hun Jie: Bei Luo Shi Men Pian Part 2', 2021, 7, 'ONA', 69.4, 'Second half of Zhen Hun Jie: Bei Luo Shi Men Pian.', 86, True, 45);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15406, 'Ijiranaide, Nagatoro-san', 2021, 12, 'TV', 88.2, 'Every day, Naoto Hachiouji is teased relentlessly by Hayase Nagatoro, a first year student he meets one day in the library while working on his manga. After reading his story and seeing his awkward demeanor, she decides from that moment on to toy with him, even calling him Senpai in lieu of using his real name.  At first, Nagatoros relentless antics are more bothersome than anything and leave him feeling embarrassed, as he is forced to cater to her whims. However, as they spend more time together, a strange sort of friendship develops between them, and Naoto finds that life with Nagatoro can even be fun. But one things for sure: his days will never be dull again.', 35, False, 46);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15407, 'Re:Zero kara Hajimeru Break Time 2nd Season', 2020, 25, 'Special', 77.3, 'Afraid that his life may end at any moment, Otto Suwen begins writing a diary documenting all of his experiences. Now part of Subaru Natsukis eccentric band of colorful characters, the apprehensive merchant is certain that new dangers lie ahead in their mission at Sanctuary. But amid the rising tensions, there are still moments of respite and reflection, ripe with opportunities to make vivid memories.', 119, True, 47);
