INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15414, 'Yuki no Furu Machi', 2012, 1, 'Music', 92.8, 'Stop motion music video for the song Yuki no Furu Machi by Aimer that was on her third maxi single. The music video was directed by Go Matsuda and Masakazu Fukatsu.', 37, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15415, 'Hataraku Saibou!! Saikyou no Teki, Futatabi. Karada no Naka wa Chou Oosawagi!', 2020, 1, 'Movie', 64.7, 'Ippan Saibou is envious of the public praise immune system cells like white blood cells receive for protecting the human body from deadly pathogens. Instead of watching safely from his home, he also wants to be useful and get recognized for his efforts. He soon comes across a group of infantile-looking bacteria getting washed away by a river current. Despite knowing the potential dangers that they hold, he rescues the bacteria and brings them to safety. However, Hakkekkyuu U-1146 picks up the presence of these bacteria and is on the hunt for them.  Meanwhile, somewhere else in the human body is NK Saibou, who is on the lookout for someone. Based on her intel, he is an antigen that the immune system cells have previously encountered, and he may have returned for revenge.', 116, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15416, 'Uracon III Opening Animation', 1984, 1, 'Special', 65.6, 'The animation was independently produced by Shinji Aramaki and his manga club during their time at Okayama University. The animation premiered at the URACON III sci-fi convention in 1984.', 44, True, 56);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15417, 'Osomatsu-san 3rd Season', 2020, 25, 'TV', 93.1, 'Third season of Osomatsu-san.', 11, True, 57);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15418, 'Grisaia: Phantom Trigger The Animation - Stargazer', 2020, 1, 'Movie', 71.4, 'While Rena and Maki recover from their injuries, the other SORD members jet off overseas for a school trip. Within moments of their arrival, though, the Mihama gang are pulled into a manhunt for a SORD deserter, assisted by student Sylvia and Velvet of St. Ailes International School. Tohkas the star of the show this time round, but shes wrestling with her own issues - old memories of her parents, and a promise to a friend that she wasnt able to keep...  (Source: Frontwing)', 103, False, 58);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15419, 'Shakunetsu Kabaddi', 2021, 12, 'TV', 84.6, 'Tatsuya Yoigoshi, a once nationally recognized soccer player, is now a first-year student at Noukin High School. Due to his developed hatred for sports, he has abandoned his previous aspirations to become a famous livestreamer on the internet. One day, Souma Azemichi, a first-year on the kabaddi team, seeks to recruit Yoigoshi and spontaneously interrupts his livestream.  Without any expectations, Yoigoshi follows Souma to the school gym, where he witnesses second-years Kyouhei Misumi and Shinji Date engaged in the primal contact sport of kabaddi. Despite ridiculing the rules of play, Yoigoshi is stunned by the intensity of the round. Because of an enticing deal and slight coercion, he agrees to settle the prospect of his recruitment through the most invigorating way: a battle of kabbadi, a team sport played empty-handed.', 28, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15420, 'Benkai to Ushiwakamaru', 1999, 1, 'Movie', 95.3, 'This is the story of the extraordinary Benkei, who after having met his enemy Yoshitsune in his childhood (then named Ushiwaka) came to guard him as a lifetime partner in later years.', 98, True, 60);
