INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15457, 'Iikaereba', 2015, 1, 'Music', 73.6, 'A minimalist animated lyric video for the song Iikaereba by Japanese music unit Every Little Thing on their 46th single ANATA TO.', 104, True, 97);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15458, 'Tsumamareru Koma', 2010, 1, 'Movie', 79.2, 'Almost everyone in our contemporary society is picked up and moved around by someone or something, like in a game of Sugoroku. Those who first do so are our parents.   We follow a boy who grows up along on Sugoroku board, during which he depends on his parents. His family play the parts of roles in the game - his father rolling the die, and his mother picking him up and placing him he passively goes about his way. But for how long will he let this continue?  (Source: YouTube)', 82, True, 98);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15459, 'Miao Xiansheng', 2020, 1, 'Movie', 76.5, 'Adapted from a short tale from self-made animator Bu Sifan, writer and director of Dahufa, the feature introduces a fictional golden-colored flower, which possesses the magical ability to debauch humans who get too close to it.  As the flower only chooses kindhearted people as hosts, a group of martial artists who want to eradicate the plants face a dilemma: Should one kill good people for rescuing men from sin?  (Source: China Daily)', 75, True, 99);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15460, 'Shadowverse Recaps', 2020, 3, 'Special', 87.4, 'Recap episodes of Shadowverse.', 56, True, 100);
