INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15555, 'Love Live! μs Go→Go! LoveLive! 2015: Dream Sensation!', 2015, 4, 'Special', 65.7, 'Love Live! μs Go→Go! LoveLive! 2015: Dream Sensation! is a DVD/Blu-Ray disc of μs live concert that took place in Saitama Super Arena on January 31st and February 1st, 2015. It was released on September 30, 2015.  Includes four Intermission Drama anime specials shown on both days of the concert.  (Source: Love Live! Wiki)', 119, True, 75);
