INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15595, 'Tales of Crestoria: Toga Waga wo Shoite Kare wa Tatsu', 2020, 1, 'Special', 61.0, 'Short animated TV special depicting the prologue of the main story of TALES OF CRESTORIA, showing Kanata and Misella setting off on their journey.', 48, True, 115);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15596, 'Miao Qiansui de Chengnian Li', 2020, 7, 'ONA', 76.3, 'Sanwei Mountain is home to an ancient civilization, where Miao Qiansui and her sister Nuluo live. Miao Qiansui is an innocent little girl, full of curiosity about the outside world. In her memory, there has always been a mysterious place called Moon Lake. But is the Moon Lake real? Can she go to Moon Lake smoothly?  (Source: bilibili, translated)', 77, True, 116);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15597, 'Renwu Dashi', 2020, 6, 'ONA', 68.1, 'This is an adventure story about Ah Shu and Ah Lang. Ah Shu is the executor of the mission, and Ah Lang is the intermediary of the Task Association, specifically looking for tasks for Ah Rat. While the two were constantly completing various difficult tasks, Ah Shu revealed his yearning for something indescribable – The Sea of \u200b\u200bStars; while Ah Lang was also looking for clues to the disappearance of the family during various tasks. The two learned from the mission that in addition to the present world, there is an upper world, and various signs indicate that Ah Shus yearning and the clues Ah Lang is looking for point directly to the upper world, even more upper world.  Through their continuous adventures, they gradually learned that no matter which world, they cannot escape the fate of the tipping point of entropy.  (Source: bilibili, translated)', 21, True, 117);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15598, 'This Is Not Blue', 2020, 1, 'Movie', 97.4, 'An experimental film by mareykrap about the color blue. Blue pigment in the natural world is very rare. Instead, what we typically observe is the reflection of blue light waves. How much true blue really exists in our world? A series of blue images. Or are they?', 88, True, 118);
