INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15607, 'Ai no Utagoe wo Kikasete', 2021, 1, 'Movie', 83.9, 'Satomi Amano is a model student as well as the daughter of the leading project manager of Hoshima, a company that has revolutionized AI technology. However, due to her standing, Satomis presence has isolated her from her classmates—an obstacle she knows she may never overcome.  On an otherwise uneventful day, while preparing for school, Satomi uncovers her mothers latest exciting proposition: an AI that will prove whether robots can live alongside humans. Intrigued by how her mother will commence the project, Satomi makes her way to school, but standing in front of the class is none other than the AI herself.  As the subject of research, Shion Ashimori is tasked to fit in like a normal teenage girl without exposing her true identity. However, Shion has another goal in mind—to make Satomi happy instead. With her talent for singing, Shion strives to compose harmonious melodies that not only connect her with her newfound friends but also dispel the dissonance within Satomis heart.', 12, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15608, 'Little Village People', 2008, 15, 'TV', 68.4, 'Set in Penguin Village Hills, one of the most boring towns in the world in a certain region, it depicts how unique young people are involved in daily events and events. While Penguin Village Hills Cable TVs popular TV show 24-hour, 365-day TV hosted by Thunder Paper Bags flows through the city, various incidents (both serious and non-critical) occur.', 111, True, 8);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15609, 'Kotobadori', 2019, 1, 'Music', 76.0, 'Music video for the song Kotobadori by Tomoyo Harada that was featured on NHKs Minna no Uta program. The video was animated by Masahiro Okano.', 30, True, 9);
