INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15669, 'Furusato (2013)', 2013, 1, 'Music', 78.7, 'Music video for the song Furusato by Japanese boy band Arashi that was featured on NHKs Minna no Uta program. The song was revealed in 2010 at the 61st NHK Kouhaku Uta Gassen and has been featured in a variety of programs since. The video was animated by Osamu Sakai, with character designs from Ichio Ootsuka.', 110, True, 69);
