INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15709, 'Wo Zhidao', 1956, 1, 'Movie', 69.7, 'The little rabbit was playing hiding and seek with its mother, but the mother worried that the little rabbit would meet a wolf. The mother sang a song that described what a wolf looks like, and mimicked a wolf. The little replied, I know, I know, despite having never seen a wolf before. The story follows the little rabbit encountering other animals and judging them to be a wolf or not by comparing them to the description from the song.', 97, True, 109);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15710, 'Jizhi de Shanyang', 1956, 1, 'Movie', 83.0, 'A puppet stop motion animation adapted from a Chinese folk tale about a witty goat who hides in a cave from a tiger. The goat lies to the tiger that it is the king of the mountain and eats tigers, scaring the tiger off. The tiger meets a fox at the bottom of the mountain and tells the fox what happened. The fox laughs and says that the tiger had been tricked by a goat.', 99, True, 110);
