INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15775, 'Dan Zhu Chuan Shuo', 2010, 52, 'TV', 82.3, 'Pinball Legend is a cartoon TV show on CCTV Shaoer Channel. It is based on five protagonists named Hai Xiaomei, Duo Jieke, Ouyang Xiaofeng, Lei Huo, and Da Li. They fight a vampire ghost named Earl using Holy Pinball Fighters. There are 52 episodes, each episode running at 22 minutes long, including the opening theme and the ending theme.  (Source: Wikipedia)', 12, True, 55);
