INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15848, 'Feather (Overdrive Version)', 2016, 1, 'Music', 82.4, 'Music video by Tarafu Otani for feather (overdrive version) by Japanese electronic artist Serph from his album PLUS ULTRA. The video was produced for Serphs 2016 music video contest featuring this song. The contest received around fifty applicants, and Otanis submission was selected as Grand Prix winner. It was subsequently posted on the offical Nobel music label YouTube channel as an official music video.', 59, False, 8);
