INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15866, 'Citrus (Music)', 2020, 1, 'Music', 90.3, 'Music video by Tarafu Otani for the single Citrus by Japanese electronic artist Serph that is included on his compilation album Nanotech Wizard.', 94, True, 26);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15867, 'Yubi no Sukima-chan', 2009, 1, 'Movie', 71.9, 'An experimental film by Tarafu Otani about hands.', 75, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15868, 'Youkina Fuukei-tachi', 2015, 1, 'Movie', 87.6, 'An experimental film created from 3 years worth of abstract pencil drawings with the goal of being a catalyst for unveiling a new mental landscape in viewers.', 86, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15869, 'Matierica', 2017, 1, 'Movie', 68.2, 'A daring film that pierces through the hearts of viewers by discarding the charming characters, interesting stories, beautiful drawings, fluid movement and pleasing music associated with anime, while remaining firmly in the medium of animation.', 37, False, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15870, 'Yamakawa Keiko-san wa Furimukanai', 2017, 1, 'Movie', 62.1, 'Man often yearns of a past more innocent and pure. This film disregards that sentimentality and depicts a constant, permanent transformation of the landscape of mountains and rivers. A beautiful and intense image poem made from thousands of pencil drawings.', 75, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15871, 'Henkei Sakuhin Dai 5-ban: Rembrandt no Shudai ni yoru Henkei Kaitai to Saikousei', 1986, 1, 'Movie', 74.1, 'The fifth entry in Kurosakas Henkei Sakuhin experimental short film series.', 37, True, 31);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15872, 'Umi no Uta', 1988, 1, 'Movie', 96.1, 'In a fishing village, a scrapped boat is cremated. Old fishing boats on the verge of death dream of deep-sea fish running through alleys, fishermen pulling their nets, the crying specter of a young girl... Various imagery appear and retreat like waves on a shore, inviting viewers into a daydream.  This poetic film garnered critical acclaim at an international scale, starting at the Oberhausen international short film festival.', 97, True, 32);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15873, 'Alice no Kisetsu', 1988, 1, 'Music', 69.0, 'Music video for the song Alice no Kisetsu by Chikaco Sawada that was featured on NHKs Minna no Uta program. The song and video animated by Tsutomu Shibayama were inspired by Alice in Wonderland.', 84, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15874, 'Mela!', 2020, 1, 'Music', 94.1, 'Music video for the song Mela! by Ryokuoushoku Shakai.  A wolf goes out at night, and rescues a girl from some sleazy pigs. They later fall in love.', 45, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15875, 'Haiiro no Saga', 2020, 1, 'Music', 80.0, 'Music video of Majo no Tabitabi ending song.  The story of a girl who wants to break free.', 51, True, 35);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15876, 'Shadows House', 2021, 13, 'TV', 89.7, 'The Shadows, characterized by their pitch-black appearance and tendency to emit soot when agitated, are a family of nobles who reside in a colossal manor deep within the mountains far from other humans. When a Shadow child is nearly of-age, they are assigned a Living Doll who acts not only as their attendant but also as their second half—the faces they could have had if not for their complexion.  Emilico is a cheerful, newly created Doll who serves a rather soft-spoken master named Kate. Despite their difference in personalities, Emilico does what she can to carry out the needs of her master. As she learns more about her role and duty, Emilico begins to meet her fellow Dolls and their respective masters and comes to know more about the purpose of her existence.  Do not fret over trivial matters, says one of the rules by which all Dolls must abide. But how could the ever-curious Emilico do so in the face of the deep secrets that the Shadows House holds?', 48, True, 36);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15877, 'Boukentai: Mori no Yuusha', 2020, 1, 'Music', 81.8, 'Music video for Chiaki Maruyamas song Boukentai: Mori no Yuusha.', 82, True, 37);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15878, 'Shiroi Spitz', 1998, 1, 'Music', 92.0, 'Music video for the song Shiroi Spitz by Japanese band Beagle Hat that was featured on NHKs Minna no Uta program. The video was animated by Taku Furukawa.', 62, True, 38);
