INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15988, 'Ookina Furudokei', 1962, 1, 'Music', 63.0, 'The original rendition of the Japanese version of the 1876 song My Grandfathers Clock by American composer and songwriter Henry Clay Work that was broadcast on NHKs Minna no Uta program. It was performed by Sumito Tachikawa and the Nagato Miho Kagekidan Jidou Gasshoudan (Miho Nagato Opera Childrens Choir) and featured artwork by Rokurou Taniuchi. Due to the copyright law of the time, price of film reels, and overwriting tapes, Ookina Furudokei from 1962 remains to be one that is missing its video tape, as such the music video is considered lost media.', 17, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15989, 'DiSCOVER THE FUTURE', 2020, 1, 'Music', 84.2, 'Official music video for IDOLiSH7’s song DiSCOVER THE FUTURE.', 68, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15990, 'Ookina Furudokei (1973)', 1973, 1, 'Music', 69.4, 'The second release of the Japanese version of the 1876 song My Grandfathers Clock by American composer and songwriter Henry Clay Work that was broadcast on NHKs Minna no Uta program. It was again performed by Sumito Tachikawa and the Nagato Miho Kagekidan Jidou Gasshoudan (Miho Nagato Opera Childrens Choir), but this time featured animation by Yoshiyuki Takeguchi.', 113, True, 30);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (15991, 'Ookina Furudokei (2002)', 2002, 1, 'Music', 65.2, 'The third release of the Japanese version of the 1876 song My Grandfathers Clock by American composer and songwriter Henry Clay Work that was broadcast on NHKs Minna no Uta program. It was performed by Ken Hirai and featured artwork by Masaki Shiota that was animated by Three-d.', 92, True, 31);
