INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (16438, 'Shallys', 2020, 1, 'Music', 83.2, 'Official 3D music video for Aki Rosenthals original song.   It is from the perspective of a half-elf singing and dancing to an otherworldly folk song, incorporating elements from fairy tails and folklore in the imagery.', 78, True, 118);
