INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18103, 'Spookiz', 2014, 26, 'ONA', 94.1, 'When night falls and the human kids from Freemont Elementary have all gone home, these wacky monsters creep out for their own slapstick adventures. Together, a vain Vampire, a happy-go-lucky Goblin, a smelly Zombie, a snuggly Frankenstein and a mischievous Ghost share a common bond and friendship in their adventures at night school.  (Source: Amazon Prime)', 99, True, 103);
