INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18110, 'Seven Knights Revolution: Eiyuu no Keishousha', 2021, 12, 'TV', 85.0, 'Seven Knights Revolution: Eiyuu no Keishousha is set in a world where eons ago valiant heroes fought against the forces of Destruction. While their deeds passed into legend, the power of these heroes was later inherited by successors who fought to protect the world. One day, Faria, a successor of the Seven Knights, saves an ordinary boy named Nemo from the forces of Destruction.  During the ensuing battle, Nemo summons the power of a hero and becomes a successor as well. However, Nemos hero is a stranger that is unknown to history, and so an epic journey where the past and present collide begins.   (Source: Crunchyroll, edited)', 31, True, 110);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18111, 'Wangzhe? Bie Nao!', 2017, 13, 'ONA', 62.9, 'No description available for this anime.', 97, True, 111);
