INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18246, 'Koi wa 1-nichi ni Shite Narazu', 2021, 1, 'ONA', 70.5, 'Mitsuki Hattori has been recklessly overworking in hopes of becoming the right-hand man to her section chief, Watanabe, one day. Having always admired him from afar, she is saddened to learn that he will soon be transferring sections. Before he leaves, Mitsuki wants Watanabe to notice how pretty she is.', 16, True, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18247, 'Ruguo Lishi Shi Yiqun Miao', 2018, 13, 'ONA', 64.9, 'When History Meows is based on the webcomic of the same name. Its based on Chinese history as the main storyline and compiled and drawn based on ancient Chinese books . It tells the history of China in various eras in a humorous and easy-to-understand way .', 62, True, 7);
