INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18249, 'Chickip Dancers', 2021, 26, 'TV', 93.7, 'TV anime based on San-Xs new series of mascot characters Chickip Dancers. The main characters in the anime will be the apprehensive but curious bone-in chicken Hone Chicken, and the dancing instructor frog Skip Gaeru, who travels by dancing.  (Source: ANN)', 42, True, 9);
