INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18778, 'Festive!', 2020, 1, 'Music', 61.7, 'A music video for one of Ensemble Stars units, MaM, of their song Festive!.', 117, True, 58);
