INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18911, 'Hare Butai', 2008, 1, 'Music', 70.3, 'An animated music video for Jeros Hare Butai single, aired on NHKs Minna no Uta.  With this video, Jero wanted to express gratitude to her grandmother, who died three years before he became famous in Japan.', 60, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18912, 'Pookys', 2007, 1, 'Movie', 73.9, 'Charming but Surreal. Scary but Adorable. Pookys is a Cool and Stylish animation comedy full of cute &amp; unique ghost characters. Designersunit Spooky graphic presents a great 3DCG animation piece to all the kids in the world.   (Source: AniDB)', 99, True, 72);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18913, 'Ling Long: Incarnation Special', 2021, 1, 'ONA', 72.6, 'Special chapter of Ling Long: Incarnation.', 33, True, 73);
