INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18924, 'Tsujitsuji Sensha', 2008, 1, 'ONA', 64.8, 'Short animation of Yawaraka Sensha created as a farewell to a retired staff member.', 51, True, 84);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (18925, 'Minami e Itta Misuke', 1971, 1, 'Movie', 77.0, 'Jumping out of the cupboard, Chi-cha and Ikeho ask for Misukes help, saying that they have to answer a quiz that the god Don-dan has given them to save their mother. Misuke then heads for a country in the south passing right through the cupboard.  (Source: Official Website)', 58, True, 85);
