INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19064, 'Yaku nara Mug Cup mo: Niban Gama', 2021, 12, 'TV', 61.5, 'The conclusion of the Mino ware contest has spurred Himeno Toyokawa to create a piece even more remarkable than the last. Anxious to embrace the future yet emboldened by her mothers legacy, Himeno strives to find the right inspiration—a task that proves to be just as ambitious as her goal. When Himenos father suggests that her next creation should be the centerpiece at the cafe, expectations for the final product only grow with each passing day.  Through new encounters and experiences, Himeno and her friends reconnect with the foundation of their passion in their search for what lies at the core of pottery.', 42, True, 104);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19065, 'Hua Jianghu: Bu Liang Ren IV', 2021, 13, 'ONA', 79.1, 'Fourth Season of Hua Jianghu: Bu Liang Ren.', 98, True, 105);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19066, 'Renou Xueyuan', 2021, 10, 'ONA', 88.3, 'The Equipment: Living Forms, or ELFs, were created over fifty thousand years ago to assist humankind in their combat against the Honkai—the decay. With the projects success, the ELFs soon became sentient, compelling humanity to treat them as near-equals. However, when the Ninth Herrscher laid waste to the planet, almost all traces of ELFs vanished into the Sea of Quantas endless abyss.  Yet, there seems to be a bubble universe where the ELFs fate has taken a brighter turn. Here, they live peacefully among humans and attend a specialized institution, ELF Academy, where they study as if they were human beings themselves. From Selunes Elegys chuunibyou tendencies to Blood Embraces gangster shenanigans, the peaceful environment of the academy is guaranteed to provide relief from the depressing state of the main universe.', 54, True, 106);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19067, 'Mao Ling Xiangce', 2021, 21, 'ONA', 76.0, 'No description available for this anime.', 36, True, 107);
