INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19147, 'Colours', 2021, 1, 'Music', 68.9, 'In the pursuit of her dream, Protagonist Lin worked alone at an animation company in a big modern city, which was too busy to answer her fathers message.   She was given an important role in a new project. However, her inspiration dried up under the pressure of the schedule. she fell into a low point where she could not hold a pencil again...Losing confidence, Lin go back to her hometown. She found out a sketchbook when drawn with her father in childhood. Encouraged by the memory, she rediscovered her first love to painting and devoted herself to creating and embracing her dreams.  (Source: Official YouTube channel)', 10, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19148, 'Ga Kan', 2012, 1, 'Movie', 84.3, 'An Escher-like metaphor for introspection: a woman and her reflection in a forest pool, plus moths.  (Source: douban)', 94, False, 68);
