INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19150, 'Ramen Chai-nyan', 2001, 1, 'OVA', 97.2, 'Chai Nyan is a 14-year-old girl who came all the way from China to spread the way of Ramen! However, a drunk named Yoiyoi refuses to accept that Chai Nyans ramen shop neither sells alcohol nor allows drinking. And so, the drunk decides to destroy the shop with robots and so on. Will Chai Nyan be able to weather this storm?  (Source: AniList)', 42, True, 70);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19151, 'Katarina Nounai Kaigi X', 2021, 23, 'ONA', 74.3, 'Short specials posted on the official twitter account where the Katarina Five introduces Otome Game no Hametsu Flag shika Nai Akuyaku Reijou ni Tensei shiteshimatta... X.', 108, True, 71);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19152, 'Deji Meets Girl', 2021, 12, 'TV', 66.0, 'Sixteen-year-old Maise Higa spends her summer days working part-time at her familys hotel, with absolutely nothing interesting to do. That is, until she meets Ichirou Suzuki—a mysterious boy who is seemingly haunted by strange supernatural occurrences. Upon interacting with him, Maise unexpectedly enters a different reality, where hotel rooms can transform into the deep ocean and banyan trees can spawn indoors out of nowhere. Intrigued, Maise accompanies Ichirou in his quest to uncover the secrets behind the inexplicable enigmas surrounding him.', 40, True, 72);
