INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19179, 'Wu Dong Qian Kun 3rd Season', 2022, 12, 'ONA', 96.7, 'Lin Dong continues his journey to find the ancient relic and make himself stronger so that his family can enter the main one. He also becomes stronger so that Ling Qingzhu approves him and they can get together.', 60, True, 99);
