INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19277, 'Getsuyoubi no Tawawa 2 Special', 2021, 1, 'Special', 99.9, 'Unaired episode 13 included with the Blu-ray release of Getsuyoubi no Tawawa 2.', 23, True, 77);
