INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19322, 'Look at Me Only', 2016, 1, 'Movie', 83.9, 'Having forgotten exciting feelings of the early days of the relationship, the man drifts along petting his guinea pig. One day he meets a beauty of flower who appreciates the pet.  (Source: YouTube)', 94, True, 2);
