INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19421, 'Yoshida Katsuko no Yabai wa! SDGs: Araburu! Trouble! Sustainable!', 2021, 13, 'TV', 68.6, 'The anime centers on Katsuko Yoshida, the cousin of Eagle Talons Yoshida-kun, and an employee in Kemonomichi Electronics special general affairs section. She educates her poorly informed colleagues about their misunderstandings of Sustainable Development Goals, the United Nations-backed goals for member nations to attain a sustainable future.  (Source: ANN)', 95, True, 101);
