INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19508, 'Bonta', 2013, 1, 'Movie', 60.5, 'A young boy becomes an unlikely hero when he sets out on an adventure-filled quest to find the legendary Bonta oasis.  (Source: IMDB)', 53, True, 68);
