INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19524, 'Mushoku Tensei: Isekai Ittara Honki Dasu - Eris no Goblin Toubatsu', 2022, 1, 'Special', 80.0, 'Unaired episode included in the fourth Blu-ray volume. The episode will take place during the same time in episode 16 (episode 5 in second cours) and depict what Eris and Ruijerd were up to outside the main story, as teased by the comment Goblin Extermination.  (Source: MAL News)', 58, True, 84);
