INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19589, 'Shenyi Jiu Xiaojie', 2021, 60, 'ONA', 74.4, 'Doctor and research specialist Jun Jiu finds herself the victim of a spiked drink in a business plot. Having been pulled into a wormhole by an unfamiliar girl, Jun Jiu inadvertently swaps souls with her and is transmigrated into an unknown cultivation world as the daughter of the Jun family. After deciding to take revenge on those who had wronged the previous owner of her body, Jun Jiu saves a sealed Mo Wuyue without realizing his true identity. With firm determination and knowledge from her previous life, Jun Jiu walks on the path of cultivation along with her mystic cat, while Mo Wuyue supports her from the shadows despite his aloof facade.', 83, True, 29);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19590, 'Shukatsu Kyosokyoku', 2012, 1, 'Movie', 92.9, 'An ordinary college girl is sucked into the frenetic job hunting, where all her friends dive into with dog-eat-dog vigor and crazed ambition. A potent look at one of Japanese social phenomenon with a dose of black humor.  Graduate Work 2012, Tokyo University of the Arts, Graduate School of Film and New Media.  (Source: Geidai Animation)', 99, True, 30);
