INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19672, 'Sumikko no Ko', 2017, 1, 'Movie', 91.5, 'It would be so much better if everyone just went away... A girl who hates school sits in the corner of the classroom and creates an imaginary world.  1st year work 2017, Tokyo University of the Arts, Graduate School of Film and New Media, Department of Animation.  (Source: Geidai Animation)', 99, True, 112);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19673, 'Radio Wave', 2017, 1, 'Movie', 76.3, 'Numbers stations were prominently used during the Cold War. A boy was tuning the radio in the snow mountain and happened to tune the shortwave of codes.', 34, True, 113);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19674, 'Teppen!!!!!!!!!!!!!!!', 2022, 12, 'TV', 86.0, 'The Teppen Grand Prix is a competition established out of an appreciation for stand-up comedy. As devoted fans of such performances, Yayoi Sakamoto and her two friends—Yomogi Takahashi and Yuzu Hosono—form the stand-up trio Young Wai-Wai. After qualifying for the final round in the prix, the three go up against other comedic trios, but only one group can emerge victorious.  With participants housed in a famous dorm where many comedians before them have lodged, the contestants time living at the establishment will give them a chance to prove they have what it takes to make their audience laugh until they cry!', 65, True, 114);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19675, 'Anata wo Hitokoto de Arawashite Kudasai: no Shitsumon ga Nigate da.', 2022, 1, 'ONA', 85.5, 'The anime depicts the smart city envisioned by Kyocera, where everyone can comfortably and safely live with the use of advanced technology, and it also depicts the worries of job seekers. The animes title and theme reflect both the vexing issue of how to describe Kyoceras extensive business in just one word, and the mood of job seekers vexed by the interview question, If you had to describe yourself in one word, what would it be?  (Source: ANN)', 32, True, 115);
