INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19731, 'Mousou Kagaku Series: Wandaba Style - Mix Juice no Tsukurikata', 2003, 1, 'OVA', 84.9, 'Mix JUICEs members are about to give a concert, they are interviewed by journalists about how the band were created. Each member gave a different story! Then, each girl sing alone but only a part of the crowd is moved. Finally they perform together and then, we learn from the producer Hanagata how he recruited the girls to give birth to Mix JUICE.  (Source: AniDB)', 98, True, 51);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19732, 'Mugen no Ao', 2022, 1, 'Music', 66.6, 'Official music video for Infinite Blue by Billain.', 14, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19733, 'Internet Overdose', 2021, 1, 'Music', 81.8, 'Music video for the song Internet Overdose by Aiobahn feat. KOTOKO made to promote the game NEEDY GIRL OVERDOSE.', 36, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19734, 'American Rabbit no Bouken', 1987, 1, 'Movie', 86.2, 'To fight evil, a young rabbit can transform into a star spangled superhero.  (Source: IMDB)', 104, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19735, 'Chimimo', 2022, 12, 'TV', 94.9, 'In her house, Mei Onigami discovers a strange round creature that only says chimi. Her sisters, Mutsumi and Hazuki, agree to let the being stay with them until its owner comes to claim it. However, as soon as one of them utters the word hell, more creatures show up until there are 12 in total. The sisters think nothing of this until the critters create a portal that summons an envoy from Hell.  Jabberwock the Eighth, a horned and fanged man covered in fur, has come to unleash a living hell on earth under orders from his boss. However, when living in the human realm proves to be challenging, the Onigami sisters allow him to stay with them. They also take in his Chimimoryo spirits—the round demons that preceded his arrival. Called Jigoku-san by the Onigami sisters, this messenger from Hell has a lot of work cut out for him if he wants to take over the world. But before that, he will have to survive the everyday hells of human life.', 79, True, 55);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19736, 'Shiyakusho', 2022, 1, 'ONA', 78.8, 'No description available for this anime.', 25, True, 56);
