INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19756, 'Kamigawa: Kagayakeru Sekai', 2022, 1, 'ONA', 91.5, 'Kamigawa: Neon Dynasty, the latest expansion set for the Magic: The Gathering collectible card game by Wizards of the Coast, releases in Japan on February 18, 2022, and to celebrate the new set an AMV-style trailer has been released that features animation production by WIT Studio and maxilla, and music by TK from Ling Tosite Sigure.   The song featured in the the trailer is entitled Scratch (with Koshi Inaba), and it features Koshi Inaba as a guest vocalist.  (Source: Crunchyroll, edited)', 23, False, 76);
