INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19798, 'Kanojo, Okarishimasu: Date Movie', 2020, 32, 'ONA', 65.7, 'Date movie shorts posted on the official Twitter account and later included on Blu-ray volumes of Kanojo, Okarishimasu.', 54, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19799, 'Kizuna no Allele', 2023, 12, 'TV', 90.8, 'It has been five years since AI Kizuna disappeared from the virtual world. Despite being an AI, she has captured the hearts of her fans, including Miracle, an aspiring virtual artist, with her performances. As Miracle attends ADEN Academy, a school for virtual artists, she makes new friends while learning more about singing, performing, and streaming.   Miracles ultimate goal is to win the prestigious Lapin dOr at the Virtual Grid Awards, an achievement Kizuna has earned five consecutive times. To do this, she works to improve her channel ranking through streams and performances, trying to stand out among other students at the academy. Determined to fulfill her dream of inspiring others the same way Kizuna inspired her, the budding star will not give up.', 117, True, 119);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19800, 'Seikimatsu Densetsu: Wonderful Tatsunoko Land', 1999, 1, 'Special', 79.0, 'The excessive adventure begins when a mysterious flying life-form, UBO came to Tatsunoko Anime World Island where all the Tatsunoko animation characters live. TV special animation program featuring all-star Tatsunoko characters.  (Source: Official Website)', 61, True, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19801, 'Pokemon Legends Arceus: Yuki Hodo Kishi Futaai', 2022, 3, 'ONA', 98.6, 'The anime tells the story of a boy named Akio and his encounter with a Hisuian Zorua. When he was younger, Akios father taught him that people and Pokémon cannot live together. But Akios interactions with the Zorua might offer a different lesson.  (Source: The Pokémon Company)', 32, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19802, 'Idol Bu Show Movie', 2022, 1, 'Movie', 94.4, 'The concept behind the project is a battle royale between three idol units, each one led by a Sengoku-era commander who has been reincarnated as a music producer. The winner of the battle royale will be determined by sales numbers and voting at each live performance. The group that wins will hold a grand live performance to adopt the name of the greatest under the heavens.  (Source: ANN)', 66, True, 2);
