INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19817, 'One Piece: Mugiwara no Ichimi kara no Kansen Yobou Message', 2020, 9, 'Special', 94.0, 'The One Piece: Infection Prevention Message from the Straw Hat Pirates is a series of animated PSAs that were made by Toei Animation and aired on Fuji TV near the start of the COVID-19 pandemic in March 2020. Each PSA features a member of the Straw Hat Pirates giving viewers brief advice about keeping themselves and others safe from the COVID-19 virus. The Straw Hats are all voiced by their regular anime voice actors.  (Source: One Piece Wiki)', 89, True, 17);
