INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19905, 'Boku wo Sonna Me de Minaide', 2011, 1, 'Music', 86.1, 'Music video for Kikuos 6th Vocaloid song, Boku wo Sonna Me de Minaide. It tells the story of a child dying in a bicycle accident, saying goodbye to his parents as he recalls what happened in the accident.  (Source: Vocaloid Wiki)', 75, True, 105);
