INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19941, 'Real Melancholy', 2021, 1, 'Music', 80.2, 'An original track created as the second part of AZKis Virtual Diva AZKi campaign, where she released songs regularly for eight consecutive months. This song embodies AZKis desire to maintain her identity and continue to perform as herself, despite the troubles and worries that accompany working in the online space.  (Source: Hololive Production)', 60, False, 21);
