INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19953, 'A lot of life', 2020, 1, 'Music', 97.7, 'Animated music video for Photon Maidens A lot of life. The track was used as the coupling track for their first single Discover Universe. It was also featured as an insert song in several episodes of the D4DJ First Mix anime.  This music video initially released on the D4DJs official YouTube on July 20, 2020, but was re-uploaded again with a CM recut on October 23, 2020.  (Source: AniList)', 34, True, 33);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19954, 'Happy Music♪', 2020, 1, 'Music', 74.7, 'Animated music video for Happy Around!s Happy Music♪. The track is the title song of their first single with the same name. It was also used as an insert song in the final episode of the D4DJ First Mix anime.  This music video initially released on D4DJs official YouTube on April 17, 2020. It was later re-uploaded with a CM recut on October 23, 2020.  (Source: AniList)', 27, True, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19955, 'Wish You Luck', 2020, 1, 'Music', 92.4, 'Animated music video for Peaky P-keys song Wish You Luck. The track is apart of their first single release Peak Peaky&amp;Peaky!! and was also used as an insert song in the final episode of the D4DJ First Mix anime.  This music video initially released on the official D4DJ Channels YouTube, but was re-uploaded again with a CM recut on October 23, 2020. It was later published standalone also through D4DJs Global Channel on January 6, 2021.  (Source: AniList)', 18, True, 35);
