INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (19968, 'Ohiru no Shocker-san', 2022, 50, 'ONA', 92.1, 'Centers on the everyday struggles of the lackeys of Shocker, the villain organization in the original Kamen Rider series.  (Source: ANN)', 43, True, 48);
