INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20212, 'Sentou Yousei Yukikaze: Experimental Movie', 2008, 1, 'Special', 60.9, 'A short film included with the Yukikaze Blu-ray box set and has new scenes animated in HD set after the final episode of the main OVA series.', 45, True, 52);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20213, 'Pokemon Moncolle Story', 2018, 8, 'ONA', 62.1, 'The Pokémon Company has unveiled a new series of adorable stop motion videos to promote the ultra popular Pokémon Moncolle figures. Each video is brief and depicts a story consisting of events in which little versions of recognizable Pokémon take part in, featuring Pikachu, Poipole, Mimikyu, Rowlet, Zeraora, Buzzwole, Charizard, Litten, Popplio, Groudon, Garchomp, Rockruff, Rayquaza and more.   (Source: pokemonblog.com)', 74, True, 53);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20214, 'Climbing', 2020, 1, 'Movie', 71.8, 'Professional climber Choi Se-hyeon, who got recovered from a car accident recently, discovers that she is pregnant just before the Climbing World Championships. As her long-time aspirations are threatened, she struggles to break free from the duties of motherhood. However, at the same time, she receives text messages from herself who seems to have been through a quite different life after the car accident. And most importantly, she wants to keep her baby.  (Source: IMDB)', 42, True, 54);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20215, 'Kono Subarashii Sekai ni Bakuen wo!', 2023, 12, 'TV', 73.2, 'Megumin is a young and passionate wizard from the Crimson Demon Village, a remote community of mages with red eyes and a flair for the dramatic. She has devoted her life to mastering explosion magic, a powerful but impractical spell that leaves her drained of mana and unable to move for the rest of the day. Regardless, she refuses to learn any other skills.  Along with her childhood friend and self-proclaimed rival, Yunyun, Megumin enrolls in the Red Prison: a prestigious academy for Crimson Demon magic users. There, she learns more about the secrets and history of her clan, as well as the threats and challenges they must face. As she polishes her power at the Red Prison with the help of her loyal familiar Chomusuke and her adorable little sister Komekko, Megumin aims to become the greatest explosion wizard of all time!', 116, True, 55);
