INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20320, 'Kirin no Koushin', 2011, 1, 'ONA', 70.3, 'A short animation created by UrumaDelvi.  Four giraffes are marching to...', 44, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20321, 'Akiba Meido Sensou', 2022, 12, 'TV', 94.5, 'The innocent Nagomi Wahira has always admired the cute girls serving at maid cafes. Hoping to fulfill her dream of becoming one, she moves to Akihabara to work at the maid cafe Ton Tokoton.  Nagomis first day seems completely normal—until she has to run an errand at a rival maid cafe along with her fellow recruit, the mature Ranko Mannen. There, things quickly go south, and Nagomi soon gets her first taste of Akihabaras violent maid wars. As she watches Ranko calmly battle her way through a horde of gun- and knife-wielding maids, Nagomi realizes that maid cafes are drastically unlike what she had envisioned.  While struggling to reconcile her expectations with the harsh reality she finds herself in, Nagomi searches for the enjoyment she once saw in the lives of maids.', 113, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20322, 'Run=Dim: Naeseoseu-ui Banran', 2001, 1, 'Movie', 96.7, 'Korean compilation movie of the previously released TV series.', 57, True, 42);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20323, 'Castle', 2019, 1, 'Movie', 71.8, 'During the period of the Provinces at war, many lives were lost. A castle architect discovers the possible role of a tea room as a place for warriors to regain humanity.  (Source: Vimeo)', 56, True, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20324, 'Kaguya-sama wa Kokurasetai: First Kiss wa Owaranai', 2022, 1, 'Movie', 98.1, 'After their first kiss, Kaguya Shinomiya and Miyuki Shirogane are left unsure where their relationship stands. The troubling uncertainty of whether they could be considered an official couple unleashes newfound problems as both Kaguya and Shirogane struggle to sort out their feelings.  While the lovestruck student council officers fret, the Christmas season rolls around, and romance is in the air. In the face of widespread tenderness, Kaguya and Shirogane must endure their affectionate battle of wits once more. Should they reconcile their feelings for one another, they may find themselves within reach of what they have both been longing for so long: true love.', 64, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20325, 'One Piece: Dai Tettei Kaibou! Kouzuki Oden Densetsu!', 2022, 1, 'Special', 91.6, 'Alongside Yamato, Momonosuke Kozuki recounts the great adventures of his father Oden—a renowned daimyo revered throughout the Land of Wano. From the days of Odens youth to his last moments of glory, Momonosuke comes to understand the hardships and personal growth that his father experienced to eventually become the man he was.', 68, True, 45);
