INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20397, 'From A to Z', 2019, 1, 'Music', 86.8, 'An original track created as the eleventh part of AZKis Virtual Diva AZKi campaign, where she released songs regularly for eight consecutive months. This song was created as part six of the clear, pop-style AZKi WHiTe series. An emotional song accompanied by a beautiful string track, written in AZKis own words about why she sings, which connects to her reasons for living.  (Source: Hololive Production)', 94, True, 117);
