INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20401, 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV Episode 0', 2022, 1, 'Special', 69.9, 'Special recapping all three previous seasons of DanMachi with Bell Cranel and Hestias VAs commentary.', 41, True, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20402, 'Hirano to Kagiura', 2023, 1, 'Movie', 77.3, 'The diligent high school freshman Akira Kagiura and his senior Taiga Hirano have been roommates for half a year. Kagiura used to be anxious about his future dormitory life, but thanks to his energetic senior looking out for him, he has come to feel content and at ease. As he continues to rely on Hirano more and more each day, he develops strong feelings for his selfless friend. In the six months they have left as roommates, Kagiura is determined to put a name to the relationship he cherishes so dearly before it comes to an end.', 32, False, 2);
