INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20411, 'Aru Asa Dummy Head Mic ni Natteita Ore-kun no Jinsei', 2022, 12, 'TV', 80.2, 'After reincarnating into a dummy head microphone, the protagonist gets involved in the lives of high school girls who do ASMR. The comedic anime will follow these high schoolers as they aim for the ASMR Koshien.  (Source: MAL News)', 18, True, 11);
