INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20424, 'Mayumi', 2016, 1, 'Movie', 91.1, 'Mayumi is a spoiled girl whose parents buy her everything she wants. She names her name Mayumi to everything she receives, and her room is gradually filled with many Mayumis. Mayumi herself gets swallowed by the characters of her name.  (Source: Geidai Animation)', 24, True, 24);
