INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20439, 'Lyeonglihan Neoguli', 1987, 63, 'TV', 90.3, 'Clever Raccoon Dog is a North Korean animated television series produced by SEK Studio which aired on North Korean state television. The series was produced for a number of years and features both old and new animation style, depending on the production year of each episode. The series focuses on three main characters: A raccoon dog, A male bear and A female cat, often involved in minor adventures or incidents. Each episode has a scholastic element or a particular message, focusing on matters as scientific information, road safety, commitment to sport and contests, among others.   (Source: Wikipedia)', 12, True, 39);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20440, 'Sore Ike! Anpanman: Tanoshiku Teasobi Mama ni Natta Kokin-chan!?', 2014, 1, 'Movie', 81.3, 'Kokin-chan, Dokin-chans little sister, is a master of fake tears. One day, she finds an egg that hatches into Tefutefu, a caterpillar who recognizes Kokin-chan as her mother! Sing and dance with Kokin-chan, Anpanman and the rest as their newborn friend grows up!', 49, True, 40);
