INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20521, 'Duoyun Shi Qing', 2020, 1, 'Movie', 98.9, 'Claude, the cloud maker, accidentally drops his cloud-making gadget and its picked up by Yin. A thunder cloud that Yin has made releases a thunderbolt on radio and causes a fire. As the gadget turns into a huge water-thirst cloud monster, Claude has to stop it from becoming a total disaster.  (Source: IMDB)', 75, True, 1);
