INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20528, 'Dengta', 2019, 1, 'Movie', 90.7, 'When the night falls, Luke climbs up to the deserted lighthouse, where he tries to light up the memory buried underneath the glass curtain walls of the citys skyscrapers with the old and worn equipment there.  (Source: IMDB)', 87, True, 8);
