INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20530, 'Dang Yigeren', 2018, 1, 'Movie', 79.8, 'The old man goes to mend window screen by his bike. He passes through all scenes which make him nervous or comfortable. It is his day and also a metaphor of his life.  (Source: IMDB)', 74, True, 10);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20531, 'Si So Mi', 2018, 1, 'Movie', 63.9, 'A love poem from the 1935 German film soundtrack has become a synonym for the funeral procession Sisomi in Taiwan, creating an interesting and absurd contrast between the two. The dance movements are interwoven with the stories of dead animals and death that belong to the city, telling their own life stories.  (Source: Goldenhorse, translated)', 33, True, 11);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20532, 'Fukuro', 2001, 1, 'Movie', 62.3, 'Fukuro (Japanese for bag or sack) is a 3-minute short film from 2001. It features Pyramid Head and a Lying Figure from Silent Hill 2, the Fukuro Lady, and many monsters from early sketches for Silent Hill 2. The film contains disturbing, surreal imagery. Credits go to Masahiro Ito (series art director) for creature design and to Akira Yamaoka (series composer) for the music.  It has been published on Art of Silent Hill, Lost Memories: The Art &amp; Music of Silent Hill, and The Silent Hill Experience.                                   (Source: Silent Hill Wiki)', 96, True, 12);
