INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20683, 'Shake it up n go: Shakitto! Corn no Uta', 2019, 1, 'Music', 68.4, 'Music video for Shake it up n go: Shakitto! Corn no Uta by Uchikubi Gokumon Doukoukai.  A special song is born from the collaboration between the Uchikubi Gokumon Club and Hagoromo Foods Shakitto! Corn! Furthermore, in creating the music video, the band even collaborated with the popular creator Nagano! The unexpected chemistry of the three parties resulted in the most heartwarming music video.  (Source: Uchikubi Gokumon Doukoukai Official YouTube Channel)', 100, True, 43);
