INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20704, 'Megami no Café Terrace', 2023, 12, 'TV', 82.2, 'When Hayatos grandmother passed, he planned to sell her rundown café on the shore—not realizing that it was also home to five young women who call themselves her family?! Their desperation to keep the café open convinces Hayato to give it a shot...but even their best intentions might not be enough to make it work! And can he even work with these five unruly women? No matter what, hes got his work cut out for him!  (Source: Kodansha USA)', 60, True, 64);
