INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20765, 'Hidden Region', 2022, 1, 'Music', 88.9, 'Official music video for the song Hidden Region by TRIGGER, released in celebration of the groups 7th Anniversary.', 73, True, 5);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20766, 'Sharkd', 2022, 1, 'ONA', 87.3, 'Finding her life in the Lost City of Atlantis too boring, friendly but impulsive shark girl Gura Gawr swims to shore in search of fun. However, she soon finds out that she cannot enjoy life on the surface peacefully without clothes. Luckily, the nearby Blue Axolotl Beachwear shop presents Gura with a shark-themed outfit that speaks to her inner child.  Thanks to a flier posted for a Hololive Production audition, Gura has since become the internets most beloved VTuber. But that has never stopped her origin story from being any less lovable than her YouTube antics.', 85, False, 6);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20767, 'Riyuu tto Kitte Kyuu tsu!!!', 2022, 1, 'Music', 63.1, 'No description available for this anime.', 23, True, 7);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20768, 'Hololive Summer 2022', 2022, 4, 'ONA', 80.0, 'The three artifacts required to bring back hololive Summer have been stolen, and even hololives leader YAGOO has gone missing.  Upon realizing this, staff member Friend A (A-chan) gathers the hololive members, and sets off on a mission to find the three artifacts, rescue YAGOO, and ensure hololive Summer can happen this year.  The long-awaited return of hololive Summer... But will that dream be quashed once more this year? Will the joy of the season be stolen again?  This summer... the girls quest begins.  (Source: hololivepro.com)', 87, True, 8);
