INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20819, 'Dokuhaku Suru Universal Yoko Mercator Egg Man', 2009, 1, 'OVA', 68.6, 'A psychopathic killer known as Egg Man has been caught, incarcerated and is awaiting his death sentence. Karen, a beautiful and brave police woman, is assigned to the Egg Man case to find the whereabouts of a missing dead body. Egg Man meets his cellmate, Prisoner 205. Who is Prisoner 205? Is Prisoner 205 another in-mate awaiting his death sentence as well or an android utilized by the police to collect information about him and his knowledge of the corpse? Who is really manipulating whom?  (Source: ANN)', 64, True, 59);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20820, 'Oni no Ko', 2022, 1, 'Music', 89.7, 'Music video for the song Oni no Ko by SETA.', 61, True, 60);
