INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20822, 'Kudamono', 2018, 1, 'Movie', 84.2, 'At some point, children diverge from the ideal path set forth for them by adults. The trigger is usually a trivial incident.  (Source: Geidai Animation)', 44, True, 62);
