INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20825, 'Majutsushi Orphen Hagure Tabi: Urbanrama-hen', 2023, 12, 'TV', 76.6, 'After the events of Kimluck, Orphen is on a quest to find Azalie, only to find himself in a war in between celestial beings and humans.', 84, True, 65);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20826, 'Kawaisugi Crisis', 2023, 12, 'TV', 85.1, 'Upon first seeing Earth from the Azatos Empires survey ship, Chief Investigator Liza Luna plans to eradicate every lifeform on it immediately, leaving behind only useful resources. While surveying the planet, Liza discovers that human civilization has evolved at a pathetic rate compared to other lifeforms.  Liza makes her way to the surface of the planet to properly inspect and understand its inhabitants. Still convinced that there is nothing beneficial to be found, the investigator makes her way into a cafe to gauge the planets food culture. Liza walks into a cat cafe, where she meets creatures far cuter than anything else in the galaxy. Motivated by this new discovery, Liza decides to investigate Earths numerous adorable inhabitants.', 18, True, 66);
