INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20880, 'JoJo no Kimyou na Bouken Part 6: Stone Ocean Part 3', 2022, 14, 'ONA', 67.2, 'After finally escaping the confines of Green Dolphin Street Jail, Jolyne Kuujou—alongside her companions Ermes Costello and Emporio Alniño—pursues the villainous priest Enrico Pucci across the state of Florida. Jolynes allies, Weather Report and Narciso Anasui, struggle to catch up with her in order to help bring an end to Puccis plot. As both parties pursue the priest, they must battle against Puccis band of enemy Stand users.  While Jolynes comrades fight for their lives, Pucci races to the Kennedy Space Center. There he hopes to enact his ultimate goal, one he believes God has entrusted to him. He aims to fulfill the will of the Joestars blood enemy Dio Brando and—by robbing humanity of free will and making them slaves to fate—to create a world where all humans are blissfully happy.  Unable to rely on the aid of her comatose father Joutarou, Jolyne must weaponize all she has learned in prison to confront Pucci in a climactic battle while the world itself hangs in the balance.', 100, False, 120);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20881, 'Fire Emblem Heroes: Fjorm ga Utau - Kouri no Hana', 2021, 1, 'Music', 76.4, 'A music video featuring Fjorm: Princess of Ice singing Kouri no Hana by Hiroki Morishita, a composer from Intelligent Systems. The English version is sung by Cristina Vee Valenzuela, and the Japanese version by Rie Takahashi.  (Source: Fire Emblem Heroes Wiki)', 116, True, 1);
