INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20917, 'Safari Bus Tayo', 2022, 8, 'ONA', 76.5, 'Tayo transformed into a safari bus and went on a safari adventure in Africa with Duri the little explorer! They save the baby lion in danger, shared the wonderful moment the baby giraffe was born, and even met a group of hyenas led by the wonderful queen!  Lets share the exciting Tayo and Duris adventure to meet various animals on the safari!  (Source: Official YouTube Channel)', 87, True, 37);
