INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20920, 'Agisang-eo Ollie Tululutulu', 2020, 12, 'TV', 84.0, 'A massive underwater earthquake sweeps the Shark Family to the opposite side of the ocean! For Baby Shark Brooklyn, who is curious about everything, this new place is an adventure playground. In a new home, Brooklyn makes new friends, and they explore the village together. When they face problems big or small, their different characteristics create synergy and help them overcome hardships.  (Source: Amazon)', 26, True, 40);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20921, 'Agisang-eo Ollie wa William', 2020, 54, 'TV', 92.2, 'Baby Sharks Big Show! follows Baby Shark and his best friend William as they journey on fun-filled comedic adventures in their community of Carnivore Cove, make new friends, and sing original catchy tunes along the way.  (Source: Amazon)', 49, True, 41);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (20922, 'Zhege Nianji Huan Neng Dang Daxia Ma', 2023, 10, 'ONA', 84.2, 'After the Lao Bai left the big city, he returned to his hometown Changan with Yanzi (Yanshan Xue) to live. While working hard to run a Changan supermarket for their former heroic dreams, they met community neighbors: A Meng, A Hun, Long Zi, Xiao Man, Long Shu, You You, and Xiao Wu.  (Source: Bilibili)', 64, True, 42);
