INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21034, 'World Dai Star', 2023, 12, 'TV', 68.2, 'After Dai Star stage performers exploded in worldwide popularity in the 20th century, 16-year-old Kokona Ootori follows her dream of becoming a World Dai Star by auditioning for the Sirius theatrical troupe.  (Source: ANN)', 36, False, 34);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21035, 'Mini Mini Pocket no Ookina Niwa de', 2022, 1, 'Movie', 68.9, 'When it shrinks, it expands. It floats and it sinks. It separates but connects. When I think I’m watching them, theyre actually watching me. A charming animation rhyme that weaves together the many days of observing, recording, and experimenting.  (Source: Official website)', 44, True, 35);
