INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21043, 'Mugen no Hi', 2016, 1, 'Movie', 66.2, 'In the pitch darkness a man cannot see anything. Only light source is a light lit with a match by someone else. The light is lit and put out. This repeats sometime and eventually the man makes up his mind.  (Source: Geidai Animation)', 103, False, 43);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21044, 'Nanimo Nakute Ii', 2015, 1, 'Movie', 63.7, 'This hand-drawn animation thematizes what we are looking at in everyday life. Created using pencils, pastels, and oil paints, the drawn pictures were then shot with a digital camera and spliced together as video. Set on a fantasy train representing a kind of mental landscape, a young man shuts himself off from the outside world by reversing his face so he does not see anything, while another man silently stuffs garbage into the face.  (Source: Japan Media Arts Festival)', 27, True, 44);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21045, 'Ano Chi', 2018, 1, 'Movie', 98.9, 'This story is about a place long ago, before birth and before death, that everyone knows and no one knows.  (Source: Geidai Animation)', 56, True, 45);
