INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21238, 'Amane Nikki', 2021, 1, 'Movie', 71.9, 'This work is based on 15 years of entries in the diary that Ive kept since age eight. Through creating this work I was searching for freedom from my preconceptions about animation and myself.  (Source: Geidai Animation)', 35, True, 118);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21239, 'Wu Liuqi: Anying Suming', 2023, 10, 'ONA', 79.4, 'The protagonist Wu Liuqi originally lived a carefree life on Xiaoji Island, but his identity became a mystery due to amnesia. As outsiders landed on the island and recognized Wu Liuqi, various conspiracies began to cover Xiaoji Island. So Wu Liuqi decided to return to Xuanwu Kingdom to meet his destiny in order to protect his partners and their homeland.   (Source: Bilibili, Google translated)', 31, True, 119);
