INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21293, 'Summer Time', 2017, 1, 'Movie', 74.6, 'Her mother was hospitalized that summer. This day from Aki-chans summer is tinged with sadness in the company of her trusted Ryukyu dog named Goyapochi.  (Source: Geidai Animation)', 82, True, 53);
