INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21361, 'Sekai, Nishihara Shoukai no Sekai! Part 2 Gyaku featuring Crazy Ken Band', 2022, 1, 'Music', 81.6, 'Music video for the song Sekai, Nishihara Shoukai no Sekai! Part 2 Gyaku featuring CRAZY KEN BAND by RHYMESTER. It is an official remix of Nishihara Shokais company song and was produced to commemorate the companys 50th anniversary.', 59, False, 1);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21362, 'Itowanai feat. Miyu Tomita ＆ Kana Ichinose', 2023, 1, 'Music', 73.8, 'Music video for the song Itowanai by MIMiNARI.', 46, True, 2);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21363, 'Rokudou no Onna-tachi', 2023, 12, 'TV', 85.0, 'Tousuke Rokudou is a first-year attending Aomori High, a school full of delinquents. He is often bullied by his classmates due to his incompatibility with their behavior, the only exceptions being his two good friends who are also social outcasts. Frustrated at the way they are treated, the three wish they could stand up and claim the fun, peaceful school life of their dreams.  However, Tousukes life takes a drastic turn when he receives a package from his late grandfather containing their family heirloom, a scroll said to possess the power to save him from impending danger. Upon holding the scroll, a sudden glow emanates, leaving a strange mark on Tousukes forehead.  Thinking that hes received the means to free himself and his friends from their daily treatment, Tousuke is shocked to find out that its effects are far different than what he had imagined. Although his bullying continues, he realizes that the mark from the scroll acts as a charm, capturing the hearts of delinquent girls—in particular, Ranna Himawari, the strongest of them all.', 117, True, 3);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21364, 'Bing Zhu Qi Hun Part 2', 2023, 12, 'ONA', 60.0, 'No description available for this anime.', 25, False, 4);
