INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21374, 'W Professors', 2018, 3, 'ONA', 68.4, 'The Two Professors is a series of three CGI-animated shorts prior to the release of Pokémon: Lets Go, Pikachu! and Lets Go, Eevee! featuring Professor Oak and Professor Willow and the Mythical Pokémon Meltan. The episodes were uploaded to the official Pokémon YouTube channel beginning on September 25, 2018.   (Source: Bulbapedia)', 114, True, 14);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21375, 'Watashi no Hashtag ga Haenakute.', 2023, 1, 'ONA', 71.7, 'The story is set in a smart city envisioned by Kyocera, where people express themselves through hashtags on overhead displays.  Yoshitoki has designed the original characters, and at first glance, you can see his style throughout the video. The female lead, Yume, closely resembles Shouko Nishimiya from A Silent Voice.  Unlike Nishimiya, however, Yume lacks confidence and she constantly worries that her hashtag wont stand out. To overcome this, she comes up with a special hashtag known as a weird tag.', 34, False, 15);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21376, 'Chinpu na Otoko', 2018, 1, 'Movie', 70.4, 'Unable to bear children, I produced labor robots. However, people did not accept the robots and began to eliminate them. I decided to take revenge on the person responsible for destroying them. Anyone who kills my children must be a monster.  (Source: Official Site, translated)', 63, True, 16);
