INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21382, 'Pinkfong Cinema Concert: Ujudaetamheom', 2020, 1, 'Movie', 66.3, 'Joined by new friends from other planets, Pinkfong and Baby Shark explore outer space and search for missing star pieces to return home.  (Source: Netflix)', 51, True, 22);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21383, 'Pinkfong Cinema Concert 2: Wonderstar Concert Daejagjeon', 2022, 1, 'Movie', 77.0, 'Wondervilles favorite problem-solving duo, Pinkfong and Hogi, assembles a group of friends to produce their first-ever live concert. The crew must learn to come together as a team and compromise as they create the ultimate interactive experience with sing-along lyrics and matching choreography. Pinkfong Sing-Along Movie 2: Wonderstar Concert is a sequel to the movie Pinkfong &amp; Baby Shark’s Space Adventure (2020), filled with Pinkfongs most beloved songs, including the global mega-hit, Baby Shark!  (Source: Fathom Events)', 56, False, 23);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21384, 'Pinkfong Wonderstar', 2019, 26, 'TV', 79.9, 'Pinkfong and Hogis epic journey begins now! After accidentally crashing into the roof of Hogis house, Pinkfong meets a new best friend and problem-solving partner.  (Source: Official YouTube Channel)', 48, True, 24);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21385, 'Pinkfong-gwa Hogi-ui Sinnaneun Iyagi', 2020, 1, 'Special', 60.9, 'The special showcases Pinkfong and Hogis best moments from key episodes such as Welcome to Wonderville, We are Wonderstar, Runaway Cheese, and Learning to Fly.  (Source: Pinkfong Wiki)', 69, True, 25);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21386, 'Myeongtamjeong Pinkfong-gwa Hogi', 2020, 26, 'TV', 91.3, 'Pinkfong and Hogi are back, helping friends in Wonderville and making memories! Watch them zoom around in their magical car and collect cube-cubes every time they solve a friends problem. Wonderville can count on Pinkfong and Hogi because no problem is too big (or too small) for team Wonderstar!  (Source: Official YouTube Channel)', 66, True, 26);
