INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21536, 'Kingyo no Isshou', 1993, 1, 'Movie', 97.5, 'An elementary school student named Mitsui won a goldfish at a summer festival. He took it home as a pet, and for a while, it attracted his attention. However, once he received a pet a turtle for Christmas, he began to lose interest in the goldfish.  (Source: Official Site)', 25, True, 56);
