INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21547, 'Stand By Me Doraemon Specials', 2015, 3, 'Special', 69.8, 'Previously unreleased scenes included as a bonus with Stand By Me Doraemon Blu-ray.', 54, True, 67);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21548, 'Kage no Jitsuryokusha ni Naritakute! 2nd Season', 2023, 12, 'TV', 88.1, 'Everything has been going according to plan, but the hour of awakening draws near. Cid Kageno and Shadow Garden investigate the Lawless City, a cesspool where the red moon hangs low in the sky and three powerful monarchs rule the streets. The true draw for Cid, however, is one who can draw blood–the Blood Queen, a vampire who has slumbered in her coffin for eons. Her awakening approaches, and Cid could finally face a day of reckoning.  (Source: HIDIVE)  Episode 1 was previewed at a screening at Anime Expo on July 1, 2023. Regular broadcasting began in October 2023.', 88, True, 68);
