INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21604, 'Pi Zhe Lang Pi De Yang', 2023, 16, 'ONA', 68.2, 'Web-writer Lai Xiaoguang accidentally entered a virtual world called The Hand of God. In this fantasy world, she turned into a werewolf named Da Niu and was involved in a national treasure theft case. In order to investigate the truth, she had to embark on a journey with Wang Cai the Goat King.  (Source: Bilibili, Google translated &amp; edited)', 70, True, 4);
