INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21627, 'Mekakure', 2019, 1, 'Movie', 88.4, 'Shun is forced into playing with four friends. But they are not friends, he hates them. The unbearable heat and heavy atmosphere deepen his depression.  (Source: eventive)', 101, True, 27);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21628, 'Aishang Ta de Liyou', 2023, 22, 'ONA', 66.2, 'Freshman Juntang Yuan, applied for Minsong University in order to get close to his senior, Zhu Zhu, whom he had a crush on for a long time. After enrolling in school, he meets Shiya Li, a former idol who had dropped out of school. He meets Zhu Zhu again on campus as well as Ruoni Cui at a social party. It was then, that Juntang fell into an emotional vortex with the three girls, hesitant, and entangled...  (Source: bilibili, translated)', 107, True, 28);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21629, 'Ikimono-san', 2023, 52, 'TV', 79.3, 'A new series of anime shorts based on Atsushi Wadas original short film and game My Exercise.  (Source: ANN)', 115, True, 29);
