INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21667, 'The Sukkiri Crawlers', 2008, 20, 'Special', 86.8, 'As a promotion for the release of the movie The Sky Crawlers, Sukkiri Crawlers was produced in collaboration with the Nippon Television Network Corporations information program Sukkiri!. It aired for one minute in the program until the day before the release date.  Characters modeled after the programs stars, Koji Kato, Terry Ito, and Elaine Hayama, wandered into the world of the film and introduced the world and characters. In addition, aphorisms by Shuji Terayama, Mamoru Oshii, and others are presented. All episodes are included in the Blu-ray Collectors Edition bonus DVD3.', 64, True, 67);
