INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (21822, 'Wang Shen Zhi Ye', 2022, 1, 'Movie', 75.4, 'On a full moon night, a 10-year-old girl from a pig farming family in a remote village is lured by Moosina to a strange cave in the mountains. There, she will discover the secret of why Moosina always plays dirty tricks on children.  (Source: Kaohsiung Film Festival)', 34, True, 102);
