INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22034, 'On Time Off Time', 2020, 1, 'Movie', 87.7, 'The juxtaposed movements resonate with each other, filling the conflict between continuity and fluctuation.  (Source: Official Website)', 110, True, 74);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22035, 'Beach', 2010, 1, 'Movie', 86.5, 'This animation was based on a scene I dreamt, where white smoke was rising from a bed. I was influenced by one of Zhuangzi’s thought, The butterfly dream, and visualized the contrast between dream and reality. While I was creating this piece, I was never aware of whom the man sleeping in the movie was, but somehow, he ended up looking just like my grandfather.  (Source: Official Website)', 44, True, 75);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22036, 'Dedari', 2007, 1, 'Movie', 91.1, 'An animation work based on rituals filmed during fieldwork in Bali, Indonesia. Among the hundreds of ceremonies known as Sangyan in Bali, the motif is Sangyan Dudari, which is said to be the most effective for exorcism. Sangyan Dudari is a ritual in which two premenstrual girls are possessed by Dudari (celestial maiden spirit) and danced continuously.  (Source: Official Website)', 99, True, 76);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22037, 'Calvin Klein x Hirotoshi Iwasaki', 2020, 3, 'Special', 67.3, 'Animations for Calvin Kleins Holiday 2020 campaign that featuring Calvin Kleins Pride campaign talents, Chella Man, Tommy Dorfman and Reece King.  (Source: Official Website)', 93, False, 77);
