INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22040, 'Mukidona Sen-tachi', 2019, 1, 'Movie', 71.9, 'Lines drawn with a pencil on paper begin to wriggle of their own volition. Then, regardless of the filmmakers intention, they begin to move inexorably towards a new horizon. The film consists of seven chapters: generation, accumulation, silence, revival, transformation, amplification and diffusion.', 18, True, 80);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22041, 'A Drawing for Mom', 2020, 1, 'Movie', 86.1, 'An animated work of pencil drawings produced and provided as a material for the Kanazawa College of Art encouragement research Study on the possibility of painting-like viewing experience in analog material 8K filmed animation.', 104, True, 81);
INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22042, 'Hui Jia Lushang', 2022, 1, 'Movie', 75.9, 'We are always going faster on the way back home. In the experiments carried out at the Large Hadron Collider (LHC), the protons apparently only exist for a billionth of a second, travelling at approximately the speed of light. Feelings are broadcasted like the passing of time.  (Source: Letterboxd)', 40, True, 82);
