INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22057, 'Knights and Magic', 2017, 13, 'TV', 62.7, 'The show tells the story of a young Japanese man who dies in a car accident and reincarnates as a child in an alternate world where magic and giant robots are real, dedicating himself since then to fulfill his longtime dream of building and piloting his own mecha.', 27, True, 97);
