INSERT INTO products (id, name, anho_edicion, numero_episodios, formato, price, descripcion, stock, warranty, market_id) VALUES (22060, 'Ying Shi', 2010, 1, 'Movie', 68.4, 'A boy takes an adventure in the old and shabby temple which was burnt down for a secret reason. The film is based on a story in Taiwanese folk culture.  (Source: Edinburgh Taiwan Film Festival)', 52, True, 100);
